    /// Synthetic Homebrew search result — shows up when user types "brew" or "homebrew".
    private var homebrewSearchResult: SearchResult? {
        let brewPath =
            FileManager.default.fileExists(atPath: "/opt/homebrew/bin/brew")
            ? "/opt/homebrew/bin/brew"
            : FileManager.default.fileExists(atPath: "/usr/local/bin/brew")
                ? "/usr/local/bin/brew" : nil
        guard let path = brewPath else { return nil }
        let icon = NSImage(
            systemSymbolName: "shippingbox.fill", accessibilityDescription: "Homebrew")
        return SearchResult(
            title: "Homebrew",
            subtitle: path,
            icon: icon,
            action: {},
            type: .application,
            filePath: path,
            contactData: nil
        )
    }

    /// Registered CLI tools appear in search results alongside applications.
    private var cliToolSearchResults: [SearchResult] {
        return TerminalPackageManager.shared.packages
            .filter(\.isEnabled)
            .map { pkg in
                let isTUI = TerminalAIBridge.shared.isTUICommand(pkg.command)
                let symbolName = isTUI ? "terminal.fill" : "arrow.right.square.fill"
                let icon = NSImage(
                    systemSymbolName: symbolName,
                    accessibilityDescription: pkg.name)
                let subtitle: String = {
                    var parts: [String] = []
                    if !pkg.name.isEmpty && pkg.name.caseInsensitiveCompare(pkg.command) != .orderedSame {
                        parts.append(pkg.name)
                    }
                    if let path = pkg.installedPath, !path.isEmpty {
                        parts.append(path)
                    } else if !pkg.description.isEmpty {
                        parts.append(pkg.description)
                    }
                    return parts.isEmpty ? pkg.command : parts.joined(separator: " · ")
                }()
                return SearchResult(
                    title: pkg.command,
                    subtitle: subtitle,
                    icon: icon,
                    action: { attachCLIToolToCurrentDock(command: pkg.command, package: pkg) },
                    type: .cliTool,
                    filePath: pkg.installedPath,
                    contactData: nil
                )
            }
    }

    // Calculate dynamic height based on content
    private var calculatedHeight: CGFloat {
        // Pinned apps are now rendered inline as a horizontal icon strip next to the search bar,
        // so they should not contribute extra height.
        let pinnedAppsHeight: CGFloat = 0
        let statusBarHeight: CGFloat = settings.enableStatusBar ? 45 : 0
        let contextHeight: CGFloat =
            (settings.enableFrontmostDetection && frontmost.isSectionExpanded) ? 45 : 0
        let dockRowHeight = CGFloat(settings.dockIconSize) + 4
        let dockVerticalPadding: CGFloat = 12
        let searchBarHeight: CGFloat = max(
            isSearchBarExpanded ? 58 : 50,
            dockRowHeight + dockVerticalPadding
        )
        let indexingBarHeight: CGFloat = fileIndexManager.progress.isIndexing ? 30 : 0
        let l2ChatHeight: CGFloat = {
            guard showContextInDock && !showMediaLayer else { return 0 }
            if l2.chatMessages.isEmpty {
                if l2.isLoading { return 50 }
                return 0
            }
            var total: CGFloat = 0
            for message in l2.chatMessages {
                var messageHeight: CGFloat = 80
                if message.content.contains("```") {
                    let codeBlockCount = message.content.components(separatedBy: "```").count - 1
                    messageHeight = 150 + CGFloat(codeBlockCount / 2) * 200
                } else if message.content.count > 200 {
                    let lines = message.content.components(separatedBy: "\n").count
                    messageHeight = CGFloat(lines * 20 + 40)
                }
                total += messageHeight
            }
            total = min(total, 500)
            if l2.isLoading {
                total += 50
            }
            if livePanelVisible, case .terminal = livePanelMode {
                total += 260
            }
            if livePanelVisible {
                switch livePanelMode {
                case .results, .filePreview:
                    total = max(total, 320)
                default:
                    break
                }
            }
            return total
        }()
        let finderSearchPanelHeight: CGFloat = {
            guard showContextInDock && !showMediaLayer
                && shouldShowFinderSearchResultsPanel(for: searchState.query)
            else { return 0 }

            if isFinderSemanticLoading && searchState.results.isEmpty {
                return 170
            }
            if !searchState.query.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                && searchState.results.isEmpty
            {
                return 150
            }

            let resultRowHeight: CGFloat = 50
            let resultsHeight = min(CGFloat(searchState.results.count) * resultRowHeight, 400)
            return resultsHeight + 48
        }()

        // Context chip height (only in L1 search mode with context and suggestions)
        let contextChipHeight: CGFloat = {
            // Not applicable in AI mode, L2 context mode, or the L3 media dock
            if aiMode.isActive || showContextInDock || showMediaLayer { return 0 }

            // If context awareness is disabled, return 0
            guard settings.enableContextAIExtensions else { return 0 }

            // Only expand if we have meaningful context
            let hasContext: Bool = {
                switch currentContext {
                case .filesSelected(let urls): return !urls.isEmpty
                case .textSelected(let text):
                    return !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                case .url(let urlString):
                    return !urlString.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                case .appFocused, .contactSelected, .none: return false
                }
            }()

            if !hasContext { return 0 }

            // Check if we have any matching shortcuts — passive only (not while typing)
            let hasSuggestions: Bool = {
                guard searchState.query.isEmpty else { return false }
                return allShortcuts.contains { shortcut in
                    guard let metadata = shortcutMetadataCache[shortcut.title] else { return false }
                    return metadata.matches(context: currentContext)
                }
            }()

            return hasSuggestions ? 70 : 0
        }()

        // AI mode has different height calculation, but keep the empty AI bar compact so
        // the glass background stays visually consistent with the L2 dock.
        if aiMode.isActive {
            // Each message bubble ~76px; cap window growth at 400px for chat.
            let aiChatHeight: CGFloat = aiMode.messages.isEmpty
                ? 0
                : min(CGFloat(aiMode.messages.count) * 76, 400)
            let aiLoadingHeight: CGFloat = aiMode.isLoading ? 48 : 0
            return statusBarHeight + pinnedAppsHeight + searchBarHeight + aiChatHeight
                + aiLoadingHeight + 12
        }

        // Folder preview height calculation
        if showFolderPreview {
            let folderPreviewHeight: CGFloat = 500  // Folder preview content height
            return statusBarHeight + pinnedAppsHeight + searchBarHeight + folderPreviewHeight + 10
        }

        // App panel (calendar/reminders/notes/etc.) — split view with fixed height
        if searchState.activeSmartQueryKey != nil {
            let panelHeight: CGFloat = searchState.activeSmartQueryKey == "clipboard" ? 430 : 480
            let panelGap: CGFloat = searchState.activeSmartQueryKey == "clipboard" ? 2 : 10
            return statusBarHeight + pinnedAppsHeight + searchBarHeight + panelHeight + panelGap
        }

        // Finder current-folder search mode uses the shared result panel instead of pills/popovers.
        if finderSearchPanelHeight > 0 {
            return statusBarHeight + pinnedAppsHeight + searchBarHeight + finderSearchPanelHeight + 14
        }

        // L2 context dock with chat results
        if showContextInDock && !showMediaLayer && (l2ChatHeight > 0) {
            return statusBarHeight + pinnedAppsHeight + searchBarHeight + l2ChatHeight + 16
        }

        // L3 Media dock — same compact pill height as normal dock
        if showMediaLayer {
            let mediaPillHeight: CGFloat = mediaObserver.duration > 0 ? 70 : searchBarHeight
            return statusBarHeight + mediaPillHeight + 12
        }

        if listViewDockHeight > 0 {
            return statusBarHeight + pinnedAppsHeight + listViewDockHeight + 12
        }

        if !searchState.results.isEmpty {
            // High-water-mark allocation: window grows to fit the largest result batch seen,
            // never shrinks mid-session. Resets when results clear. One resize per new max, not per count.
            let h = l1ResultsReservedHeight > 0 ? l1ResultsReservedHeight : 450
            return statusBarHeight + contextHeight + pinnedAppsHeight + searchBarHeight
                + contextChipHeight + indexingBarHeight + h + 10
        } else if searchState.isLoadingApps {
            return statusBarHeight + contextHeight + pinnedAppsHeight + searchBarHeight
                + contextChipHeight + indexingBarHeight + 60
        } else {
            return statusBarHeight + contextHeight + pinnedAppsHeight + searchBarHeight
                + contextChipHeight + indexingBarHeight
        }
    }

    private var expandedDockWidth: CGFloat { 660 }   // Spotlight-matched width
    private var collapsedDockWidth: CGFloat { 52 }    // Icon-only when unfocused

    private var visibleDockWidth: CGFloat {
        let hasResultsOrChat =
            !searchState.results.isEmpty || searchState.isLoadingApps || showFolderPreview
            || searchState.activeSmartQueryKey != nil
            || usesVerticalListDockLayout
            || (aiMode.isActive && (!aiMode.messages.isEmpty || aiMode.isLoading || aiMode.streamingId != nil))
            || (showContextInDock && (!l2.chatMessages.isEmpty || l2.isLoading))
        if isSearchBarExpanded || hasResultsOrChat {
            return expandedDockWidth
        }
        return collapsedDockWidth
    }

    private var notificationDockPopoverWidth: CGFloat {
        let usableDockWidth = max(visibleDockWidth - 28, 280)
        let reservedInputWidth: CGFloat = isSearchBarExpanded
            ? min(340, max(usableDockWidth * 0.48, 300))
            : 108
        let candidate = usableDockWidth - reservedInputWidth
        return min(420, max(280, candidate))
    }

    private var calculatedWidth: CGFloat {
        // Keep the NSVisualEffectView/window sampling surface stable. The visible dock
        // shell shrinks inside this width, which avoids wallpaper blur/tint changes.
        // When transient side buttons are visible, reserve their width so the dock
        // row can draw separately without changing the results sheet width.
        expandedDockWidth + floatingClipboardOccupiedWidth + floatingAppLogoOccupiedWidth
    }

    private var floatingClipboardOccupiedWidth: CGFloat {
        guard shouldShowClipboardFloatingIcon else { return 0 }
        return (CGFloat(settings.dockIconSize) * 0.909 * 1.1) + 8
    }

    private var shouldShowClipboardFloatingIcon: Bool {
        clipboardDropTargetVisible || (showGlobalClipboardPill && !globalClipboardText.isEmpty)
    }

    private var shouldShowFloatingAppLogo: Bool {
        !showMediaLayer
            && settings.showFloatingAppLogo
            && (settings.enableLayer2 || (aiMode.isActive && hasAIExtensionsToShow)
                || notificationManager.unreadCount > 0)
    }

    private var floatingAppLogoOccupiedWidth: CGFloat {
        shouldShowFloatingAppLogo ? 44 : 0
    }

    private var hasSecondaryDockContentBesideInput: Bool {
        if aiMode.isActive { return false }
        if searchState.activeSmartQueryKey == "clipboard" { return false }
        if usesVerticalListDockLayout { return false }
        if showMediaLayer || searchState.activeSmartQueryKey != nil { return true }
        if showContextInDock {
            if aiMode.isActive { return false }
            if isGlobalContextActive {
                return settings.showRunningAppsInBar || !settings.pinnedApps.isEmpty
                    || !searchState.query.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            }
            return hasAIExtensionsToShow || !searchState.query.isEmpty
        }
        return !searchState.query.isEmpty
    }

    private var usesVerticalListDockLayout: Bool {
        shouldShowSeparateActionList
    }

    /// Single source of truth for "is there meaningful selected content right now?"
    /// Uses >3 char threshold for text to filter cursor-position noise from Electron/Catalyst apps.
    /// Does NOT include frozenSelectionText — that is a captured label, not live content.
    var activeSelection: ActiveSelection? {
        // Files: shared resolver handles AX paths + currentContext + dismissal
        let files = effectiveFinderSelectionURLsForPills()
        if !files.isEmpty { return .files(files) }
        // AX text (>3 chars filters cursor-position events)
        let axText = (axContext.selectedText ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        if axText.count > 3 { return .text(axText) }
        // Resolved context (Share Sheet, Services, or explicit set)
        switch currentContext {
        case .textSelected(let t):
            let trimmed = t.trimmingCharacters(in: .whitespacesAndNewlines)
            if trimmed.count > 3 { return .text(trimmed) }
        case .url(let u):
            let trimmed = u.trimmingCharacters(in: .whitespacesAndNewlines)
            if !trimmed.isEmpty { return .url(trimmed) }
        default: break
        }
        return nil
    }

    var hasActiveDockContextSelection: Bool {
        // frozenSelectionText covers the "chip visible after focus moved to dock" case
        activeSelection != nil || frozenSelectionText != nil
    }

    private var shouldUsePureGlobalAppSearch: Bool {
        isGlobalContextActive
            && !hasActiveDockContextSelection
            && l2.targetApp == nil
            && searchState.activeSmartQueryKey == nil
            && searchState.contextApp == nil
            && lockedSubmenuParent == nil
            && !aiMode.isActive
            && !showMediaLayer
    }

    private var shouldShowSeparateActionList: Bool {
        guard showContextInDock,
              !showMediaLayer,
              !aiMode.isActive,
              searchState.activeSmartQueryKey != "clipboard",
              shouldShowL2UnifiedDockRow
        else { return false }

        let q = searchState.query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        if shouldUsePureGlobalAppSearch {
            return !q.isEmpty
        }
        let finderSearchPopoverActive = shouldUseFinderSearchPopover(for: q)
        let pillQuery = finderSearchPopoverActive ? "" : q
        let pills = currentVisibleDockPills(for: pillQuery)
        let hasActiveContextSelection = hasActiveDockContextSelection

        let showPinnedRow = q.isEmpty
            && l2.targetApp == nil
            && (pills.isEmpty || (isGlobalContextActive && !hasActiveContextSelection))
        let showGlobalAppSearch = shouldUsePureGlobalAppSearch && !q.isEmpty
        let hasListContent =
            pills.contains(where: { !$0.isSeparator })
            || showGlobalAppSearch
            || pendingDockPillQuery == pillQuery
            || (!q.isEmpty && lastPillQuery != pillQuery)
        return hasListContent && !showPinnedRow
    }

    private func currentCachedDockPills(for query: String) -> [DockPill] {
        if lastPillQuery == query { return cachedDockPills }
        return []
    }

    private func selectionScopedDockPills(_ pills: [DockPill]) -> [DockPill] {
        guard isGlobalContextActive, hasActiveDockContextSelection else { return pills }
        return pills.filter { pill in
            guard !pill.isSeparator else { return false }
            let badge = (pill.badge ?? "").trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
            let kind = pill.rankingKind.lowercased()
            let name = pill.name.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
            if kind == "applaunch" { return false }
            if !isGlobalContextActive,
               (badge == "recent items" || kind.contains("recent") || name.hasSuffix(".app")) {
                return false
            }
            return true
        }
    }

    private func currentVisibleDockPills(for query: String) -> [DockPill] {
        selectionScopedDockPills(currentCachedDockPills(for: query))
    }

    private func cachedMenuItemsForApp(_ app: NSRunningApplication, maxResults: Int = 120) -> [AXMenuItem] {
        let pid = app.processIdentifier
        let name = app.localizedName ?? ""
        var items = AppMenuCapabilityCache.shared.menuItems(for: app, maxResults: maxResults)
        for index in items.indices {
            items[index].sourcePID = pid
            items[index].sourceAppName = name
        }
        return items
    }

    private func menuItemWithSourceFallback(_ item: AXMenuItem, pid: pid_t, appName: String) -> AXMenuItem {
        var copy = item
        if copy.sourcePID == 0 { copy.sourcePID = pid }
        if copy.sourceAppName.isEmpty { copy.sourceAppName = appName }
        copy.children = copy.children.map {
            menuItemWithSourceFallback($0, pid: pid, appName: appName)
        }
        return copy
    }

    private func lockSubmenuParentForNavigation(_ item: AXMenuItem) {
        let fallbackPID = item.sourcePID != 0
            ? item.sourcePID
            : (AppDelegate.shared?.previousFrontmostApp?.processIdentifier ?? 0)
        let fallbackName = item.sourceAppName.isEmpty ? frontmost.name : item.sourceAppName
        withAnimation(.spring(response: 0.22, dampingFraction: 0.8)) {
            lockedSubmenuParent = menuItemWithSourceFallback(
                item,
                pid: fallbackPID,
                appName: fallbackName
            )
            searchState.query = ""
            l2.focusedPillIndex = nil
            l2.pillNavViaKeyboard = false
            listViewHoveredIndex = nil
        }
        l2.appCompletion = nil
        l2.showResultsPopover = false
        cachedDockPills = []
    }

    private func makeMenuDockPill(
        id: String,
        item: AXMenuItem,
        sourceBundleId: String,
        sourceAppName: String,
        accentColorName: String = "gray",
        badge: String?,
        trackingIdentifier: String,
        searchTerms: [String],
        executeLeaf: @escaping () -> Void
    ) -> DockPill {
        let isSubmenuParent = !item.children.isEmpty
        var pill = DockPill(
            id: id,
            name: item.title,
            icon: isSubmenuParent ? "chevron.right.circle" : menuSymbol(for: item),
            accentColorName: isSubmenuParent ? "blue" : accentColorName,
            badge: isSubmenuParent ? (badge ?? "Submenu") : badge,
            execute: {
                if isSubmenuParent {
                    lockSubmenuParentForNavigation(item)
                } else {
                    executeLeaf()
                }
            }
        )
        pill.menuItemImage = isSubmenuParent ? nil : resolvedMenuIcon(for: item)
        pill.menuItemName = item.title
        pill.sourceBundleId = sourceBundleId
        pill.sourceAppName = sourceAppName
        pill.menuContext = menuContextLabel(from: item.path)
        pill.rankingKind = isSubmenuParent ? "submenuParent" : "menu"
        pill.isEnabled = isSubmenuParent ? true : item.isEnabled
        pill.trackingIdentifier = trackingIdentifier
        pill.searchTerms = searchTerms + item.children.map(\.title)
        return pill
    }

    private func hasFrontmostMenuPillsInCurrentCache(for query: String) -> Bool {
        guard isGlobalContextActive, !hasActiveDockContextSelection else { return false }
        let q = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard !q.isEmpty else { return false }
        guard !resolveDockScope(for: q).isExplicitAppScope else { return false }
        return !cachedFrontmostGlobalMenuPills(query: q, maxResults: 1).isEmpty
    }

    private func dedupeDockPillsByTrackingIdentifier(_ pills: [DockPill]) -> [DockPill] {
        var seen = Set<String>()
        var output: [DockPill] = []
        for pill in pills {
            let key =
                !pill.trackingIdentifier.isEmpty
                ? pill.trackingIdentifier
                : "\(pill.sourceBundleId):\(pill.rankingKind):\(normalizedDockPillText(pill.name))"
            guard seen.insert(key).inserted else { continue }
            output.append(pill)
        }
        return output
    }

    private var searchInputVisualWidth: CGFloat {
        let dockHorizontalPadding: CGFloat = 24
        let interItemSpacing: CGFloat = 12
        let usable = max(visibleDockWidth - dockHorizontalPadding, 44)
        guard hasSecondaryDockContentBesideInput else { return usable }
        return max(44, (usable - interItemSpacing) / 2)
    }

    private var contextDockRunningOnlyAppMatching: Bool {
        false
    }

    private var contextDockInstalledAppScopeMatching: Bool {
        false
    }

    private var maxListViewDockPills: Int {
        28
    }

    private func currentGlobalAppMatches(for query: String) -> [SearchResult] {
        let q = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard !q.isEmpty else { return [] }
        guard cachedGlobalAppQuery == q else { return [] }
        return cachedGlobalAppMatches
    }

    private func isGenericApplicationListQuery(_ query: String) -> Bool {
        switch normalizedDockPillText(query) {
        case "app", "apps", "application", "applications":
            return true
        default:
            return false
        }
    }

    private func bundleIdentifier(forApplicationResult result: SearchResult) -> String? {
        if let path = result.filePath, !path.isEmpty {
            return Bundle(url: URL(fileURLWithPath: path))?.bundleIdentifier
        }
        let subtitle = result.subtitle.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !subtitle.isEmpty else { return nil }
        return Bundle(url: URL(fileURLWithPath: subtitle))?.bundleIdentifier
    }

    private func rankedTextMatchScore(
        query: String,
        primary: String,
        aliases: [String] = [],
        contexts: [String] = []
    ) -> Double? {
        let q = normalizedDockPillText(query)
        guard !q.isEmpty else { return nil }

        let primaryText = normalizedDockPillText(primary)
        let aliasTexts = aliases.map(normalizedDockPillText).filter { !$0.isEmpty && $0 != primaryText }
        let contextTexts = contexts.map(normalizedDockPillText).filter { !$0.isEmpty }
        let queryTokens = q.split(separator: " ").map(String.init)

        func wordPrefixScore(_ text: String, base: Double) -> Double? {
            let words = text.split(separator: " ").map(String.init)
            guard let idx = words.firstIndex(where: { $0.hasPrefix(q) }) else { return nil }
            return base - Double(idx * 34) - min(Double(text.count), 42)
        }

        var best: Double?
        func keep(_ score: Double?) {
            guard let score else { return }
            best = max(best ?? -Double.infinity, score)
        }

        if primaryText == q { keep(12_000) }
        if aliasTexts.contains(q) { keep(10_600) }
        if primaryText.hasPrefix(q) { keep(9_600 + Double(q.count * 20) - min(Double(primaryText.count), 48)) }
        keep(wordPrefixScore(primaryText, base: 8_900 + Double(q.count * 12)))

        for alias in aliasTexts {
            if alias.hasPrefix(q) { keep(8_250 + Double(q.count * 14) - min(Double(alias.count), 48)) }
            keep(wordPrefixScore(alias, base: 7_700 + Double(q.count * 10)))
        }

        for context in contextTexts {
            if context == q { keep(6_800) }
            if context.hasPrefix(q) { keep(6_100 - min(Double(context.count), 48)) }
            keep(wordPrefixScore(context, base: 5_700))
        }

        if q.count >= 2 {
            if let range = primaryText.range(of: q) {
                let offset = primaryText.distance(from: primaryText.startIndex, to: range.lowerBound)
                keep(4_900 - Double(offset * 72) - min(Double(primaryText.count), 48))
            }
            for alias in aliasTexts {
                if let range = alias.range(of: q) {
                    let offset = alias.distance(from: alias.startIndex, to: range.lowerBound)
                    keep(4_250 - Double(offset * 58) - min(Double(alias.count), 48))
                }
            }
            for context in contextTexts where context.contains(q) {
                keep(3_400 - min(Double(context.count), 48))
            }
        }

        if queryTokens.count > 1 {
            let primaryTokens = Set(dockPillTokens(primaryText))
            let aliasTokens = Set(aliasTexts.flatMap(dockPillTokens))
            let contextTokens = Set(contextTexts.flatMap(dockPillTokens))
            let qSet = Set(queryTokens)
            keep(Double(qSet.intersection(primaryTokens).count) * 820)
            keep(Double(qSet.intersection(aliasTokens).count) * 680)
            keep(Double(qSet.intersection(contextTokens).count) * 420)
        }

        return best
    }

    private func appSearchMatchScore(
        query: String,
        appName: String,
        bundleIdentifier: String?
    ) -> Double? {
        let q = normalizedDockPillText(query)
        guard !q.isEmpty else { return nil }

        let aliases = dockPillAppAliases(appName: appName, bundleId: bundleIdentifier ?? "")
        guard var score = rankedTextMatchScore(query: q, primary: appName, aliases: aliases) else { return nil }
        if bundleIdentifier == "com.apple.Photos", q == "photos" {
            score += 2_000
        }
        score += min(UsageTracker.shared.getScore(for: "app:\(bundleIdentifier ?? appName)") / 100.0, 45)
        return score
    }

    private func pureGlobalAppMenuFallbackScope(
        for query: String,
        appMatches: [SearchResult]? = nil
    ) -> DockScopeResolution? {
        guard shouldUsePureGlobalAppSearch else { return nil }
        let q = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard q.split(separator: " ").count >= 2 else { return nil }
        guard (appMatches ?? currentGlobalAppMatches(for: q)).isEmpty else { return nil }

        let scope = resolveDockScope(for: q)
        let actionQuery = scope.scopedSearchQuery.trimmingCharacters(in: .whitespacesAndNewlines)
        guard scope.isExplicitAppScope, !actionQuery.isEmpty else { return nil }
        return scope
    }

    private func focusedDockPillForInputPreview() -> DockPill? {
        guard usesVerticalListDockLayout,
              let idx = l2.focusedPillIndex
        else { return nil }

        if shouldUsePureGlobalAppSearch {
            let q = searchState.query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
            let state = globalGroupedListNavigationState(for: q)
            let menuIndex = idx - state.appResults.count
            guard menuIndex >= 0,
                  menuIndex < state.menuPills.count,
                  !state.menuPills[menuIndex].isSeparator
            else { return nil }
            return state.menuPills[menuIndex]
        }

        let q =
            isL2ContextActive
            ? searchState.query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
            : ""
        let pillQuery = shouldUseFinderSearchPopover(for: q) ? "" : q
        let pills = currentVisibleDockPills(for: pillQuery)
        guard idx >= 0, idx < pills.count, !pills[idx].isSeparator else { return nil }
        return pills[idx]
    }

    private func focusedGlobalAppResultForInputPreview() -> SearchResult? {
        guard usesVerticalListDockLayout,
              isGlobalContextActive,
              shouldUsePureGlobalAppSearch,
              let idx = focusedAppPillIndex
        else { return nil }

        let q = searchState.query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        let state = globalGroupedListNavigationState(for: q)
        guard idx >= 0, idx < state.appResults.count else { return nil }
        return state.appResults[idx]
    }

    private func topGlobalAppResultForInputPreview() -> SearchResult? {
        guard shouldUsePureGlobalAppSearch else { return nil }
        let q = searchState.query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard !q.isEmpty else { return nil }
        return globalGroupedListNavigationState(for: q).appResults.first
    }

    private func moveGlobalAppResultFocus(direction: Int) -> Bool {
        let q = searchState.query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        let matches = currentGlobalAppMatches(for: q)
        guard !matches.isEmpty else {
            focusedAppPillIndex = nil
            l2.pillNavViaKeyboard = false
            return false
        }

        if direction > 0 {
            let next = min((focusedAppPillIndex ?? -1) + 1, matches.count - 1)
            focusedAppPillIndex = next
            l2.pillNavViaKeyboard = true
            return true
        }

        if direction < 0 {
            guard let current = focusedAppPillIndex else {
                focusedAppPillIndex = matches.count - 1
                l2.pillNavViaKeyboard = true
                return true
            }
            if current <= 0 {
                focusedAppPillIndex = nil
                l2.pillNavViaKeyboard = false
                DispatchQueue.main.async { self.reclaimSearchInputFocus() }
                return true
            }
            focusedAppPillIndex = current - 1
            l2.pillNavViaKeyboard = true
            return true
        }

        return true
    }

    private struct MenuPillGroup: Identifiable {
        let id: String           // normalized title key
        let primaryPill: DockPill
        let allPills: [DockPill] // allPills[0] == primaryPill
        var isGrouped: Bool { allPills.count > 1 }
    }

    /// Cross-app menus from a single source app — used in global context app-grouped display.
    private struct AppMenuGroup: Identifiable {
        let id: String       // bundleId
        let appName: String
        let icon: NSImage?
        let pills: [DockPill]
    }

    /// Lightweight descriptor for a cross-app menu pill computed off the main thread.
    /// No closures, no @State — safe for Task.detached. Converted to DockPill on MainActor.
    private struct CrossAppPillDescriptor {
        let id: String
        let name: String
        let badge: String?
        let bundleID: String
        let appName: String
        let appIcon: NSImage?
        let path: [String]
        let shortcutChar: String?
        let shortcutModifiers: Int
    }

    private struct GlobalGroupedListNavigationState {
        var appResults: [SearchResult]
        var menuPills: [DockPill]           // flat — frontmost + cross-app pills for keyboard nav
        var menuGroups: [MenuPillGroup]     // frontmost app menus grouped by title, for visual render
        var appMenuGroups: [AppMenuGroup]   // cross-app menus grouped by source app
        var menuFirst: Bool = false

        var totalCount: Int { appResults.count + menuPills.count }

        init(
            appResults: [SearchResult],
            menuPills: [DockPill],
            menuGroups: [MenuPillGroup]? = nil,
            appMenuGroups: [AppMenuGroup] = [],
            menuFirst: Bool = false
        ) {
            self.appResults = appResults
            self.menuPills = menuPills
            self.menuGroups = menuGroups ?? menuPills.map {
                MenuPillGroup(id: $0.name.lowercased(), primaryPill: $0, allPills: [$0])
            }
            self.appMenuGroups = appMenuGroups
            self.menuFirst = menuFirst
        }
    }

    /// Three-layer intent signal: learned picks → verb heuristic → on-device AI cache.
    private func intentFavorsMenu(_ q: String) -> Bool {
        guard !q.isEmpty else { return false }

        // Layer 1: user's own pick history — strongest signal, overrides everything
        if let pref = AppUsageLearner.shared.intentPreference(for: q) {
            return pref > 0
        }

        // Layer 2: static heuristics (cold start)
        if q.contains(" ") { return true }
        let actionVerbs: Set<String> = [
            "close", "quit", "save", "undo", "redo", "copy", "paste", "cut",
            "find", "select", "zoom", "hide", "minimize", "print", "export",
            "import", "share", "delete", "duplicate", "rename", "refresh",
            "reload", "bookmark", "history", "preferences", "settings",
            "help", "fullscreen", "revert", "lock", "sleep", "restart",
            "shutdown", "eject", "connect", "disconnect", "inspect"
        ]
        if actionVerbs.contains(q) { return true }
        if q.count >= 4, actionVerbs.contains(where: { $0.hasPrefix(q) }) { return true }

        // Layer 3: on-device AI cache — async result from previous keystroke
        if let aiPref = QueryIntentCache.shared.cachedIntent(for: q) {
            return aiPref
        }
        // Trigger classification for next keystroke (fire-and-forget)
        QueryIntentCache.shared.classify(q)
        return false
    }

    private func emptyGlobalGroupedListNavigationState() -> GlobalGroupedListNavigationState {
        GlobalGroupedListNavigationState(appResults: [], menuPills: [])
    }

    private func globalGroupedListNavigationState(for query: String) -> GlobalGroupedListNavigationState {
        let q = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard !q.isEmpty || globalInlineAppScope != nil else {
            return emptyGlobalGroupedListNavigationState()
        }
        if cachedGlobalGroupedQuery == q, let state = cachedGlobalGroupedState {
            return state
        }
        return emptyGlobalGroupedListNavigationState()
    }

    private func scheduleGlobalGroupedListRebuild(query: String, delayNanoseconds: UInt64 = 18_000_000) {
        let q = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        globalGroupedTask?.cancel()
        guard !q.isEmpty || globalInlineAppScope != nil else {
            cachedGlobalGroupedQuery = ""
            cachedGlobalGroupedState = nil
            pendingGlobalGroupedQuery = nil
            return
        }

        pendingGlobalGroupedQuery = q
        globalGroupedTask = Task { @MainActor in
            if delayNanoseconds > 0 {
                try? await Task.sleep(nanoseconds: delayNanoseconds)
            }
            guard !Task.isCancelled else {
                if pendingGlobalGroupedQuery == q { pendingGlobalGroupedQuery = nil }
                return
            }

            // ── Phase 1: snapshot @State + compute @State-dependent parts on MainActor ──
            // (fast — all reads from in-memory caches or simple property lookups)
            guard shouldUsePureGlobalAppSearch, !q.isEmpty || globalInlineAppScope != nil else {
                cachedGlobalGroupedQuery = q
                cachedGlobalGroupedState = emptyGlobalGroupedListNavigationState()
                if pendingGlobalGroupedQuery == q { pendingGlobalGroupedQuery = nil }
                globalGroupedTask = nil
                return
            }

            // "notes n" pattern: query implies direct app scope with a non-empty action query.
            // Build synchronously and skip the async cross-app scan — it would overwrite
            // the correct scoped result with unrelated cross-app menus.
            if globalInlineAppScope == nil,
               let target = installedAppMenuTarget(
                   for: q, runningOnly: false,
                   includeAppsWithoutMenuSnapshot: true, allowPrefixAlias: true),
               !target.actionQuery.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                let state = buildGlobalGroupedListNavigationState(for: q)
                cachedGlobalGroupedQuery = q
                cachedGlobalGroupedState = state
                if pendingGlobalGroupedQuery == q { pendingGlobalGroupedQuery = nil }
                globalGroupedTask = nil
                return
            }

            let isGenericAppQuery = isGenericApplicationListQuery(q)
            let inlineScope = activeGlobalInlineDockScope(for: q)
            let rawAppMatches = inlineScope?.isExplicitAppScope == true ? [] : currentGlobalAppMatches(for: q)
            let favorMenu = intentFavorsMenu(q)
            let frontmostSnap = (bundleID: frontmost.bundleID, name: frontmost.name, icon: frontmost.icon)
            let maxPills = maxListViewDockPills

            // Frontmost / inline-scope menu pills — global context uses live AX snapshot,
            // so Apple Menu items stay session-scoped instead of coming from disk cache.
            let frontmostMenuPills: [DockPill] = {
                if let scope = inlineScope, scope.isExplicitAppScope {
                    return cachedGlobalAppScopeDockPills(query: q, scope: scope)
                }
                guard !isGenericAppQuery else { return [] }
                return cachedFrontmostGlobalMenuPills(query: q, maxResults: maxPills)
            }()

            // Snapshot sorted running apps on MainActor (AppUsageLearner not thread-safe).
            // AppMenuCapabilityCache reads happen off-thread below.
            let ownBundleId = Bundle.main.bundleIdentifier ?? ""
            let snappedRunningApps: [(bundleID: String, name: String, icon: NSImage?, pid: pid_t)] = {
                guard !isGenericAppQuery,
                      settings.enableLearnedGhostSuggestions,
                      isGlobalContextActive,
                      !hasActiveDockContextSelection,
                      globalInlineAppScope == nil
                else { return [] }
                return NSWorkspace.shared.runningApplications
                    .filter { app in
                        guard let bid = app.bundleIdentifier else { return false }
                        return app.activationPolicy == .regular
                            && !app.isTerminated
                            && bid != frontmostSnap.bundleID
                            && bid != ownBundleId
                            && AppMenuCapabilityCache.shared.hasSnapshot(bundleIdentifier: bid)
                    }
                    .sorted {
                        AppUsageLearner.shared.score(forBundleID: $0.bundleIdentifier ?? "") >
                        AppUsageLearner.shared.score(forBundleID: $1.bundleIdentifier ?? "")
                    }
                    .map { ($0.bundleIdentifier!, $0.localizedName ?? "", $0.icon, $0.processIdentifier) }
            }()

            guard !Task.isCancelled else { return }

            // ── Phase 2: cross-app cache reads off MainActor ─────────────────────────
            // AppMenuCapabilityCache uses NSLock — thread-safe for concurrent reads.
            // DockPill closures cannot be created here (capture self); use descriptors instead.
            let perAppCap = q.count == 1 ? 3 : (q.count == 2 ? 4 : 6)
            let crossDescriptors: [[CrossAppPillDescriptor]] = await Task.detached(priority: .userInitiated) {
                var result: [[CrossAppPillDescriptor]] = []
                var total = 0
                for app in snappedRunningApps {
                    guard total < maxPills else { break }
                    let remaining = min(perAppCap, maxPills - total)
                    let rawItems = AppMenuCapabilityCache.shared.menuItems(
                        bundleIdentifier: app.bundleID,
                        appName: app.name,
                        processIdentifier: app.pid,
                        query: q,
                        maxResults: remaining
                    )
                    var appDescs: [CrossAppPillDescriptor] = []
                    for item in rawItems {
                        let nameLower = item.title.lowercased()
                        guard nameLower.hasPrefix(q) || nameLower.contains(q),
                              item.title.count >= q.count else { continue }
                        appDescs.append(CrossAppPillDescriptor(
                            id: "xapp-\(app.bundleID)-\(item.title)",
                            name: item.title,
                            badge: item.shortcutDisplay,
                            bundleID: app.bundleID,
                            appName: app.name,
                            appIcon: app.icon,
                            path: item.path,
                            shortcutChar: item.shortcutChar,
                            shortcutModifiers: item.shortcutModifiers
                        ))
                    }
                    guard !appDescs.isEmpty else { continue }
                    result.append(appDescs)
                    total += appDescs.count
                }
                return result
            }.value

            guard !Task.isCancelled else { return }

            // ── Phase 3: convert descriptors → DockPills + build final state on MainActor ─
            let crossAppGroups: [AppMenuGroup] = zip(snappedRunningApps, crossDescriptors)
                .compactMap { (app, descs) -> AppMenuGroup? in
                    guard !descs.isEmpty else { return nil }
                    let pills: [DockPill] = descs.map { d in
                        let bid = d.bundleID, path = d.path, sc = d.shortcutChar, mod = d.shortcutModifiers
                        var pill = DockPill(
                            id: d.id, name: d.name,
                            icon: "menubar.rectangle", accentColorName: nil,
                            badge: d.badge,
                            execute: { [self] in
                                executeLearnedGhostAction(
                                    bundleID: bid, path: path,
                                    shortcutChar: sc, shortcutModifiers: mod)
                            }
                        )
                        pill.sourceBundleId = bid
                        pill.sourceAppName = d.appName
                        pill.rankingKind = "menu"
                        return pill
                    }
                    return AppMenuGroup(id: app.bundleID, appName: app.name, icon: app.icon, pills: pills)
                }

            let frontmostMenuGroups: [AppMenuGroup] = {
                guard !frontmostMenuPills.isEmpty, inlineScope?.isExplicitAppScope != true else { return [] }
                return [AppMenuGroup(
                    id: frontmostSnap.bundleID,
                    appName: frontmostSnap.name,
                    icon: frontmostSnap.icon,
                    pills: frontmostMenuPills
                )]
            }()

            let groupedRunningMenuApps = frontmostMenuGroups + crossAppGroups
            let totalMenuCount = groupedRunningMenuApps.flatMap(\.pills).count
            let appLimit = totalMenuCount == 0
                ? maxPills
                : min(rawAppMatches.count, max(8, maxPills - min(totalMenuCount, 12)))
            let limitedAppResults = Array(rawAppMatches.prefix(appLimit))
            let appResults =
                limitedAppResults.filter { runningApplication(forGlobalResult: $0) != nil }
                + limitedAppResults.filter { runningApplication(forGlobalResult: $0) == nil }

            let maxFrontmost = appResults.isEmpty ? maxPills : max(0, maxPills - appResults.count)
            let cappedFrontmost = Array(frontmostMenuPills.prefix(maxFrontmost))
            let menuGroups = groupMenuPillsByTitle(cappedFrontmost)
            let groupedMenuPills = groupedRunningMenuApps.flatMap(\.pills)
            let menuPills = groupedMenuPills.isEmpty ? menuGroups.map(\.primaryPill) : groupedMenuPills

            let state = GlobalGroupedListNavigationState(
                appResults: appResults,
                menuPills: menuPills,
                menuGroups: groupedRunningMenuApps.isEmpty ? menuGroups : [],
                appMenuGroups: groupedRunningMenuApps,
                menuFirst: favorMenu && !menuPills.isEmpty
            )

            guard !Task.isCancelled else { return }
            cachedGlobalGroupedQuery = q
            cachedGlobalGroupedState = state
            if pendingGlobalGroupedQuery == q { pendingGlobalGroupedQuery = nil }
            globalGroupedTask = nil
        }
    }

    private func buildGlobalGroupedListNavigationState(for query: String) -> GlobalGroupedListNavigationState {
        let q = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard shouldUsePureGlobalAppSearch, !q.isEmpty || globalInlineAppScope != nil else {
            return emptyGlobalGroupedListNavigationState()
        }

        if globalInlineAppScope == nil,
           let target = installedAppMenuTarget(
                for: q,
                runningOnly: false,
                includeAppsWithoutMenuSnapshot: true,
                allowPrefixAlias: true
           ),
           !target.actionQuery.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            let pills = cachedScopedAppMenuPills(
                bundleIdentifier: target.bundleId,
                appName: target.appName,
                appPath: target.appPath,
                query: target.actionQuery,
                maxResults: maxListViewDockPills,
                allowLiveRefresh: false
            )
            let icon: NSImage? = {
                if !target.appPath.isEmpty, FileManager.default.fileExists(atPath: target.appPath) {
                    return NSWorkspace.shared.icon(forFile: target.appPath)
                }
                return resolvedApplicationIcon(bundleIdentifier: target.bundleId, appName: target.appName)
            }()
            let group = AppMenuGroup(
                id: target.bundleId,
                appName: target.appName,
                icon: icon,
                pills: pills
            )
            return GlobalGroupedListNavigationState(
                appResults: [],
                menuPills: pills,
                menuGroups: [],
                appMenuGroups: pills.isEmpty ? [] : [group],
                menuFirst: true
            )
        }

        let rawAppMatches: [SearchResult] = {
            let scope = activeGlobalInlineDockScope(for: q)
            return scope?.isExplicitAppScope == true ? [] : currentGlobalAppMatches(for: q)
        }()

        let isGenericAppQuery = isGenericApplicationListQuery(q)
        // Frontmost app menus — cache-only so global typing never touches AX.
        let frontmostMenuPills: [DockPill] = {
            if let scope = activeGlobalInlineDockScope(for: q), scope.isExplicitAppScope {
                return cachedGlobalAppScopeDockPills(query: q, scope: scope)
            }
            guard !isGenericAppQuery else { return [] }
            return cachedFrontmostGlobalMenuPills(query: q, maxResults: maxListViewDockPills)
        }()

        // Cross-app menus grouped by source app — always shown alongside app results
        // so users can see matching actions from every running app (not just the frontmost).
        let crossAppGroups: [AppMenuGroup] = {
            guard !isGenericAppQuery else { return [] }
            return crossAppMenuGroups(for: q)
        }()

        let frontmostMenuGroups: [AppMenuGroup] = {
            let app = NSWorkspace.shared.runningApplications.first {
                $0.bundleIdentifier == frontmost.bundleID && !$0.isTerminated
            }
            guard let bundleID = app?.bundleIdentifier,
                  !frontmostMenuPills.isEmpty,
                  activeGlobalInlineDockScope(for: q)?.isExplicitAppScope != true
            else { return [] }
            return [AppMenuGroup(
                id: bundleID,
                appName: app?.localizedName ?? frontmost.name,
                icon: app?.icon ?? frontmost.icon,
                pills: frontmostMenuPills
            )]
        }()
        let groupedRunningMenuApps = frontmostMenuGroups + crossAppGroups
        let totalMenuCount = groupedRunningMenuApps.flatMap(\.pills).count
        let appLimit = totalMenuCount == 0
            ? maxListViewDockPills
            : min(rawAppMatches.count, max(8, maxListViewDockPills - min(totalMenuCount, 12)))
        let limitedAppResults = Array(rawAppMatches.prefix(appLimit))
        let appResults =
            limitedAppResults.filter { runningApplication(forGlobalResult: $0) != nil }
            + limitedAppResults.filter { runningApplication(forGlobalResult: $0) == nil }

        let maxFrontmost = appResults.isEmpty ? maxListViewDockPills : max(0, maxListViewDockPills - appResults.count)
        let cappedFrontmost = Array(frontmostMenuPills.prefix(maxFrontmost))
        let menuGroups = groupMenuPillsByTitle(cappedFrontmost)
        let groupedMenuPills = groupedRunningMenuApps.flatMap(\.pills)
        let menuPills = groupedMenuPills.isEmpty ? menuGroups.map(\.primaryPill) : groupedMenuPills

        return GlobalGroupedListNavigationState(
            appResults: appResults,
            menuPills: menuPills,
            menuGroups: groupedRunningMenuApps.isEmpty ? menuGroups : [],
            appMenuGroups: groupedRunningMenuApps,
            menuFirst: intentFavorsMenu(q) && !menuPills.isEmpty
        )
    }

    private func groupMenuPillsByTitle(_ pills: [DockPill]) -> [MenuPillGroup] {
        var seen: [String: Int] = [:]
        var groups: [MenuPillGroup] = []
        for pill in pills {
            let key = normalizedDockPillText(pill.name)
            if let idx = seen[key] {
                let g = groups[idx]
                groups[idx] = MenuPillGroup(id: g.id, primaryPill: g.primaryPill, allPills: g.allPills + [pill])
            } else {
                seen[key] = groups.count
                groups.append(MenuPillGroup(id: key, primaryPill: pill, allPills: [pill]))
            }
        }
        return groups
    }

    private func currentGlobalGroupedFocusIndex(
        state: GlobalGroupedListNavigationState
    ) -> Int? {
        if let idx = focusedAppPillIndex, idx >= 0, idx < state.appResults.count {
            return idx
        }
        if let idx = l2.focusedPillIndex,
           idx >= state.appResults.count,
           idx < state.totalCount {
            return idx
        }
        return nil
    }

    private func setGlobalGroupedFocus(
        _ index: Int?,
        state: GlobalGroupedListNavigationState
    ) {
        guard let index, index >= 0, index < state.totalCount else {
            focusedAppPillIndex = nil
            l2.focusedPillIndex = nil
            l2.pillNavViaKeyboard = false
            DispatchQueue.main.async { self.reclaimSearchInputFocus() }
            return
        }

        l2.pillNavViaKeyboard = true
        if index < state.appResults.count {
            focusedAppPillIndex = index
            l2.focusedPillIndex = nil
        } else {
            focusedAppPillIndex = nil
            l2.focusedPillIndex = index
        }
    }

    private func moveGlobalGroupedListFocus(direction: Int) -> Bool {
        let q = searchState.query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        let state = globalGroupedListNavigationState(for: q)
        guard state.totalCount > 0 else {
            setGlobalGroupedFocus(nil, state: state)
            return false
        }

        if direction > 0 {
            let next = min((currentGlobalGroupedFocusIndex(state: state) ?? -1) + 1, state.totalCount - 1)
            setGlobalGroupedFocus(next, state: state)
            return true
        }

        if direction < 0 {
            guard let current = currentGlobalGroupedFocusIndex(state: state) else {
                setGlobalGroupedFocus(0, state: state)
                return true
            }
            if current <= 0 {
                setGlobalGroupedFocus(nil, state: state)
            } else {
                setGlobalGroupedFocus(current - 1, state: state)
            }
            return true
        }

        return true
    }

    private func executeFocusedGlobalGroupedListRow() -> Bool {
        let q = searchState.query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        let state = globalGroupedListNavigationState(for: q)
        guard state.totalCount > 0 else { return false }

        let index = currentGlobalGroupedFocusIndex(state: state) ?? 0
        if index < state.appResults.count {
            executeGlobalAppSearchResult(state.appResults[index])
            return true
        }

        let menuIndex = index - state.appResults.count
        guard menuIndex >= 0, menuIndex < state.menuPills.count else { return false }
        executeDockPill(state.menuPills[menuIndex])
        searchState.query = ""
        focusedAppPillIndex = nil
        l2.focusedPillIndex = nil
        l2.pillNavViaKeyboard = false
        return true
    }

    private func quitFocusedGlobalGroupedRunningApp() -> Bool {
        let q = searchState.query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        let state = globalGroupedListNavigationState(for: q)
        guard let index = currentGlobalGroupedFocusIndex(state: state),
              index >= 0,
              index < state.appResults.count
        else { return false }

        let result = state.appResults[index]
        guard let app = runningApplication(forGlobalResult: result) else { return false }
        terminateRunningAppFromDock(app)

        let nextCount = max(0, state.totalCount - 1)
        if nextCount == 0 {
            setGlobalGroupedFocus(nil, state: state)
        } else {
            setGlobalGroupedFocus(min(index, nextCount - 1), state: state)
        }
        return true
    }

    private func focusedOrTopGlobalAppResult() -> SearchResult? {
        let q = searchState.query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        let matches = currentGlobalAppMatches(for: q)
        guard !matches.isEmpty else { return nil }
        if let idx = focusedAppPillIndex, idx >= 0, idx < matches.count {
            return matches[idx]
        }
        return matches[0]
    }

    private func executeGlobalAppSearchResult(_ result: SearchResult) {
        AppLaunchTracker.shared.record(bundleId: result.title)
        result.action()
        searchState.query = ""
        focusedAppPillIndex = nil
        hoveredAppPillIndex = nil
        l2.pillNavViaKeyboard = false

        let bundleId = result.filePath.flatMap { Bundle(path: $0)?.bundleIdentifier }
        if let bid = bundleId {
            AppUsageLearner.shared.recordApp(bundleID: bid, appName: result.title)
        }
        scheduleContextDockTransition(bundleId: bundleId, appName: result.title)
    }

    private func reclaimSearchInputFocus() {
        l2.focusedPillIndex = nil
        focusedAppPillIndex = nil
        l2.pillNavViaKeyboard = false
        if let window = AppDelegate.shared?.launcherWindow {
            window.makeKeyAndOrderFront(nil)
        }

        if let textView = NSApp.keyWindow?.firstResponder as? NSTextView {
            moveSearchInsertionPointToEnd(in: textView)
            isSearchFieldFocused = true
            return
        }

        DispatchQueue.main.async {
            isSearchFieldFocused = true
            DispatchQueue.main.async {
                if let textView = NSApp.keyWindow?.firstResponder as? NSTextView {
                    moveSearchInsertionPointToEnd(in: textView)
                }
            }
        }
    }

    private func moveSearchInsertionPointToEnd(in textView: NSTextView) {
        let end = (textView.string as NSString).length
        textView.setSelectedRange(NSRange(location: end, length: 0))
    }

    private func scheduleGlobalAppMatchRebuild(query: String, delayNanoseconds: UInt64 = 18_000_000) {
        let q = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        globalAppMatchTask?.cancel()
        guard !q.isEmpty else {
            cachedGlobalAppQuery = ""
            cachedGlobalAppMatches = []
            pendingGlobalAppQuery = nil
            cachedGlobalGroupedQuery = ""
            cachedGlobalGroupedState = nil
            pendingGlobalGroupedQuery = nil
            globalGroupedTask?.cancel()
            return
        }

        pendingGlobalAppQuery = q
        globalAppMatchTask = Task.detached(priority: .userInitiated) {
            try? await Task.sleep(nanoseconds: delayNanoseconds)
            guard !Task.isCancelled else {
                await MainActor.run {
                    if self.pendingGlobalAppQuery == q { self.pendingGlobalAppQuery = nil }
                }
                return
            }
            let matches = globalApplicationMatches(for: q, limit: maxListViewDockPills)
            await MainActor.run {
                self.cachedGlobalAppMatches = matches
                self.cachedGlobalAppQuery = q
                if self.pendingGlobalAppQuery == q { self.pendingGlobalAppQuery = nil }
                self.globalAppMatchTask = nil
                self.scheduleGlobalGroupedListRebuild(query: q, delayNanoseconds: 0)
            }
        }
    }

    private func activeGlobalInlineDockScope(for query: String) -> DockScopeResolution? {
        guard shouldUsePureGlobalAppSearch,
              isGlobalContextActive,
              !hasActiveDockContextSelection,
              l2.targetApp == nil
        else { return nil }

        let actionQuery = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        if let inlineScope = globalInlineAppScope {
            return DockScopeResolution(
                scopedBundleId: inlineScope.bundleId,
                scopedAppName: inlineScope.appName,
                scopedSearchQuery: actionQuery,
                isExplicitAppScope: true,
                isGlobalScope: false
            )
        }

        return nil
    }

    @discardableResult
    private func applyGlobalInlineAppScopeIfNeeded(for rawQuery: String) -> Bool {
        guard shouldUsePureGlobalAppSearch,
              isGlobalContextActive,
              !hasActiveDockContextSelection,
              l2.targetApp == nil,
              lockedSubmenuParent == nil,
              globalInlineAppScope == nil
        else { return false }

        let raw = rawQuery.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !raw.isEmpty, !isGenericApplicationListQuery(raw.lowercased()) else { return false }
        guard let target = installedAppMenuTarget(
            for: raw,
            includeAppsWithoutMenuSnapshot: true,
            allowPrefixAlias: true
        ) else { return false }

        globalInlineAppScope = GlobalInlineAppScope(
            appName: target.appName,
            bundleId: target.bundleId,
            appPath: target.appPath,
            matchedAlias: target.matchedAlias
        )
        let actionQuery = target.actionQuery.trimmingCharacters(in: .whitespacesAndNewlines)
        if actionQuery != rawQuery {
            suppressGlobalInlineAppScopeDetection = true
            searchState.query = actionQuery
        } else {
            scheduleGlobalAppMatchRebuild(query: actionQuery, delayNanoseconds: 0)
            scheduleGlobalGroupedListRebuild(query: actionQuery, delayNanoseconds: 0)
        }
        warmMenuCacheIfNeeded(bundleId: target.bundleId, appName: target.appName)
        return true
    }

    private func clearGlobalInlineAppScope(preserveQuery: Bool = true) {
        globalInlineAppScope = nil
        suppressGlobalInlineAppScopeDetection = false
        focusedAppPillIndex = nil
        l2.focusedPillIndex = nil
        let q = preserveQuery ? searchState.query : ""
        if !preserveQuery {
            searchState.query = ""
        }
        scheduleGlobalAppMatchRebuild(query: q, delayNanoseconds: 0)
        scheduleGlobalGroupedListRebuild(query: q, delayNanoseconds: 0)
    }

    private func cachedGlobalAppScopeDockPills(
        query: String,
        scope: DockScopeResolution
    ) -> [DockPill] {
        guard scope.isExplicitAppScope else { return [] }
        let actionQuery = (scope.scopedSearchQuery.isEmpty ? query : scope.scopedSearchQuery)
            .trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        return cachedScopedAppMenuPills(
            bundleIdentifier: scope.scopedBundleId,
            appName: scope.scopedAppName,
            appPath: globalInlineAppScope?.appPath,
            query: actionQuery,
            maxResults: maxListViewDockPills,
            allowLiveRefresh: false
        )
            .filter { pill in
                guard !pill.isSeparator else { return false }
                guard pill.rankingKind != "appLaunch" else { return false }
                if !isGlobalContextActive,
                   (pill.menuContext ?? "").caseInsensitiveCompare("Apple Menu") == .orderedSame {
                    return false
                }
                guard !actionQuery.isEmpty else { return true }
                // Match name OR menu context path so e.g. "recent" surfaces "Recently Closed" tabs
                // whose pill name is the tab title, not the submenu label.
                let nameLower = pill.name.lowercased()
                let contextLower = (pill.menuContext ?? "").lowercased()
                return nameLower.contains(actionQuery) || contextLower.contains(actionQuery)
            }
    }

    private func cachedFrontmostGlobalMenuPills(query: String, maxResults: Int) -> [DockPill] {
        let bundleId = frontmost.bundleID.trimmingCharacters(in: .whitespacesAndNewlines)
        let appName = frontmost.name.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !bundleId.isEmpty, !appName.isEmpty else { return [] }
        let liveItems = orderedScopedMenuItemsLikeContextDock(
            liveMenuItems
                .filter { !$0.title.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }
                .filter { !($0.path.first?.isEmpty ?? true) }
                .filter { cachedScopedMenuItemMatchesQuery($0, query: query) },
            filterQuery: query,
            limit: maxResults
        )
        if !liveItems.isEmpty {
            let pid = contextTargetApp()?.processIdentifier ?? 0
            return liveItems.map { item in
                let path = item.path
                let shortcutChar = item.shortcutChar
                let shortcutModifiers = item.shortcutModifiers
                return makeMenuDockPill(
                    id: "global-live-menu-\(bundleId)-\(path.joined(separator: ">"))",
                    item: item,
                    sourceBundleId: bundleId,
                    sourceAppName: appName,
                    badge: item.shortcutDisplay,
                    trackingIdentifier: "global-live-menu:\(bundleId):\(path.joined(separator: " > ").lowercased())",
                    searchTerms: item.path + [appName],
                    executeLeaf: {
                        guard pid != 0 else { return }
                        executeDockMenuAction(
                            sourcePID: pid,
                            path: path,
                            shortcutChar: shortcutChar,
                            shortcutModifiers: shortcutModifiers
                        )
                    }
                )
            }
        }

        return cachedScopedAppMenuPills(
            bundleIdentifier: bundleId,
            appName: appName,
            appPath: nil,
            query: query,
            maxResults: maxResults,
            allowLiveRefresh: false
        )
    }

    // Max visible list height: rows beyond this scroll inside the glass card.
    private let listViewVisibleHeight: CGFloat = 372

    private var currentListViewDockRowCount: Int {
        guard showContextInDock,
              !showMediaLayer,
              !aiMode.isActive,
              shouldShowL2UnifiedDockRow
        else { return 0 }

        let q = searchState.query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        if shouldUsePureGlobalAppSearch {
            guard !q.isEmpty || globalInlineAppScope != nil else { return 0 }
            let state = globalGroupedListNavigationState(for: q)
            if state.totalCount > 0 {
                return min(maxListViewDockPills, state.totalCount)
            }
            if pendingGlobalGroupedQuery == q || pendingGlobalAppQuery == q {
                return 1
            }
            return 0
        }

        let pillQuery = shouldUseFinderSearchPopover(for: q) ? "" : q
        let pillCount = currentVisibleDockPills(for: pillQuery)
            .filter { !$0.isSeparator }
            .count
        if pillCount > 0 { return min(maxListViewDockPills, pillCount) }
        if pendingDockPillQuery == pillQuery || (!q.isEmpty && lastPillQuery != pillQuery) {
            return 1
        }
        return 0
    }

    private var currentListViewDockContentHeight: CGFloat {
        // Full fixed height once any rows exist — never varies with count.
        // Pill list scrolls within the container; window stays stable while typing.
        guard currentListViewDockRowCount > 0 else { return 0 }
        return listViewVisibleHeight
    }

    private var isExplicitAppScopeLocked: Bool {
        guard let target = l2.targetApp else { return false }
        guard !isGlobalContextActive else { return false }
        return target.bundleId != "scope://clipboard"
    }

    private func runningBundleIdsForContextDock() -> Set<String> {
        Set((runningRegularApps.isEmpty ? currentRegularRunningApps() : runningRegularApps).compactMap { $0.bundleIdentifier })
    }

    private var implicitContextDockAppScopeBlockedBundleIds: Set<String> {
        [
            "com.apple.news"
        ]
    }

    private func shouldIgnoreApplicationFromAppSearch(
        appName: String,
        bundleIdentifier: String?,
        path: String?
    ) -> Bool {
        let normalizedName = normalizedDockPillText(appName)
        if normalizedName == "news" { return true }
        if bundleIdentifier == "com.apple.news" { return true }
        if let path {
            let url = URL(fileURLWithPath: path)
            if Bundle(url: url)?.bundleIdentifier == "com.apple.news" { return true }
            if normalizedDockPillText(url.deletingPathExtension().lastPathComponent) == "news" {
                return true
            }
        }
        return false
    }

    private var resultsPanelLeadingInset: CGFloat {
        floatingClipboardOccupiedWidth + 12
    }

    private var resultsPanelWidth: CGFloat {
        max(visibleDockWidth - 24, 280)
    }

    private var calculatedDockHeight: CGFloat {
        // Fixed height anchors the NSVisualEffectView sampling surface vertically.
        // Computed from max dockIconSize (72): input row (92) + pill row (88) + gap (20) = 200.
        // The actual content is clipped by the mask — glass stays constant.
        let maxSz: CGFloat = 72
        let inputRow = maxSz + 8 + 12    // inputPillHeight + 2×inputVerticalPadding
        let pillRow  = maxSz + 4 + 12    // pinnedRowHeight  + 2×outerVerticalPadding
        return inputRow + pillRow + 20   // 200
    }

    private var listViewDockHeight: CGFloat {
        guard showContextInDock,
              !showMediaLayer,
              !aiMode.isActive,
              shouldShowL2UnifiedDockRow
        else { return 0 }

        let contentHeight = currentListViewDockContentHeight
        guard contentHeight > 0 else { return 0 }
        let dockChromeHeight = CGFloat(settings.dockIconSize) + 20
        return dockChromeHeight + contentHeight + 20
    }

    private var listViewResizeToken: String {
        // Only changes when L2 dock activates/deactivates — not per pill or result count.
        // Content scrolls within a fixed container; window never resizes during typing.
        usesVerticalListDockLayout ? "on" : "off"
    }

    private var contentWithModifiers: some View {
        mainContent
            .frame(width: calculatedWidth)
            // In dock mode anchor content to bottom so dock bar stays fixed while results grow upward.
            // In normal mode anchor to top so results grow downward.
            .frame(
                height: calculatedHeight, alignment: settings.effectiveDockAtBottom ? .bottom : .top
            )
            .background(
                backgroundView
                    .animation(.spring(response: 0.35, dampingFraction: 0.8), value: shouldShowBackground)
            )
            .opacity(isVisible ? 1.0 : 0.0)
            .animation(.spring(response: 0.3, dampingFraction: 0.7), value: isVisible)
            .onChange(of: searchState.results.isEmpty) { _, isEmpty in
                if isEmpty {
                    l1ResultsReservedHeight = 0
                }
                updateWindowSize()
            }
            .onChange(of: searchState.results.count) { _, newCount in
                guard !showContextInDock, !showMediaLayer, !aiMode.isActive else { return }
                let needed = min(CGFloat(newCount) * 50 + 16, 450)
                if needed > l1ResultsReservedHeight {
                    l1ResultsReservedHeight = needed
                    updateWindowSize()
                }
            }
            .onChange(of: listViewResizeToken) { _, _ in updateWindowSize() }
            .onChange(of: aiMode.messages.count) { _, _ in
                updateWindowSize()
            }
            .onChange(of: aiMode.isLoading) { _, _ in
                updateWindowSize()
            }
            .onChange(of: aiMode.streamingId) { _, _ in
                updateWindowSize()
            }
            .onChange(of: aiMode.isActive) { _, newValue in
                suppressHoverExpand = true
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.6) {
                    self.suppressHoverExpand = false
                }
                if newValue {
                    cancelBrowserContextWarmup()
                    menuLoadTask?.cancel()
                    liveMenuRefreshTask?.cancel()
                    liveMenuItems = []
                    crossAppMenuItems = []
                    contextMenuPills = []
                    cachedDockPills = []
                    l2.focusedPillIndex = nil
                    focusedAppPillIndex = nil
                    l2.appCompletion = nil
                } else {
                    scheduleBrowserContextWarmup(reason: "AI mode toggled")
                }
                // Delay resize so it runs after the animation starts (prevents background flash)
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.05) {
                    updateWindowSize()
                }
            }
            .onChange(of: frontmost.isSectionExpanded) { _, _ in updateWindowSize() }
            .onChange(of: isSearchBarExpanded) { _, _ in updateWindowSize() }
            .onChange(of: usesVerticalListDockLayout) { _, active in
                if active {
                    collapseTimer?.cancel()
                    isSearchBarExpanded = true
                    // reclaimSearchInputFocus() intentionally removed: it was only needed to
                    // recover focus after the old structural identity switch (dockBaseView ↔
                    // unifiedListDockCard). The NSTextField now always lives in the same view
                    // hierarchy, so calling it here would select-all the already-typed text.
                }
                updateWindowSize()
            }
            .onChange(of: l2.chatMessages.count) { _, _ in updateWindowSize() }
            .onChange(of: l2.isLoading) { _, _ in updateWindowSize() }
            .onChange(of: showContextInDock) { _, newValue in
                // Block expand during layer transition (icon swap fires phantom hover)
                suppressHoverExpand = true
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.6) {
                    self.suppressHoverExpand = false
                }
                if newValue {
                    guard !aiMode.isActive else {
                        liveMenuItems = []
                        crossAppMenuItems = []
                        contextMenuPills = []
                        cachedDockPills = []
                        return
                    }
                    let activeApp = contextTargetApp()
                    // Refresh AX context snapshot (URL, selection, window title, focused role)
                    if let app = activeApp {
                        AXContextReader.shared.refresh(from: app)
                        axContext = AXContextReader.shared.current
                    }
                    scheduleBrowserContextWarmup(reason: "context dock opened")
                    // Reload dock tool extensions so newly installed ones show immediately
                    Task { await L2ExtensionManager.shared.loadExtensions() }
                    updateL2ContextExtensions()
                    l2.focusedPillIndex = nil  // don't auto-focus; user must arrow-key to a pill

                    // Load live menu items from frontmost app only (primary context).
                    // Session-scoped only: Apple Menu items should come from live AX, not disk cache.
                    menuLoadTask?.cancel()
                    let useCacheOnly = false
                    menuLoadTask = Task.detached(priority: .userInitiated) {
                        let app = await MainActor.run { self.contextTargetApp() }
                        guard let app, !app.isTerminated else { return }
                        let pid = app.processIdentifier
                        let name = app.localizedName ?? ""
                        var loadedFromPersistentCache = false
                        var items: [AXMenuItem] = []
                        if useCacheOnly {
                            items = AppMenuCapabilityCache.shared.menuItems(for: app, maxResults: 120)
                            loadedFromPersistentCache = !items.isEmpty
                        } else {
                            items = AXMenuReader.shared.refreshAllMenuItems(for: pid, maxDepth: 6)
                            if items.isEmpty {
                                try? await Task.sleep(nanoseconds: 180_000_000)
                                items = AXMenuReader.shared.refreshAllMenuItems(for: pid, maxDepth: 6)
                            }
                            if items.isEmpty {
                                let snapshotItems = await MainActor.run {
                                    AXContextReader.shared.current.menuItems
                                }
                                items = snapshotItems.compactMap { info in
                                    let path = info.fullPath
                                        .components(separatedBy: " > ")
                                        .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
                                        .filter { !$0.isEmpty }
                                    guard let title = path.last, !title.isEmpty else { return nil }
                                    return AXMenuItem(
                                        title: title,
                                        path: path,
                                        isEnabled: info.enabled,
                                        element: AXUIElementCreateApplication(pid),
                                        children: [],
                                        sourcePID: pid,
                                        sourceAppName: name,
                                        isAppleMenu: path.first == "Apple",
                                        shortcutChar: nil,
                                        shortcutModifiers: 0
                                    )
                                }
                            }
                            if items.isEmpty {
                                items = AppMenuCapabilityCache.shared.menuItems(
                                    for: app,
                                    maxResults: 120
                                )
                                loadedFromPersistentCache = !items.isEmpty
                            }
                            if !loadedFromPersistentCache {
                                AppMenuCapabilityCache.shared.store(items: items, for: app)
                            }
                        }
                        let debug = AXMenuReader.shared.lastDebug(for: pid) ?? "no reader detail"
                        await MainActor.run {
                            self.liveMenuItems = items
                            self.menuDebugText = "\(name): \(items.count) menus, \(debug)"
                            self.lastLiveMenuSignature = self.menuSignature(for: items)
                            // Seed the enabled-ID baseline so first delta is meaningful
                            self.previousEnabledIDs = Set(items.filter(\.isEnabled).map(\.id))
                            // Sync recentApps from Apple menu "Recent Items > Applications"
                            // — more authoritative than activation-order tracking
                            self.syncRecentAppsFromAppleMenu(items)
                        }
                    }
                    // Auto-generate a synthetic adapter for unknown frontmost apps
                    if let app = activeApp {
                        Task { await adapterManager.autoGenerateAdapterIfNeeded(for: app) }
                    }

                    // Run contextReaders for the frontmost app's adapter (current file, git branch, etc.)
                    if let frontmostBundleId = activeApp?.bundleIdentifier
                    {
                        let capturedCtx = axContext
                        Task {
                            let data = await adapterManager.runContextReaders(
                                for: frontmostBundleId, axContext: capturedCtx)
                            await MainActor.run { adapterContextData = data }
                        }
                    }

                    // Pre-warm AXMenuReader cache for the top running apps so cross-app queries are instant
                    Task.detached(priority: .background) {
                        let selfBundle = Bundle.main.bundleIdentifier ?? "ILauncher"
                        let frontPID =
                            await MainActor.run { self.contextTargetApp()?.processIdentifier ?? 0 }
                        let candidates = NSWorkspace.shared.runningApplications
                            .filter {
                                $0.activationPolicy == .regular
                                    && !($0.bundleIdentifier ?? "").hasPrefix(selfBundle)
                                    && $0.processIdentifier != frontPID && !$0.isTerminated
                            }
                            .prefix(5)
                        for app in candidates {
                            // cachedAllMenuItems warms the cache; subsequent cross-app queries hit it instantly
                            var items = AXMenuReader.shared.cachedAllMenuItems(
                                for: app.processIdentifier, maxDepth: 5)
                            for i in items.indices {
                                items[i].sourcePID = app.processIdentifier
                                items[i].sourceAppName = app.localizedName ?? ""
                            }
                            AppMenuCapabilityCache.shared.store(items: items, for: app)
                            try? await Task.sleep(nanoseconds: 600_000_000)  // 0.6s between apps
                        }
                    }

                    // Start AX selection observer for the frontmost app
                    if let pid = activeApp?.processIdentifier {
                        selectionModel.start(for: pid)
                    }
                    // Refresh running apps list (for Layer 1 bar) — off main thread
                    runningRegularApps = currentRegularRunningApps()
                    // Refresh AX context periodically while dock is open so pills update as user interacts
                    axContextRefreshTimer?.invalidate()
                    axContextRefreshTimer = Timer.scheduledTimer(
                        withTimeInterval: 0.35, repeats: true
                    ) { [self] _ in
                        guard self.showContextInDock else { return }
                        self.refreshLiveContextDockState()
                    }
                } else {
                    if !aiMode.isActive { cancelBrowserContextWarmup() }
                    axContextRefreshTimer?.invalidate()
                    axContextRefreshTimer = nil
                    selectionModel.stop()
                    l2.extensionResults = []
                    l2.chatMessages = []
                    l2.isLoading = false
                    l2.activeRequestID = nil
                        l2.currentTask?.cancel()
                        l2.currentTask = nil
                        liveMenuRefreshTask?.cancel()
                        liveMenuRefreshTask = nil
                        lastLiveMenuStructureRefresh = .distantPast
                        lastLiveMenuSignature = ""
                        searchState.results = []
                    searchState.selectedIndex = nil
                    liveMenuItems = []
                    crossAppMenuItems = []
                    crossAppMenuTargetPID = 0
                    contextMenuPills = []
                    previousEnabledIDs = []
                    l2.focusedPillIndex = nil
                    focusedAppPillIndex = nil
                    adapterContextData = [:]
                    l2.appCompletion = nil
                    l2.targetApp = nil
                    menuLoadTask?.cancel()
                    crossAppMenuTask?.cancel()
                }
                updateWindowSize()
            }
            .onChange(of: showMediaLayer) { _, newValue in
                if newValue {
                    l2.extensionResults = []
                    l2.chatMessages = []
                    l2.isLoading = false
                    l2.activeRequestID = nil
                    l2.currentTask?.cancel()
                    l2.currentTask = nil
                    searchState.results = []
                    searchState.selectedIndex = nil
                    // Block expand during layer transition (globe ↔ magnifying glass icon swap)
                    suppressHoverExpand = true
                    DispatchQueue.main.asyncAfter(deadline: .now() + 0.6) {
                        self.suppressHoverExpand = false
                    }
                }
                updateWindowSize()
            }
            // AX selection observer fired — diff enabled states and surface context pills
            .onChange(of: selectionModel.changeCount) { _, _ in
                handleSelectionChange()
            }
    }

    private var contentLifecycleView: some View {
        contentWithModifiers
            .onAppear {
                // Load running apps immediately so the dock bar shows them on first launch
                runningRegularApps = currentRegularRunningApps()

                loadApplicationsInBackground()
                activateSearchField()
                setupQuickLookEventMonitor()
                setupSwipeGestureMonitor()  // swipe up/down for layer switching
                setupDockPillKeyMonitor()  // Left/Right/Enter for dock pill navigation
                setupCmdHoldMonitor()  // Cmd held 1.5s → shortcut sheet
                startClipboardExpiryTimer()

                // Start observing app switches if enabled (frontmost app already detected in ILauncherApp)
                if settings.enableFrontmostDetection {
                    startObservingAppSwitches()
                }

                // Detect initial context
                detectAndUpdateContext()

                // Reset chat visibility flag on launch
                hasUserSentMessageInCurrentSession = false

                // Load user profile picture
                loadUserProfilePicture()

                // Update smart positioning on launch (with slight delay to ensure window is positioned)
                DispatchQueue.main.async {
                    updateResultsPosition()
                }

                // Also update after a short delay to catch final window position
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.1) {
                    updateResultsPosition()
                    // Mark initial launch complete after position is set
                    searchState.isInitialLaunch = false
                }
            }
            .onDisappear {
                removeQuickLookEventMonitor()
                removeSwipeGestureMonitor()  // Cleanup swipe gesture monitor
                stopObservingAppSwitches()
                // Cancel collapse timer when window closes
                collapseTimer?.cancel()
                clipboardExpiryTimer?.invalidate()
                clipboardExpiryTimer = nil
            }
    }

    private var contentSettingsHandlersView: some View {
        contentLifecycleView
            .onChange(of: settings.enableFrontmostDetection) { oldValue, newValue in
                if newValue {
                    // Start observing when enabled
                    startObservingAppSwitches()
                } else {
                    // Clear frontmost app data when disabled
                    frontmost.name = ""
                    frontmost.icon = nil
                    frontmost.bundleID = ""
                    stopObservingAppSwitches()
                }
            }
            .onChange(of: settings.enableContextAIExtensions) { oldValue, newValue in
                // Smooth transition when context awareness is toggled
                withAnimation(.spring(response: 0.4, dampingFraction: 0.8)) {
                    isContextExpanded = newValue

                    if newValue {
                        // When enabled, detect context immediately
                        detectAndUpdateContext()
                    } else {
                        // When disabled, clear context
                        currentContext = .none
                        l2.contextExtensions = []
                    }
                }
            }
            .onChange(of: settings.showRunningAppsInBar) { _, newValue in
                if newValue {
                    runningRegularApps = currentRegularRunningApps()
                }
                updateWindowSize()
            }
            .onChange(of: settings.clipboardHistoryRetentionHours) { _, _ in
                pruneExpiredClipboardEntries()
            }
            .onChange(of: settings.clipboardHistoryLimit) { _, _ in
                trimClipboardHistoryToLimits()
            }
            .onChange(of: settings.enableL1DocumentSearch) { _, _ in
                indexedFileResults = indexedFileResults.filter(includeIndexedSearchResult)
                if !searchState.query.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                    performSearch()
                }
            }
            .onChange(of: settings.enableL1FileSearch) { _, _ in
                indexedFileResults = indexedFileResults.filter(includeIndexedSearchResult)
                if !searchState.query.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                    performSearch()
                }
            }
            .onChange(of: settings.effectiveDockAtBottom) { oldValue, newValue in
                // Update positioning immediately when setting changes
                updateResultsPosition()

                // Reposition window based on new setting
                guard
                    let window = (NSApp.keyWindow as? KeyableWindow)
                        ?? (NSApp.windows.first(where: {
                            ($0 as? KeyableWindow) != nil && $0.isVisible
                        }) as? KeyableWindow),
                    let screen = window.screen ?? NSScreen.main
                else { return }

                let screenFrame = screen.visibleFrame
                let currentFrame = window.frame

                let newY: CGFloat
                if newValue {
                    // Move to bottom and enable bottom anchoring
                    newY = screenFrame.minY + 10
                    window.anchorAtBottom = true
                } else {
                    // Move to upper third and disable bottom anchoring
                    newY = screenFrame.maxY - screenFrame.height / 3
                    window.anchorAtBottom = false
                }

                let newFrame = NSRect(
                    x: currentFrame.origin.x, y: newY, width: currentFrame.width,
                    height: currentFrame.height)
                window.setFrame(newFrame, display: true, animate: true)
            }
    }

    private var contentCoreLifecycleHandlersView: some View {
        contentSettingsHandlersView
            .onReceive(NotificationCenter.default.publisher(for: .launcherWindowOpened)) { _ in
                handleLauncherWindowOpened()
            }

            .onChange(of: searchState.results.count) { oldValue, newValue in
                handleSearchResultsCountChanged(newValue)
            }
            .onChange(of: l2.chatMessages.count) { _, _ in
                persistActiveL2DockSession()
            }
            .onChange(of: isGlobalContextActive) { _, _ in
                if !isGlobalContextActive {
                    globalInlineAppScope = nil
                    suppressGlobalInlineAppScopeDetection = false
                    pendingGlobalAppQuery = nil
                    focusedAppPillIndex = nil
                    if showContextInDock {
                        searchState.results = []
                        searchState.selectedIndex = nil
                        indexedFileResults = []
                    }
                }
                syncL2DockSession(force: true)
                updateL2ContextExtensions()
                scheduleDockPillRebuild(query: lastPillQuery, delayNanoseconds: 0)
            }
            // Rebuild pills immediately when AX selection changes (file picked, text highlighted)
            .onChange(of: axContext.selectedFilePaths) { _, paths in
                scheduleDockPillRebuild(query: lastPillQuery, delayNanoseconds: 0)
                autoReturnFromGlobalContextIfNeeded()
                if !paths.isEmpty { l2.appCompletion = nil }
            }
            .onChange(of: axContext.selectedText) { _, text in
                scheduleDockPillRebuild(query: lastPillQuery, delayNanoseconds: 0)
                autoReturnFromGlobalContextIfNeeded()
                if !(text ?? "").trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                    l2.appCompletion = nil
                }
            }
            // When Safari tab popover dismisses, reclaim key window so vibrancy stays active
            .onChange(of: showSafariTabPicker) { _, isShowing in
                if !isShowing {
                    DispatchQueue.main.asyncAfter(deadline: .now() + 0.05) {
                        NSApp.keyWindow?.makeKey()
                        NSApp.activate(ignoringOtherApps: true)
                    }
                }
            }
    }

    private var contentLifecycleHandlersView: some View {
        contentCoreLifecycleHandlersView
            .onChange(of: l2.targetApp?.bundleId) { _, newBundleId in
                syncL2DockSession(force: true)
                scheduleDockPillRebuild(query: lastPillQuery, delayNanoseconds: 0)
                // Keep search field focused while in scope so .onKeyPress(.escape) always fires
                if newBundleId != nil {
                    DispatchQueue.main.async { isSearchFieldFocused = true }
                }
            }
            .onChange(of: showContextInDock) { _, newValue in
                if newValue {
                    syncL2DockSession(force: true)
                    scheduleDockPillRebuild(query: lastPillQuery, delayNanoseconds: 0)
                }
            }
            // Rebuild pills whenever the live menu content changes — catches both count changes
            // (new app) and title/enabled-state-only changes (e.g. Show→Hide Tab Bar, message
            // selected/deselected). The signature encodes titles + enabled flags so it fires on
            // any menu mutation, not just when the item count differs.
            .onChange(of: lastLiveMenuSignature) { _, _ in
                scheduleDockPillRebuild(query: lastPillQuery, delayNanoseconds: 0)
            }
            // Global context always shows a fully expanded input — same size as context dock
            .onChange(of: isGlobalContextActive) { _, active in
                if active { isSearchBarExpanded = true }
            }
    }

    private var contentNotificationHandlersViewA: some View {
        contentLifecycleHandlersView
            // AppKit-level Escape fallback — fires only when SwiftUI doesn't capture it
            .onReceive(NotificationCenter.default.publisher(for: .escapePressed)) { _ in
                if showFolderPreview {
                    withAnimation(.easeInOut(duration: 0.2)) {
                        showFolderPreview = false; folderPreviewPath = nil
                        folderPreviewSelectedFile = nil; searchState.isInSmartMode = false
                        searchState.lastSmartQuery = ""; searchState.results = []; searchState.selectedIndex = nil
                    }
                    return
                }
                if l2.targetApp != nil || searchState.activeSmartQueryKey != nil || searchState.contextApp != nil {
                    clearSearchContext()
                    remPanelIsProcessing = false; remIsInstalled = nil
                    systemDataResults = []; searchState.lastSmartQuery = ""
                    isSearchFieldFocused = true
                    return
                }
                if l2.focusedPillIndex != nil || focusedAppPillIndex != nil || searchState.selectedIndex != nil {
                    l2.focusedPillIndex = nil; focusedAppPillIndex = nil
                    l2.pillNavViaKeyboard = false; searchState.selectedIndex = nil
                    isSearchFieldFocused = true
                    return
                }
                AppDelegate.shared?.hideLauncher()
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.06) {
                    AppDelegate.shared?.previousFrontmostApp?.activate(options: [.activateIgnoringOtherApps])
                }
            }
            .onReceive(NotificationCenter.default.publisher(for: .launcherBackspacePressed)) { _ in
                guard searchState.query.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
                    return
                }
                if lockedSubmenuParent != nil {
                    withAnimation(.spring(response: 0.2, dampingFraction: 0.8)) {
                        lockedSubmenuParent = nil
                    }
                    isSearchFieldFocused = true
                    return
                }
                if l2.targetApp != nil || searchState.contextApp != nil || searchState.activeSmartQueryKey != nil {
                    clearSearchContext()
                    remPanelIsProcessing = false
                    remIsInstalled = nil
                    systemDataResults = []
                    searchState.lastSmartQuery = ""
                    isSearchFieldFocused = true
                    return
                }
                if detachFinderFolderQueryModeFromEmptyBackspace() {
                    isSearchFieldFocused = true
                    return
                }
                if isGlobalContextActive || frozenSelectionText != nil {
                    dismissContextAndReturnToDock()
                    isSearchFieldFocused = true
                }
            }
            .onReceive(NotificationCenter.default.publisher(for: .focusSearchField)) { _ in
                l2.focusedPillIndex = nil
                focusedAppPillIndex = nil
                l2.pillNavViaKeyboard = false
                showMediaLayer = false
                showContextInDock = true
                expandSearchBar()
                DispatchQueue.main.async {
                    // Window must be key before @FocusState will stick
                    if let window = AppDelegate.shared?.launcherWindow {
                        window.makeKeyAndOrderFront(nil)
                        NSApp.activate(ignoringOtherApps: true)
                    }
                    isSearchFieldFocused = true
                }
            }
            .onReceive(contextEnv.userContextUpdates) { context in
                // Receive pre-detected context from AppDelegate (before ILauncher becomes frontmost)
                if isL2ContextActive || AppDelegate.shared?.isDockContextMode == true {
                    setFrontmostAppContextOnly(reason: "dock context pre-detection")
                    return
                }
                currentContext = context
                print("✅ [ContentView] Received pre-detected context: \(context.description)")
            }
            .onReceive(NotificationCenter.default.publisher(for: .overlayAskAboutSelection)) {
                notification in
                guard !isExplicitAppScopeLocked else { return }
                guard let text = notification.userInfo?["text"] as? String else { return }
                searchState.query = text
                aiMode.isActive = true
                showContextInDock = false
                showMediaLayer = false
                AppDelegate.shared?.showLauncher()
            }
            .onReceive(contextEnv.frontmostAppUpdates) { appInfo in
                let appName = appInfo.name
                let bundleID = appInfo.bundleID

                // Check if app changed (not just re-detection of same app)
                let appChanged =
                    !frontmost.bundleID.isEmpty && frontmost.bundleID != bundleID

                frontmost.name = appName
                frontmost.bundleID = bundleID

                // Get icon from bundle ID
                if let app = NSWorkspace.shared.runningApplications.first(where: {
                    $0.bundleIdentifier == bundleID
                }) {
                    frontmost.icon =
                        resolvedApplicationIcon(bundleIdentifier: bundleID, appName: appName)
                        ?? preparedDockIcon(app.icon)
                } else {
                    frontmost.icon = resolvedApplicationIcon(
                        bundleIdentifier: bundleID, appName: appName)
                }

                print("📱 Received frontmost app: \(appName) (\(bundleID))")

                if let pendingSwitch = pendingGlobalLaunchContextSwitch,
                   pendingSwitch.bundleId == bundleID,
                   isGlobalContextActive
                {
                    switchGlobalLaunchToContextDock(bundleId: bundleID, appName: appName)
                }

                if appChanged {
                    l2.appCompletion = nil
                    l2.focusedPillIndex = nil
                    l2.pillNavViaKeyboard = false
                    // Immediately clear stale pills so the result panel disappears
                    // and rebuilds for the new frontmost app
                    cachedDockPills = []
                    let ownId = Bundle.main.bundleIdentifier ?? ""
                    // Only exit global context when switching to a real other app
                    // (not when our own dock gains focus — that would clear the chip)
                    let isInlineGlobalTargetSwitch =
                        isGlobalContextActive && l2.targetApp?.bundleId == bundleID
                    if bundleID != ownId && !isInlineGlobalTargetSwitch {
                        // Only auto-deactivate global context if it was auto-activated.
                        // Manual global context (swipe-down) survives app switches.
                        if globalContextActivation?.autoActivated == true {
                            globalContextActivation = nil
                        }
                    }
                    // Clear stale AX selection and clipboard pill from the previous app
                    axContext = .empty
                    currentContext = .none
                    showGlobalClipboardPill = false
                    globalClipboardText = ""
                    // Stamp time so autoSwitch won't re-fire from the AX observer debounce
                    frontmost.lastSwitchDate = Date()
                }

                // Scope lock: when user explicitly entered an app scope (l2.targetApp set),
                // ignore frontmost app changes — the dock stays on the pinned app until
                // the user presses Escape or clicks "Exit Scope".
                let scopeLocked = l2.targetApp != nil

                // Reload menu whenever dock is visible (or when app actually changed)
                if showContextInDock && !scopeLocked {
                    // Sync session on app switch. syncL2DockSession saves the previous app's
                    // session and loads the new app's saved session (or empty if none).
                    // We do NOT call activateInlineDockAppScope here because that would pin
                    // l2.targetApp, causing scopeLocked=true on the next app switch.
                    syncL2DockSession(force: appChanged)
                    // Always reload — covers first open (appChanged=false) AND app switches
                    let allApps: [NSRunningApplication] = Array(NSWorkspace.shared.runningApplications)
                    let matchedApp: NSRunningApplication? = allApps.first { $0.bundleIdentifier == bundleID }
                    if let newApp = matchedApp { reloadMenuForApp(newApp) }
                }

                // Re-detect full context (text selection, etc.) from the new frontmost app
                if !scopeLocked {
                    detectAndUpdateContext()
                }

                // Refresh deep per-app context when app switches while L2 is open
                if showContextInDock && appChanged && !scopeLocked {
                    let capturedCtx = axContext
                    Task {
                        let data = await adapterManager.runContextReaders(
                            for: bundleID, axContext: capturedCtx)
                        await MainActor.run {
                            adapterContextData = data
                            let runningApps: [NSRunningApplication] = Array(NSWorkspace.shared.runningApplications)
                            if let app = runningApps.first(where: { $0.bundleIdentifier == bundleID }) {
                                Task { await adapterManager.autoGenerateAdapterIfNeeded(for: app) }
                            }
                        }
                    }
                }
            }
            .onReceive(NotificationCenter.default.publisher(for: .servicesOpenWithFiles)) {
                notification in
                // Receive files shared via Services/Share Sheet
                if let urls = notification.userInfo?["urls"] as? [URL], !urls.isEmpty {
                    currentContext = .filesSelected(urls)
                    updateL2ContextExtensions()
                }
            }
            .onReceive(NotificationCenter.default.publisher(for: .servicesOpenWithText)) {
                notification in
                // Receive text shared via Services/Share Sheet
                if let text = notification.userInfo?["text"] as? String, !text.isEmpty {
                    print("📝 [Services] Received text via Share Sheet: \(text.prefix(100))...")

                    // Update context with the shared text
                    currentContext = .textSelected(text)
                    updateL2ContextExtensions()
                    print("✅ [Services] Context updated with shared text")
                }
            }
    }

    private var contentNotificationHandlersView: some View {
        contentNotificationHandlersViewA
            .onReceive(NotificationCenter.default.publisher(for: .toggleAIExtensions)) { _ in
                // Toggle AI Extension Suggestions overlay
                detectAndUpdateContext()  // Update context before showing
                withAnimation(.spring(response: 0.3)) {
                    showAIExtensionSuggestions.toggle()
                }
            }
            .onReceive(NotificationCenter.default.publisher(for: .activateContextDock)) { _ in
                // Instant switch — no animation so the layer change feels immediate
                showMediaLayer = false
                aiMode.isActive = false
                showContextInDock = true
                globalContextActivation = nil
                setFrontmostAppContextOnly(reason: "activate context dock")
            }
            .onReceive(NotificationCenter.default.publisher(for: .activateGlobalContext)) { _ in
                showMediaLayer = false
                aiMode.isActive = false
                showContextInDock = true
                globalContextActivation = GlobalContextActivation(autoActivated: false)
                l2.targetApp = nil
                l2.focusedPillIndex = nil
                focusedAppPillIndex = nil
                lockedSubmenuParent = nil
                showShortcutSheet = false
                scheduleDockPillRebuild(query: lastPillQuery, delayNanoseconds: 0)
                activateSearchField()
            }
            .onReceive(NotificationCenter.default.publisher(for: .activateClipboardScope)) { _ in
                activateClipboardScope()
            }
            .onChange(of: currentContext.description) { _, _ in
                // Trigger smooth expansion when context is detected
                if settings.enableContextAIExtensions {
                    let hasValidContext: Bool = {
                        switch currentContext {
                        case .filesSelected(let urls): return !urls.isEmpty
                        case .textSelected(let text):
                            return !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                        case .url(let urlString):
                            return !urlString.trimmingCharacters(in: .whitespacesAndNewlines)
                                .isEmpty
                        default: return false
                        }
                    }()

                    withAnimation(.spring(response: 0.35, dampingFraction: 0.75)) {
                        isContextExpanded = hasValidContext
                    }
                }

                // Clear stale chat when the selected content changes so AI focuses on the new context.
                // App-level changes are already handled by .frontmostAppDetected; this covers file/text/URL switches.
                let newKey = contextIdentityKey(currentContext)
                if l2.activeRequestID == nil && newKey != "none" && !l2.chatContextKey.isEmpty
                    && newKey != l2.chatContextKey
                    && !l2.chatMessages.isEmpty
                {
                    print(
                        "🔄 [Context] Content changed (\(l2.chatContextKey) → \(newKey)) — clearing L2 chat"
                    )
                    persistActiveL2DockSession()
                    l2.chatMessages = []
                    l2.isLoading = false
                    l2.currentTask?.cancel()
                    l2.currentTask = nil
                    updateL2Results([])
                }
                if newKey != "none" {
                    l2.chatContextKey = newKey
                }
                // Auto-return to Context Dock if context cleared and global context was auto-activated
                autoReturnFromGlobalContextIfNeeded()
            }
    }

    private func handleLauncherWindowOpened() {
        suppressOpenResize = true
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.30) { [self] in
            suppressOpenResize = false
            updateWindowSize()
        }

        let openingForDockContext = AppDelegate.shared?.isDockContextMode ?? true
        globalContextActivation = nil
        if !openingForDockContext {
            searchState.query = ""
            searchState.results = []
            searchState.selectedIndex = nil
            aiMode.isActive = false
            showMediaLayer = false
            showFolderPreview = false
            showContextInDock = true
            searchState.activeSmartQueryKey = nil
            searchState.contextApp = nil
            searchState.isInSmartMode = false
            searchState.appPanelAllItems = []
        }

        activateSearchField()
        if openingForDockContext {
            setFrontmostAppContextOnly(reason: "window opened")
        } else {
            DispatchQueue.main.async { [self] in
                detectAndUpdateContext()
            }
        }

        if let app = AppDelegate.shared?.previousFrontmostApp {
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.12) { [self] in
                AXContextReader.shared.refresh(from: app)
                axContext = AXContextReader.shared.current
                // After AX refresh, check if there's already a selection active
                autoSwitchGlobalContextIfNeeded()
            }
        }
        syncL2DockSession(force: true)
        backgroundScanRunningAppMenusIfNeeded()
    }

    /// Low-priority background scan: snapshot menus for all running regular apps
    /// that have no cached snapshot or a stale one (>7 days). Runs once per launcher open,
    /// staggered so it doesn't compete with the foreground AX read of the frontmost app.
    private func backgroundScanRunningAppMenusIfNeeded() {
        let staleThreshold: TimeInterval = 7 * 24 * 3600
        let appsToScan = NSWorkspace.shared.runningApplications.filter { app in
            guard let bid = app.bundleIdentifier,
                  !bid.isEmpty,
                  bid != Bundle.main.bundleIdentifier,
                  app.activationPolicy == .regular,
                  !app.isTerminated
            else { return false }
            let age = AppMenuCapabilityCache.shared.snapshotAge(bundleIdentifier: bid) ?? .infinity
            return age > staleThreshold
        }
        guard !appsToScan.isEmpty else { return }
        Task.detached(priority: .background) {
            // Stagger by 0.4 s per app. Also wait if another AX scan is running —
            // concurrent full-tree reads serialize on the AX server and freeze input.
            for (i, app) in appsToScan.enumerated() {
                try? await Task.sleep(nanoseconds: UInt64(i) * 400_000_000)
                guard !Task.isCancelled else { return }
                while AXMenuReader.shared.isScanningMenus {
                    try? await Task.sleep(nanoseconds: 200_000_000)  // 200ms back-off
                }
                let pid = app.processIdentifier
                var items = AXMenuReader.shared.refreshAllMenuItems(for: pid, maxDepth: 6)
                guard !items.isEmpty else { continue }
                for j in items.indices {
                    items[j].sourcePID = pid
                    items[j].sourceAppName = app.localizedName ?? ""
                }
                AppMenuCapabilityCache.shared.store(items: items, for: app)
            }
        }
    }

    private func handleSearchResultsCountChanged(_ newValue: Int) {
        if newValue > 0 && !isL2ContextActive {
            updateResultsPosition()
        }
    }

    private func persistActiveL2DockSession() {
        if let key = l2.activeDockSessionKey {
            AppPanelChatStore.shared.save(l2.chatMessages, for: key)
        }
    }

    private var contentKeyHandlersView: some View {
        contentNotificationHandlersView
            .onExitCommand {
                // Layer overlays close first
                if showMediaLayer {
                    withAnimation(.spring(response: 0.3, dampingFraction: 0.75)) {
                        showMediaLayer = false
                    }
                    return
                }
                if showAIExtensionSuggestions {
                    withAnimation(.spring(response: 0.3)) {
                        showAIExtensionSuggestions = false
                    }
                    return
                }
                if showFolderPreview {
                    withAnimation(.easeInOut(duration: 0.2)) {
                        showFolderPreview = false
                        folderPreviewPath = nil
                        folderPreviewSelectedFile = nil
                        searchState.isInSmartMode = false
                        searchState.lastSmartQuery = ""
                        searchState.results = []
                        searchState.selectedIndex = nil
                    }
                    return
                }
                // App scope: exit scope, close dock, switch to scoped app
                if let targetInfo = l2.targetApp {
                    let bundleId = targetInfo.bundleId
                    clearSearchContext()
                    AppDelegate.shared?.hideLauncher()
                    DispatchQueue.main.asyncAfter(deadline: .now() + 0.06) {
                        let app = NSWorkspace.shared.runningApplications.first {
                            $0.bundleIdentifier == bundleId && !$0.isTerminated
                        } ?? AppDelegate.shared?.previousFrontmostApp
                        app?.activate(options: [.activateIgnoringOtherApps])
                    }
                    return
                }
                // Smart panel / search context: exit back to normal search, keep dock open
                if searchState.activeSmartQueryKey != nil || searchState.contextApp != nil {
                    clearSearchContext()
                    remPanelIsProcessing = false
                    remIsInstalled = nil
                    systemDataResults = []
                    searchState.lastSmartQuery = ""
                    return
                }
                // Pills / results highlighted: clear selection, return focus to search field
                if l2.focusedPillIndex != nil || focusedAppPillIndex != nil || searchState.selectedIndex != nil {
                    l2.focusedPillIndex = nil
                    focusedAppPillIndex = nil
                    l2.pillNavViaKeyboard = false
                    searchState.selectedIndex = nil
                    isSearchFieldFocused = true
                    return
                }
                // Nothing active: close dock and return to previous app
                onClose()
            }
            .onKeyPress(.upArrow) {
                if searchState.activeSmartQueryKey == "clipboard" {
                    navigateClipboardScope(direction: -1)
                    return .handled
                }
                if !showFolderPreview {
                    navigateResults(direction: -1)
                    return .handled
                }
                return .ignored
            }
            .onKeyPress(.downArrow) {
                if showContextInDock, isGlobalContextActive, !aiMode.isActive {
                    let q = searchState.query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
                    // File/text selection chip is showing: Down arrow moves focus into the action pills
                    // instead of dismissing the context (let the user act on the selected file via keyboard)
                    let hasSelection = frozenSelectionText != nil || !effectiveFinderSelectionURLsForPills().isEmpty
                    if hasSelection && l2.focusedPillIndex == nil {
                        let pills = buildDockPills(query: q)
                        if !pills.isEmpty {
                            l2.pillNavViaKeyboard = true
                            var idx = 0
                            while idx < pills.count - 1 && pills[idx].isSeparator { idx += 1 }
                            l2.focusedPillIndex = idx
                            return .handled
                        }
                    }
                    // Only an empty input field switches layers. Typed global queries keep
                    // the current dock so Down can navigate visible results/menus.
                    if q.isEmpty && l2.focusedPillIndex == nil && focusedAppPillIndex == nil {
                        switchDockLayer(.down)
                        return .handled
                    }
                }
                if searchState.activeSmartQueryKey == "clipboard" {
                    navigateClipboardScope(direction: 1)
                    return .handled
                }
                if !showFolderPreview {
                    navigateResults(direction: 1)
                    return .handled
                }
                return .ignored
            }
            .onKeyPress(.space) {
                if searchState.activeSmartQueryKey == "clipboard", focusedClipboardEntryIndex != nil {
                    quickLookFocusedClipboardEntry()
                    return .handled
                }

                // Close contact preview if it's showing
                if showContactPreview {
                    withAnimation {
                        showContactPreview = false
                        contactPreviewData = nil
                    }
                    return .handled
                }

                // Only handle space for Quick Look when the search field is NOT focused
                // This allows typing spaces in the search field
                if !showFolderPreview && !isSearchFieldFocused && searchState.selectedIndex != nil
                    && !searchState.results.isEmpty
                {
                    quickLookSelectedItem()
                    return .handled
                }
                return .ignored
            }
            .onKeyPress(keys: [.init("y")], phases: .down) { keyPress in
                // Cmd+Y for Quick Look (like Finder)
                if keyPress.modifiers.contains(.command) && !showFolderPreview
                    && searchState.selectedIndex != nil && !searchState.results.isEmpty
                {
                    quickLookSelectedItem()
                    return .handled
                }
                return .ignored
            }
            .onKeyPress(.return) {
                if !showFolderPreview {
                    // Submenu ghost: Enter executes the first matching child directly
                    if let subCtx = submenuGhostContext, let firstChild = subCtx.children.first {
                        let frontPID = AppDelegate.shared?.previousFrontmostApp?.processIdentifier ?? 0
                        let pid  = firstChild.sourcePID != 0 ? firstChild.sourcePID : frontPID
                        searchState.query = ""
                        lockedSubmenuParent = nil
                        executeDockMenuAction(
                            sourcePID: pid, path: firstChild.path,
                            shortcutChar: firstChild.shortcutChar, shortcutModifiers: firstChild.shortcutModifiers
                        )
                        return .handled
                    }
                    // Execute inline pill ghost completion if available
                    if let ghost = ghostPillCompletion {
                        ghost.execute()
                        searchState.query = ""
                        l2.focusedPillIndex = nil
                        return .handled
                    }
                    if isL2ContextActive,
                        l2.focusedPillIndex != nil,
                        executeFocusedOrDirectAppPillIfNeeded()
                    {
                        return .handled
                    }
                    if isL2ContextActive, executeFirstMatchingFinderFolderPillIfNeeded() {
                        return .handled
                    }
                    if launchTypedAppMatchIfNeeded() {
                        return .handled
                    }
                    if searchState.activeSmartQueryKey == "clipboard" {
                        if focusedClipboardEntryIndex != nil {
                            quickLookFocusedClipboardEntry()
                        } else {
                            navigateClipboardScope(direction: 1)
                        }
                        return .handled
                    }
                    // Any context panel (app, file, folder, contact, Reminders, etc.) routes Enter → AI chat
                    let isAIAppPanel = searchState.contextApp != nil || searchState.activeSmartQueryKey != nil
                    if isAIAppPanel
                        && !searchState.query.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                    {
                        handleRemPanelQuery()
                        return .handled
                    } else if isL2ContextActive {
                        // NSEvent monitor handles Enter when pills exist (returns nil, consuming the event).
                        // We only reach here when no pills are visible — escalate to AI.
                        let trimmed = searchState.query.trimmingCharacters(in: .whitespacesAndNewlines)
                        guard !trimmed.isEmpty else { return .handled }
                        if executeFocusedOrDirectAppPillIfNeeded() {
                            return .handled
                        }
                        if executeFirstMatchingFinderFolderPillIfNeeded() {
                            return .handled
                        }
                        dismissMediaLayer()
                        handleL2Query()
                    } else if aiMode.isActive {
                        submitAIQuery()
                    } else {
                        // L1/L2: Execute selected result
                        executeSelectedResult()
                    }
                    return .handled
                }
                return .ignored
            }
            .onKeyPress(.tab) {
                if isL2ContextActive && !isGlobalContextActive {
                    return .handled
                }

                // Tab on submenu ghost — lock parent if not yet locked; execute if already locked
                if let subCtx = submenuGhostContext, !subCtx.children.isEmpty {
                    if lockedSubmenuParent == nil {
                        // First Tab: lock the parent as a chip, clear all app-detection state
                        withAnimation(.spring(response: 0.22, dampingFraction: 0.8)) {
                            lockedSubmenuParent = subCtx.parent
                            searchState.query = ""
                        }
                        l2.appCompletion = nil
                        l2.showResultsPopover = false
                        crossAppMenuItems = []
                        cachedDockPills = []
                        return .handled
                    } else if let firstChild = subCtx.children.first {
                        // Already locked + Tab: execute the highlighted child
                        let frontPID = AppDelegate.shared?.previousFrontmostApp?.processIdentifier ?? 0
                        let pid  = firstChild.sourcePID != 0 ? firstChild.sourcePID : frontPID
                        let path = firstChild.path
                        let sc   = firstChild.shortcutChar
                        let mod  = firstChild.shortcutModifiers
                        searchState.query = ""
                        lockedSubmenuParent = nil
                        executeDockMenuAction(sourcePID: pid, path: path, shortcutChar: sc, shortcutModifiers: mod)
                        return .handled
                    }
                }
                // Tab accepts pill ghost completion (prefix match on pill name)
                if let ghost = ghostPillCompletion {
                    searchState.query = ghost.name
                    return .handled
                }

                // L1 mode: Tab fills ghost from selected result when it's a prefix match.
                if !isL2ContextActive, !isGlobalContextActive {
                    let typed = searchState.query.trimmingCharacters(in: .whitespaces)
                    if !typed.isEmpty,
                       let idx = searchState.selectedIndex,
                       idx < searchState.results.count
                    {
                        let result = searchState.results[idx]
                        if result.title.lowercased().hasPrefix(typed.lowercased()) {
                            searchState.query = result.title
                            return .handled
                        }
                    }
                }

                // Global context: Tab fills ghost text from top/focused match.
                // Scope resolves inline from query — no dock switch.
                if isGlobalContextActive {
                    let q = searchState.query.trimmingCharacters(in: .whitespaces)
                    if !q.isEmpty {
                        let hit = focusedGlobalAppResultForInputPreview()
                            ?? topGlobalAppResultForInputPreview()
                        if let result = hit {
                            searchState.query = result.title
                            focusedAppPillIndex = nil
                            return .handled
                        }
                    }
                }

                // Non-global context: Tab may enter explicit app sub-scope
                if !isGlobalContextActive {
                    if activateTypedAppScopeIfPossible() {
                        return .handled
                    }
                }

                if isL2ContextActive && !isGlobalContextActive {
                    if focusFirstDockPillIfAvailable(for: searchState.query) {
                        return .handled
                    }
                    return .handled
                }

                // Tab → always open context panel for selected result (files, folders, apps, etc.)
                if let idx = searchState.selectedIndex, idx < searchState.results.count {
                    let result = searchState.results[idx]
                    activateSearchContext(for: result)
                    return .handled
                }

                toggleAIModePreservingLayer()
                return .handled
            }
            .onKeyPress(.escape) {
                // Folder preview: ESC exits back to normal search
                if showFolderPreview {
                    withAnimation(.easeInOut(duration: 0.2)) {
                        showFolderPreview = false
                        folderPreviewPath = nil
                        folderPreviewSelectedFile = nil
                        searchState.isInSmartMode = false
                        searchState.lastSmartQuery = ""
                        searchState.results = []
                        searchState.selectedIndex = nil
                    }
                    return .handled
                }
                // App scope or app panel: ESC exits scope and returns to L1 (stays open)
                if l2.targetApp != nil || searchState.activeSmartQueryKey != nil || searchState.contextApp != nil {
                    let wasAppScope = l2.targetApp != nil
                    clearSearchContext()
                    remPanelIsProcessing = false
                    remIsInstalled = nil
                    systemDataResults = []
                    searchState.lastSmartQuery = ""
                    // Restore global app-search mode so dock shows app search, not empty limbo
                    if wasAppScope { globalContextActivation = GlobalContextActivation(autoActivated: false) }
                    isSearchFieldFocused = true
                    return .handled
                }
                // Pills focused (no scope): ESC returns focus to search field, keeps dock open
                if l2.focusedPillIndex != nil || focusedAppPillIndex != nil || searchState.selectedIndex != nil {
                    l2.focusedPillIndex = nil
                    focusedAppPillIndex = nil
                    l2.pillNavViaKeyboard = false
                    searchState.selectedIndex = nil
                    isSearchFieldFocused = true
                    return .handled
                }
                // Dock visible, nothing active: ESC hides dock and returns to previous app
                AppDelegate.shared?.hideLauncher()
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.06) {
                    AppDelegate.shared?.previousFrontmostApp?.activate(options: [.activateIgnoringOtherApps])
                }
                return .handled
            }
            .onKeyPress(.delete) {
                let text = searchState.query.trimmingCharacters(in: .whitespacesAndNewlines)
                if text.isEmpty {
                    // Unlock locked submenu parent first
                    if lockedSubmenuParent != nil {
                        withAnimation(.spring(response: 0.2, dampingFraction: 0.8)) {
                            lockedSubmenuParent = nil
                        }
                        isSearchFieldFocused = true
                        return .handled
                    }
                    // Dismiss file/text selection chip (same as clicking "-")
                    if isGlobalContextActive || frozenSelectionText != nil {
                        dismissContextAndReturnToDock()
                        isSearchFieldFocused = true
                        return .handled
                    }
                    // Exit app/smart-query scope — same as Esc, restores L1
                    if l2.targetApp != nil || searchState.contextApp != nil || searchState.activeSmartQueryKey != nil {
                        let wasAppScope = l2.targetApp != nil
                        clearSearchContext()
                        remPanelIsProcessing = false
                        remIsInstalled = nil
                        systemDataResults = []
                        searchState.lastSmartQuery = ""
                        if wasAppScope { globalContextActivation = GlobalContextActivation(autoActivated: false) }
                        isSearchFieldFocused = true
                        return .handled
                    }
                }
                return detachFinderFolderQueryModeFromEmptyBackspace() ? .handled : .ignored
            }
            // Right Arrow: accept ghost text completion (fill app name) without entering scope.
            // Does NOT enter L2 scope — that's Tab's job.
            .onKeyPress(.rightArrow) {
                if let completion = l2.appCompletion, !completion.ghost.isEmpty {
                    let full = completion.appName
                    if !full.isEmpty && searchState.query.lowercased() != full.lowercased() {
                        withAnimation(.easeInOut(duration: 0.1)) {
                            searchState.query = full
                        }
                        return .handled
                    }
                }
                return showContextInDock ? .handled : .ignored
            }
    }

    var body: some View {
        ZStack {
            contentKeyHandlersView

            // Contact Preview Overlay
            if showContactPreview, let contact = contactPreviewData {
                ContactPreviewCard(contact: contact, isPresented: $showContactPreview)
                    .transition(.opacity.combined(with: .scale(scale: 0.95)))
            }

            // AI Extension Suggestions Overlay
            if showAIExtensionSuggestions {
                ZStack {
                    // Dim background
                    Color.black.opacity(0.3)
                        .ignoresSafeArea()
                        .onTapGesture {
                            withAnimation(.spring(response: 0.3)) {
                                showAIExtensionSuggestions = false
                            }
                        }

                    // AI Suggestions View
                    AIModeView(
                        currentContext: $currentContext,
                        isVisible: $showAIExtensionSuggestions
                    )
                    .transition(.opacity.combined(with: .scale(scale: 0.95)))
                }
            }

        }
        .onReceive(adapterManager.$pendingApproval) { pending in
            DispatchQueue.main.async {
                if let pending {
                    openAdapterApprovalWindow(request: pending)
                } else {
                    AdapterApprovalWindowHost.close()
                }
            }
        }
        .onReceive(TerminalAIBridge.shared.$pendingApproval) { pending in
            if let pending = pending {
                let risk = pending.classification.riskLevel.displayName
                let approvalMsg = AIChatMessage(
                    role: .approval,
                    content: pending.command,
                    structuredData: "\(pending.purpose)|||/\(risk)"
                )
                if l2.targetApp != nil || showContextInDock {
                    // L2 app scope active — show inline in L2 chat
                    l2.chatMessages.append(approvalMsg)
                } else if searchState.activeSmartQueryKey != nil {
                    // Legacy panel fallback
                    remPanelChatMessages.append(approvalMsg)
                } else {
                    openCommandApprovalWindow(pending: pending)
                }
            } else {
                // Close popup if one was open (for non-panel contexts)
                CommandApprovalWindowHost.close()
            }
        }
    }

    private func openCommandApprovalWindow(pending: TerminalAIBridge.PendingCommand) {
        CommandApprovalWindowHost.close()
        let view = CommandApprovalView(
            command: pending.command,
            classification: pending.classification,
            purpose: pending.purpose,
            onApprove: { approvedCommand in
                TerminalAIBridge.shared.approveCommand(approvedCommand)
            },
            onDeny: {
                TerminalAIBridge.shared.denyCommand()
            }
        )
        let controller = NSHostingController(rootView: view)
        let win = NSWindow(contentViewController: controller)
        win.title = "Terminal Command Approval"
        win.styleMask = [.titled, .closable]
        win.level = .floating
        let isCritical = pending.classification.riskLevel == .critical
        win.setContentSize(NSSize(width: 520, height: isCritical ? 460 : 410))
        win.isReleasedWhenClosed = false
        win.center()
        win.makeKeyAndOrderFront(nil)
        NSApp.activate(ignoringOtherApps: true)
        CommandApprovalWindowHost.window = win
        // When the user closes via the X button, treat as deny
        win.delegate = CommandApprovalWindowHost.shared
    }

    private func openAdapterApprovalWindow(request: AdapterActionRequest) {
        AdapterApprovalWindowHost.close()

        let size = NSSize(width: 460, height: 252)
        let view = AdapterApprovalPopupView(request: request)
        let controller = NSHostingController(rootView: view)
        let panel = AdapterApprovalPanel(
            contentRect: NSRect(origin: .zero, size: size),
            styleMask: [.borderless, .fullSizeContentView],
            backing: .buffered,
            defer: false
        )

        panel.contentViewController = controller
        panel.level = .floating
        panel.isOpaque = false
        panel.backgroundColor = .clear
        panel.hasShadow = true
        panel.hidesOnDeactivate = false
        panel.isMovableByWindowBackground = true
        panel.collectionBehavior = [.fullScreenAuxiliary, .moveToActiveSpace, .transient]

        positionAdapterApprovalPanel(panel, size: size)

        AdapterApprovalWindowHost.shared.onClose = request.onDeny
        AdapterApprovalWindowHost.window = panel
        panel.delegate = AdapterApprovalWindowHost.shared
        panel.makeKeyAndOrderFront(nil)
        NSApp.activate(ignoringOtherApps: true)
    }

    private func positionAdapterApprovalPanel(_ panel: NSPanel, size: NSSize) {
        if let launcherWindow = AppDelegate.shared?.launcherWindow, launcherWindow.isVisible {
            let screenFrame = (launcherWindow.screen ?? NSScreen.main)?.visibleFrame
                ?? NSScreen.main?.visibleFrame
                ?? NSRect(origin: .zero, size: size)
            let margin: CGFloat = 16
            let verticalGap: CGFloat = 18

            var x = launcherWindow.frame.midX - (size.width / 2)
            var y = launcherWindow.frame.maxY + verticalGap

            x = min(max(x, screenFrame.minX + margin), screenFrame.maxX - size.width - margin)

            if y + size.height > screenFrame.maxY - margin {
                y = max(
                    screenFrame.minY + margin,
                    launcherWindow.frame.minY - size.height - verticalGap
                )
            }

            panel.setFrame(NSRect(x: x, y: y, width: size.width, height: size.height), display: false)
            return
        }

        panel.center()
    }

