                        NSItemProvider(object: app.id.uuidString as NSString)
                    }
                    .onDrop(
                        of: [.text],
                        delegate: PinnedAppDropDelegate(
                            item: app,
                            pinnedApps: $settings.pinnedApps,
                            settings: settings
                        ))
                }

                // Running apps (when enabled) — shown after pinned, deduplicated
                if settings.showRunningAppsInBar {
                    let pinnedPaths = Set(settings.pinnedApps.map { $0.path })
                    let pinnedBundleIds = Set(
                        settings.pinnedApps.compactMap { $0.bundleIdentifier })
                    let runningApps = runningRegularApps.filter { app in
                        guard let path = app.bundleURL?.path else { return false }
                        return !pinnedPaths.contains(path)
                            && (app.bundleIdentifier == nil
                                || !pinnedBundleIds.contains(app.bundleIdentifier!))
                    }

                    if !runningApps.isEmpty && !settings.pinnedApps.isEmpty {
                        Divider()
                            .frame(height: 28)
                            .padding(.horizontal, 2)
                    }

                    ForEach(runningApps, id: \.processIdentifier) { app in
                        appIconButton(
                            icon: resolvedRunningAppIcon(for: app),
                            label: app.localizedName ?? "App",
                            isRunning: true,
                            hoverKey: "running-\(app.processIdentifier)",
                            onCloseRunningApp: { terminateRunningAppFromDock(app) },
                            action: { activateRunningAppFromDock(app) }
                        )
                        .contextMenu {
                            Button("Pin to Launcher") {
                                if let path = app.bundleURL?.path,
                                    let name = app.localizedName
                                {
                                    settings.pinApp(
                                        name: name, path: path,
                                        bundleIdentifier: app.bundleIdentifier)
                                }
                            }
                        Divider()
                        Button("Quit \(app.localizedName ?? "App")", role: .destructive) {
                                terminateRunningAppFromDock(app)
                        }
                        }
                    }
                }
            }
        }
    }

    private func currentRegularRunningApps() -> [NSRunningApplication] {
        NSWorkspace.shared.runningApplications.filter {
            $0.activationPolicy == .regular
                && $0.bundleIdentifier != Bundle.main.bundleIdentifier
                && !$0.isTerminated
        }
    }

    private struct DockPillItem: Identifiable {
        let id: String
        let index: Int
        let icon: NSImage?
        let label: String
        let subtitle: String?
        let hoverKey: String
        let action: () -> Void
        let destructiveAction: (() -> Void)?
        let removeAction: (() -> Void)?
    }

    private func buildAppCascadeItems(
        pinnedApps: [PinnedApp],
        runningApps: [NSRunningApplication],
        pinnedCount: Int
    ) -> [DockPillItem] {
        var items: [DockPillItem] = []
        for (idx, app) in pinnedApps.enumerated() {
            let c = app
            let isRunning = runningApp(for: app) != nil
            items.append(DockPillItem(
                id: "pinned-\(app.id)", index: idx,
                icon: resolvedPinnedIcon(for: app), label: app.name,
                subtitle: isRunning ? "Running" : "Launch",
                hoverKey: "dock-pinned-\(app.id.uuidString)",
                action: {
                    launchPinnedApp(c)
                    if isGlobalContextActive { scheduleContextDockTransition(bundleId: c.bundleIdentifier, appName: c.name) }
                },
                destructiveAction: nil,
                removeAction: { settings.unpinApp(c) }
            ))
        }
        for (off, app) in runningApps.enumerated() {
            let i = pinnedCount + off; let c = app
            items.append(DockPillItem(
                id: "running-\(app.processIdentifier)", index: i,
                icon: resolvedRunningAppIcon(for: app), label: app.localizedName ?? "App",
                subtitle: "Running",
                hoverKey: "dock-running-\(app.processIdentifier)",
                action: {
                    activateRunningAppFromDock(c)
                    if isGlobalContextActive { scheduleContextDockTransition(bundleId: c.bundleIdentifier, appName: c.localizedName ?? "App") }
                },
                destructiveAction: { terminateRunningAppFromDock(c) },
                removeAction: nil
            ))
        }
        return items
    }

    @ViewBuilder
    private var pinnedAndRecentAppsRow: some View {
        let pinnedPaths = Set(settings.pinnedApps.map { $0.path })
        let pinnedBundleIds = Set(settings.pinnedApps.compactMap { $0.bundleIdentifier })

        // The input field already represents the frontmost app in global context mode —
        // remove it from the pill row so it never appears twice.
        let inGlobalAutoFocus = isGlobalContextActive && settings.showRunningAppsInBar
        let searchQuery = searchState.query.trimmingCharacters(in: .whitespaces).lowercased()

        let dockApps: [NSRunningApplication] = {
            guard settings.showRunningAppsInBar else { return [] }
            let source =
                runningRegularApps.isEmpty ? currentRegularRunningApps() : runningRegularApps
            var seen = Set<String>()
            let filtered = source.filter { app in
                guard app.bundleIdentifier != Bundle.main.bundleIdentifier else { return false }
                // Input field already represents the frontmost — skip from pill row
                if inGlobalAutoFocus, app.bundleIdentifier == frontmost.bundleID { return false }
                if let path = app.bundleURL?.path, pinnedPaths.contains(path) { return false }
                if let bundleId = app.bundleIdentifier, pinnedBundleIds.contains(bundleId) {
                    return false
                }
                if !searchQuery.isEmpty,
                   !(app.localizedName ?? "").lowercased().contains(searchQuery) { return false }
                let key = app.bundleIdentifier ?? app.bundleURL?.path ?? "\(app.processIdentifier)"
                return seen.insert(key).inserted
            }
            return filtered
        }()

        // Pinned apps visible in the pill row (frontmost hidden when input field represents it)
        let basePinnedApps = inGlobalAutoFocus
            ? settings.pinnedApps.filter { $0.bundleIdentifier != frontmost.bundleID }
            : settings.pinnedApps
        let visiblePinnedApps = searchQuery.isEmpty
            ? basePinnedApps
            : basePinnedApps.filter { $0.name.lowercased().contains(searchQuery) }

        let pinnedCount = visiblePinnedApps.count

        // Auto-detect frontmost app index so global context highlights it without keyboard input.
        // Disabled when inGlobalAutoFocus — the input field is already the frontmost representation.
        let autoFrontmostIdx: Int? = {
            guard !inGlobalAutoFocus,
                  isGlobalContextActive, settings.showRunningAppsInBar,
                  focusedAppPillIndex == nil else { return nil }
            // Check pinned apps first
            if let i = visiblePinnedApps.firstIndex(where: {
                $0.bundleIdentifier == frontmost.bundleID }) { return i }
            // Check running apps list (using same order as dockApps above)
            if let i = dockApps.firstIndex(where: {
                $0.bundleIdentifier == frontmost.bundleID }) { return pinnedCount + i }
            return nil
        }()

        // Keyboard navigation (focusedAppPillIndex) takes priority; auto-detection is the fallback
        let focusedIdx = focusedAppPillIndex ?? autoFrontmostIdx

        if let kbIdx = focusedAppPillIndex {
            // ── Keyboard nav cascade: prev compact | FOCUSED expanded fills | next compact ──
            // Mirrors context dock action-pill cascade exactly.
            let allAppItems = buildAppCascadeItems(
                pinnedApps: visiblePinnedApps,
                runningApps: dockApps,
                pinnedCount: pinnedCount
            )
            let prevItem    = allAppItems.first(where: { $0.index == kbIdx - 1 })
            let focusedItem = allAppItems.first(where: { $0.index == kbIdx })
            let nextItem    = allAppItems.first(where: { $0.index == kbIdx + 1 })

            HStack(alignment: .top, spacing: 6) {
                if let p = prevItem {
                    appPillButton(icon: p.icon, label: p.label, subtitle: p.subtitle, hoverKey: p.hoverKey,
                                  focused: false, index: p.index, isExpanded: false,
                                  destructiveAction: p.destructiveAction, removeAction: p.removeAction, action: p.action)
                    .transition(.asymmetric(insertion: .opacity.combined(with: .scale(scale: 0.9)),
                                            removal:  .opacity.combined(with: .scale(scale: 0.9))))
                }
                if let f = focusedItem {
                    appPillButton(icon: f.icon, label: f.label, subtitle: f.subtitle, hoverKey: f.hoverKey,
                                  focused: true, index: f.index, isExpanded: true,
                                  destructiveAction: nil, removeAction: nil, action: f.action)
                    .frame(maxWidth: .infinity)
                    .transition(.opacity)
                }
                if let n = nextItem {
                    appPillButton(icon: n.icon, label: n.label, subtitle: n.subtitle, hoverKey: n.hoverKey,
                                  focused: false, index: n.index, isExpanded: false,
                                  destructiveAction: n.destructiveAction, removeAction: n.removeAction, action: n.action)
                    .transition(.asymmetric(insertion: .opacity.combined(with: .scale(scale: 0.9)),
                                            removal:  .opacity.combined(with: .scale(scale: 0.9))))
                }
            }
            .animation(.spring(response: 0.22, dampingFraction: 0.78), value: focusedAppPillIndex)
        } else {
            // ── Normal scrollable row — all apps visible, frontmost auto-highlighted ──
            ScrollViewReader { proxy in
                ScrollView(.horizontal, showsIndicators: false) {
                    HStack(spacing: 10) {
                        ForEach(Array(visiblePinnedApps.enumerated()), id: \.element.id) { idx, app in
                            appPillButton(
                                icon: resolvedPinnedIcon(for: app), label: app.name,
                                hoverKey: "dock-pinned-\(app.id.uuidString)",
                                focused: idx == focusedIdx, index: idx,
                                removeAction: { settings.unpinApp(app) },
                                action: {
                                    launchPinnedApp(app)
                                    if isGlobalContextActive { scheduleContextDockTransition(bundleId: app.bundleIdentifier, appName: app.name) }
                                }
                            )
                            .id("app-pill-\(idx)")
                            .scrollTransition(.interactive, axis: .horizontal) { effect, phase in
                                effect
                                    .rotation3DEffect(.degrees(phase.value * 22), axis: (x: 0, y: 1, z: 0), perspective: 0.45)
                                    .scaleEffect(max(0.78, 1 - abs(phase.value) * 0.18))
                                    .opacity(max(0.45, 1 - abs(phase.value) * 0.38))
                            }
                            .contextMenu {
                                Button { settings.unpinApp(app) } label: {
                                    Label("Unpin from Launcher", systemImage: "pin.slash")
                                }
                                Divider()
                                Button { launchPinnedApp(app) } label: {
                                    Label("Open", systemImage: "arrow.up.right.square")
                                }
                                if app.type == .folder {
                                    Button { NSWorkspace.shared.selectFile(app.path, inFileViewerRootedAtPath: "") } label: {
                                        Label("Show in Finder", systemImage: "folder")
                                    }
                                }
                            }
                        }

                        if !dockApps.isEmpty && !visiblePinnedApps.isEmpty {
                            Divider().frame(height: 28).padding(.horizontal, 2)
                        }

                        ForEach(Array(dockApps.enumerated()), id: \.element.processIdentifier) { offset, app in
                            let idx = pinnedCount + offset
                            appPillButton(
                                icon: resolvedRunningAppIcon(for: app), label: app.localizedName ?? "App",
                                hoverKey: "dock-running-\(app.processIdentifier)",
                                focused: idx == focusedIdx, index: idx,
                                destructiveAction: { terminateRunningAppFromDock(app) },
                                action: {
                                    activateRunningAppFromDock(app)
                                    if isGlobalContextActive { scheduleContextDockTransition(bundleId: app.bundleIdentifier, appName: app.localizedName ?? "App") }
                                }
                            )
                            .id("app-pill-\(idx)")
                            .scrollTransition(.interactive, axis: .horizontal) { effect, phase in
                                effect
                                    .rotation3DEffect(.degrees(phase.value * 22), axis: (x: 0, y: 1, z: 0), perspective: 0.45)
                                    .scaleEffect(max(0.78, 1 - abs(phase.value) * 0.18))
                                    .opacity(max(0.45, 1 - abs(phase.value) * 0.38))
                            }
                            .contextMenu {
                                Button {
                                    if let path = app.bundleURL?.path, let name = app.localizedName {
                                        settings.pinApp(name: name, path: path, bundleIdentifier: app.bundleIdentifier)
                                    }
                                } label: {
                                    Label("Pin to Launcher", systemImage: "pin")
                                }
                                Divider()
                                Button(role: .destructive) { terminateRunningAppFromDock(app) } label: {
                                    Label("Quit \(app.localizedName ?? "App")", systemImage: "xmark.circle")
                                }
                            }
                        }
                    }
                }
                .onChange(of: focusedAppPillIndex) { idx in
                    guard let idx else { return }
                    withAnimation(.spring(response: 0.25, dampingFraction: 0.82)) {
                        proxy.scrollTo("app-pill-\(idx)", anchor: .center)
                    }
                }
            }
        }
    }

    @ViewBuilder
    private func globalAppSearchPillRow(query: String, matches providedMatches: [SearchResult]? = nil) -> some View {
        let matches = providedMatches ?? globalApplicationMatches(for: query)

        let makeAction: (SearchResult) -> () -> Void = { result in
            {
                result.action()
                searchState.query = ""
                focusedAppPillIndex = nil
                let bundleId = result.filePath.flatMap { Bundle(path: $0)?.bundleIdentifier }
                scheduleContextDockTransition(bundleId: bundleId, appName: result.title)
                if let bid = bundleId { AppUsageLearner.shared.recordApp(bundleID: bid, appName: result.title) }
            }
        }
        let makeQuitAction: (SearchResult) -> (() -> Void)? = { result in
            guard let runningApp = runningApplication(forGlobalResult: result) else { return nil }
            return { terminateRunningAppFromDock(runningApp) }
        }

        let makePinAction: (SearchResult) -> (() -> Void)? = { result in
            guard let path = result.filePath, !settings.isPinned(path: path) else { return nil }
            return {
                let bid = Bundle(path: path)?.bundleIdentifier
                settings.pinApp(name: result.title, path: path, bundleIdentifier: bid)
                AppUsageLearner.shared.recordAction("pin:\(result.title)", inBundleID: nil)
            }
        }

        if matches.isEmpty {
            HStack {
                Text("No apps matching \"\(query)\"")
                    .font(.system(size: 12))
                    .foregroundStyle(.secondary.opacity(0.6))
                    .padding(.horizontal, 8)
            }
        } else if let focIdx = focusedAppPillIndex, focIdx < matches.count {
            // ── Keyboard nav: icon-anchor + prev(normal) + FOCUSED(expanded) + next(normal) ──
            let prev = focIdx > 0 ? matches[focIdx - 1] : nil
            let focused = matches[focIdx]
            let next = focIdx + 1 < matches.count ? matches[focIdx + 1] : nil

            HStack(alignment: .top, spacing: 6) {
                if let prev {
                    let pi = focIdx - 1
                    appPillButton(
                        icon: prev.icon, label: prev.title,
                        hoverKey: "gsearch-\(prev.title)", focused: false, index: pi,
                        isExpanded: false, destructiveAction: makeQuitAction(prev),
                        pinAction: makePinAction(prev), action: makeAction(prev)
                    )
                    .transition(.asymmetric(
                        insertion: .opacity.combined(with: .scale(scale: 0.9)),
                        removal: .opacity.combined(with: .scale(scale: 0.9))))
                }

                appPillButton(
                    icon: focused.icon, label: focused.title,
                    hoverKey: "gsearch-\(focused.title)", focused: true, index: focIdx,
                    isExpanded: true, destructiveAction: makeQuitAction(focused),
                    pinAction: makePinAction(focused), action: makeAction(focused)
                )
                .frame(maxWidth: .infinity)
                .transition(.opacity)

                if let next {
                    let ni = focIdx + 1
                    appPillButton(
                        icon: next.icon, label: next.title,
                        hoverKey: "gsearch-\(next.title)", focused: false, index: ni,
                        isExpanded: false, destructiveAction: makeQuitAction(next),
                        pinAction: makePinAction(next), action: makeAction(next)
                    )
                    .transition(.asymmetric(
                        insertion: .opacity.combined(with: .scale(scale: 0.9)),
                        removal: .opacity.combined(with: .scale(scale: 0.9))))
                }
            }
            .animation(.spring(response: 0.22, dampingFraction: 0.78), value: focIdx)
        } else {
            // ── Normal scrollable row ──
            ScrollViewReader { proxy in
                ScrollView(.horizontal, showsIndicators: false) {
                    HStack(spacing: 10) {
                        ForEach(Array(matches.enumerated()), id: \.element.title) { idx, result in
                            appPillButton(
                                icon: result.icon,
                                label: result.title,
                                hoverKey: "global-search-\(result.title)",
                                focused: false,
                                index: idx,
                                isExpanded: false,
                                destructiveAction: makeQuitAction(result),
                                pinAction: makePinAction(result),
                                action: makeAction(result)
                            )
                            .id("gsearch-pill-\(idx)")
                            .scrollTransition(.interactive, axis: .horizontal) { effect, phase in
                                effect
                                    .rotation3DEffect(
                                        .degrees(phase.value * 22),
                                        axis: (x: 0, y: 1, z: 0),
                                        perspective: 0.45
                                    )
                                    .scaleEffect(max(0.78, 1 - abs(phase.value) * 0.18))
                                    .opacity(max(0.45, 1 - abs(phase.value) * 0.38))
                            }
                        }
                    }
                }
                .onChange(of: focusedAppPillIndex) { idx in
                    guard let idx else { return }
                    withAnimation(.spring(response: 0.25, dampingFraction: 0.82)) {
                        proxy.scrollTo("gsearch-pill-\(idx)", anchor: .center)
                    }
                }
            }
        }
    }

    private func globalAppSearchListView(
        query: String,
        matches providedMatches: [SearchResult]? = nil,
        menuPills providedMenuPills: [DockPill] = [],
        appMenuGroups providedAppMenuGroups: [AppMenuGroup] = [],
        launchHint: (bundleId: String, appName: String, appPath: String?)? = nil,
        scopedMenuAppName: String? = nil,
        scopedMenuActionQuery: String = "",
        menuFirst: Bool = false
    ) -> some View {
        let rawMatches = Array((providedMatches ?? globalApplicationMatches(for: query)).prefix(maxListViewDockPills))
        let scopedMenuAppName = scopedMenuAppName?.trimmingCharacters(in: .whitespacesAndNewlines)
        let isScopedMenuMode = scopedMenuAppName?.isEmpty == false
        let scopedMenuActionQuery = scopedMenuActionQuery.trimmingCharacters(in: .whitespacesAndNewlines)
        let candidateMenuPills = providedMenuPills
            .filter { !$0.isSeparator }
            .filter { $0.rankingKind != "appLaunch" }
            .filter { !$0.name.lowercased().hasPrefix("open ") || rawMatches.isEmpty }
        // Count all menu pills (frontmost/scoped + cross-app) to match the nav state's appLimit formula.
        // When cross-app groups exist, candidateMenuPills is empty (menuGroups=[]) so without this
        // the view includes more app results than the nav state, causing index mismatches and missing highlights.
        let totalMenuPillCount = candidateMenuPills.count + providedAppMenuGroups.flatMap(\.pills).count
        let appLimit =
            totalMenuPillCount == 0
            ? maxListViewDockPills
            : min(rawMatches.count, max(8, maxListViewDockPills - min(totalMenuPillCount, 12)))
        let limitedMatches = Array(rawMatches.prefix(appLimit))
        let matches =
            limitedMatches.filter { runningApplication(forGlobalResult: $0) != nil }
            + limitedMatches.filter { runningApplication(forGlobalResult: $0) == nil }
        let indexedMatches = Array(matches.enumerated())
        // In global context, isEnabled reflects AX state of whatever app was frontmost at
        // snapshot time — meaningless here. Force enabled so no "Unavailable" badge shows.
        let visibleMenuPills = Array(
            candidateMenuPills.prefix(matches.isEmpty ? maxListViewDockPills : max(0, maxListViewDockPills - matches.count))
        ).map { pill -> DockPill in var p = pill; p.isEnabled = true; return p }
        let menuGroups = groupMenuPillsByTitle(visibleMenuPills)
        let showLaunchHint = launchHint != nil && visibleMenuPills.isEmpty
        let isEmpty = matches.isEmpty && visibleMenuPills.isEmpty && providedAppMenuGroups.isEmpty && !showLaunchHint
        let listHeight: CGFloat = isEmpty ? 58 : listViewVisibleHeight

        let makeAction: (SearchResult) -> () -> Void = { result in
            {
                let q = searchState.query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
                result.action()
                searchState.query = ""
                focusedAppPillIndex = nil
                hoveredAppPillIndex = nil
                let bundleId = result.filePath.flatMap { Bundle(path: $0)?.bundleIdentifier }
                scheduleContextDockTransition(bundleId: bundleId, appName: result.title)
                if let bid = bundleId {
                    AppUsageLearner.shared.recordApp(bundleID: bid, appName: result.title)
                }
                // Teach intent: user picked an app for this query
                if !q.isEmpty { AppUsageLearner.shared.recordQueryIntent(query: q, wasMenu: false) }
            }
        }
        let makeQuitAction: (SearchResult) -> (() -> Void)? = { result in
            guard let runningApp = runningApplication(forGlobalResult: result) else { return nil }
            return { terminateRunningAppFromDock(runningApp) }
        }
        let makePinAction: (SearchResult) -> (() -> Void)? = { result in
            guard let path = result.filePath, !settings.isPinned(path: path) else { return nil }
            return {
                let bid = Bundle(path: path)?.bundleIdentifier
                settings.pinApp(name: result.title, path: path, bundleIdentifier: bid)
                AppUsageLearner.shared.recordAction("pin:\(result.title)", inBundleID: nil)
            }
        }

        return ScrollViewReader { proxy in
            ScrollView(.vertical, showsIndicators: false) {
                LazyVStack(spacing: 2) {
                    if matches.isEmpty && visibleMenuPills.isEmpty && providedAppMenuGroups.isEmpty {
                        HStack {
                            Text(
                                isScopedMenuMode
                                ? (
                                    scopedMenuActionQuery.isEmpty
                                    ? "No cached menus for \(scopedMenuAppName ?? "this app")"
                                    : "No \(scopedMenuAppName ?? "app") menus matching \"\(scopedMenuActionQuery)\""
                                )
                                : "No apps matching \"\(query)\""
                            )
                                .font(.system(size: 13, weight: .medium))
                                .foregroundStyle(.secondary.opacity(0.65))
                            Spacer()
                        }
                        .padding(.horizontal, 12)
                        .padding(.vertical, 14)
                    }

                    // When intent favours a menu action, surface menus above app results.
                    if menuFirst {
                        if !menuGroups.isEmpty {
                            resultGroupHeader(isScopedMenuMode ? "\(scopedMenuAppName ?? "App") Menus" : "Menus")
                        }
                        ForEach(Array(menuGroups.enumerated()), id: \.element.id) { idx, group in
                            if group.isGrouped {
                                groupedMenuPillRow(group: group, index: matches.count + idx)
                                    .id("global-menu-list-\(idx)")
                            } else {
                                pillListRow(pill: group.primaryPill, index: matches.count + idx)
                                    .id("global-menu-list-\(idx)")
                            }
                        }
                    }

                    if !indexedMatches.isEmpty {
                        resultGroupHeader("Apps")
                    }
                    ForEach(indexedMatches, id: \.element.id) { idx, result in
                        let isRunning = runningApplication(forGlobalResult: result) != nil
                        appListRow(
                            icon: result.icon,
                            name: result.title,
                            subtitle: isRunning ? "Running" : (settings.isPinned(path: result.filePath ?? result.subtitle) ? "Pinned" : "Open"),
                            index: idx,
                            quitAction: isRunning ? makeQuitAction(result) : nil,
                            action: makeAction(result)
                        )
                        .id("global-app-list-\(idx)")
                        .contextMenu {
                            if let pinAction = makePinAction(result) {
                                Button(action: pinAction) {
                                    Label("Pin to Launcher", systemImage: "pin")
                                }
                            }
                            if let quitAction = makeQuitAction(result) {
                                Divider()
                                Button(role: .destructive, action: quitAction) {
                                    Label("Quit \(result.title)", systemImage: "xmark.circle")
                                }
                            }
                        }
                    }

                    if !menuFirst {
                        if !menuGroups.isEmpty {
                            resultGroupHeader(isScopedMenuMode ? "\(scopedMenuAppName ?? "App") Menus" : "Menus")
                        }
                        ForEach(Array(menuGroups.enumerated()), id: \.element.id) { idx, group in
                            if group.isGrouped {
                                groupedMenuPillRow(group: group, index: matches.count + idx)
                                    .id("global-menu-list-\(idx)")
                            } else {
                                pillListRow(pill: group.primaryPill, index: matches.count + idx)
                                    .id("global-menu-list-\(idx)")
                            }
                        }
                    }

                    // Cross-app menus grouped by source app.
                    // Each group shows app icon + name header, then matching menu pills below.
                    if !providedAppMenuGroups.isEmpty {
                        let crossBase = matches.count + menuGroups.count
                        let groupStartIndices: [String: Int] = {
                            var d: [String: Int] = [:]
                            var offset = 0
                            for g in providedAppMenuGroups { d[g.id] = crossBase + offset; offset += g.pills.count }
                            return d
                        }()
                        ForEach(providedAppMenuGroups) { group in
                            let groupBase = groupStartIndices[group.id] ?? crossBase
                            resultGroupHeader(group.appName, icon: group.icon)
                            ForEach(Array(group.pills.enumerated()), id: \.element.id) { pillIdx, pill in
                                pillListRow(pill: pill, index: groupBase + pillIdx)
                                    .id("xapp-pill-\(group.id)-\(pillIdx)")
                            }
                        }
                    }

                    // No cached menus + app not running: invite user to open it once so menus get snapshotted.
                    if showLaunchHint, let hint = launchHint {
                        Button {
                            if let path = hint.appPath {
                                NSWorkspace.shared.openApplication(
                                    at: URL(fileURLWithPath: path),
                                    configuration: .init()
                                )
                            } else {
                                NSWorkspace.shared.launchApplication(withBundleIdentifier: hint.bundleId,
                                    options: [], additionalEventParamDescriptor: nil, launchIdentifier: nil)
                            }
                            searchState.query = ""
                        } label: {
                            HStack(spacing: 12) {
                                if let path = hint.appPath {
                                    Image(nsImage: NSWorkspace.shared.icon(forFile: path))
                                        .resizable().aspectRatio(contentMode: .fit)
                                        .frame(width: 32, height: 32)
                                } else {
                                    Image(systemName: "app.badge.checkmark")
                                        .font(.system(size: 20))
                                        .foregroundStyle(.secondary)
                                        .frame(width: 32, height: 32)
                                }
                                VStack(alignment: .leading, spacing: 2) {
                                    Text("Open \(hint.appName) to enable menu search")
                                        .font(.system(size: 13, weight: .medium))
                                        .foregroundStyle(.primary)
                                    Text("Menus are cached after first launch")
                                        .font(.system(size: 11))
                                        .foregroundStyle(.secondary)
                                }
                                Spacer()
                                Image(systemName: "arrow.up.right")
                                    .font(.system(size: 11, weight: .medium))
                                    .foregroundStyle(.tertiary)
                            }
                            .padding(.horizontal, 8)
                            .padding(.vertical, 10)
                        }
                        .buttonStyle(.plain)
                        .transition(.opacity)
                    }
                }
                .padding(6)
                .frame(maxWidth: .infinity, alignment: .topLeading)
            }
            .frame(maxWidth: .infinity, alignment: .topLeading)
            .frame(height: listHeight, alignment: .topLeading)
            .clipShape(RoundedRectangle(cornerRadius: 14, style: .continuous))
            .onChange(of: focusedAppPillIndex) { idx in
                guard let idx else { return }
                withAnimation(.spring(response: 0.22, dampingFraction: 0.82)) {
                    proxy.scrollTo("global-app-list-\(idx)", anchor: .center)
                }
            }
            .onChange(of: l2.focusedPillIndex) { idx in
                guard let idx, idx >= matches.count else { return }
                let menuIdx = idx - matches.count
                if menuIdx >= 0, menuIdx < visibleMenuPills.count {
                    withAnimation(.spring(response: 0.22, dampingFraction: 0.82)) {
                        proxy.scrollTo("global-menu-list-\(menuIdx)", anchor: .center)
                    }
                } else if menuIdx >= menuGroups.count {
                    // Cross-app group pill — find which group and local index
                    let crossIdx = menuIdx - menuGroups.count
                    var offset = 0
                    for group in providedAppMenuGroups {
                        let localIdx = crossIdx - offset
                        if localIdx < group.pills.count {
                            withAnimation(.spring(response: 0.22, dampingFraction: 0.82)) {
                                proxy.scrollTo("xapp-pill-\(group.id)-\(localIdx)", anchor: .center)
                            }
                            break
                        }
                        offset += group.pills.count
                    }
                }
            }
            .onChange(of: matches.count) { count in
                guard let idx = focusedAppPillIndex else { return }
                let totalCount = count + visibleMenuPills.count
                if totalCount <= 0 {
                    focusedAppPillIndex = nil
                    l2.focusedPillIndex = nil
                    l2.pillNavViaKeyboard = false
                } else if idx >= totalCount {
                    focusedAppPillIndex = totalCount - 1
                }
            }
        }
    }

    private func resolvedPinnedIcon(for app: PinnedApp) -> NSImage? {
        if app.type == .application {
            if let bundleId = app.bundleIdentifier,
                let runningURL = runningRegularApps.first(where: {
                    $0.bundleIdentifier == bundleId
                })?.bundleURL
            {
                return preparedDockIcon(NSWorkspace.shared.icon(forFile: runningURL.path))
            }
            if let bundleId = app.bundleIdentifier,
                let appURL = NSWorkspace.shared.urlForApplication(withBundleIdentifier: bundleId)
            {
                return preparedDockIcon(NSWorkspace.shared.icon(forFile: appURL.path))
            }
        }

        return preparedDockIcon(NSWorkspace.shared.icon(forFile: app.path))
    }

    private func globalApplicationMatches(for query: String, limit: Int = Int.max) -> [SearchResult] {
        let q = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard !q.isEmpty else { return [] }

        if isGenericApplicationListQuery(q) {
            return groupedGlobalApplicationList(limit: limit)
        }

        var candidates: [(result: SearchResult, score: Double, order: Int)] = []
        var seen = Set<String>()
        var order = 0

        func add(_ result: SearchResult, bundleIdentifier explicitBundleId: String? = nil) {
            let bundleId = explicitBundleId ?? bundleIdentifier(forApplicationResult: result)
            guard let score = appSearchMatchScore(
                query: q,
                appName: result.title,
                bundleIdentifier: bundleId
            ) else { return }

            let key = bundleId ?? result.filePath ?? result.title.lowercased()
            guard seen.insert(key).inserted else { return }
            // Cross-register the file path so a later path-keyed entry for the same app is blocked.
            if let bid = bundleId, !bid.isEmpty, let path = result.filePath, !path.isEmpty, path != bid {
                seen.insert(path)
            }
            var enriched = result
            enriched.score = score
            candidates.append((enriched, score, order))
            order += 1
        }

        for app in settings.pinnedApps where app.type == .application {
            guard !shouldIgnoreApplicationFromAppSearch(
                appName: app.name,
                bundleIdentifier: app.bundleIdentifier,
                path: app.path
            ) else { continue }
            let path = app.path
            let title = app.name
            add(SearchResult(
                title: title,
                subtitle: path,
                icon: resolvedPinnedIcon(for: app),
                action: { launchPinnedApp(app) },
                type: .application,
                filePath: path,
                contactData: nil
            ), bundleIdentifier: app.bundleIdentifier)
        }

        // Recent apps from macOS Recent Items — higher signal than full installed list.
        // Deduped by seen set; running/pinned apps already inserted win on action (activate vs open).
        if isGlobalContextActive {
            for recent in RecentItemsService.shared.recentApplications() {
                guard !shouldIgnoreApplicationFromAppSearch(
                    appName: recent.name,
                    bundleIdentifier: recent.bundleId,
                    path: recent.url.path
                ) else { continue }
                let capturedURL = recent.url
                add(SearchResult(
                    title: recent.name,
                    subtitle: recent.url.path,
                    icon: recent.icon,
                    action: { NSWorkspace.shared.openApplication(at: capturedURL, configuration: .init()) },
                    type: .application,
                    filePath: recent.url.path,
                    contactData: nil
                ), bundleIdentifier: recent.bundleId)
            }
        }

        let runningSource = runningRegularApps.isEmpty ? currentRegularRunningApps() : runningRegularApps
        for app in runningSource {
            guard let name = app.localizedName else { continue }
            guard !shouldIgnoreApplicationFromAppSearch(
                appName: name,
                bundleIdentifier: app.bundleIdentifier,
                path: app.bundleURL?.path
            ) else { continue }
            let path = app.bundleURL?.path
            add(SearchResult(
                title: name,
                subtitle: path ?? "Running",
                icon: resolvedRunningAppIcon(for: app),
                action: { activateRunningAppFromDock(app) },
                type: .application,
                filePath: path,
                contactData: nil
            ), bundleIdentifier: app.bundleIdentifier)
        }

        let installedMatches = allApplications
            .filter {
                $0.type == .application
                    && !shouldIgnoreApplicationFromAppSearch(
                        appName: $0.title,
                        bundleIdentifier: Bundle(url: URL(fileURLWithPath: $0.subtitle))?.bundleIdentifier,
                        path: $0.subtitle
                    )
            }

        for app in installedMatches {
            add(app)
        }

        let builtInAppTargets: [(name: String, bundleId: String, path: String)] = [
            ("Safari", "com.apple.Safari", "/Applications/Safari.app"),
            ("Notes", "com.apple.Notes", "/System/Applications/Notes.app"),
            ("Messages", "com.apple.MobileSMS", "/System/Applications/Messages.app"),
            ("Mail", "com.apple.mail", "/System/Applications/Mail.app"),
            ("Calendar", "com.apple.iCal", "/System/Applications/Calendar.app"),
            ("Reminders", "com.apple.reminders", "/System/Applications/Reminders.app"),
            ("Photos", "com.apple.Photos", "/System/Applications/Photos.app"),
            ("Contacts", "com.apple.AddressBook", "/System/Applications/Contacts.app"),
            ("System Settings", "com.apple.systempreferences", "/System/Applications/System Settings.app"),
            ("FaceTime", "com.apple.FaceTime", "/System/Applications/FaceTime.app"),
            ("Freeform", "com.apple.freeform", "/System/Applications/Freeform.app"),
            ("Maps", "com.apple.Maps", "/System/Applications/Maps.app"),
            ("Music", "com.apple.Music", "/System/Applications/Music.app"),
            ("QuickTime Player", "com.apple.QuickTimePlayerX", "/System/Applications/QuickTime Player.app")
        ]
        for target in builtInAppTargets {
            let path =
                NSWorkspace.shared.urlForApplication(withBundleIdentifier: target.bundleId)?.path
                ?? target.path
            guard !shouldIgnoreApplicationFromAppSearch(
                appName: target.name,
                bundleIdentifier: target.bundleId,
                path: path
            ) else { continue }
            add(SearchResult(
                title: target.name,
                subtitle: path,
                icon: resolvedApplicationIcon(bundleIdentifier: target.bundleId, appName: target.name)
                    ?? preparedDockIcon(NSWorkspace.shared.icon(forFile: path)),
                action: {
                    if let url = NSWorkspace.shared.urlForApplication(withBundleIdentifier: target.bundleId) {
                        NSWorkspace.shared.openApplication(at: url, configuration: NSWorkspace.OpenConfiguration())
                    } else {
                        NSWorkspace.shared.open(URL(fileURLWithPath: path))
                    }
                },
                type: .application,
                filePath: path,
                contactData: nil
            ), bundleIdentifier: target.bundleId)
        }

        // Recent documents from macOS Recent Items — cross-app files.
        // Only included when query is long enough (≥2 chars) to reduce noise.
        if isGlobalContextActive, q.count >= 2 {
            for doc in RecentItemsService.shared.recentDocuments() {
                let docName = doc.name.lowercased()
                guard docName.contains(q) || docName.hasPrefix(q) else { continue }
                let capturedURL = doc.url
                let key = doc.url.path
                guard seen.insert(key).inserted else { continue }
                let score: Double = docName.hasPrefix(q) ? 2_500 - Double(docName.count) : 1_800
                var result = SearchResult(
                    title: doc.name,
                    subtitle: doc.url.deletingLastPathComponent().path,
                    icon: doc.icon,
                    action: { NSWorkspace.shared.open(capturedURL) },
                    type: .document,
                    filePath: doc.url.path,
                    contactData: nil
                )
                result.score = score
                candidates.append((result, score, order))
                order += 1
            }
        }

        return Array(
            candidates
                .sorted {
                    if $0.score != $1.score { return $0.score > $1.score }
                    if $0.result.title.count != $1.result.title.count {
                        return $0.result.title.count < $1.result.title.count
                    }
                    return $0.order < $1.order
                }
                .map(\.result)
                .prefix(limit)
        )
    }

    private func groupedGlobalApplicationList(limit: Int) -> [SearchResult] {
        var results: [SearchResult] = []
        var seen = Set<String>()

        func bundleIdentifier(for path: String?) -> String? {
            guard let path, !path.isEmpty else { return nil }
            return Bundle(url: URL(fileURLWithPath: path))?.bundleIdentifier
        }

        func add(_ result: SearchResult) {
            guard results.count < limit else { return }
            let bundleId = bundleIdentifier(for: result.filePath ?? result.subtitle)
            guard !shouldIgnoreApplicationFromAppSearch(
                appName: result.title,
                bundleIdentifier: bundleId,
                path: result.filePath ?? result.subtitle
            ) else { return }

            let key = bundleId ?? result.filePath ?? result.subtitle.lowercased()
            guard seen.insert(key).inserted else { return }
            results.append(result)
        }

        let runningSource = runningRegularApps.isEmpty ? currentRegularRunningApps() : runningRegularApps
        for app in runningSource where results.count < limit {
            guard let name = app.localizedName else { continue }
            let path = app.bundleURL?.path
            let bundleId = app.bundleIdentifier
            guard !shouldIgnoreApplicationFromAppSearch(
                appName: name,
                bundleIdentifier: bundleId,
                path: path
            ) else { continue }

            let key = bundleId ?? path ?? name.lowercased()
            guard seen.insert(key).inserted else { continue }
            results.append(SearchResult(
                title: name,
                subtitle: path ?? "Running",
                icon: resolvedRunningAppIcon(for: app),
                action: { activateRunningAppFromDock(app) },
                type: .application,
                filePath: path,
                contactData: nil
            ))
        }

        for app in settings.pinnedApps where app.type == .application {
            add(SearchResult(
                title: app.name,
                subtitle: app.path,
                icon: resolvedPinnedIcon(for: app),
                action: { launchPinnedApp(app) },
                type: .application,
                filePath: app.path,
                contactData: nil
            ))
        }

        for app in allApplications where app.type == .application {
            add(app)
        }

        return results
    }

    private func runningApplication(forGlobalResult result: SearchResult) -> NSRunningApplication? {
        let source = runningRegularApps.isEmpty ? currentRegularRunningApps() : runningRegularApps

        if let path = result.filePath {
            if let bundleId = Bundle(path: path)?.bundleIdentifier,
                let match = source.first(where: { $0.bundleIdentifier == bundleId }) {
                return match
            }
            if let match = source.first(where: { $0.bundleURL?.path == path }) {
                return match
            }
        }

        return source.first {
            $0.localizedName?.compare(
                result.title,
                options: [.caseInsensitive, .diacriticInsensitive]
            ) == .orderedSame
        }
    }

    private func resolvedApplicationIcon(bundleIdentifier: String?, appName: String? = nil)
        -> NSImage?
    {
        if let bundleIdentifier, !bundleIdentifier.isEmpty {
            if let runningURL = runningRegularApps.first(where: {
                $0.bundleIdentifier == bundleIdentifier
            })?.bundleURL {
                return preparedDockIcon(NSWorkspace.shared.icon(forFile: runningURL.path))
            }
            if let appURL = NSWorkspace.shared.urlForApplication(
                withBundleIdentifier: bundleIdentifier)
            {
                return preparedDockIcon(NSWorkspace.shared.icon(forFile: appURL.path))
            }
        }

        guard let appName, !appName.isEmpty else { return nil }
        if let result = allApplications.first(where: {
            $0.title.compare(appName, options: [.caseInsensitive, .diacriticInsensitive])
                == .orderedSame
        }) {
            return preparedDockIcon(result.icon)
        }

        let appDirectories = [
            "/Applications",
            "/System/Applications",
            "/System/Volumes/Preboot/Cryptexes/App/System/Applications",
            "\(NSHomeDirectory())/Applications",
        ]
        let fileManager = FileManager.default
        for directory in appDirectories {
            let url = URL(fileURLWithPath: directory)
                .appendingPathComponent(appName)
                .appendingPathExtension("app")
            if fileManager.fileExists(atPath: url.path) {
                return preparedDockIcon(NSWorkspace.shared.icon(forFile: url.path))
            }
        }

        return nil
    }

    private func typedL2AppIcon(for query: String) -> (icon: NSImage, bundleId: String)? {
        let trimmed = query.trimmingCharacters(in: .whitespacesAndNewlines)
        guard isL2ContextActive, isGlobalContextActive, !trimmed.isEmpty else { return nil }

        let normalized = trimmed.lowercased()
        let installedScopeMode = contextDockInstalledAppScopeMatching
        let dockOnlyMode = contextDockRunningOnlyAppMatching && !installedScopeMode
        let runningBundleIds = runningBundleIdsForContextDock()
        if let target = L2AppActionRouter.shared.appScopeTarget(for: normalized),
            (!dockOnlyMode || runningBundleIds.contains(target.bundleId)),
            let icon = resolvedApplicationIcon(
                bundleIdentifier: target.bundleId, appName: target.appName)
        {
            return (icon, target.bundleId)
        }

        if let target = installedAppMenuTarget(
            for: normalized,
            runningOnly: dockOnlyMode,
            includeAppsWithoutMenuSnapshot: installedScopeMode,
            allowPrefixAlias: installedScopeMode
        ),
            let icon = resolvedApplicationIcon(
                bundleIdentifier: target.bundleId,
                appName: target.appName
            ) ?? preparedDockIcon(NSWorkspace.shared.icon(forFile: target.appPath))
        {
            return (icon, target.bundleId)
        }

        if let completion = l2.appCompletion,
            let icon = resolvedApplicationIcon(
                bundleIdentifier: completion.bundleId, appName: completion.appName)
        {
            return (icon, completion.bundleId)
        }

        if let completion = bestL2PartialAppCompletion(for: normalized, runningOnly: dockOnlyMode),
            let icon = resolvedApplicationIcon(
                bundleIdentifier: completion.bundleId,
                appName: completion.appName
            )
                ?? installedApplicationResult(bundleIdentifier: completion.bundleId)?.icon
                    .flatMap(preparedDockIcon)
        {
            return (icon, completion.bundleId)
        }

        guard let firstToken = normalized.split(separator: " ").first,
              firstToken.count >= (dockOnlyMode ? 3 : 2)
        else { return nil }
        let first = String(firstToken)
        if dockOnlyMode {
            let runningSource = runningRegularApps.isEmpty ? currentRegularRunningApps() : runningRegularApps
            if let app = runningSource.first(where: { app in
                guard let name = app.localizedName?.lowercased() else { return false }
                return name == first || name.hasPrefix(first)
            }), let bundleId = app.bundleIdentifier,
               let icon = resolvedRunningAppIcon(for: app) {
                return (icon, bundleId)
            }
            return nil
        }
        let appMatch = allApplications.first { result in
            let title = result.title.lowercased()
            let bundleId = Bundle(url: URL(fileURLWithPath: result.subtitle))?.bundleIdentifier
            return title == first
                || (
                    title.hasPrefix(first)
                        && shouldAllowShortAppPrefixMatch(
                            prefix: first,
                            appName: result.title,
                            bundleIdentifier: bundleId
                        )
                )
        }
        guard let appMatch else { return nil }

        let bundleId =
            Bundle(url: URL(fileURLWithPath: appMatch.subtitle))?.bundleIdentifier
            ?? appMatch.subtitle
        if let icon = resolvedApplicationIcon(bundleIdentifier: bundleId, appName: appMatch.title)
            ?? preparedDockIcon(appMatch.icon)
        {
            return (icon, bundleId)
        }
        return nil
    }

    private func globalScopedAppIcon(for query: String) -> (icon: NSImage, bundleId: String)? {
        guard isL2ContextActive, isGlobalContextActive, !hasActiveDockContextSelection else { return nil }
        let scope = resolveDockScope(for: query)
        guard scope.isExplicitAppScope, !scope.scopedBundleId.isEmpty else { return nil }
        let appPath =
            allApplications.first { result in
                Bundle(url: URL(fileURLWithPath: result.subtitle))?.bundleIdentifier == scope.scopedBundleId
            }?.subtitle
            ?? NSWorkspace.shared.urlForApplication(withBundleIdentifier: scope.scopedBundleId)?.path
        let icon =
            resolvedApplicationIcon(bundleIdentifier: scope.scopedBundleId, appName: scope.scopedAppName)
            ?? appPath.map { preparedDockIcon(NSWorkspace.shared.icon(forFile: $0)) } ?? nil
        guard let icon else { return nil }
        return (icon, scope.scopedBundleId)
    }

    private func bestL2PartialAppCompletion(
        for query: String, runningOnly: Bool = false
    ) -> AppCompletion? {
        let rawTrimmed = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        // Strip .app suffix so "Clock.app" completes the same as "Clock"
        let trimmed = rawTrimmed.hasSuffix(".app")
            ? String(rawTrimmed.dropLast(4)).trimmingCharacters(in: .whitespacesAndNewlines)
            : rawTrimmed
        guard trimmed.count >= (runningOnly ? 3 : 2) else { return nil }
        let runningBundleIds: Set<String>? = runningOnly
            ? Set(NSWorkspace.shared.runningApplications.compactMap { $0.bundleIdentifier })
            : nil

        if !runningOnly, "clipboard".hasPrefix(trimmed) && trimmed != "clipboard" {
            return AppCompletion(
                appName: "Clipboard",
                bundleId: "scope://clipboard",
                ghost: String("clipboard".dropFirst(trimmed.count)),
                actionQuery: ""
            )
        }

        if let routerCompletion = L2AppActionRouter.shared.partialAppCompletion(for: trimmed),
           runningBundleIds == nil || runningBundleIds?.contains(routerCompletion.bundleId) == true {
            return routerCompletion
        }

        let tokens = trimmed.split(separator: " ").map(String.init)
        guard let firstToken = tokens.first, firstToken.count >= (runningOnly ? 3 : 2) else { return nil }
        let actionQuery = tokens.dropFirst().joined(separator: " ")
        guard shouldAllowLocalAppPartialCompletion(
            fullQuery: trimmed,
            firstToken: firstToken,
            actionQuery: actionQuery
        ) else { return nil }

        func normalizeAppAlias(_ text: String) -> String {
            text.lowercased()
                .replacingOccurrences(of: "[^a-z0-9]+", with: " ", options: .regularExpression)
                .trimmingCharacters(in: .whitespacesAndNewlines)
        }

        var best: (appName: String, bundleId: String, ghost: String, actionQuery: String, score: Double)?

        for result in allApplications where result.type == .application {
            let appName = result.title.trimmingCharacters(in: .whitespacesAndNewlines)
            let appPath = result.subtitle.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !appName.isEmpty, !appPath.isEmpty else { continue }

            let bundleId = Bundle(url: URL(fileURLWithPath: appPath))?.bundleIdentifier ?? appPath
            // In context dock mode: skip apps that aren't currently running
            if let runningBundleIds, !runningBundleIds.contains(bundleId) { continue }
            let normalizedName = normalizeAppAlias(appName)
            guard !normalizedName.isEmpty else { continue }

            var aliases = Set<String>()
            aliases.insert(normalizedName)
            if let first = normalizedName.split(separator: " ").first {
                aliases.insert(String(first))
            }
            if normalizedName.hasSuffix("s"), normalizedName.count > 3 {
                aliases.insert(String(normalizedName.dropLast()))
            }

            for alias in aliases {
                let aliasTokens = alias.split(separator: " ").map(String.init)
                guard let firstAliasToken = aliasTokens.first else { continue }
                guard firstAliasToken.hasPrefix(firstToken), firstAliasToken != firstToken else {
                    continue
                }
                guard shouldAllowShortAppPrefixMatch(
                    prefix: firstToken,
                    appName: appName,
                    bundleIdentifier: bundleId
                ) else { continue }

                let ghost = String(alias.dropFirst(firstToken.count))
                let aliasUsage = UsageTracker.shared.getScore(for: "app:\(appPath)") / 100.0
                let exactFirstTokenBonus = firstAliasToken == normalizedName ? 0.4 : 0.0
                let score = Double(firstAliasToken.count) + aliasUsage + exactFirstTokenBonus

                if best == nil || score > best!.score {
                    best = (appName, bundleId, ghost, actionQuery, score)
                }
            }
        }

        guard let best else { return nil }
        return AppCompletion(
            appName: best.appName,
            bundleId: best.bundleId,
            ghost: best.ghost,
            actionQuery: best.actionQuery
        )
    }

    private func installedApplicationResult(bundleIdentifier: String) -> SearchResult? {
        allApplications.first { result in
            result.type == .application
                && Bundle(url: URL(fileURLWithPath: result.subtitle))?.bundleIdentifier
                    == bundleIdentifier
        }
    }

    private func launchTypedAppMatchIfNeeded() -> Bool {
        let trimmed = searchState.query.trimmingCharacters(in: .whitespacesAndNewlines)
        let normalized = trimmed.lowercased()
        guard normalized.count >= 2 else { return false }
        guard !(isL2ContextActive && !isGlobalContextActive) else { return false }

        let installedScopeMode = contextDockInstalledAppScopeMatching
        let runningOnly = contextDockRunningOnlyAppMatching && !installedScopeMode
        let runningBundleIds = runningOnly ? runningBundleIdsForContextDock() : []

        if let target = L2AppActionRouter.shared.appScopeTarget(for: normalized),
            (!runningOnly || runningBundleIds.contains(target.bundleId)),
            target.actionQuery.isEmpty
        {
            return launchApplication(
                bundleIdentifier: target.bundleId,
                appName: target.appName
            )
        }

        if let target = installedAppMenuTarget(
            for: normalized,
            runningOnly: runningOnly,
            includeAppsWithoutMenuSnapshot: installedScopeMode,
            allowPrefixAlias: installedScopeMode
        ),
            target.actionQuery.isEmpty
        {
            return launchApplication(
                bundleIdentifier: target.bundleId,
                appName: target.appName,
                path: target.appPath
            )
        }

        guard !normalized.contains(" ") else { return false }
        let shouldUsePrefixMatch = (runningOnly ? 3...3 : 2...3).contains(normalized.count)

        if isL2ContextActive,
            let completion = l2.appCompletion ?? bestL2PartialAppCompletion(for: normalized, runningOnly: runningOnly),
            completion.actionQuery.isEmpty,
            !completion.ghost.isEmpty
        {
            return launchApplication(
                bundleIdentifier: completion.bundleId, appName: completion.appName)
        }

        if shouldUsePrefixMatch,
            let completion = bestL2PartialAppCompletion(for: normalized, runningOnly: runningOnly),
            completion.actionQuery.isEmpty
        {
            return launchApplication(
                bundleIdentifier: completion.bundleId, appName: completion.appName)
        }

        if let result = allApplications.first(where: { result in
            guard !runningOnly else { return false }
            let title = result.title.lowercased()
            return title == normalized
                || (
                    shouldUsePrefixMatch
                        && title.hasPrefix(normalized)
                        && shouldAllowShortAppPrefixMatch(
                            prefix: normalized,
                            appName: result.title,
                            bundleIdentifier: Bundle(url: URL(fileURLWithPath: result.subtitle))?
                                .bundleIdentifier
                        )
                )
        }) {
            let bundleId = Bundle(url: URL(fileURLWithPath: result.subtitle))?.bundleIdentifier
            return launchApplication(
                bundleIdentifier: bundleId, appName: result.title, path: result.subtitle)
        }

        if let app = runningRegularApps.first(where: { app in
            guard let name = app.localizedName?.lowercased() else { return false }
            return name == normalized
                || (
                    shouldUsePrefixMatch
                        && name.hasPrefix(normalized)
                        && shouldAllowShortAppPrefixMatch(
                            prefix: normalized,
                            appName: app.localizedName ?? "",
                            bundleIdentifier: app.bundleIdentifier
                        )
                )
        }) {
            return launchApplication(
                bundleIdentifier: app.bundleIdentifier,
                appName: app.localizedName,
                path: app.bundleURL?.path
            )
        }

        return false
    }

    private func launchApplication(bundleIdentifier: String?, appName: String?, path: String? = nil)
        -> Bool
    {
        // Track launch for usage-based completion ranking
        if let bid = bundleIdentifier, !bid.isEmpty {
            AppLaunchTracker.shared.record(bundleId: bid)
        }

        if let path, !path.isEmpty {
            openApplicationKeepingDockFocus(
                URL(fileURLWithPath: path),
                bundleIdentifier: bundleIdentifier
            )
            return true
        }

        if let bundleIdentifier,
            let url = NSWorkspace.shared.urlForApplication(withBundleIdentifier: bundleIdentifier)
        {
            openApplicationKeepingDockFocus(url, bundleIdentifier: bundleIdentifier)
            return true
        }

        guard let appName, !appName.isEmpty else { return false }
        let appDirectories = [
            "/Applications",
            "/System/Applications",
            "/System/Volumes/Preboot/Cryptexes/App/System/Applications",
            "\(NSHomeDirectory())/Applications",
        ]
        for directory in appDirectories {
            let url = URL(fileURLWithPath: directory)
                .appendingPathComponent(appName)
                .appendingPathExtension("app")
            if FileManager.default.fileExists(atPath: url.path) {
                openApplicationKeepingDockFocus(url, bundleIdentifier: bundleIdentifier)
                return true
            }
        }

        return false
    }

    private func runningApp(for pinnedApp: PinnedApp) -> NSRunningApplication? {
        if let bundleId = pinnedApp.bundleIdentifier, !bundleId.isEmpty {
            return runningRegularApps.first {
                $0.bundleIdentifier == bundleId && !$0.isTerminated
            }
        }
        let itemPath = URL(fileURLWithPath: pinnedApp.path).path
        return runningRegularApps.first {
            guard let runningPath = $0.bundleURL?.path else { return false }
            return runningPath == itemPath && !$0.isTerminated
        }
    }

    private func resetDockStateAfterAppAction() {
        searchState.query = ""
        searchState.results = []
        searchState.selectedIndex = nil
        l2.focusedPillIndex = nil
        hoveredDockAppKey = nil
        lockedSubmenuParent = nil
    }

    private func refocusLauncherWindowAfterAppAction(delay: TimeInterval = 0.12) {
        DispatchQueue.main.asyncAfter(deadline: .now() + delay) {
            self.isVisible = true
            self.expandSearchBar()
            self.isSearchFieldFocused = true

            if let window = AppDelegate.shared?.launcherWindow
                ?? NSApp.windows.first(where: { $0.isVisible })
            {
                window.orderFrontRegardless()
                window.makeKeyAndOrderFront(nil)
            }

            NSApp.activate(ignoringOtherApps: true)
        }
    }

    private func openApplicationKeepingDockFocus(_ url: URL, bundleIdentifier: String? = nil) {
        let resolvedBundleId = bundleIdentifier ?? Bundle(url: url)?.bundleIdentifier
        let urlAppName = url.deletingPathExtension().lastPathComponent
        resetDockStateAfterAppAction()

        if let resolvedBundleId,
            let runningApp = NSWorkspace.shared.runningApplications.first(where: {
                $0.bundleIdentifier == resolvedBundleId && !$0.isTerminated
            })
        {
            activateRunningAppFromDock(runningApp)
            return
        }

        let launchId = DockActionFeedback.start("Opening", subject: urlAppName, icon: "arrow.up.right.circle.fill", tint: .accentColor)

        let configuration = NSWorkspace.OpenConfiguration()
        configuration.activates = true

        Task {
            var launchedApp: NSRunningApplication?
            do {
                launchedApp = try await NSWorkspace.shared.openApplication(at: url, configuration: configuration)
            } catch {
                NSWorkspace.shared.open(url)
            }

            await MainActor.run {
                let name = launchedApp?.localizedName ?? urlAppName
                DockActionFeedback.complete(launchId, label: "\(name) opened")
                if let pid = launchedApp?.processIdentifier {
                    centerAppWindowIfPersistentDock(pid: pid)
                }
            }
        }
    }

    private func activateRunningAppFromDock(_ app: NSRunningApplication) {
        resetDockStateAfterAppAction()
        let name = app.localizedName ?? "App"
        let switchId = DockActionFeedback.start("Switching to", subject: name, icon: "arrow.up.right.circle", tint: .white.opacity(0.8))
        if app.isHidden { app.unhide() }
        app.activate(options: [.activateIgnoringOtherApps])
        let pid = app.processIdentifier
        // Dismiss the "Switching to" toast once the app has had time to become frontmost
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.45) {
            DockActionFeedback.complete(switchId)
        }
        // Un-minimize any minimized windows
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.05) {
            let axApp = AXUIElementCreateApplication(pid)
            var windowsRef: CFTypeRef?
            if AXUIElementCopyAttributeValue(axApp, kAXWindowsAttribute as CFString, &windowsRef) == .success,
               let windows = windowsRef as? [AXUIElement]
            {
                for win in windows {
                    var minimized: CFTypeRef?
                    if AXUIElementCopyAttributeValue(win, kAXMinimizedAttribute as CFString, &minimized) == .success,
                       (minimized as? Bool) == true
                    {
                        AXUIElementSetAttributeValue(win, kAXMinimizedAttribute as CFString, kCFBooleanFalse)
                    }
                }
            }
        }
        centerAppWindowIfPersistentDock(pid: pid)
        // Don't steal focus back — the activated app should remain frontmost
    }

    /// Called when an app is launched/activated from global context.
    /// Waits for macOS to confirm the app is frontmost, then hands off to Context Dock.
    private func scheduleContextDockTransition(bundleId: String?, appName: String) {
        guard let bundleId else { return }
        pendingGlobalLaunchContextSwitch = (bundleId: bundleId, appName: appName)
        globalInlineAppScope = nil
        l2.targetApp = nil
        searchState.query = ""
        focusedAppPillIndex = nil
        hoveredAppPillIndex = nil
        l2.focusedPillIndex = nil
        l2.pillNavViaKeyboard = false
        scheduleGlobalGroupedListRebuild(query: "", delayNanoseconds: 0)

        // Fallback for apps that activate before the observer publishes its event.
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.75) {
            guard self.pendingGlobalLaunchContextSwitch?.bundleId == bundleId else { return }
            let activeBundleId = NSWorkspace.shared.frontmostApplication?.bundleIdentifier
            guard self.frontmost.bundleID == bundleId || activeBundleId == bundleId else { return }
            self.switchGlobalLaunchToContextDock(bundleId: bundleId, appName: appName)
        }
    }

    private func switchGlobalLaunchToContextDock(bundleId: String, appName: String) {
        pendingGlobalLaunchContextSwitch = nil
        globalContextActivation = nil
        globalInlineAppScope = nil
        suppressGlobalInlineAppScopeDetection = false
        l2.targetApp = nil
        searchState.query = ""
        focusedAppPillIndex = nil
        hoveredAppPillIndex = nil
        l2.focusedPillIndex = nil
        l2.pillNavViaKeyboard = false
        showMediaLayer = false
        aiMode.isActive = false
        showContextInDock = true
        if let app = NSWorkspace.shared.runningApplications.first(where: { $0.bundleIdentifier == bundleId }) {
            frontmost.bundleID = bundleId
            frontmost.name = app.localizedName ?? appName
            frontmost.icon =
                resolvedApplicationIcon(bundleIdentifier: bundleId, appName: frontmost.name)
                ?? preparedDockIcon(app.icon)
        } else {
            frontmost.bundleID = bundleId
            frontmost.name = appName
            frontmost.icon = resolvedApplicationIcon(bundleIdentifier: bundleId, appName: appName)
        }
        setFrontmostAppContextOnly(reason: "global launch became frontmost")
        syncL2DockSession(force: true)
        scheduleDockPillRebuild(query: "", delayNanoseconds: 0, refreshContext: false)
    }

    /// When Persistent Dock Mode is active, center the app's frontmost window in the
    /// visible screen area so it doesn't hide behind the dock.
    private func centerAppWindowIfPersistentDock(pid: pid_t) {
        guard settings.persistentContextDock else { return }
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.35) {
            guard let screen = NSScreen.main else { return }
            let visibleFrame = screen.visibleFrame          // Cocoa coords (Y from bottom)
            let screenHeight = screen.frame.height          // For flipping to AX coords
            let axApp = AXUIElementCreateApplication(pid)
            var windowsRef: CFTypeRef?
            guard AXUIElementCopyAttributeValue(axApp, kAXWindowsAttribute as CFString, &windowsRef) == .success,
                  let windows = windowsRef as? [AXUIElement], let win = windows.first else { return }

            var sizeRef: CFTypeRef?
            guard AXUIElementCopyAttributeValue(win, kAXSizeAttribute as CFString, &sizeRef) == .success,
                  let sv = sizeRef else { return }
            var winSize = CGSize.zero
            AXValueGetValue(sv as! AXValue, .cgSize, &winSize)
            guard winSize.width > 0 else { return }

            // Convert visible frame to AX coordinate space (Y increases downward from top)
            let axVisibleTop  = screenHeight - visibleFrame.maxY
            let axVisibleLeft = visibleFrame.minX
            let cx = axVisibleLeft + (visibleFrame.width  - winSize.width)  / 2
            let cy = axVisibleTop  + (visibleFrame.height - winSize.height) / 2
            var pt = CGPoint(x: max(axVisibleLeft, cx), y: max(axVisibleTop, cy))
            if let posVal = AXValueCreate(.cgPoint, &pt) {
                AXUIElementSetAttributeValue(win, kAXPositionAttribute as CFString, posVal)
            }
        }
    }

    private func terminateRunningAppFromDock(_ app: NSRunningApplication) {
        let name = app.localizedName ?? "App"
        hoveredDockAppKey = nil
        app.terminate()
        DockActionFeedback.start("Quit", subject: name, icon: "xmark.circle.fill", tint: .red.opacity(0.85))
        refocusLauncherWindowAfterAppAction(delay: 0.06)
        scheduleDockRefreshAfterTerminationAttempt(for: app)
    }

    private func shouldRequireFullAppNameMatch(
        appName: String,
        bundleIdentifier: String?
    ) -> Bool {
        let normalizedName = normalizedDockPillText(appName)
        if normalizedName == "news" { return true }
        return bundleIdentifier == "com.apple.news"
    }

    private func shouldAllowShortAppPrefixMatch(
        prefix: String,
        appName: String,
        bundleIdentifier: String?
    ) -> Bool {
        guard !shouldRequireFullAppNameMatch(
            appName: appName,
            bundleIdentifier: bundleIdentifier
        ) else {
            return prefix.count >= 4
        }
        return true
    }

    private func shouldAllowLocalAppPartialCompletion(
        fullQuery: String,
        firstToken: String,
        actionQuery: String
    ) -> Bool {
        guard !actionQuery.isEmpty else { return true }
        if isQuestionLikeAppPartialQuery(fullQuery) { return false }
        if isCommonLanguageAppPartialStart(firstToken)
            && !looksLikeAppCommandRemainder(actionQuery)
        {
            return false
        }
        return true
    }

    private func isQuestionLikeAppPartialQuery(_ query: String) -> Bool {
        let tokens = query.split(separator: " ").map(String.init)
        guard let first = tokens.first else { return false }
        let questionStarts: Set<String> = [
            "what", "whats", "who", "when", "where", "why", "how",
            "is", "are", "do", "does", "did", "can", "could", "should",
            "tell", "explain", "describe", "summarize", "analyse", "analyze"
        ]
        if questionStarts.contains(first) { return true }
        if tokens.count >= 2 {
            let firstTwo = tokens.prefix(2).joined(separator: " ")
            if ["what is", "what are", "how do", "how can", "tell me"].contains(firstTwo) {
                return true
            }
        }
        return false
    }

    private func isCommonLanguageAppPartialStart(_ token: String) -> Bool {
        let commonStarts: Set<String> = [
            "a", "an", "the", "this", "that", "these", "those",
            "what", "whats", "who", "when", "where", "why", "how",
            "is", "are", "do", "does", "did", "can", "could", "should",
            "i", "me", "my", "we", "you", "it", "its",
            "tell", "explain", "describe", "summarize", "analyse", "analyze"
        ]
        return commonStarts.contains(token)
    }

    private func looksLikeAppCommandRemainder(_ actionQuery: String) -> Bool {
        guard let first = actionQuery.split(separator: " ").map(String.init).first else {
            return false
        }
        let commandStarts: Set<String> = [
            "open", "new", "close", "send", "message", "call", "search", "find",
            "show", "list", "compose", "create", "add", "play", "pause", "stop",
            "next", "previous", "download", "share", "copy", "paste", "reply"
        ]
        return commandStarts.contains(first)
    }

    private func isQuitMenuPath(_ path: [String]) -> Bool {
        guard let last = path.last else { return false }
        let normalized = normalizedDockPillText(last)
        return normalized == "quit" || normalized.hasPrefix("quit ")
    }

    private func fallbackRunningAppAfterTermination(
        excludingProcessIdentifier processIdentifier: pid_t,
        excludingBundleIdentifier bundleIdentifier: String?
    ) -> NSRunningApplication? {
        let candidates = currentRegularRunningApps().filter { app in
            guard app.processIdentifier != processIdentifier else { return false }
            if let bundleIdentifier, !bundleIdentifier.isEmpty {
                return app.bundleIdentifier != bundleIdentifier
            }
            return true
        }

        if let finder = candidates.first(where: { $0.bundleIdentifier == "com.apple.finder" }) {
            return finder
        }
        return candidates.first
    }

    private func clearLiveDockMenuState() {
        liveMenuItems = []
        crossAppMenuItems = []
        crossAppMenuTargetPID = 0
        contextMenuPills = []
        previousEnabledIDs = []
        menuDebugText = "menu debug unavailable"
    }

    private func reconcileDockAfterTermination(of app: NSRunningApplication) {
        runningRegularApps = currentRegularRunningApps()

        if let delegate = AppDelegate.shared,
            delegate.previousFrontmostApp?.processIdentifier == app.processIdentifier
                || (
                    !(app.bundleIdentifier ?? "").isEmpty
                        && delegate.previousFrontmostApp?.bundleIdentifier == app.bundleIdentifier
                )
        {
            delegate.previousFrontmostApp = fallbackRunningAppAfterTermination(
                excludingProcessIdentifier: app.processIdentifier,
                excludingBundleIdentifier: app.bundleIdentifier
            )
        }

        if frontmost.bundleID == app.bundleIdentifier
            || frontmost.name == (app.localizedName ?? "")
        {
            frontmost.bundleID = ""
            frontmost.name = ""
            frontmost.icon = nil
        }

        detectAndUpdateContext()

        if showContextInDock, let targetApp = contextTargetApp() {
            reloadMenuForApp(targetApp)
        } else {
            clearLiveDockMenuState()
        }

        updateWindowSize()
    }

    private func scheduleDockRefreshAfterTerminationAttempt(for app: NSRunningApplication) {
        let targetPID = app.processIdentifier
        let targetBundleId = app.bundleIdentifier

        Task {
            for _ in 0..<18 {
                try? await Task.sleep(nanoseconds: 150_000_000)
                let apps = currentRegularRunningApps()
                runningRegularApps = apps

                let stillRunning = apps.contains { running in
                    if running.processIdentifier == targetPID { return true }
                    if let targetBundleId, !targetBundleId.isEmpty {
                        return running.bundleIdentifier == targetBundleId
                    }
                    return false
                }

                guard !stillRunning else { continue }
                reconcileDockAfterTermination(of: app)
                return
            }

            runningRegularApps = currentRegularRunningApps()
        }
    }

    private func executeDockMenuAction(
        sourcePID: pid_t,
        path: [String],
        shortcutChar: String?,
        shortcutModifiers: Int
    ) {
        guard sourcePID != 0 else { return }
        let isQuitAction = isQuitMenuPath(path)
        let normalizedPath = path.map(normalizedDockPillText)
        let isFinderEmptyBinAction =
            normalizedPath.contains("empty bin")
            || normalizedPath.contains("empty trash")
            || normalizedPath.contains("empty bin...")
            || normalizedPath.contains("empty trash...")

        let isFinderMoveToBinAction =
            normalizedPath.contains("move to bin")
            || normalizedPath.contains("move to trash")
            || normalizedPath.contains("move to bin...")
            || normalizedPath.contains("move to trash...")
        let needsLiveSelectionValidation = isVolatileSelectionMenuPath(path)

        Task {
            guard let sourceApp = NSWorkspace.shared.runningApplications.first(where: {
                $0.processIdentifier == sourcePID && !$0.isTerminated
            }) else { return }

            // Move to Bin for Finder: use AppleScript on the current selection (works for
            // Desktop items and background Finder windows without needing AX + frontmost).
            if sourceApp.bundleIdentifier == "com.apple.finder", isFinderMoveToBinAction {
                let result = await moveFinderSelectionToBinDirectly()
                await MainActor.run {
                    AppToast.show(
                        result.success ? "Moved to Bin" : result.message,
                        icon: result.success ? "trash" : "exclamationmark.triangle",
                        tint: result.success ? .red.opacity(0.9) : .orange.opacity(0.9)
                    )
                    reloadMenuForApp(sourceApp)
                }
                return
            }

            let pid = sourceApp.processIdentifier

            if sourceApp.bundleIdentifier == "com.apple.finder", isFinderEmptyBinAction {
                let result = await emptyFinderBinDirectly()
                await MainActor.run {
                    AppToast.show(
                        result.success ? "Bin emptied" : result.message,
                        icon: result.success ? "trash" : "exclamationmark.triangle",
                        tint: result.success ? .green.opacity(0.85) : .orange.opacity(0.9)
                    )
                    reloadMenuForApp(sourceApp)
                }
                return
            }

            if await MainActor.run(body: {
                executeWindowManagementMenuActionIfNeeded(
                    path: path,
                    sourceApp: sourceApp
                )
            }) {
                try? await Task.sleep(nanoseconds: 120_000_000)
                await MainActor.run { reloadMenuForApp(sourceApp) }
                return
            }

            var executablePath = path
            var executableShortcutChar = shortcutChar
            var executableShortcutModifiers = shortcutModifiers
            if needsLiveSelectionValidation {
                let liveMatch = await waitForExecutableMenuItem(
                    path: path,
                    app: sourceApp,
                    in: sourcePID,
                    attempts: 5,
                    pauseNanoseconds: 80_000_000
                )
                guard let liveMatch, liveMatch.isEnabled else {
                    await MainActor.run {
                        AppToast.show(
                            "Action is not available for the current selection",
                            icon: "exclamationmark.triangle",
                            tint: .orange.opacity(0.9)
                        )
                        reloadMenuForApp(sourceApp)
                    }
                    return
                }
                executablePath = liveMatch.path
                executableShortcutChar = executableShortcutChar ?? liveMatch.shortcutChar
                if executableShortcutModifiers == 0 {
                    executableShortcutModifiers = liveMatch.shortcutModifiers
                }
            }

            // Window-state actions (full screen, minimize, zoom) must let the app keep focus
            // after execution — stealing focus back would abort the OS transition animation.
            let isWindowStateAction: Bool = {
                let name = executablePath.last?.lowercased() ?? ""
                let root = executablePath.first?.lowercased() ?? ""
                return name.contains("full screen") || name.contains("fullscreen")
                    || name.contains("minimize") || name.contains("minimise")
                    || name == "zoom" || name.contains("slideshow")
                    || root == "window"
            }()

            // Both keyboard shortcuts (CGEvent.postToPid) and AX navigation require
            // the target app to be active — NSMenu only dispatches ⌘-key events for
            // the frontmost process, and AX is more reliable with the app focused.
            await MainActor.run {
                AppDelegate.shared?.launcherWindow?.resignKey()
                if sourceApp.isHidden { sourceApp.unhide() }
                sourceApp.activate(options: [.activateIgnoringOtherApps])
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.05) {
                    let axApp = AXUIElementCreateApplication(pid)
                    var windowsRef: CFTypeRef?
                    if AXUIElementCopyAttributeValue(axApp, kAXWindowsAttribute as CFString, &windowsRef) == .success,
                       let windows = windowsRef as? [AXUIElement]
                    {
                        for win in windows {
                            var minimized: CFTypeRef?
                            if AXUIElementCopyAttributeValue(win, kAXMinimizedAttribute as CFString, &minimized) == .success,
                               (minimized as? Bool) == true
                            {
                                AXUIElementSetAttributeValue(win, kAXMinimizedAttribute as CFString, kCFBooleanFalse)
                            }
                        }
                    }
                }
            }
            try? await Task.sleep(nanoseconds: 80_000_000)

            let preferredShortcut = executableShortcutChar?
                .trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
            let shortcutSent =
                !preferredShortcut.isEmpty
                && AXMenuReader.shared.executeShortcut(
                    char: preferredShortcut,
                    modifiers: executableShortcutModifiers,
                    in: sourcePID
                )

            if !shortcutSent {
                AXActionResolver.shared.execute(menuPath: executablePath, in: sourceApp)
            }

            try? await Task.sleep(nanoseconds: 250_000_000)
            AXMenuReader.shared.invalidateCache(for: sourcePID)

            await MainActor.run {
                if isQuitAction {
                    scheduleDockRefreshAfterTerminationAttempt(for: sourceApp)
                    return
                }

                if !isWindowStateAction {
                    // Return focus to Context Dock so the next keystroke lands here.
                    // Skip for window-state actions (full screen, minimize, zoom) where
                    // stealing focus aborts the OS transition animation.
                    AppDelegate.shared?.launcherWindow?.makeKeyAndOrderFront(nil)
                    isSearchFieldFocused = true
                }
                runningRegularApps = currentRegularRunningApps()
                if let liveApp = NSWorkspace.shared.runningApplications.first(where: {
                    $0.processIdentifier == sourcePID && !$0.isTerminated
                }) {
                    reloadMenuForApp(liveApp)
                } else {
                    clearLiveDockMenuState()
                }
            }

            // Safety-net: some apps (Mail, Safari) update their menu bar slightly after
            // the action completes. Re-read at 650 ms to catch Show→Hide / toggle changes
            // that weren't reflected in the 250 ms pass.
            try? await Task.sleep(nanoseconds: 400_000_000)
            AXMenuReader.shared.invalidateCache(for: sourcePID)
            await MainActor.run {
                guard let liveApp = NSWorkspace.shared.runningApplications.first(where: {
                    $0.processIdentifier == sourcePID && !$0.isTerminated
                }) else { return }
                reloadMenuForApp(liveApp)
            }
        }
    }

    private func emptyFinderBinDirectly() async -> (success: Bool, message: String) {
        await Task.detached(priority: .userInitiated) {
            let script = """
            tell application "Finder"
                empty trash
            end tell
            """
            var error: NSDictionary?
            NSAppleScript(source: script)?.executeAndReturnError(&error)
            if let error {
                let message = error[NSAppleScript.errorMessage] as? String
                    ?? "Could not empty Bin"
                return (false, message)
            }
            return (true, "Bin emptied")
        }.value
    }

    private func moveFinderSelectionToBinDirectly() async -> (success: Bool, message: String) {
        await Task.detached(priority: .userInitiated) {
            let script = """
            tell application "Finder"
                set sel to (selection as alias list)
                if sel is {} then
                    return
                end if
                move sel to trash
            end tell
            """
            var error: NSDictionary?
            NSAppleScript(source: script)?.executeAndReturnError(&error)
            if let error {
                let message = error[NSAppleScript.errorMessage] as? String
                    ?? "Could not move to Bin"
                return (false, message)
            }
            return (true, "Moved to Bin")
        }.value
    }

    @MainActor
    private func executeWindowManagementMenuActionIfNeeded(
        path: [String],
        sourceApp: NSRunningApplication
    ) -> Bool {
        let normalizedPath = path.map(normalizedDockPillText)
        guard normalizedPath.contains("window") else { return false }
        guard let title = normalizedPath.last else { return false }

        if title == "centre" || title == "center" {
            return centerFrontmostWindowForApp(
                pid: sourceApp.processIdentifier,
                appName: sourceApp.localizedName ?? "App",
                screenCoverage: 0.85
            )
        }

        return false
    }

    @MainActor
    private func centerFrontmostWindowForApp(
        pid: pid_t,
        appName: String,
        screenCoverage: CGFloat
    ) -> Bool {
        guard let screen = NSScreen.main else { return false }
        let visibleFrame = screen.visibleFrame
        let screenHeight = screen.frame.height
        let targetWidth = visibleFrame.width * screenCoverage
        let targetHeight = visibleFrame.height * screenCoverage
        let targetX = visibleFrame.minX + (visibleFrame.width - targetWidth) / 2
        let targetYFromBottom = visibleFrame.minY + (visibleFrame.height - targetHeight) / 2
        let targetY = screenHeight - targetYFromBottom - targetHeight

        let axApp = AXUIElementCreateApplication(pid)
        var windowsRef: CFTypeRef?
        guard AXUIElementCopyAttributeValue(axApp, kAXWindowsAttribute as CFString, &windowsRef) == .success,
              let windows = windowsRef as? [AXUIElement],
              let window = windows.first
        else {
            AppToast.show("No \(appName) window found", icon: "macwindow", tint: .orange)
            return true
        }

        var minimizedRef: CFTypeRef?
        if AXUIElementCopyAttributeValue(window, kAXMinimizedAttribute as CFString, &minimizedRef) == .success,
           (minimizedRef as? Bool) == true {
            AXUIElementSetAttributeValue(window, kAXMinimizedAttribute as CFString, kCFBooleanFalse)
        }

        var targetSize = CGSize(width: targetWidth, height: targetHeight)
        var targetPoint = CGPoint(x: targetX, y: targetY)
        guard let sizeValue = AXValueCreate(.cgSize, &targetSize),
              let pointValue = AXValueCreate(.cgPoint, &targetPoint)
        else { return true }

        let sizeResult = AXUIElementSetAttributeValue(window, kAXSizeAttribute as CFString, sizeValue)
        let positionResult = AXUIElementSetAttributeValue(window, kAXPositionAttribute as CFString, pointValue)
        if sizeResult == .success || positionResult == .success {
            AppToast.show("Centered \(appName)", icon: "rectangle.inset.filled", tint: .blue.opacity(0.9))
        } else {
            AppToast.show("Could not center \(appName)", icon: "exclamationmark.triangle", tint: .orange)
        }
        return true
    }

    private func isCurrentFinderFolderAttachedToConversation() -> Bool {
        guard frontmost.bundleID == "com.apple.finder"
            || contextTargetApp()?.bundleIdentifier == "com.apple.finder"
        else { return false }
        guard canAttachCurrentFinderFolderToConversation else { return false }

        return isFinderFolderSearchAttached(currentFolderPath: currentFinderFolderPath())
    }

    private func isCurrentMailContextAttached() -> Bool {
        guard frontmost.bundleID == "com.apple.mail"
            || contextTargetApp()?.bundleIdentifier == "com.apple.mail"
        else { return false }
        return isMailContextAttached
    }

    private func toggleMailContextAttachment() {
        isMailContextAttached.toggle()
    }

    private func addCurrentFinderFolderToConversation() {
        refreshCachedFinderCurrentDirectory(for: "com.apple.finder")
        let folderPath = currentFinderFolderPath()
        let normalizedPath = URL(fileURLWithPath: folderPath).standardizedFileURL.path
        guard isAttachableFinderHomeFolder(normalizedPath) else { return }
        guard FileManager.default.fileExists(atPath: normalizedPath) else { return }

        if isFinderFolderSearchAttached(currentFolderPath: normalizedPath) {
            detachFinderFolderSearch(path: normalizedPath)
        } else {
            attachFinderFolderSearch(path: normalizedPath)
            finderFolderQueryModeActive = true
            l2.focusedPillIndex = nil
            focusedAppPillIndex = nil
            l2.pillNavViaKeyboard = false
            expandSearchBar()
            isSearchFieldFocused = true
        }
    }

    private func isFinderFolderSearchAttached(currentFolderPath: String? = nil) -> Bool {
        let folderPath =
            currentFolderPath.map { URL(fileURLWithPath: $0).standardizedFileURL.path }
            ?? URL(fileURLWithPath: currentFinderFolderPath()).standardizedFileURL.path
        guard !attachedFinderFolderSearchPath.isEmpty else { return false }
        return attachedFinderFolderSearchPath == folderPath
    }

    private func isAttachableFinderHomeFolder(_ path: String) -> Bool {
        let normalizedPath = URL(fileURLWithPath: path).standardizedFileURL.path
        let home = URL(fileURLWithPath: NSHomeDirectory()).standardizedFileURL.path
        guard normalizedPath.hasPrefix(home + "/") else { return false }
        guard normalizedPath != "\(home)/Desktop" else { return false }
        var isDir: ObjCBool = false
        return FileManager.default.fileExists(atPath: normalizedPath, isDirectory: &isDir)
            && isDir.boolValue
    }

    private var canAttachCurrentFinderFolderToConversation: Bool {
        guard !isFinderDesktopOnlyMode else { return false }
        return isAttachableFinderHomeFolder(currentFinderFolderPath())
    }

    private func attachFinderFolderSearch(path: String) {
        let normalizedPath = URL(fileURLWithPath: path).standardizedFileURL.path
        approvedFinderFolderSearchPaths.insert(normalizedPath)
        attachedFinderFolderSearchPath = normalizedPath
        finderFolderQueryModeActive = true
        refreshCachedFinderCurrentDirectory(for: "com.apple.finder")

        if showContextInDock {
            scheduleFinderSemanticSearchIfNeeded(for: searchState.query)
        }
    }

    private func detachFinderFolderSearch(path: String? = nil) {
        let currentAttached = attachedFinderFolderSearchPath
        guard !currentAttached.isEmpty else { return }

        if let path {
            let normalizedPath = URL(fileURLWithPath: path).standardizedFileURL.path
            guard normalizedPath == currentAttached else { return }
        }

        attachedFinderFolderSearchPath = ""
        finderFolderQueryModeActive = false
        clearFinderSemanticState()
    }

    @discardableResult
    private func detachFinderFolderQueryModeFromEmptyBackspace() -> Bool {
        guard finderFolderQueryModeActive else { return false }
        guard searchState.query.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return false }
        guard isFinderFolderSearchAttached() else { return false }

        detachFinderFolderSearch()
        l2.focusedPillIndex = nil
        focusedAppPillIndex = nil
        l2.pillNavViaKeyboard = false
        scheduleDockPillRebuild(query: "", delayNanoseconds: 0)
        isSearchFieldFocused = true
        return true
    }

    private func presentFinderFolderSearchPermissionAlert(for path: String) {
        let normalizedPath = URL(fileURLWithPath: path).standardizedFileURL.path
        let folderName = URL(fileURLWithPath: normalizedPath).lastPathComponent
        let alert = NSAlert()
        alert.alertStyle = .informational
        alert.messageText = "Allow Folder Search?"
        alert.informativeText =
            "Allow Context-Dock to search names and indexed file contents inside “\(folderName.isEmpty ? normalizedPath : folderName)” for this Finder session."
        alert.addButton(withTitle: "Allow")
        alert.addButton(withTitle: "Cancel")
        alert.icon = NSWorkspace.shared.icon(forFile: normalizedPath)

        NSApp.activate(ignoringOtherApps: true)
        let response = alert.runModal()
        if response == .alertFirstButtonReturn {
            attachFinderFolderSearch(path: normalizedPath)
        }
    }

    private func clearFinderFolderSearchAttachmentIfNeeded() {
        if attachedFinderFolderSearchPath.isEmpty { return }
        if !isFinderFolderSearchAttached() {
            clearFinderSemanticState()
        }
    }

    private func resolvedRunningAppIcon(for app: NSRunningApplication) -> NSImage? {
        if let bundleURL = app.bundleURL {
            return preparedDockIcon(NSWorkspace.shared.icon(forFile: bundleURL.path))
        }
        return preparedDockIcon(app.icon)
    }

    private func preparedDockIcon(_ icon: NSImage?) -> NSImage? {
        guard let icon else { return nil }
        let copy = icon.copy() as? NSImage ?? icon
        copy.size = NSSize(width: 64, height: 64)
        return copy
    }

    @ViewBuilder
    private func appPillButton(
        icon: NSImage?,
        label: String,
        subtitle: String? = nil,
        hoverKey: String,
        focused: Bool = false,
        index: Int? = nil,
        isExpanded: Bool = false,          // fills the vacated search-bar width
        destructiveAction: (() -> Void)? = nil,
        removeAction: (() -> Void)? = nil,
        pinAction: (() -> Void)? = nil,    // double-click to pin
        action: @escaping () -> Void
    ) -> some View {
        let hovered = hoveredDockAppKey == hoverKey || focused
        let sz = CGFloat(settings.dockIconSize)
        let iconSize: CGFloat = isExpanded ? sz * 0.78 : sz * 0.72
        let textSize: CGFloat = min(isExpanded ? 15 : 13, max(12, sz * (isExpanded ? 0.24 : 0.22)))
        let pillHeight: CGFloat = isExpanded ? sz + 8 : sz + 4
        let cornerRadius: CGFloat = max(5, iconSize / 4.2)
        let leadingPad: CGFloat = isExpanded ? max(10, sz * 0.20) : max(10, sz * 0.18)
        let separatorHeight: CGFloat = isExpanded ? max(24, sz * 0.50) : max(24, sz * 0.46)
        let trailingPad: CGFloat = isExpanded ? 12 : (destructiveAction != nil || removeAction != nil ? 8 : 12)
        let isDarkMode = systemColorScheme == .dark

        ZStack(alignment: .topTrailing) {
            Button(action: action) {
                HStack(spacing: 0) {
                    if let icon {
                        Image(nsImage: icon)
                            .resizable()
                            .aspectRatio(contentMode: .fit)
                            .frame(width: iconSize, height: iconSize)
                            .clipShape(RoundedRectangle(cornerRadius: cornerRadius))
                            .padding(.leading, leadingPad)
                    } else {
                        Image(systemName: "app.fill")
                            .font(.system(size: iconSize * 0.72, weight: .medium))
                            .foregroundStyle(.secondary)
                            .frame(width: iconSize, height: iconSize)
                            .padding(.leading, leadingPad)
                    }
                    Rectangle()
                        .fill(Color.white.opacity(isExpanded ? 0.16 : 0.12))
                        .frame(width: 1, height: separatorHeight)
                        .padding(.horizontal, isExpanded ? 10 : 8)
                    VStack(alignment: .leading, spacing: 1) {
                        HStack(spacing: 4) {
                            Text(label)
                                .font(.system(size: textSize, weight: isExpanded ? .semibold : .medium))
                                .foregroundStyle(Color.primary.opacity(isExpanded ? 1.0 : (focused ? 1.0 : 0.9)))
                            if destructiveAction != nil {
                                Image(systemName: "chevron.right")
                                    .font(.system(size: max(9, textSize - 3), weight: .semibold))
                                    .foregroundStyle(.secondary.opacity(isExpanded ? 0.75 : 0.62))
                            }
                        }
                        .lineLimit(1)
                        if isExpanded, let sub = subtitle {
                            Text(sub)
                                .font(.system(size: 10, weight: .medium))
                                .foregroundStyle(sub == "Running"
                                    ? Color.green.opacity(0.85)
                                    : Color.secondary.opacity(0.65))
                                .lineLimit(1)
                        }
                    }
                        .padding(.trailing, isExpanded ? 4 : trailingPad)
                        .mask(alignment: .leading) {
                            // Smooth gradient fade on the trailing edge for expanded pills
                            if isExpanded {
                                LinearGradient(
                                    stops: [
                                        .init(color: .black, location: 0),
                                        .init(color: .black, location: 0.75),
                                        .init(color: .clear, location: 1.0),
                                    ],
                                    startPoint: .leading, endPoint: .trailing)
                            } else {
                                Color.black
                            }
                        }
                    if isExpanded {
                        Spacer(minLength: 0)
                        if destructiveAction != nil {
                            Image(systemName: "delete.left")
                                .font(.system(size: 11, weight: .medium))
                                .foregroundStyle(.secondary.opacity(0.55))
                                .padding(.trailing, 8)
                        }
                        Image(systemName: "return")
                            .font(.system(size: 11, weight: .medium))
                            .foregroundStyle(.secondary.opacity(0.55))
                            .padding(.trailing, pinAction != nil ? 8 : 12)
                        if let pin = pinAction {
                            Button(action: pin) {
                                Image(systemName: "pin")
                                    .font(.system(size: 11, weight: .medium))
                                    .foregroundStyle(.secondary.opacity(0.55))
                                    .padding(.trailing, 12)
                            }
                            .buttonStyle(.plain)
                            .help("Pin \(label)")
                        }
                    }
                }
                .frame(maxWidth: isExpanded ? .infinity : nil)
                .frame(height: pillHeight)
                .background {
                    ZStack {
                        Capsule().fill(.ultraThinMaterial)
                        Capsule().fill(
                            isDarkMode
                            ? Color.black.opacity(isExpanded ? 0.10 : 0.06)
                            : Color.white.opacity(isExpanded ? 0.22 : 0.14)
                        )
                        Capsule().fill(
                            LinearGradient(
                                colors: [
                                    .white.opacity(isExpanded ? 0.18 : (focused ? 0.16 : (hovered ? 0.12 : 0.07))),
                                    .white.opacity(isExpanded ? 0.035 : (focused ? 0.04 : 0.015))
                                ],
                                startPoint: .top, endPoint: .bottom)
                        )
                        Capsule().strokeBorder(
                            LinearGradient(
                                colors: [
                                    .white.opacity(isExpanded ? 0.34 : (hovered ? 0.28 : 0.16)),
                                    .white.opacity(0.035)
                                ],
                                startPoint: .topLeading, endPoint: .bottomTrailing),
                            lineWidth: isExpanded ? 1.0 : (focused ? 1.0 : 0.75))
                    }
                }
                .shadow(
                    color: .black.opacity(isExpanded ? 0.20 : (focused ? 0.16 : (hovered ? 0.10 : 0.06))),
                    radius: isExpanded ? 10 : (focused ? 8 : 5),
                    y: isExpanded ? 5 : 3)
                .animation(.spring(response: 0.22, dampingFraction: 0.75), value: isExpanded)
                .animation(.spring(response: 0.18, dampingFraction: 0.75), value: focused)
            }
            .buttonStyle(.plain)
            .zIndex(isExpanded ? 20 : (focused ? 10 : (hovered ? 5 : 0)))

            if hovered, !isExpanded, let quit = destructiveAction {
                Button(action: quit) {
                        Image(systemName: "xmark.circle.fill")
                        .font(.system(size: max(14, sz * 0.24), weight: .semibold))
                        .foregroundStyle(.white, Color.black.opacity(0.65))
                }
                .buttonStyle(.plain)
                .offset(x: max(4, sz * 0.08), y: -max(4, sz * 0.08))
                .transition(.scale(scale: 0.6).combined(with: .opacity))
            } else if hovered, !isExpanded, let remove = removeAction {
                Button(action: remove) {
                    Image(systemName: "minus.circle.fill")
                        .font(.system(size: max(14, sz * 0.24), weight: .semibold))
                        .foregroundStyle(.white, Color.black.opacity(0.65))
                }
                .buttonStyle(.plain)
                .offset(x: max(4, sz * 0.08), y: -max(4, sz * 0.08))
                .transition(.scale(scale: 0.6).combined(with: .opacity))
            }

        }
        .simultaneousGesture(
            TapGesture(count: 2).onEnded { pinAction?() }
        )
        .onHover { hovering in
            withAnimation(.spring(response: 0.15, dampingFraction: 0.80)) {
                hoveredDockAppKey = hovering ? hoverKey : nil
                if let index { hoveredAppPillIndex = hovering ? index : nil }
            }
        }
        .help(pinAction != nil ? "\(label) — double-click to pin" : label)
    }

    private func appIconButton(
        icon: NSImage?,
        label: String,
        isRunning: Bool,
        hoverKey: String? = nil,
        onCloseRunningApp: (() -> Void)? = nil,
        action: @escaping () -> Void
    ) -> some View {
        let sz = CGFloat(settings.dockIconSize)
        let outerSz = sz + 4
        let cornerRadius = sz / 4.4
        let dotSize = max(5, sz * 0.159)
        return ZStack(alignment: .topTrailing) {
            Button(action: action) {
                ZStack(alignment: .bottomTrailing) {
                    if let icon {
                        Image(nsImage: icon)
                            .resizable()
                            .aspectRatio(contentMode: .fit)
                            .frame(width: sz, height: sz)
                            .clipShape(RoundedRectangle(cornerRadius: cornerRadius))
                    } else {
                        Image(systemName: "app")
                            .font(.system(size: sz * 0.636, weight: .medium))
                            .foregroundStyle(.secondary)
                            .frame(width: sz, height: sz)
                    }

                    if isRunning {
                        Circle()
                            .fill(.green)
                            .frame(width: dotSize, height: dotSize)
                            .overlay(
                                Circle().strokeBorder(Color.black.opacity(0.3), lineWidth: 0.5)
                            )
                            .offset(x: 2, y: 2)
                    }
                }
                .frame(width: outerSz, height: outerSz)
            }
            .buttonStyle(.plain)

            if let hoverKey, let onCloseRunningApp, isRunning {
                Button(action: onCloseRunningApp) {
                    Image(systemName: "xmark.circle.fill")
                        .font(.system(size: 14, weight: .semibold))
                        .foregroundStyle(.white, Color.black.opacity(0.72))
                        .background(Color.black.opacity(0.12), in: Circle())
                }
                .buttonStyle(.plain)
                .opacity(hoveredDockAppKey == hoverKey ? 1 : 0)
                .offset(x: 4, y: -4)
                .help("Quit \(label)")
            }
        }
        .frame(width: outerSz, height: outerSz)
        .onHover { hovering in
            guard let hoverKey else { return }
            if hovering {
                hoveredDockAppKey = hoverKey
            } else if hoveredDockAppKey == hoverKey {
                hoveredDockAppKey = nil
            }
        }
        .help(label)
        .animation(.spring(response: 0.25, dampingFraction: 0.72), value: sz)
    }

    @ViewBuilder
    private func compactSuggestionPillButton(pill: DockPill, index: Int) -> some View {
        let accent = accentColor(for: pill.accentColorName)
        Button {
