    // MARK: - Finder selected-file context pills

    private func finderSelectionSignature(_ paths: [String]) -> String {
        paths
            .map { URL(fileURLWithPath: $0).standardizedFileURL.path }
            .sorted()
            .joined(separator: "\n")
    }

    private func finderSelectionSignature(_ urls: [URL]) -> String {
        finderSelectionSignature(urls.map(\.path))
    }

    private func isDismissedFinderSelection(_ paths: [String]) -> Bool {
        guard let dismissedFinderSelectionSignature,
              !dismissedFinderSelectionSignature.isEmpty,
              !paths.isEmpty
        else { return false }
        return finderSelectionSignature(paths) == dismissedFinderSelectionSignature
    }

    private func isDismissedFinderSelection(_ urls: [URL]) -> Bool {
        isDismissedFinderSelection(urls.map(\.path))
    }

    private func updateDismissedFinderSelectionAfterSelectionChange(_ paths: [String]) {
        guard let dismissedFinderSelectionSignature else { return }
        if paths.isEmpty || finderSelectionSignature(paths) != dismissedFinderSelectionSignature {
            self.dismissedFinderSelectionSignature = nil
        }
    }

    private func effectiveFinderSelectionURLsForPills() -> [URL] {
        let liveSelection = canonicalExistingURLs(
            axContext.selectedFilePaths.map { URL(fileURLWithPath: $0) }
        )
        if !liveSelection.isEmpty {
            return isDismissedFinderSelection(liveSelection) ? [] : liveSelection
        }

        if case .filesSelected(let urls) = currentContext {
            let contextSelection = canonicalExistingURLs(urls)
            if !contextSelection.isEmpty {
                return isDismissedFinderSelection(contextSelection) ? [] : contextSelection
            }
        }

        return []
    }

    /// When Finder is frontmost and files are selected, generate instant-action pills
    /// for those files so they appear *before* the generic adapter pills.
    func buildFinderFilePills(query q: String) -> [DockPill] {
        let selectedURLs = effectiveFinderSelectionURLsForPills()
        guard !selectedURLs.isEmpty else { return [] }
        let paths = selectedURLs.map(\.path)
        let count = paths.count
        let first = paths[0]
        let firstName = URL(fileURLWithPath: first).lastPathComponent
        let label = count == 1 ? firstName : "\(count) items selected"
        let ext = URL(fileURLWithPath: first).pathExtension.lowercased()
        let imageExtsForFinderSelection = ["jpg", "jpeg", "png", "gif", "heic", "tiff", "bmp", "webp", "svg"]

        // Pills that always make sense for any selection
        var pills: [DockPill] = []

        func add(
            _ id: String, _ name: String, _ icon: String, _ color: String,
            _ action: @escaping () -> Void
        ) {
            if !q.isEmpty && !name.lowercased().contains(q) { return }
            pills.append(
                DockPill(
                    id: "finder-ctx-\(id)", name: name, icon: icon,
                    accentColorName: color, badge: label, execute: action))
        }

        add("ql", "Quick Look", "eye", "blue") {
            NSWorkspace.shared.activateFileViewerSelecting(
                paths.compactMap { URL(fileURLWithPath: $0) })
        }
        add("open", "Open", "arrow.up.right.square", "blue") {
            for p in paths { NSWorkspace.shared.open(URL(fileURLWithPath: p)) }
        }
        add("reveal", "Show in Finder", "folder", "gray") {
            NSWorkspace.shared.activateFileViewerSelecting([URL(fileURLWithPath: first)])
        }
        add("copypath", "Copy Path", "doc.on.clipboard", "teal") {
            let pb = NSPasteboard.general
            pb.clearContents()
            pb.setString(paths.joined(separator: "\n"), forType: .string)
        }
        add("share", "Share…", "square.and.arrow.up", "blue") {
            let urls = paths.map { URL(fileURLWithPath: $0) }
            presentSharingPicker(items: urls)
        }
        if count > 1 {
            add("new-folder-selection", "New Folder with Selection", "folder.badge.plus", "green") {
                executeFinderSelectionMenuAction(titleContains: "new folder with selection")
            }
        }
        add("compress", count > 1 ? "Compress \(count) Items" : "Compress", "archivebox", "yellow") {
            executeFinderSelectionMenuAction(titleContains: "compress")
        }
        if selectedURLs.allSatisfy({ imageExtsForFinderSelection.contains($0.pathExtension.lowercased()) }) {
            add("remove-background", "Remove Background", "person.crop.rectangle", "purple") {
                executeFinderSelectionMenuAction(titleContains: "remove background")
            }
            add("convert-image", "Convert Image", "photo.stack", "purple") {
                executeFinderSelectionMenuAction(titleContains: "convert image")
            }
        }
        add("trash", "Move to Bin", "trash", "red") {
            let urls = paths.map { URL(fileURLWithPath: $0) }
            var failures: [String] = []
            for url in urls {
                do {
                    try FileManager.default.trashItem(at: url, resultingItemURL: nil)
                } catch {
                    failures.append("\(url.lastPathComponent): \(error.localizedDescription)")
                }
            }
            if failures.isEmpty {
                AppToast.show(
                    urls.count == 1 ? "Moved to Bin" : "\(urls.count) items moved to Bin",
                    icon: "trash",
                    tint: .red.opacity(0.9)
                )
                axContext.selectedFilePaths.removeAll()
                if case .filesSelected = currentContext {
                    currentContext = .none
                }
                scheduleDockPillRebuild(query: lastPillQuery, delayNanoseconds: 0)
            } else {
                AppToast.show(
                    "Could not move to Bin: \(failures.prefix(2).joined(separator: ", "))",
                    icon: "exclamationmark.triangle",
                    tint: .orange
                )
            }
        }

        // Extension-aware pills
        let imageExts = ["jpg", "jpeg", "png", "gif", "heic", "tiff", "bmp", "webp", "svg"]
        let videoExts = ["mp4", "mov", "m4v", "avi", "mkv", "wmv"]
        let archiveExts = ["zip", "tar", "gz", "bz2", "xz", "7z", "rar"]
        let textExts = [
            "txt", "md", "markdown", "rtf", "csv", "json", "xml", "yaml", "yml", "toml", "log",
        ]
        let pdfExts = ["pdf"]

        func openInApp(_ fileURL: URL, appName: String) {
            let proc = Process()
            proc.executableURL = URL(fileURLWithPath: "/usr/bin/open")
            proc.arguments = ["-a", appName, fileURL.path]
            try? proc.run()
        }

        if imageExts.contains(ext) {
            add("preview-img", "Open in Preview", "photo", "purple") {
                openInApp(URL(fileURLWithPath: first), appName: "Preview")
            }
        }
        if videoExts.contains(ext) {
            add("play", "Play in QuickTime", "play.circle", "red") {
                openInApp(URL(fileURLWithPath: first), appName: "QuickTime Player")
            }
        }
        if pdfExts.contains(ext) {
            add("preview-pdf", "Open in Preview", "doc.richtext", "red") {
                openInApp(URL(fileURLWithPath: first), appName: "Preview")
            }
        }
        if archiveExts.contains(ext) {
            add("unzip", "Unarchive", "archivebox.circle", "yellow") {
                let dir = URL(fileURLWithPath: first).deletingLastPathComponent().path
                let proc = Process()
                proc.executableURL = URL(fileURLWithPath: "/usr/bin/unzip")
                proc.arguments = ["-o", first, "-d", dir]
                try? proc.run()
            }
        }
        if textExts.contains(ext) {
            add("texteditor", "Open in TextEdit", "doc.plaintext", "gray") {
                openInApp(URL(fileURLWithPath: first), appName: "TextEdit")
            }
        }
        return pills
    }

    private func buildFinderHomeFolderPills(query q: String) -> [DockPill] {
        let query = q.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard !query.hasPrefix("+") else { return [] }
        guard query.count >= 2 else { return [] }
        guard frontmost.bundleID == "com.apple.finder"
            || l2.targetApp?.bundleId == "com.apple.finder"
            || axContext.bundleId == "com.apple.finder"
        else { return [] }
        guard effectiveFinderSelectionURLsForPills().isEmpty else { return [] }

        let home = URL(fileURLWithPath: NSHomeDirectory()).standardizedFileURL.path
        let currentFolder = URL(fileURLWithPath: currentFinderFolderPath()).standardizedFileURL.path
        // Desktop mode = no Finder window, user is on ~/Desktop which is inside ~.
        // Any Finder context inside the home tree should show home folder pills.
        guard isFinderDesktopOnlyMode
            || currentFolder == home
            || currentFolder.hasPrefix(home + "/")
        else { return [] }
        let searchRoot = home
        var seen = Set<String>()
        var candidates: [(url: URL, isDirectory: Bool, score: Double)] = []

        func addCandidate(_ url: URL, isDirectory: Bool, score: Double) {
            let path = url.standardizedFileURL.path
            guard path == searchRoot || path.hasPrefix(searchRoot + "/") else { return }
            guard !url.lastPathComponent.hasPrefix(".") else { return }
            guard seen.insert(path).inserted else { return }
            candidates.append((URL(fileURLWithPath: path), isDirectory, score))
        }

        let indexed = fileIndexManager.advancedSearch(AdvancedFileSearchQuery(
            rootPath: searchRoot,
            residualQuery: query,
            includeDirectories: true,
            filesOnly: false,
            limit: 48
        ))
        for file in indexed {
            let url = URL(fileURLWithPath: file.path)
            guard let nameScore = strictFinderHomeSearchScore(query: query, url: url) else {
                continue
            }
            let depthPenalty = max(0, file.path.replacingOccurrences(of: searchRoot, with: "").split(separator: "/").count - 1)
            addCandidate(
                url,
                isDirectory: file.isDirectory,
                score: nameScore + (file.isDirectory ? 90 : 30) - Double(depthPenalty * 8)
            )
        }

        // Instant fallback before Spotlight finishes: direct Home children and common Home folders.
        let fallbackRoots = [
            searchRoot,
            "\(home)/Desktop",
            "\(home)/Documents",
            "\(home)/Downloads",
            "\(home)/Pictures",
            "\(home)/Movies",
            "\(home)/Music",
            "\(home)/Library/Mobile Documents/com~apple~CloudDocs"
        ]
        for root in fallbackRoots {
            guard candidates.count < 16,
                  let items = try? FileManager.default.contentsOfDirectory(
                    at: URL(fileURLWithPath: root),
                    includingPropertiesForKeys: [.isDirectoryKey, .contentModificationDateKey, .fileSizeKey],
                    options: [.skipsHiddenFiles, .skipsPackageDescendants]
                  )
            else { continue }
            for url in items {
                guard let score = strictFinderHomeSearchScore(query: query, url: url) else { continue }
                let values = (try? url.resourceValues(forKeys: [.isDirectoryKey])) ?? URLResourceValues()
                let isDirectory = values.isDirectory ?? url.hasDirectoryPath
                addCandidate(url, isDirectory: isDirectory, score: score + (isDirectory ? 75 : 20))
            }
        }

        return candidates
            .sorted {
                if $0.score != $1.score { return $0.score > $1.score }
                if $0.isDirectory != $1.isDirectory { return $0.isDirectory && !$1.isDirectory }
                return $0.url.lastPathComponent.localizedCaseInsensitiveCompare($1.url.lastPathComponent)
                    == .orderedAscending
            }
            .prefix(10)
            .map { candidate in
                let url = candidate.url
                let itemPath = url.standardizedFileURL.path
                let displayParent = finderDisplayPath(url.deletingLastPathComponent().path)
                var pill = DockPill(
                    id: "finder-home-search-\(itemPath)",
                    name: url.lastPathComponent,
                    icon: candidate.isDirectory ? "folder.fill" : finderSemanticSymbol(for: FinderSemanticMatch(
                        path: itemPath,
                        title: url.lastPathComponent,
                        subtitle: "",
                        isDirectory: candidate.isDirectory,
                        score: candidate.score,
                        source: "Home",
                        searchTerms: []
                    )),
                    accentColorName: candidate.isDirectory ? "blue" : "teal",
                    badge: displayParent == "~" ? "Home" : displayParent,
                    execute: {
                        UsageTracker.shared.recordAccess(for: finderGoToTrackingIdentifier(for: itemPath))
                        rememberFinderFollowUpTargets(
                            [url],
                            folderPath: candidate.isDirectory ? itemPath : url.deletingLastPathComponent().path,
                            sourceQuery: query
                        )
                        NSWorkspace.shared.open(url)
                        searchState.query = ""
                        l2.focusedPillIndex = nil
                    }
                )
                pill.menuItemImage = NSWorkspace.shared.icon(forFile: itemPath)
                pill.sourceBundleId = "com.apple.finder"
                pill.sourceAppName = "Finder"
                pill.rankingKind = candidate.isDirectory ? "finderGoTo" : "finderSearch"
                pill.trackingIdentifier = candidate.isDirectory
                    ? finderGoToTrackingIdentifier(for: itemPath)
                    : "finder-home-search:\(itemPath.lowercased())"
                pill.searchTerms = [
                    url.lastPathComponent,
                    itemPath,
                    displayParent,
                    "finder",
                    "home",
                    candidate.isDirectory ? "folder" : "file"
                ]
                pill.rankingScore = candidate.score
                return pill
            }
    }

    private func strictFinderHomeSearchScore(query: String, url: URL) -> Double? {
        let normalizedQuery = normalizedDockPillText(query)
        guard normalizedQuery.count >= 2 else { return nil }

        let name = normalizedDockPillText(url.lastPathComponent)
        let parent = normalizedDockPillText(url.deletingLastPathComponent().lastPathComponent)
        guard !name.isEmpty else { return nil }

        if name == normalizedQuery { return 1200 }
        if name.hasPrefix(normalizedQuery) { return 1080 + Double(min(normalizedQuery.count, 12) * 6) }
        if name.contains(normalizedQuery) { return 960 + Double(min(normalizedQuery.count, 10) * 4) }

        let queryTokens = dockPillTokens(normalizedQuery).filter { $0.count >= 2 }
        let nameTokens = dockPillTokens(name)
        if !queryTokens.isEmpty {
            let matched = queryTokens.filter { qToken in
                nameTokens.contains { token in
                    token == qToken || token.hasPrefix(qToken) || token.contains(qToken)
                }
            }
            if !matched.isEmpty {
                return 850 + Double(matched.count * 36)
            }
        }

        // Allow small typo tolerance for real name tokens only, not broad path fuzzy matching.
        if normalizedQuery.count >= 4 {
            let bestDistance = nameTokens
                .filter { $0.count >= 4 }
                .map { levenshteinDistance(normalizedQuery, $0) }
                .min()
            if let bestDistance, bestDistance <= 1 {
                return 790 + Double(max(0, normalizedQuery.count - bestDistance) * 18)
            }
        }

        // Parent match is lower priority and only for multi-word queries.
        if normalizedQuery.contains(" "), parent.contains(normalizedQuery) {
            return 420
        }

        return nil
    }

    private func executeFinderSelectionMenuAction(titleContains fragment: String) {
        guard let finder = NSWorkspace.shared.runningApplications.first(where: {
            $0.bundleIdentifier == "com.apple.finder"
        }) else { return }

        let needle = fragment.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard !needle.isEmpty else { return }

        let pid = finder.processIdentifier
        let items = AXMenuReader.shared.refreshAllMenuItems(for: pid, maxDepth: 7)
        let preferredRoots = ["file", "quick actions", "services"]
        let match = items
            .filter { $0.isEnabled }
            .first { item in
                let title = normalizedDockPillText(item.title)
                let path = normalizedDockPillText(item.pathString)
                let hasPreferredRoot = item.path.contains { part in
                    preferredRoots.contains { normalizedDockPillText(part).contains($0) }
                }
                return hasPreferredRoot && (title.contains(needle) || path.contains(needle))
            }
            ?? items.first { item in
                item.isEnabled && normalizedDockPillText(item.title).contains(needle)
            }

        guard let match else {
            AppToast.show("Finder action unavailable", icon: "exclamationmark.triangle", tint: .orange)
            return
        }

        AXActionResolver.shared.execute(menuPath: match.path, in: finder)
    }

    private func buildFinderSelectionMenuPills(query q: String, excludingTitles: Set<String>) -> [DockPill] {
        guard !effectiveFinderSelectionURLsForPills().isEmpty else { return [] }

        let limit = q.isEmpty ? 12 : 10
        let items = FileContextOverlayController.shared.finderMenuResults(query: q, limit: limit)

        var pills: [DockPill] = []
        for item in items {
            let normalizedTitle = normalizedDockPillText(item.title)
            guard !excludingTitles.contains(normalizedTitle) else { continue }

            let path = item.path
            let sourcePID = item.sourcePID
            let shortcutChar = item.shortcutChar
            let shortcutModifiers = item.shortcutModifiers
            let badge = item.shortcutDisplay   // parent menu name dropped — use shortcut only
            let isShareItem = item.title.lowercased().hasPrefix("share")

            let menuImg = resolvedMenuIcon(for: item)
            var pill = DockPill(
                id: "finder-menu-\(item.id)",
                name: item.title,
                icon: isShareItem ? "square.and.arrow.up" : menuSymbol(for: item),
                accentColorName: isShareItem ? "blue" : "gray",
                badge: badge,
                execute: {
                    if isShareItem {
                        showShareSheetForContext()
                        return
                    }

                    guard sourcePID != 0 else { return }
                    executeDockMenuAction(
                        sourcePID: sourcePID,
                        path: path,
                        shortcutChar: shortcutChar,
                        shortcutModifiers: shortcutModifiers
                    )
                }
            )
            pill.menuItemImage = menuImg
            pill.isShareAction = isShareItem
            pill.menuItemName = item.title
            pill.sourceBundleId = "com.apple.finder"
            pill.sourceAppName = "Finder"
            pill.menuContext = menuContextLabel(from: item.path)
            pill.rankingKind = "finderMenu"
            pill.trackingIdentifier =
                "finder-menu:\(path.joined(separator: " > ").lowercased())"
            pill.searchTerms = item.path + ["finder", "files", "selection"]
            pills.append(pill)
        }

        return pills
    }

    // MARK: - Cross-app / clipboard / session pill helpers

    /// Native share sheet entry for active global selections. This is intentionally
    /// cache/context based only; it must not trigger live menu or AX reads while typing.
    func buildGlobalSelectionSharePills(query q: String) -> [DockPill] {
        guard isGlobalContextActive, hasActiveDockContextSelection else { return [] }
        let normalizedQuery = normalizedDockPillText(q)
        if !normalizedQuery.isEmpty {
            let shareTerms = ["share", "send", "airdrop", "export", "message", "mail"]
            guard shareTerms.contains(where: {
                $0.hasPrefix(normalizedQuery) || normalizedQuery.contains($0)
            }) else { return [] }
        }

        let context = effectiveAXContextForConversation()
        guard !ShareIntentRouter.shared.shareItems(for: context).isEmpty else { return [] }

        let badge: String = {
            switch activeSelection {
            case .files(let urls):
                return urls.count == 1 ? "File" : "\(urls.count) Items"
            case .text:
                return "Text"
            case .url:
                return "URL"
            case .none:
                return "Selection"
            }
        }()
        var pill = DockPill(
            id: "global-selection-share",
            name: "Share Selection",
            icon: "square.and.arrow.up",
            accentColorName: "blue",
            badge: badge,
            execute: { showShareSheetForContext() }
        )
        pill.rankingKind = "payload"
        pill.trackingIdentifier = "global-selection-share"
        pill.searchTerms = ["share", "send", "airdrop", "export", "selection", "files", "text", "url"]
        return [pill]
    }

    /// Pills for apps that can receive the current context (URL, text, file).
    /// Delegates to CrossAppRouter for capability-aware, content-type routing.
    func buildCrossAppPills(query q: String) -> [DockPill] {
        guard settings.crossAppPills else { return [] }
        let context = effectiveAXContextForConversation()
        guard context.selectedFilePaths.isEmpty == false
            || !(context.selectedText ?? "").trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            || !(context.currentURL ?? "").trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            || !q.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
        else { return [] }

        let runningIds = Set(
            NSWorkspace.shared.runningApplications
                .filter { $0.activationPolicy == .regular }
                .compactMap(\.bundleIdentifier)
        )
        let routed = CrossAppRouter.shared.buildPills(
            context: context,
            runningBundleIds: runningIds,
            query: q
        )
        let normalizedQuery = normalizedDockPillText(q)
        let shareIntentQuery =
            isGlobalContextActive
            && hasActiveDockContextSelection
            && ["share", "send", "airdrop", "export"].contains { term in
                normalizedQuery.isEmpty || term.hasPrefix(normalizedQuery) || normalizedQuery.contains(term)
            }
        return routed.compactMap { pill in
            let searchable = normalizedDockPillText("\(pill.label) \(pill.appName)")
            if !normalizedQuery.isEmpty && !shareIntentQuery && !searchable.contains(normalizedQuery) {
                return nil
            }
            var dockPill = DockPill(
                id: "cross-\(pill.bundleId)-\(normalizedDockPillText(pill.label))",
                name: pill.label,
                icon: pill.icon,
                accentColorName: pill.badgeColor,
                badge: isGlobalContextActive && hasActiveDockContextSelection ? pill.appName : nil,
                execute: pill.action
            )
            dockPill.sourceBundleId = pill.bundleId
            dockPill.sourceAppName = pill.appName
            dockPill.rankingKind = "crossApp"
            dockPill.trackingIdentifier = "cross:\(pill.bundleId):\(normalizedDockPillText(pill.label))"
            dockPill.searchTerms = [
                pill.appName, pill.label, "share", "send", "selection", "text", "files", "url"
            ]
            return dockPill
        }
    }

    /// Pills derived from the current clipboard content.
    func buildClipboardPills(query q: String) -> [DockPill] {
        guard settings.clipboardAwarePills else { return [] }
        let pb = NSPasteboard.general
        var pills: [DockPill] = []

        // URL on clipboard
        if let urlStr = pb.string(forType: .string),
            let url = URL(string: urlStr.trimmingCharacters(in: .whitespacesAndNewlines)),
            url.scheme?.hasPrefix("http") == true
        {
            let label = "Open Clipboard URL"
            if q.isEmpty || label.lowercased().contains(q) || "clipboard".contains(q) {
                pills.append(
                    DockPill(
                        id: "clip-url", name: label, icon: "link",
                        accentColorName: "blue", badge: "Clipboard",
                        execute: { NSWorkspace.shared.open(url) }))
            }
            let label2 = "Copy Clipboard URL"
            if q.isEmpty || label2.lowercased().contains(q) {
                pills.append(
                    DockPill(
                        id: "clip-copy-url", name: label2, icon: "doc.on.clipboard",
                        accentColorName: "blue", badge: "Clipboard",
                        execute: {
                            let p = NSPasteboard.general
                            p.clearContents()
                            p.setString(urlStr, forType: .string)
                        }))
            }
        } else if let text = pb.string(forType: .string), !text.isEmpty {
            // Plain text on clipboard
            let preview = String(text.prefix(30)).replacingOccurrences(of: "\n", with: " ")
            let label = "Use: \"\(preview)\""
            if q.isEmpty || label.lowercased().contains(q) || "clipboard".contains(q) {
                pills.append(
                    DockPill(
                        id: "clip-text", name: label, icon: "doc.on.clipboard",
                        accentColorName: "yellow", badge: "Clipboard",
                        execute: {
                            // Re-paste into frontmost app
                            if let app = AppDelegate.shared?.previousFrontmostApp {
                                app.activate(options: .activateIgnoringOtherApps)
                                DispatchQueue.main.asyncAfter(deadline: .now() + 0.15) {
                                    let src = CGEventSource(stateID: .hidSystemState)
                                    let vKey: CGKeyCode = 9  // 'v'
                                    CGEvent(
                                        keyboardEventSource: src, virtualKey: vKey, keyDown: true)?
                                        .flags = .maskCommand
                                    CGEvent(
                                        keyboardEventSource: src, virtualKey: vKey, keyDown: true)?
                                        .post(tap: .cgSessionEventTap)
                                    CGEvent(
                                        keyboardEventSource: src, virtualKey: vKey, keyDown: false)?
                                        .post(tap: .cgSessionEventTap)
                                }
                            }
                        }))
            }
        }

        // File URL(s) on clipboard
        if let urls = pb.readObjects(
            forClasses: [NSURL.self], options: [.urlReadingFileURLsOnly: true]) as? [URL],
            !urls.isEmpty
        {
            let label =
                "Open \(urls.count == 1 ? urls[0].lastPathComponent : "\(urls.count) Files")"
            if q.isEmpty || label.lowercased().contains(q) {
                let captured = urls
                pills.append(
                    DockPill(
                        id: "clip-files", name: label, icon: "doc",
                        accentColorName: "green", badge: "Clipboard",
                        execute: { NSWorkspace.shared.activateFileViewerSelecting(captured) }))
            }
        }
        return pills
    }

    /// Compact pills that surface automatically detected context (files, browser tab, selection text).
    /// Shown when context-awareness is enabled so L2 stays focused on user-selected context.
    private func buildAutoDetectedContextPills(query q: String) -> [DockPill] {
        guard settings.enableContextAIExtensions else { return [] }

        let needle = q.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        var pills: [DockPill] = []

        func add(
            _ id: String, _ name: String, _ icon: String, _ color: String, badge: String?,
            action: @escaping () -> Void
        ) {
            if !needle.isEmpty {
                let haystack = "\(name) \(badge ?? "")".lowercased()
                guard haystack.contains(needle) else { return }
            }
            pills.append(
                DockPill(
                    id: "autocx-\(id)",
                    name: name,
                    icon: icon,
                    accentColorName: color,
                    badge: badge,
                    execute: action
                ))
        }

        switch currentContext {
        case .filesSelected(let urls) where !urls.isEmpty:
            let firstName = urls[0].lastPathComponent
            let badge = urls.count == 1 ? firstName : "\(urls.count) selected"
            add("files", "File Context", "folder.badge.person.crop", "blue", badge: badge) {
                NSWorkspace.shared.activateFileViewerSelecting(urls)
            }

        case .url(let urlString):
            let trimmedURL = urlString.trimmingCharacters(in: .whitespacesAndNewlines)
            if let url = URL(string: trimmedURL), !trimmedURL.isEmpty {
                let badge = url.host ?? "Browser"
                add("url", "Web Context", "globe", "teal", badge: badge) {
                    NSWorkspace.shared.open(url)
                }
            }

        case .textSelected(let text):
            let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
            if !trimmed.isEmpty {
                let compact = trimmed.replacingOccurrences(of: "\n", with: " ")
                let preview = String(compact.prefix(28))
                add("text", "Text Context", "text.quote", "orange", badge: preview) {
                    let pb = NSPasteboard.general
                    pb.clearContents()
                    pb.setString(trimmed, forType: .string)
                }
            }

        default:
            break
        }

        // Fallback for cases where AX captured file selection but currentContext hasn't switched yet.
        if pills.isEmpty && !axContext.selectedFilePaths.isEmpty {
            let urls = axContext.selectedFilePaths.map { URL(fileURLWithPath: $0) }
            let firstName = urls[0].lastPathComponent
            let badge = urls.count == 1 ? firstName : "\(urls.count) selected"
            add("files-ax", "File Context", "folder", "blue", badge: badge) {
                NSWorkspace.shared.activateFileViewerSelecting(urls)
            }
        }

        return Array(pills.prefix(2))
    }

    /// Detect current work session from running apps and re-order adapter actions.
    func sessionRankedAdapterActions(base: [AdapterAction]) -> [AdapterAction] {
        guard settings.sessionDetectionPills else { return base }
        let runningIds = Set(
            NSWorkspace.shared.runningApplications.compactMap { $0.bundleIdentifier })
        // Session profiles: bundles that signal a session type, and action keywords to boost
        let devBundles = [
            "com.apple.dt.Xcode", "com.microsoft.VSCode", "com.jetbrains", "io.cursor",
            "com.sublimetext", "com.github.atom", "com.panic.Nova",
        ]
        let browseBundles = [
            "com.apple.Safari", "com.google.Chrome", "org.mozilla.firefox", "com.microsoft.edgemac",
        ]
        let commsBundles = [
            "com.apple.MobileSMS", "com.tinyspeck.slackmacgap", "com.microsoft.teams",
            "com.discord", "com.apple.mail",
        ]

        let isDev = devBundles.contains { b in runningIds.contains { $0.hasPrefix(b) } }
        let isBrowse = browseBundles.contains { b in runningIds.contains { $0.hasPrefix(b) } }
        let isComms = commsBundles.contains { b in runningIds.contains { $0.hasPrefix(b) } }

        let boostKeywords: [String]
        if isDev {
            boostKeywords = ["build", "run", "debug", "test", "deploy", "commit", "push", "pull"]
        } else if isBrowse {
            boostKeywords = ["open", "browse", "search", "bookmark", "read", "save"]
        } else if isComms {
            boostKeywords = ["send", "share", "copy", "message", "paste", "email"]
        } else {
            return base
        }

        return base.sorted { a, b in
            let aBoost = boostKeywords.contains { a.name.lowercased().contains($0) }
            let bBoost = boostKeywords.contains { b.name.lowercased().contains($0) }
            if aBoost != bBoost { return aBoost }
            return false
        }
    }

    private func normalizedDockPillText(_ text: String) -> String {
        let lowered = text.lowercased()
        let mapped = lowered.unicodeScalars.map { scalar -> Character in
            if CharacterSet.alphanumerics.contains(scalar)
                || CharacterSet.whitespacesAndNewlines.contains(scalar)
            {
                return Character(scalar)
            }
            return " "
        }
        return String(mapped)
            .components(separatedBy: .whitespacesAndNewlines)
            .filter { !$0.isEmpty }
            .joined(separator: " ")
    }

    private func dockPillTokens(_ text: String) -> [String] {
        normalizedDockPillText(text).split(separator: " ").flatMap { rawToken -> [String] in
            let token = String(rawToken)
            switch token {
            case "fav", "favs", "favourite", "favourites", "favorite", "favorites", "favourate", "favourates":
                return [token, "favorite"]
            default:
                return [token]
            }
        }
    }

    /// Returns a human-readable parent menu label from an AXMenuItem path.
    /// e.g. ["File", "Open Recent", "doc.txt"] → "Open Recent"
    ///      ["Apple", "About This Mac"] → "Apple Menu"
    nonisolated private func menuContextLabel(from path: [String]) -> String? {
        guard path.count > 1 else { return nil }
        let parent = path[path.count - 2]
        switch parent {
        case "Apple": return "Apple Menu"
        case "Open Recent": return "Recent Items"
        default: return parent
        }
    }

    nonisolated private func isAppleMenuItem(_ item: AXMenuItem) -> Bool {
        item.isAppleMenu
            || menuContextLabel(from: item.path) == "Apple Menu"
            || item.path.first == "Apple"
    }

    /// macOS-style dock magnification scale for a pill at `index`.
    /// Peaked at the hovered/focused index, falls off smoothly with distance.
    private func dockMagnificationScale(for index: Int) -> CGFloat {
        let refIdx = l2.focusedPillIndex ?? hoveredDockPillIndex
        guard let ref = refIdx else { return 1.0 }
        let dist = CGFloat(abs(index - ref))
        let peak: CGFloat = 0.30   // +30% at the focal pill
        let falloff: CGFloat = 2.5 // distance at which magnification reaches zero
        return 1.0 + peak * max(0, 1.0 - dist / falloff)
    }

    private func dockPillAppAliases(appName: String, bundleId: String) -> [String] {
        var aliases = Set<String>()
        let normalizedName = normalizedDockPillText(appName)
        if !normalizedName.isEmpty {
            aliases.insert(normalizedName)
            if let firstWord = normalizedName.split(separator: " ").first {
                aliases.insert(String(firstWord))
            }
            if normalizedName == "visual studio code" || normalizedName == "vs code" {
                aliases.formUnion(["code", "vscode", "vs code", "visual studio code"])
            }
            if normalizedName.hasSuffix("s"), normalizedName.count > 3 {
                aliases.insert(String(normalizedName.dropLast()))
            }
        }

        if let bundleTail = bundleId.split(separator: ".").last {
            let tail = normalizedDockPillText(String(bundleTail))
            if !tail.isEmpty && tail != "app" {
                aliases.insert(tail)
            }
        }

        switch bundleId {
        case "com.apple.MobileSMS":
            aliases.formUnion(["messages", "message", "imessage", "texts"])
        case "com.apple.mail":
            aliases.formUnion(["mail", "email"])
        case "com.apple.systempreferences":
            aliases.formUnion(["settings", "preferences", "system settings", "system preferences"])
        case "com.apple.Safari":
            aliases.insert("safari")
        case "com.microsoft.VSCode", "com.microsoft.VSCodeInsiders":
            aliases.formUnion(["code", "vscode", "vs code", "visual studio code"])
        default:
            break
        }

        return aliases.filter { !$0.isEmpty }
    }

    private func defaultDockPillTrackingIdentifier(_ pill: DockPill) -> String {
        if !pill.trackingIdentifier.isEmpty {
            return pill.trackingIdentifier
        }

        let scope = pill.sourceBundleId.isEmpty ? "global" : pill.sourceBundleId
        let baseName =
            !pill.menuItemName.isEmpty ? pill.menuItemName : pill.name
        let normalizedBase = normalizedDockPillText(baseName)
        if pill.rankingKind == "menu", !normalizedBase.isEmpty {
            return "dock-menu:\(scope):\(normalizedBase)"
        }
        return "dock-pill:\(scope):\(pill.rankingKind):\(normalizedBase)"
    }

    private func dockPillKindBaseScore(_ pill: DockPill) -> Double {
        switch pill.rankingKind {
        case "appLaunch": return 136
        case "semanticIntent": return 128
        case "finderCurrent": return 114
        case "finderSearch": return 104
        case "adapter", "appAdapter": return 108
        case "menu": return 98
        case "submenuParent": return 96
        case "payload": return 94
        case "cliTool": return 92
        case "quickAction": return 90
        case "contextExtension": return 86
        case "tool": return 82
        case "crossApp": return 72
        case "finderContext": return 68
        case "context", "clipboard": return 62
        default: return 58
        }
    }

    private func scoreDockPill(
        _ pill: DockPill,
        originalIndex: Int,
        query: String,
        rawQuery: String,
        scopedBundleId: String,
        scopedAppName: String,
        isExplicitAppScope: Bool
    ) -> Double {
        var score = dockPillKindBaseScore(pill)
        let trackingIdentifier = defaultDockPillTrackingIdentifier(pill)
        let usageScore = UsageTracker.shared.getScore(for: trackingIdentifier)
        score += usageScore * (query.isEmpty ? 8.5 : 6.5)

        // Boost frequently-used actions from per-app interaction history
        if let bid = pill.sourceBundleId.isEmpty ? nil : Optional(pill.sourceBundleId),
           let aid = trackingIdentifier.components(separatedBy: ":").dropFirst().joined(separator: ":") as String? {
            let boost = AppInteractionStore.shared.frequencyBoost(bundleId: bid, actionId: aid)
            score += boost * (query.isEmpty ? 55 : 35)
        }

        if pill.isFavourited {
            score += 190
        }

        let frontBundleId =
            frontmost.bundleID.isEmpty ? axContext.bundleId : frontmost.bundleID
        let sourceBundleId = pill.sourceBundleId.isEmpty ? scopedBundleId : pill.sourceBundleId
        let sourceAppName = pill.sourceAppName.isEmpty ? scopedAppName : pill.sourceAppName

        if !sourceBundleId.isEmpty {
            if sourceBundleId == scopedBundleId {
                score += isExplicitAppScope ? 220 : 125
            } else if sourceBundleId == frontBundleId {
                score += isExplicitAppScope ? 28 : 92
            } else if isExplicitAppScope {
                score -= 35
            }
        }

        let appAliases = dockPillAppAliases(appName: sourceAppName, bundleId: sourceBundleId)
        let normalizedName = normalizedDockPillText(pill.name)
        let normalizedBadge = normalizedDockPillText(pill.badge ?? "")
        let corpora = ([normalizedName, normalizedBadge] + pill.searchTerms.map(normalizedDockPillText)
            + appAliases)
            .filter { !$0.isEmpty }

        if !rawQuery.isEmpty && appAliases.contains(rawQuery) {
            score += sourceBundleId == scopedBundleId ? 120 : 60
        }

        if query.isEmpty {
            let isPureScopedAppSelection =
                isExplicitAppScope && !rawQuery.isEmpty && appAliases.contains(rawQuery)
            if pill.rankingKind == "adapter" || pill.rankingKind == "appAdapter" {
                score += isPureScopedAppSelection ? 72 : 28
            }
            if pill.rankingKind == "quickAction" {
                score += isPureScopedAppSelection ? 40 : 18
            }
            if pill.rankingKind == "menu" {
                score += isPureScopedAppSelection ? 34 : 18
            }
            if pill.rankingKind == "cliTool" {
                score += isPureScopedAppSelection ? 8 : 24
            }
            if pill.rankingKind == "appLaunch" && isPureScopedAppSelection {
                score -= 84
            }
            if normalizedName.hasPrefix("new ") || normalizedName == "new" {
                score += 22
            }
            return score - (Double(originalIndex) * 0.01)
        }

        if let relevance = rankedTextMatchScore(
            query: query,
            primary: normalizedName,
            aliases: pill.searchTerms,
            contexts: [normalizedBadge] + appAliases
        ) {
            score += relevance / 24.0
        }

        if normalizedName == query {
            score += 280
        } else if corpora.contains(query) {
            score += 220
        }

        if normalizedName.hasPrefix(query) {
            score += 195
        } else if corpora.contains(where: { $0.hasPrefix(query) }) {
            score += 165
        }

        if normalizedName.contains(query) {
            score += 120
        } else if corpora.contains(where: { $0.contains(query) }) {
            score += 82
        }

        let orderedQueryTokens = dockPillTokens(query)
        let queryTokens = Set(orderedQueryTokens)
        if !queryTokens.isEmpty {
            let nameTokens = Set(dockPillTokens(normalizedName))
            let corpusTokens = Set(corpora.flatMap(dockPillTokens))
            let nameOverlap = queryTokens.intersection(nameTokens).count
            let corpusOverlap = queryTokens.intersection(corpusTokens).count

            if nameOverlap > 0 {
                score += Double(nameOverlap) * 54
            }
            if corpusOverlap > nameOverlap {
                score += Double(corpusOverlap - nameOverlap) * 30
            }

            if let firstToken = orderedQueryTokens.first {
                if nameTokens.contains(firstToken) {
                    score += 34
                }
                if normalizedName.hasPrefix(firstToken) {
                    score += 28
                }
            }

            // Typo-tolerance: boost when a query token is within edit distance 1-2 of a corpus token
            // Handles "wallpapper" → "wallpaper", "settngs" → "settings", etc.
            for qt in queryTokens where qt.count >= 4 {
                for ct in corpusTokens where ct.count >= 4 {
                    guard !queryTokens.contains(ct) else { continue } // already scored exactly
                    let dist = pillEditDistance(qt, ct)
                    let maxLen = max(qt.count, ct.count)
                    if dist == 1 {
                        score += 38 * (1.0 - Double(dist) / Double(maxLen))
                    } else if dist == 2 && maxLen >= 7 {
                        score += 18 * (1.0 - Double(dist) / Double(maxLen))
                    }
                }
            }
        }

        return score - (Double(originalIndex) * 0.01)
    }

    /// Levenshtein edit distance (capped early at 3 for performance).
    private func pillEditDistance(_ a: String, _ b: String) -> Int {
        let a = Array(a), b = Array(b)
        let m = a.count, n = b.count
        if abs(m - n) > 3 { return 4 }
        var prev = Array(0...n)
        var curr = [Int](repeating: 0, count: n + 1)
        for i in 1...m {
            curr[0] = i
            var rowMin = i
            for j in 1...n {
                curr[j] = a[i-1] == b[j-1] ? prev[j-1] : 1 + min(prev[j-1], prev[j], curr[j-1])
                rowMin = min(rowMin, curr[j])
            }
            if rowMin > 3 { return 4 }
            swap(&prev, &curr)
        }
        return prev[n]
    }

    private func rankDockPills(
        _ pills: [DockPill],
        rawQuery: String,
        rankingQuery: String,
        scopedBundleId: String,
        scopedAppName: String,
        isExplicitAppScope: Bool,
        includeNonMatching: Bool = false
    ) -> [DockPill] {
        guard !rawQuery.isEmpty else { return pills }

        let normalizedRawQuery = normalizedDockPillText(rawQuery)
        let normalizedRankingQuery = normalizedDockPillText(rankingQuery)

        return pills.enumerated()
            .map { index, pill in
                var enriched = pill
                enriched.trackingIdentifier = defaultDockPillTrackingIdentifier(pill)
                enriched.rankingScore = scoreDockPill(
                    enriched,
                    originalIndex: index,
                    query: normalizedRankingQuery,
                    rawQuery: normalizedRawQuery,
                    scopedBundleId: scopedBundleId,
                    scopedAppName: scopedAppName,
                    isExplicitAppScope: isExplicitAppScope
                )
                return enriched
            }
            .filter { pill in
                includeNonMatching
                    || normalizedRankingQuery.isEmpty
                    || dockPillHasQuerySignal(
                        pill,
                        query: normalizedRankingQuery,
                        rawQuery: normalizedRawQuery,
                        scopedBundleId: scopedBundleId,
                        scopedAppName: scopedAppName
                    )
            }
            .sorted { lhs, rhs in
                if lhs.rankingScore == rhs.rankingScore {
                    return lhs.name.localizedCaseInsensitiveCompare(rhs.name) == .orderedAscending
                }
                return lhs.rankingScore > rhs.rankingScore
            }
    }

    private func dockPillHasQuerySignal(
        _ pill: DockPill,
        query: String,
        rawQuery: String,
        scopedBundleId: String,
        scopedAppName: String
    ) -> Bool {
        if query.isEmpty { return true }
        if ["payload", "finderSearch", "finderCurrent", "finderGoTo", "submenuChild", "submenuParent"].contains(pill.rankingKind) {
            return true
        }

        let sourceBundleId = pill.sourceBundleId.isEmpty ? scopedBundleId : pill.sourceBundleId
        let sourceAppName = pill.sourceAppName.isEmpty ? scopedAppName : pill.sourceAppName
        let appAliases = dockPillAppAliases(appName: sourceAppName, bundleId: sourceBundleId)
        if !rawQuery.isEmpty, appAliases.contains(rawQuery) { return true }

        let normalizedName = normalizedDockPillText(pill.name)
        let normalizedBadge = normalizedDockPillText(pill.badge ?? "")
        let corpora = ([normalizedName, normalizedBadge] + pill.searchTerms.map(normalizedDockPillText) + appAliases)
            .filter { !$0.isEmpty }

        if corpora.contains(query) { return true }
        if corpora.contains(where: { $0.hasPrefix(query) || $0.contains(query) }) { return true }

        let queryTokens = Set(dockPillTokens(query))
        guard !queryTokens.isEmpty else { return false }
        let corpusTokens = Set(corpora.flatMap(dockPillTokens))
        if !queryTokens.intersection(corpusTokens).isEmpty { return true }

        for qt in queryTokens where qt.count >= 4 {
            for ct in corpusTokens where ct.count >= 4 {
                if pillEditDistance(qt, ct) <= 2 { return true }
            }
        }
        return false
    }

    /// If `q` starts with a known recent/running app name, returns (that app, remainder query).
    /// e.g. "safari tab" → (safariApp, "tab")   "xcode build" → (xcodeApp, "build")
    // MARK: - Instant menu reload on app switch

    /// Called immediately when the frontmost app changes while the dock is open.
    /// Cancels any in-flight menu load and starts a fresh one for `app`.
    private func reloadMenuForApp(_ app: NSRunningApplication) {
        guard showContextInDock, !app.isTerminated else { return }
        let pid = app.processIdentifier
        let name = app.localizedName ?? ""
        let useCacheOnly = isGlobalContextActive

        menuLoadTask?.cancel()
        liveMenuRefreshTask?.cancel()
        liveMenuRefreshTask = nil
        lastLiveMenuStructureRefresh = .distantPast
        contextMenuPills = []
        previousEnabledIDs = []

        menuLoadTask = Task.detached(priority: .userInitiated) {
            var loadedFromPersistentCache = false
            var items: [AXMenuItem] = []

            if useCacheOnly {
                items = AppMenuCapabilityCache.shared.menuItems(for: app, maxResults: 120)
                loadedFromPersistentCache = !items.isEmpty
            } else {
                items = AXMenuReader.shared.refreshAllMenuItems(for: pid, maxDepth: 6)
                if items.isEmpty {
                    try? await Task.sleep(nanoseconds: 180_000_000)
                    items = AXMenuReader.shared.refreshAllMenuItems(for: pid, maxDepth: 6)
                }
                if items.isEmpty {
                    let snapshotItems = await MainActor.run { AXContextReader.shared.current.menuItems }
                    items = snapshotItems.compactMap { info in
                        let path = info.fullPath
                            .components(separatedBy: " > ")
                            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
                            .filter { !$0.isEmpty }
                        guard let title = path.last, !title.isEmpty else { return nil }
                        return AXMenuItem(
                            title: title,
                            path: path,
                            isEnabled: info.enabled,
                            element: AXUIElementCreateApplication(pid),
                            children: [],
                            sourcePID: pid,
                            sourceAppName: name,
                            isAppleMenu: path.first == "Apple",
                            shortcutChar: nil,
                            shortcutModifiers: 0
                        )
                    }
                }
                if items.isEmpty {
                    items = AppMenuCapabilityCache.shared.menuItems(for: app, maxResults: 120)
                    loadedFromPersistentCache = !items.isEmpty
                }
                if !loadedFromPersistentCache {
                    AppMenuCapabilityCache.shared.store(items: items, for: app)
                }
            }
            let debug = AXMenuReader.shared.lastDebug(for: pid) ?? "no reader detail"
            await MainActor.run {
                self.liveMenuItems = items
                self.menuDebugText = "\(name): \(items.count) menus, \(debug)"
                self.lastLiveMenuSignature = self.menuSignature(for: items)
                self.previousEnabledIDs = Set(items.filter(\.isEnabled).map(\.id))
                self.syncRecentAppsFromAppleMenu(items)
            }
        }

        // Restart observer for the new app
        selectionModel.start(for: pid)

        // Refresh AX context snapshot
        AXContextReader.shared.refresh(from: app)
        axContext = AXContextReader.shared.current
    }

    // MARK: - Finder AI — natural language over current folder

    private func handleFinderAIQuery(query: String) {
        guard !query.isEmpty else { return }

        let scope = resolveDockScope(for: query)
        let effectiveQuery =
            scope.scopedBundleId == "com.apple.finder"
                && scope.isExplicitAppScope
                && !scope.scopedSearchQuery.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            ? scope.scopedSearchQuery
            : query
        let normalized = effectiveQuery.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        let folderPath = currentFinderFolderPath()
        let finderFrontmostWindowActive = isFinderFrontmostWindowContext()
        let folderSearchAttached = isFinderCurrentWindowSearchAttached(currentFolderPath: folderPath)
        guard finderFolderQueryModeActive && folderSearchAttached else {
            clearFinderSemanticState()
            return
        }
        let selectedFileURLs = effectiveFinderSelectedFileURLs(
            for: normalized,
            currentFolderPath: folderPath
        )
        let selectedFiles = selectedFileURLs.map(\.path)

        if let pending = pendingFinderOperation {
            l2.chatMessages.append(AIChatMessage(role: .user, content: query))
            if isAffirmativeResponse(normalized) {
                pendingFinderOperation = nil
                runFinderIntent(pending.intent, folderPath: pending.folderPath, confirmed: true)
                return
            }
            if isNegativeResponse(normalized) {
                pendingFinderOperation = nil
                l2.chatMessages.append(
                    AIChatMessage(
                        role: .assistant, content: "Okay, I won't reorganize that folder."))
                return
            }
        }

        if let intent = parseFinderIntent(query: normalized) {
            l2.chatMessages.append(AIChatMessage(role: .user, content: query))
            l2.isLoading = true
            searchState.query = ""
            dismissMediaLayer()
            runFinderIntent(
                intent, folderPath: folderPath, confirmed: false, originalQuery: normalized)
            return
        }

        if isFinderSearchStyleQuery(normalized) {
            let profile = finderSemanticProfile(for: normalized)
            guard folderSearchAttached else {
                l2.chatMessages.append(AIChatMessage(role: .user, content: query))
                l2.chatMessages.append(
                    AIChatMessage(
                        role: .assistant,
                        content:
                            finderFrontmostWindowActive
                                ? "Add the current Finder folder first, then I’ll search only the files and folders in this frontmost Finder window."
                                : "Bring Finder to the front, add the current folder, then I’ll search only the files and folders in that frontmost Finder window."
                    )
                )
                searchState.query = ""
                dismissMediaLayer()
                clearFinderSemanticState()
                return
            }

            let cachedResults = finderSemanticQuery == normalized ? finderSemanticResults : []
            if !cachedResults.isEmpty {
                l2.chatMessages.append(AIChatMessage(role: .user, content: query))
                l2.chatMessages.append(
                    AIChatMessage(
                        role: .assistant,
                        content: finderSubmissionSummary(for: effectiveQuery, results: cachedResults)
                    ))
                searchState.query = ""
                dismissMediaLayer()
                updateL2Results(cachedResults)
                return
            }

            l2.chatMessages.append(AIChatMessage(role: .user, content: query))
            l2.isLoading = true
            searchState.query = ""
            dismissMediaLayer()
            l2.currentTask = Task {
                let spotlightEnabled = settings.enableSpotlightSearch
                let advancedMatches = await MainActor.run {
                    buildAdvancedFinderDataMatches(
                        profile: profile,
                        currentFolderPath: folderPath,
                        limit: 24
                    )
                }
                let fastMatches = await buildFastFinderSemanticMatches(
                    query: normalized,
                    currentFolderPath: folderPath
                )
                let spotlightMatches =
                    spotlightEnabled && normalized.count >= 3
                    ? runFinderSpotlightSearch(
                        query: normalized,
                        currentFolderPath: folderPath,
                        limit: 18
                    )
                    : []
                let targetMatches = await buildFinderTargetSemanticMatches(
                    for: normalized,
                    currentFolderPath: folderPath,
                    spotlightEnabled: spotlightEnabled
                )
                let mergedMatches = mergeFinderSemanticMatches(
                    mergeFinderSemanticMatches(
                        mergeFinderSemanticMatches(advancedMatches, with: fastMatches),
                        with: spotlightMatches
                    ),
                    with: targetMatches
                )

                await MainActor.run {
                    let results = makeFinderSemanticSearchResults(from: mergedMatches)
                    finderSemanticQuery = normalized
                    finderSemanticResults = results
                    finderSemanticPills = makeFinderSemanticDockPills(from: mergedMatches)
                    l2.chatMessages.append(
                        AIChatMessage(
                            role: .assistant,
                            content: finderSubmissionSummary(for: effectiveQuery, results: results)
                        ))
                    updateL2Results(results)
                    l2.isLoading = false
                    l2.currentTask = nil
                }
            }
            return
        }

        l2.chatMessages.append(AIChatMessage(role: .user, content: query))
        l2.isLoading = true
        searchState.query = ""
        dismissMediaLayer()

        // Snapshot everything we know about Finder right now
        let fallbackFolderPath =
            axContext.currentURL?
            .replacingOccurrences(of: "file://", with: "")
            .removingPercentEncoding
            ?? axContext.windowTitle
            ?? "unknown folder"
        // Set currentContext so on-device AI gets proper file/PDF content via buildContextPrompt
        if !selectedFileURLs.isEmpty {
            currentContext = .filesSelected(selectedFileURLs)
        }

        // Read all visible filenames in the current folder via AppleScript
        l2.currentTask = Task {
            let spotlightEnabled = settings.enableSpotlightSearch && folderSearchAttached
            let finderProfile = finderSemanticProfile(for: normalized)
            let advancedSemanticMatches =
                folderSearchAttached || finderProfile.explicitLocationPath != nil || isFinderFrontmostWindowContext()
                ? await MainActor.run {
                    buildAdvancedFinderDataMatches(
                        profile: finderProfile,
                        currentFolderPath: folderPath,
                        limit: 16
                    )
                }
                : []
            let fastSemanticMatches =
                folderSearchAttached
                ? await buildFastFinderSemanticMatches(
                    query: normalized,
                    currentFolderPath: folderPath
                )
                : []
            let spotlightSemanticMatches =
                spotlightEnabled && normalized.count >= 3
                ? runFinderSpotlightSearch(
                    query: normalized,
                    currentFolderPath: folderPath,
                    limit: 12
                )
                : []
            let targetMatches =
                folderSearchAttached
                ? await buildFinderTargetSemanticMatches(
                    for: normalized,
                    currentFolderPath: folderPath,
                    spotlightEnabled: spotlightEnabled
                )
                : []
            let retrievedMatches = mergeFinderSemanticMatches(
                mergeFinderSemanticMatches(
                    advancedSemanticMatches,
                    with: fastSemanticMatches
                ),
                with: mergeFinderSemanticMatches(spotlightSemanticMatches, with: targetMatches)
            )

            // 1. Get visible files in current Finder window
            let visibleFilesScript = """
                tell application "Finder"
                    try
                        set theItems to every item of (target of front window) as alias
                        set nameList to {}
                        repeat with i in theItems
                            set end of nameList to name of i
                        end repeat
                        return nameList as string
                    end try
                end tell
                """
            var visibleFiles: [String] = []
            if let raw = await runAppleScript(visibleFilesScript), !raw.isEmpty {
                visibleFiles = raw.components(separatedBy: ", ").filter { !$0.isEmpty }
            }

            // 2. Read file content for selected files (text, PDF, code, etc.)
            var fileContentBlock = ""
            for filePath in selectedFiles.prefix(3) {
                let fileURL = URL(fileURLWithPath: filePath)
                let ext = fileURL.pathExtension.lowercased()
                let textExts = Set([
                    "txt", "md", "markdown", "swift", "py", "js", "ts", "jsx", "tsx", "html", "css",
                    "scss", "json", "xml", "yaml", "yml", "csv", "log", "sh", "bash", "zsh", "conf",
                    "config", "ini", "toml", "r", "c", "cpp", "h", "java", "go", "rs", "rb", "php",
                    "sql", "rtf",
                ])
                var content: String? = nil
                if textExts.contains(ext) {
                    content = try? String(contentsOf: fileURL, encoding: .utf8)
                    if content == nil {
                        content = try? String(contentsOf: fileURL, encoding: .isoLatin1)
                    }
                    if let c = content { content = String(c.prefix(4000)) }
                } else if ext == "pdf" {
                    if let pdf = PDFDocument(url: fileURL) {
                        var text = ""
                        for i in 0..<min(pdf.pageCount, 8) {
                            if let pageText = pdf.page(at: i)?.string { text += pageText + "\n" }
                            if text.count > 4000 { break }
                        }
                        if !text.isEmpty { content = String(text.prefix(4000)) }
                    }
                } else if ext == "docx" || ext == "rtfd" {
                    if let attr = try? NSAttributedString(
                        url: fileURL, options: [:], documentAttributes: nil)
                    {
                        content = String(attr.string.prefix(4000))
                    }
                }
                if let content, !content.isEmpty {
                    fileContentBlock +=
                        "\n\n### Content of \(fileURL.lastPathComponent):\n```\n\(content)\n```"
                }
            }

            let retrievedSummaryBlock: String = {
                guard !retrievedMatches.isEmpty else { return "" }
                let lines = retrievedMatches.prefix(8).map { match in
                    "- \(match.title) [\(match.source)] \(finderDisplayPath(match.path))"
                }
                return "\nRETRIEVED FINDER MATCHES:\n" + lines.joined(separator: "\n")
            }()

            let currentFolderCatalogBlock =
                folderSearchAttached
                ? buildFinderFileCatalogBlock(
                    currentFolderPath: folderPath,
                    selectedFilePaths: selectedFiles
                )
                : ""

            let resolvedTargetContext = buildFinderResolvedTargetContext(
                query: normalized,
                selectedFilePaths: selectedFiles,
                retrievedMatches: retrievedMatches
            )

            let retrievedContentBlock: String = {
                let candidateURLs = retrievedMatches
                    .filter { !$0.isDirectory }
                    .prefix(2)
                    .map { URL(fileURLWithPath: $0.path) }
                guard !candidateURLs.isEmpty else { return "" }

                let analyzedFiles = ContextDetector.shared.analyzeFiles(Array(candidateURLs))
                var block = ""
                for file in analyzedFiles.prefix(2) {
                    guard let content = file.content,
                        !content.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                    else { continue }
                    block +=
                        "\n\n### Retrieved content from \(file.url.lastPathComponent):\n```\n\(String(content.prefix(2500)))\n```"
                }
                return block
            }()

            // 3. Build the AI prompt
            let systemPrompt = """
                You are a macOS Finder assistant embedded in Context-Dock.
                You help users with file operations AND answer questions about file contents.

                \(currentDateTimeContextBlock())

                CURRENT STATE:
                - Folder: \(fallbackFolderPath)
                - Selected files: \(selectedFiles.isEmpty ? "none" : selectedFiles.map { URL(fileURLWithPath: $0).lastPathComponent }.joined(separator: ", "))
                - Visible files in window: \(visibleFiles.isEmpty ? "unknown" : visibleFiles.prefix(30).joined(separator: ", "))
                - Finder menu actions: disabled in folder query mode
                \(retrievedSummaryBlock)
                \(currentFolderCatalogBlock)
                \(resolvedTargetContext.summaryBlock)
                \(fileContentBlock)
                \(retrievedContentBlock)
                \(resolvedTargetContext.contentBlock)

                RULES:
                1. Respond with EITHER:
                   a) ACTION:APPLESCRIPT:<applescript code on one line using \\n for newlines>
                   b) ACTION:SHELL:<shell command>
                   c) ANSWER:<plain text answer if the user asks about file contents, explanations, summaries, or informational questions>

                2. For questions about what a file contains, what it is, summarize, explain, translate — use ANSWER with the file content above.
                3. For file operations prefer AppleScript (it integrates with Finder natively).
                4. For conversions, compressions, bulk renames prefer SHELL.
                5. Do not use Finder menu actions in folder query mode.
                6. Use the EXACT filenames from the visible files list when referencing files.
                7. For selected files use: \(selectedFiles.map { "\"\($0)\"" }.joined(separator: ", "))
                8. Shell commands run in bash. $HOME = /Users/\(NSUserName()). Current dir = \(fallbackFolderPath)
                9. For ACTION responses, output ONLY the ACTION line. For ANSWER responses, provide a helpful answer.
                10. For file operations, prefer RESOLVED TARGET FILES first. If there are no resolved targets, use SELECTED FILES. If there is still ambiguity, ask a short clarification instead of guessing.
                11. When converting or chaining actions, use the exact file path from RESOLVED TARGET FILES or SELECTED FILES.

                EXAMPLES:
                User: move selected files to desktop
                ACTION:APPLESCRIPT:tell application "Finder" to move selection to (path to desktop)

                User: rename all jpg files to add today's date
                ACTION:SHELL:cd "\(fallbackFolderPath)" && for f in *.jpg; do mv "$f" "$(date +%Y-%m-%d)_$f"; done

                User: what is this file about?
                ANSWER:This file is about [summary based on the file content above].

                User: how many files are here
                ANSWER:There are \(visibleFiles.count) visible items in \(fallbackFolderPath).
                """

            let provider = await MainActor.run { self.settings.selectedAIProvider }

            do {
                let context: [[String: String]] = [
                    ["role": "system", "content": systemPrompt],
                    ["role": "user", "content": query],
                ]

                if selectedFileURLs.isEmpty && !resolvedTargetContext.targetURLs.isEmpty {
                    await MainActor.run {
                        self.rememberFinderFollowUpTargets(
                            Array(resolvedTargetContext.targetURLs.prefix(3)),
                            folderPath: folderPath,
                            sourceQuery: normalized
                        )
                        self.currentContext = .filesSelected(Array(resolvedTargetContext.targetURLs.prefix(3)))
                    }
                } else if !selectedFileURLs.isEmpty {
                    await MainActor.run {
                        self.rememberFinderFollowUpTargets(
                            Array(selectedFileURLs.prefix(3)),
                            folderPath: folderPath,
                            sourceQuery: normalized
                        )
                    }
                }

                let response: String
                if provider == .onDevice {
                    response = try await self.sendToOnDeviceAI(query: query, context: context)
                } else {
                    response = try await self.sendToProvider(query: query, context: context)
                }

                await MainActor.run {
                    self.l2.isLoading = false
                    self.l2.currentTask = nil
                    DispatchQueue.main.async {
                        self.executeFinderAIResponse(response, folderPath: fallbackFolderPath)
                    }
                }
            } catch {
                await MainActor.run {
                    self.l2.chatMessages.append(
                        AIChatMessage(
                            role: .assistant,
                            content: "❌ \(error.localizedDescription)",
                            isError: true
                        ))
                    self.l2.isLoading = false
                    self.l2.currentTask = nil
                }
            }
        }
    }

    private func parseFinderIntent(query: String) -> FinderIntent? {
        if query.contains("organize"),
            query.contains("type") || query.contains("types") || query.contains("category")
        {
            return .organizeByType
        }

        let detectedCategory = FinderFileCategory.detect(in: query)

        if query.contains("recent"),
            detectedCategory == nil,
            !query.contains("today"),
            !query.contains("yesterday"),
            !query.contains("week"),
            !query.contains("large"),
            !query.contains("small")
        {
            return .showRecentFiles(limit: 30)
        }

        return nil
    }

    private func runFinderIntent(
        _ intent: FinderIntent, folderPath: String, confirmed: Bool, originalQuery: String = ""
    ) {
        l2.currentTask?.cancel()
        l2.currentTask = Task {
            switch intent {
            case .showRecentFiles(let limit):
                let urls = recentFinderItems(in: folderPath, limit: limit)
                let summary: String
                if urls.isEmpty {
                    summary =
                        "No recent files found in \(URL(fileURLWithPath: folderPath).lastPathComponent)."
                } else {
                    summary =
                        "Found \(urls.count) recent item\(urls.count == 1 ? "" : "s") in \(URL(fileURLWithPath: folderPath).lastPathComponent). Showing newest first."
                }
                let results = buildFinderSearchResults(from: urls, subtitle: "Recent Files")
                await MainActor.run {
                    l2.chatMessages.append(AIChatMessage(role: .assistant, content: summary))
                    updateL2Results(results)
                    l2.isLoading = false
                    l2.currentTask = nil
                }

            case .filterFiles(let category):
                // For archives, further filter by a specific extension if the original query mentions one
                let lowerQuery = originalQuery.lowercased()
                let specificExt: String? = {
                    if category == .archive {
                        if lowerQuery.contains("torrent") { return "torrent" }
                        if lowerQuery.contains("dmg") { return "dmg" }
                        if lowerQuery.contains("zip") { return "zip" }
                    }
                    return nil
                }()
                let all = finderItems(in: folderPath).filter { category.matches($0) }
                let urls =
                    specificExt != nil
                    ? all.filter { $0.pathExtension.lowercased() == specificExt! }
                    : all
                let typeName = specificExt ?? category.displayName
                let folderName = URL(fileURLWithPath: folderPath).lastPathComponent
                let summary: String
                if urls.isEmpty {
                    summary = "No \(typeName) files found in \(folderName)."
                } else {
                    let names = urls.prefix(5).map { $0.lastPathComponent }.joined(
                        separator: "\n• ")
                    summary =
                        "Found \(urls.count) \(typeName) file\(urls.count == 1 ? "" : "s") in \(folderName):\n• \(names)"
                        + (urls.count > 5 ? "\n…and \(urls.count - 5) more." : "")
                }
                let results = buildFinderSearchResults(from: urls, subtitle: category.resultTitle)
                await MainActor.run {
                    l2.chatMessages.append(AIChatMessage(role: .assistant, content: summary))
                    updateL2Results(results)
                    l2.isLoading = false
                    l2.currentTask = nil
                }

            case .organizeByType:
                if !confirmed {
                    let preview = previewOrganizeFinderItems(in: folderPath)
                    await MainActor.run {
                        if preview.moveCount == 0 {
                            l2.chatMessages.append(
                                AIChatMessage(
                                    role: .assistant,
                                    content:
                                        "Nothing to reorganize in \(URL(fileURLWithPath: folderPath).lastPathComponent)."
                                ))
                        } else {
                            pendingFinderOperation = PendingFinderOperation(
                                intent: intent, folderPath: folderPath)
                            l2.chatMessages.append(
                                AIChatMessage(role: .assistant, content: preview.message))
                        }
                        l2.isLoading = false
                        l2.currentTask = nil
                    }
                    return
                }

                let result = organizeFinderItemsByType(in: folderPath)
                await MainActor.run {
                    l2.chatMessages.append(
                        AIChatMessage(
                            role: .assistant, content: result.message, isError: !result.success))
                    if !result.createdFolders.isEmpty {
                        updateL2Results(
                            buildFinderSearchResults(
                                from: result.createdFolders, subtitle: "Organized Folders"))
                    }
                    l2.isLoading = false
                    l2.currentTask = nil
                }
            }
        }
    }

    private func currentFinderFolderPath() -> String {
        let cachedPath = cachedFinderCurrentDirectoryPath.trimmingCharacters(
            in: .whitespacesAndNewlines)
        if !cachedPath.isEmpty {
            return cachedPath
        }

        let decodedURLPath =
            axContext.currentURL?
            .replacingOccurrences(of: "file://", with: "")
            .removingPercentEncoding?
            .trimmingCharacters(in: .whitespacesAndNewlines)

        let fallback =
            (decodedURLPath?.isEmpty == false ? decodedURLPath : nil)
            ?? {
                let title = axContext.windowTitle?.trimmingCharacters(in: .whitespacesAndNewlines)
                return title?.isEmpty == false ? title : nil
            }()

        return fallback ?? NSHomeDirectory()
    }

    private func refreshCachedFinderCurrentDirectory(for bundleID: String) {
        guard bundleID == "com.apple.finder" else {
            cachedFinderCurrentDirectoryPath = ""
            return
        }

        cachedFinderCurrentDirectoryPath =
            ContextDetector.shared.getCurrentFinderDirectory()?
            .trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
    }

    private func isFinderFrontmostWindowContext() -> Bool {
        if frontmost.bundleID == "com.apple.finder" { return true }
        if contextTargetApp()?.bundleIdentifier == "com.apple.finder" { return true }
        return axContext.bundleId == "com.apple.finder"
    }

    /// Returns true when Finder is frontmost AND has at least one real Finder window
    /// (folder/file browser), distinguishing it from the "desktop-only" state where
    /// Finder is active but the user clicked the wallpaper (no window open).
    private func finderHasActiveWindow() -> Bool {
        guard frontmost.bundleID == "com.apple.finder" || axContext.bundleId == "com.apple.finder" else { return false }
        guard let finderApp = NSWorkspace.shared.runningApplications.first(where: { $0.bundleIdentifier == "com.apple.finder" }) else { return false }
        let axApp = AXUIElementCreateApplication(finderApp.processIdentifier)
        var windowsRef: CFTypeRef?
        guard AXUIElementCopyAttributeValue(axApp, kAXWindowsAttribute as CFString, &windowsRef) == .success,
              let windows = windowsRef as? [AXUIElement], !windows.isEmpty else { return false }
        // A window is "real" if it has a non-empty title that isn't the desktop pseudo-window
        for win in windows {
            var titleRef: CFTypeRef?
            if AXUIElementCopyAttributeValue(win, kAXTitleAttribute as CFString, &titleRef) == .success,
               let title = titleRef as? String, !title.isEmpty, title.lowercased() != "desktop" {
                return true
            }
        }
        return false
    }

    /// True when Finder is frontmost but only the desktop is visible (no folder window).
    /// In this state the dock behaves like a "no-app" global context.
    private var isFinderDesktopOnlyMode: Bool {
        (frontmost.bundleID == "com.apple.finder") && !finderHasActiveWindow()
    }

    private func isFinderCurrentWindowSearchAttached(currentFolderPath: String? = nil) -> Bool {
        guard isFinderFrontmostWindowContext() else { return false }
        return isFinderFolderSearchAttached(currentFolderPath: currentFolderPath)
    }

    private func shouldUseFinderSearchPopover(for query: String) -> Bool {
        // File search popup removed — folder path used as AI context only.
        return false
    }

    private func shouldKeepFinderSearchPopoverVisible(for query: String) -> Bool {
        return false
    }

    private func isFinderFolderSearchModeEnabled(for query: String) -> Bool {
        // File search results disabled — the attached folder path flows into AI context only.
        return false
    }

    private func shouldShowFinderSearchResultsPanel(for query: String) -> Bool {
        // File search results panel removed — folder path is used as AI context only.
        return false
    }

    private func applyFinderSemanticPanelResults(_ results: [SearchResult]) {
        // Finder search results are shown as dock pills only (finderSemanticPills).
        // We don't populate the results list above the dock — pills are the UI.
        guard showContextInDock, !showMediaLayer else { return }
        if !isSearchBarExpanded && !results.isEmpty {
            withAnimation(.spring(response: 0.3, dampingFraction: 0.8)) {
                isSearchBarExpanded = true
            }
        }
        // Clear any stale results from previous queries rather than showing a list
        searchState.results = []
        searchState.grouped = {
            var grouped = GroupedResults()
            results.forEach { grouped.add($0) }
            return grouped
        }()
        searchState.selectedIndex = nil
    }

    private func finderItems(in folderPath: String) -> [URL] {
        let folderURL = URL(fileURLWithPath: folderPath)
        let keys: [URLResourceKey] = [
            .isDirectoryKey, .contentModificationDateKey, .localizedNameKey,
        ]
        let urls =
            (try? FileManager.default.contentsOfDirectory(
                at: folderURL,
                includingPropertiesForKeys: keys,
                options: [.skipsHiddenFiles]
            )) ?? []

        return urls.sorted {
            $0.lastPathComponent.localizedCaseInsensitiveCompare($1.lastPathComponent)
                == .orderedAscending
        }
    }

    private func recentFinderItems(in folderPath: String, limit: Int) -> [URL] {
        finderItems(in: folderPath)
            .sorted {
                let lhs =
                    (try? $0.resourceValues(forKeys: [.contentModificationDateKey])
                        .contentModificationDate) ?? .distantPast
                let rhs =
                    (try? $1.resourceValues(forKeys: [.contentModificationDateKey])
                        .contentModificationDate) ?? .distantPast
                return lhs > rhs
            }
            .prefix(limit)
            .map { $0 }
    }

    private func buildFinderSearchResults(from urls: [URL], subtitle: String) -> [SearchResult] {
        urls.map { url in
            let path = url.path
            let isDirectory =
                (try? url.resourceValues(forKeys: [.isDirectoryKey]).isDirectory) ?? false
            let resultType: SearchResult.ResultType = {
                if isDirectory { return .folder }
                let ext = url.pathExtension.lowercased()
                if ["pdf", "txt", "md", "doc", "docx", "pages", "rtf"].contains(ext) {
                    return .document
                }
                return .file
            }()

            return SearchResult(
                title: url.lastPathComponent,
                subtitle: subtitle,
                icon: NSWorkspace.shared.icon(forFile: path),
                action: {
                    rememberFinderFollowUpTargets(
                        [url],
                        folderPath: url.deletingLastPathComponent().path,
                        sourceQuery: url.lastPathComponent
                    )
                    NSWorkspace.shared.open(url)
                },
                score: 0.0,
                type: resultType,
                filePath: path,
                contactData: nil
            )
        }
    }

    private func previewOrganizeFinderItems(in folderPath: String) -> (
        moveCount: Int, message: String
    ) {
        let items = finderItems(in: folderPath).filter { !($0.hasDirectoryPath) }
        var bucketCounts: [(FinderFileCategory, Int)] = []
        var examples: [String] = []

        for category in FinderFileCategory.allCases where category != .folder {
            let matches = items.filter { category.matches($0) }
            guard !matches.isEmpty else { continue }
            bucketCounts.append((category, matches.count))
            for url in matches.prefix(2) {
                examples.append("• \(url.lastPathComponent) → \(category.destinationFolderName)/")
            }
        }

        let moveCount = bucketCounts.reduce(0) { $0 + $1.1 }
        guard moveCount > 0 else {
            return (0, "")
        }

        var lines = [
            "I can organize \(URL(fileURLWithPath: folderPath).lastPathComponent) by type:"
        ]
        lines.append(contentsOf: bucketCounts.map { "- \($0.0.destinationFolderName): \($0.1)" })
        if !examples.isEmpty {
            lines.append("")
            lines.append("Preview:")
            lines.append(contentsOf: examples.prefix(6))
        }
        lines.append("")
        lines.append("Shall I proceed?")
        return (moveCount, lines.joined(separator: "\n"))
    }

    private func organizeFinderItemsByType(in folderPath: String) -> (
        success: Bool, message: String, createdFolders: [URL]
    ) {
        let items = finderItems(in: folderPath).filter { !($0.hasDirectoryPath) }
        guard !items.isEmpty else {
            return (
                true,
                "No files found to organize in \(URL(fileURLWithPath: folderPath).lastPathComponent).",
                []
            )
        }

        let baseURL = URL(fileURLWithPath: folderPath)
        let fileManager = FileManager.default
        var movedCount = 0
        var createdFolders: [URL] = []
        var failures: [String] = []

        for fileURL in items {
            guard
                let category = FinderFileCategory.allCases.first(where: {
                    $0 != .folder && $0.matches(fileURL)
                })
            else {
                continue
            }

            let destinationFolder = baseURL.appendingPathComponent(
                category.destinationFolderName, isDirectory: true)
            if !fileManager.fileExists(atPath: destinationFolder.path) {
                do {
                    try fileManager.createDirectory(
                        at: destinationFolder, withIntermediateDirectories: true)
                    createdFolders.append(destinationFolder)
                } catch {
                    failures.append("Couldn't create \(category.destinationFolderName)")
                    continue
                }
            }

            let destinationURL = uniqueFinderDestination(for: fileURL, in: destinationFolder)
            do {
                try fileManager.moveItem(at: fileURL, to: destinationURL)
                movedCount += 1
            } catch {
                failures.append("Couldn't move \(fileURL.lastPathComponent)")
            }
        }

        let folderLabel = URL(fileURLWithPath: folderPath).lastPathComponent
        if movedCount == 0 {
            let failureText =
                failures.isEmpty
                ? "No matching files needed organizing." : failures.joined(separator: "\n")
            return (false, failureText, createdFolders)
        }

        var lines = ["Organized \(movedCount) file\(movedCount == 1 ? "" : "s") in \(folderLabel)."]
        if !createdFolders.isEmpty {
            lines.append(
                "Created \(createdFolders.count) folder\(createdFolders.count == 1 ? "" : "s").")
        }
        if !failures.isEmpty {
            lines.append("")
            lines.append("Some items were skipped:")
            lines.append(contentsOf: failures.prefix(5))
        }
        return (failures.isEmpty, lines.joined(separator: "\n"), createdFolders)
    }

    private func uniqueFinderDestination(for fileURL: URL, in folderURL: URL) -> URL {
        let fileManager = FileManager.default
        let ext = fileURL.pathExtension
        let baseName = fileURL.deletingPathExtension().lastPathComponent
        var candidate = folderURL.appendingPathComponent(fileURL.lastPathComponent)
        var index = 2

        while fileManager.fileExists(atPath: candidate.path) {
            let name = ext.isEmpty ? "\(baseName) \(index)" : "\(baseName) \(index).\(ext)"
            candidate = folderURL.appendingPathComponent(name)
            index += 1
        }

        return candidate
    }

    private func executeFinderAIResponse(_ response: String, folderPath: String) {
        let trimmed = response.trimmingCharacters(in: .whitespacesAndNewlines)

        if trimmed.hasPrefix("ACTION:APPLESCRIPT:") {
            let script = String(trimmed.dropFirst("ACTION:APPLESCRIPT:".count))
                .replacingOccurrences(of: "\\n", with: "\n")
            l2.chatMessages.append(
                AIChatMessage(role: .assistant, content: "```applescript\n\(script)\n```"))
            Task.detached(priority: .userInitiated) {
                var err: NSDictionary?
                NSAppleScript(source: script)?.executeAndReturnError(&err)
                if let e = err {
                    await MainActor.run {
                        self.l2.chatMessages.append(
                            AIChatMessage(
                                role: .assistant,
                                content:
                                    "⚠️ \(e["NSAppleScriptErrorMessage"] as? String ?? "Script error")",
                                isError: true))
                    }
                }
                try? await Task.sleep(nanoseconds: 400_000_000)
                await MainActor.run {
                    if let app = NSWorkspace.shared.runningApplications.first(where: {
                        $0.bundleIdentifier == "com.apple.finder"
                    }) {
                        AXMenuReader.shared.invalidateCache(for: app.processIdentifier)
                        self.reloadMenuForApp(app)
                    }
                }
            }

        } else if trimmed.hasPrefix("ACTION:SHELL:") {
            let cmd = String(trimmed.dropFirst("ACTION:SHELL:".count))
            l2.chatMessages.append(AIChatMessage(role: .assistant, content: "```bash\n\(cmd)\n```"))
            Task.detached(priority: .userInitiated) {
                let process = Process()
                process.launchPath = "/bin/bash"
                process.arguments = ["-c", cmd]
                process.currentDirectoryPath = folderPath
                let pipe = Pipe()
                process.standardOutput = pipe
                process.standardError = pipe
                try? process.run()
                process.waitUntilExit()
                let output =
                    String(data: pipe.fileHandleForReading.readDataToEndOfFile(), encoding: .utf8)
                    ?? ""
                let createdURL =
                    process.terminationStatus == 0
                    ? self.detectCreatedFile(command: cmd, output: output) : nil
                await MainActor.run {
                    let status =
                        process.terminationStatus == 0
                        ? "✅ Done" : "❌ Failed (exit \(process.terminationStatus))"
                    let msg =
                        output.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                        ? status
                        : "\(status)\n```\n\(output.prefix(500))\n```"
                    self.l2.chatMessages.append(AIChatMessage(role: .assistant, content: msg))
                    if let createdURL {
                        self.rememberFinderFollowUpTargets(
                            [createdURL],
                            folderPath: createdURL.deletingLastPathComponent().path,
                            sourceQuery: cmd
                        )
                        self.currentContext = .filesSelected([createdURL])
                    }
                    ILauncherNotificationManager.shared.shellFinished(
                        command: cmd,
                        exitCode: process.terminationStatus
                    )
                }
            }

        } else if trimmed.hasPrefix("ACTION:MENU:") {
            let menuTitle = String(trimmed.dropFirst("ACTION:MENU:".count))
            l2.chatMessages.append(AIChatMessage(role: .assistant, content: "▶ \(menuTitle)"))
            if let item = liveMenuItems.first(where: {
                $0.title.lowercased() == menuTitle.lowercased()
            }),
                let pid = NSWorkspace.shared.runningApplications
                    .first(where: { $0.bundleIdentifier == "com.apple.finder" })?.processIdentifier
            {
                executeDockMenuAction(
                    sourcePID: pid,
                    path: item.path,
                    shortcutChar: item.shortcutChar,
                    shortcutModifiers: item.shortcutModifiers
                )
            }

        } else if trimmed.hasPrefix("ANSWER:") {
            let answer = String(trimmed.dropFirst("ANSWER:".count))
            l2.chatMessages.append(AIChatMessage(role: .assistant, content: answer))

        } else {
            // Model didn't follow the format — show the raw response
            l2.chatMessages.append(AIChatMessage(role: .assistant, content: trimmed))
        }
    }

    @discardableResult
    private func runAppleScript(_ source: String) async -> String? {
        return await withCheckedContinuation { cont in
            DispatchQueue.global(qos: .userInitiated).async {
                var err: NSDictionary?
                guard let s = NSAppleScript(source: source) else {
                    cont.resume(returning: nil)
                    return
                }
                let result = s.executeAndReturnError(&err)
                cont.resume(returning: result.stringValue)
            }
        }
    }

    // MARK: - Apple menu recent apps sync

    /// Reads "Recent Items > Applications" from the already-loaded liveMenuItems and
    /// updates AppDelegate.recentApps with running apps that match — giving us the
    /// same list macOS itself tracks, not just apps activated while our dock was open.
    private func syncRecentAppsFromAppleMenu(_ items: [AXMenuItem]) {
        // Apple menu items: path[0] == "" (the  symbol), path[1] == "Recent Items"
        let recentNames =
            items
            .filter { $0.path.count >= 2 && $0.path[0].isEmpty && $0.path[1] == "Recent Items" }
            .map { $0.title.replacingOccurrences(of: ".app", with: "") }
            .filter { !$0.isEmpty && $0 != "Clear Menu" }

        guard !recentNames.isEmpty else { return }

        let running = NSWorkspace.shared.runningApplications
        let frontPID = AppDelegate.shared?.previousFrontmostApp?.processIdentifier ?? 0

        // Match names to running processes, preserving Apple menu order, skip frontmost & self
        let matched: [NSRunningApplication] = recentNames.compactMap { name in
            running.first {
                $0.activationPolicy == .regular
                    && !$0.isTerminated
                    && $0.processIdentifier != frontPID
                    && $0.bundleIdentifier != Bundle.main.bundleIdentifier
                    && ($0.localizedName ?? "") == name
            }
        }

        // Deduplicate and update
        var seen = Set<pid_t>()
        let deduped = matched.filter { seen.insert($0.processIdentifier).inserted }
        AppDelegate.shared?.setRecentAppsFromMenu(Array(deduped.prefix(5)))
    }

    private func menuSignature(for items: [AXMenuItem]) -> String {
        items
            .prefix(500)
            .map { item in
                [
                    item.path.joined(separator: " > "),
                    item.isEnabled ? "1" : "0",
                    item.shortcutChar ?? "",
                    "\(item.shortcutModifiers)",
                ].joined(separator: "|")
            }
            .joined(separator: "\n")
    }

    private func refreshFrontmostMenuStructureIfNeeded(
        for app: NSRunningApplication,
        force: Bool = false
    ) {
        guard showContextInDock, !app.isTerminated else { return }
        guard liveMenuRefreshTask == nil else { return }

        let now = Date()
        let minInterval: TimeInterval = force ? 0 : 1.15
        guard force || now.timeIntervalSince(lastLiveMenuStructureRefresh) >= minInterval else {
            return
        }
        lastLiveMenuStructureRefresh = now

        let pid = app.processIdentifier
        let name = app.localizedName ?? ""
        let bundleId = app.bundleIdentifier

        liveMenuRefreshTask = Task.detached(priority: force ? .userInitiated : .utility) {
            var items = AXMenuReader.shared.refreshAllMenuItems(for: pid, maxDepth: 6)
            guard !Task.isCancelled else { return }
            guard !items.isEmpty else {
                await MainActor.run {
                    if self.liveMenuRefreshTask != nil {
                        self.liveMenuRefreshTask = nil
                    }
                }
                return
            }

            for i in items.indices {
                items[i].sourcePID = pid
                items[i].sourceAppName = name
            }
            if let liveApp = NSWorkspace.shared.runningApplications.first(where: {
                $0.processIdentifier == pid && !$0.isTerminated
            }) {
                AppMenuCapabilityCache.shared.store(items: items, for: liveApp)
            }

            let debug = AXMenuReader.shared.lastDebug(for: pid) ?? "no reader detail"
            await MainActor.run {
                self.liveMenuRefreshTask = nil
                guard self.showContextInDock else { return }
                guard self.contextTargetApp()?.processIdentifier == pid else {
                    return
                }
                let signature = self.menuSignature(for: items)
                guard force || signature != self.lastLiveMenuSignature else { return }

                self.liveMenuItems = items
                self.lastLiveMenuSignature = signature
                self.menuDebugText = "\(name): \(items.count) menus, \(debug), live"
                self.previousEnabledIDs = Set(items.filter(\.isEnabled).map(\.id))
                self.contextMenuPills = []
                self.syncRecentAppsFromAppleMenu(items)
                if self.frontmost.bundleID.isEmpty, let bundleId {
                    self.frontmost.bundleID = bundleId
                }
            }
        }
    }

    // MARK: - Selection-change handler

    /// Called (debounced 200ms) whenever AXObserver detects a selection/focus change
    /// in the frontmost app. Re-reads only `kAXEnabled` for all cached menu items,
    /// computes the delta (newly enabled items), and surfaces them as context pills.
    private func handleSelectionChange() {
        guard showContextInDock else { return }

        if !liveMenuItems.isEmpty {
            let items = liveMenuItems
            let previousIDs = previousEnabledIDs
            Task.detached(priority: .userInitiated) {
                // Re-read enabled states off the main thread — one attribute call per item,
                // no tree traversal, but still AX IPC and therefore not free.
                let enabledMap = AXMenuReader.shared.refreshEnabledStates(for: items)
                var updated = items
                for i in updated.indices {
                    if let enabled = enabledMap[updated[i].id] {
                        updated[i].isEnabled = enabled
                    }
                }

                let newEnabledIDs = Set(updated.filter(\.isEnabled).map(\.id))
                let deltaIDs = newEnabledIDs.subtracting(previousIDs)
                let delta = updated.filter { deltaIDs.contains($0.id) && !self.isAppleMenuItem($0) }
                    .sorted { ($0.shortcutChar != nil ? 0 : 1) < ($1.shortcutChar != nil ? 0 : 1) }

                await MainActor.run {
                    self.previousEnabledIDs = newEnabledIDs
                    self.liveMenuItems = updated
                    self.contextMenuPills = Array(delta.prefix(6))
                }
            }
        }

        refreshLiveContextDockState()
    }

    private func refreshLiveContextDockState() {
        guard showContextInDock, let app = contextTargetApp() else { return }

        refreshFrontmostMenuStructureIfNeeded(for: app)

        AXContextReader.shared.refresh(from: app)
        let newCtx = AXContextReader.shared.current
        refreshCachedFinderCurrentDirectory(for: app.bundleIdentifier ?? "")

        // URL-change detection: recache page when user navigates
        if AXWebReader.shared.isBrowser(bundleId: app.bundleIdentifier ?? ""),
            let newURL = newCtx.currentURL, !newURL.isEmpty,
            newURL != lastKnownBrowserURL
        {
            lastKnownBrowserURL = newURL
            AXWebReader.shared.invalidate(pid: app.processIdentifier)
            scheduleBrowserContextWarmup(reason: "browser URL changed", urlOverride: newURL)
        }

        if newCtx.bundleId == "com.apple.finder" {
            updateDismissedFinderSelectionAfterSelectionChange(newCtx.selectedFilePaths)
            if isDismissedFinderSelection(newCtx.selectedFilePaths) {
                var suppressedCtx = newCtx
                suppressedCtx.selectedFilePaths = []
                if case .filesSelected(let urls) = currentContext,
                   isDismissedFinderSelection(urls) {
                    currentContext = .none
                }
                axContext = suppressedCtx
                detectAndUpdateContext()
                checkClipboardForGlobalContext()
                autoReturnFromGlobalContextIfNeeded()
                return
            }
        }

        let contextChanged =
            newCtx.selectedFilePaths != axContext.selectedFilePaths
            || newCtx.selectedText != axContext.selectedText
            || newCtx.currentURL != axContext.currentURL
            || newCtx.windowTitle != axContext.windowTitle

        if contextChanged {
            axContext = newCtx
            detectAndUpdateContext()
        }
        // Clipboard monitoring: detect copies from any app (covers Electron/VS Code where AX selectedText is nil)
        checkClipboardForGlobalContext()
        // Always check for selection-based global context switch after AX refresh
        autoSwitchGlobalContextIfNeeded()
        // Auto-return to dock if selection was cleared since last poll
        autoReturnFromGlobalContextIfNeeded()
    }

    private func refreshFinderSelectionContextFromFinder() {
        guard showContextInDock, !showMediaLayer, !aiMode.isActive else { return }
        let now = Date()
        guard now.timeIntervalSince(lastFinderSelectionRefresh) > 0.25 else { return }
        lastFinderSelectionRefresh = now
        guard frontmost.bundleID == "com.apple.finder"
            || AppDelegate.shared?.previousFrontmostApp?.bundleIdentifier == "com.apple.finder"
            || contextTargetApp()?.bundleIdentifier == "com.apple.finder"
        else { return }

        let urls = canonicalExistingURLs(ContextDetector.shared.getFinderSelectedFiles())
        guard !urls.isEmpty else { return }
        let paths = urls.map(\.path)
        updateDismissedFinderSelectionAfterSelectionChange(paths)
        if isDismissedFinderSelection(paths) {
            if axContext.bundleId == "com.apple.finder" {
                axContext.selectedFilePaths = []
            }
            if case .filesSelected(let current) = currentContext,
               isDismissedFinderSelection(current) {
                currentContext = .none
            }
            return
        }

        if axContext.bundleId != "com.apple.finder" || axContext.selectedFilePaths != paths {
            axContext.bundleId = "com.apple.finder"
            axContext.selectedFilePaths = paths
        }
        if case .filesSelected(let current) = currentContext, current.map(\.path) == paths {
            return
        }
        currentContext = .filesSelected(urls)
    }

    private func checkClipboardForGlobalContext() {
        let pb = NSPasteboard.general
        let currentCount = pb.changeCount
        guard currentCount != lastCheckedPasteboardCount else { return }
        lastCheckedPasteboardCount = currentCount

        pruneExpiredClipboardEntries()

        if let fileURLs = pb.readObjects(forClasses: [NSURL.self], options: nil) as? [URL] {
            let paths = fileURLs
                .filter { $0.isFileURL }
                .map(\.path)
                .filter { !$0.isEmpty }
            if !paths.isEmpty {
                addClipboardEntry(text: paths.joined(separator: "\n"), filePaths: paths)
                return
            }
        }

        if let image = NSImage(pasteboard: pb),
           let tiffData = image.tiffRepresentation {
            addClipboardEntry(text: "Image copied to clipboard", filePaths: [], imageData: tiffData)
            return
        }

        guard pb.pasteboardItems?.first?.types.contains(.string) == true,
              let text = pb.string(forType: .string)
        else { return }
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard trimmed.count > 3 else { return }

        addClipboardEntry(text: trimmed, filePaths: [])
    }

    private func addClipboardEntry(text: String, filePaths: [String], imageData: Data? = nil) {
        let sourceApp = clipboardSourceApp()
        let entry = ClipboardEntry(
            text: text,
            timestamp: Date(),
            filePaths: filePaths,
            imageData: imageData,
            sourceAppName: sourceApp.name,
            sourceBundleId: sourceApp.bundleId
        )

        let duplicateKey = imageData != nil
            ? "image:\(imageData?.count ?? 0)"
            : (filePaths.isEmpty ? text : filePaths.joined(separator: "\n"))
        clipboardHistory.removeAll { old in
            let oldKey = old.imageData != nil
                ? "image:\(old.imageData?.count ?? 0)"
                : (old.filePaths.isEmpty ? old.text : old.filePaths.joined(separator: "\n"))
            return oldKey == duplicateKey
        }
        clipboardHistory.insert(entry, at: 0)
        trimClipboardHistoryToLimits()
        if searchState.activeSmartQueryKey == "clipboard" {
            searchState.appPanelAllItems = clipboardSearchResults()
        }

        withAnimation(.spring(response: 0.25, dampingFraction: 0.8)) {
            globalClipboardText = text
            showGlobalClipboardPill = true
        }
        scheduleClipboardIndicatorAutoHide()
        // Auto-switch to global context if we're in dock mode and not already there
        if showContextInDock && !isGlobalContextActive && !isExplicitAppScopeLocked && l2.targetApp == nil {
            withAnimation(.spring(response: 0.25, dampingFraction: 0.8)) {
                globalContextActivation = GlobalContextActivation(autoActivated: true)
            }
        }
        // Rebuild pills so clipboard chip appears immediately
        scheduleDockPillRebuild(query: lastPillQuery, delayNanoseconds: 0)
    }

    private func scheduleClipboardIndicatorAutoHide() {
        clipboardIndicatorHideTask?.cancel()
        clipboardIndicatorHideTask = Task { @MainActor in
            try? await Task.sleep(nanoseconds: 5_000_000_000)
            guard !Task.isCancelled else { return }
            withAnimation(.spring(response: 0.25, dampingFraction: 0.82)) {
                showGlobalClipboardPill = false
                clipboardHistoryExpanded = false
            }
            updateWindowSize()
        }
        updateWindowSize()
    }

    private func clipboardSourceApp() -> (name: String, bundleId: String) {
        let app = AppDelegate.shared?.previousFrontmostApp
            ?? NSWorkspace.shared.frontmostApplication
        return (app?.localizedName ?? "", app?.bundleIdentifier ?? "")
    }

    private func clipboardRetentionInterval() -> TimeInterval {
        TimeInterval(max(1, settings.clipboardHistoryRetentionHours)) * 3600
    }

    private func trimClipboardHistoryToLimits() {
        pruneExpiredClipboardEntries(updateVisibleState: false)
        let limit = settings.clipboardHistoryLimit
        if clipboardHistory.count > limit {
            clipboardHistory = Array(clipboardHistory.prefix(limit))
        }
        syncVisibleClipboardStateAfterPrune()
    }

    private func pruneExpiredClipboardEntries(updateVisibleState: Bool = true) {
        let cutoff = Date().addingTimeInterval(-clipboardRetentionInterval())
        clipboardHistory.removeAll { $0.timestamp < cutoff }
        if updateVisibleState {
            syncVisibleClipboardStateAfterPrune()
        }
    }

    private func syncVisibleClipboardStateAfterPrune() {
        if let first = clipboardHistory.first {
            globalClipboardText = first.text
        } else {
            globalClipboardText = ""
            showGlobalClipboardPill = false
            showClipboardHistory = false
            clipboardHistoryExpanded = false
        }
    }

    private func startClipboardExpiryTimer() {
        clipboardExpiryTimer?.invalidate()
        clipboardExpiryTimer = Timer.scheduledTimer(withTimeInterval: 60, repeats: true) { [self] _ in
            self.pruneExpiredClipboardEntries()
        }
    }

    /// Switches to Global Context automatically when files, text, or a URL are selected
    /// in the frontmost app. Checks both axContext (live AX state) and currentContext.
    private func autoSwitchGlobalContextIfNeeded() {
        guard showContextInDock, !isExplicitAppScopeLocked, l2.targetApp == nil, !isGlobalContextActive else { return }
        // Don't re-trigger within 600ms of an app switch — the AX observer fires for the
        // new app with stale/cursor-position state which would immediately flip back to global.
        guard Date().timeIntervalSince(frontmost.lastSwitchDate) > 0.6 else { return }
        // Ignore AX selection if it came from a different app than the current frontmost —
        // stale events from the previous app can arrive after the switch.
        if !axContext.bundleId.isEmpty, axContext.bundleId != frontmost.bundleID {
            return
        }
        refreshFinderSelectionContextFromFinder()

        // Files selected: always meaningful
        let hasFileSelection =
            !axContext.selectedFilePaths.isEmpty
            && !isDismissedFinderSelection(axContext.selectedFilePaths)
        // Text: require > 15 chars to avoid cursor-position false positives in Electron apps
        let axText = (axContext.selectedText ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let hasTextSelection = axText.count > 15
        let hasContextSelection: Bool = {
            switch currentContext {
            case .filesSelected(let u): return !u.isEmpty && !isDismissedFinderSelection(u)
            case .textSelected(let t):
                return t.trimmingCharacters(in: .whitespacesAndNewlines).count > 15
            case .url(let s):
                return !s.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            default: return false
            }
        }()
        if hasFileSelection || hasTextSelection || hasContextSelection {
            // Compute frozen label + icon before creating the activation struct
            let (frozenText, frozenIcon): (String?, String?) = {
                if hasFileSelection {
                    let paths = axContext.selectedFilePaths.map { URL(fileURLWithPath: $0) }
                    let text = paths.count == 1 ? paths[0].lastPathComponent : "\(paths.count) files selected"
                    let icon = paths.count == 1
                        ? fileIcon(for: paths[0].pathExtension.lowercased())
                        : "doc.on.doc.fill"
                    return (text, icon)
                } else if hasTextSelection {
                    return (String(axText.prefix(50)), "text.cursor")
                } else {
                    switch currentContext {
                    case .textSelected(let t):
                        return (String(t.trimmingCharacters(in: .whitespacesAndNewlines).prefix(50)), "text.cursor")
                    case .filesSelected(let urls):
                        let text = urls.count == 1 ? urls[0].lastPathComponent : "\(urls.count) files"
                        return (text, "doc.on.doc.fill")
                    case .url(let u):
                        let text = URL(string: u)?.host ?? String(u.prefix(40))
                        return (text, "link")
                    default:
                        return (nil, nil)
                    }
                }
            }()
            globalContextActivation = GlobalContextActivation(
                autoActivated: true,
                frozenText: frozenText,
                frozenIcon: frozenIcon,
                sourceBundleId: axContext.bundleId
            )
            // Expand and focus the search bar so the user can type their query immediately
            isSearchBarExpanded = true
            DispatchQueue.main.async { self.isSearchFieldFocused = true }
        }
    }

    /// Auto-returns to Context Dock when the selection that triggered global context is gone.
    /// Only fires if global context was auto-activated (not manually swiped by user).
    private func autoReturnFromGlobalContextIfNeeded() {
        guard isGlobalContextActive, isGlobalContextAutoActivated, !aiMode.isActive else { return }

        // If we have a frozen selection, only allow auto-return when the AX update comes from the
        // same source app that originally provided the selection — not from our own dock gaining focus.
        if let sourceId = frozenSelectionSourceBundleId {
            let currentContextApp = axContext.bundleId ?? ""
            let ownBundleId = Bundle.main.bundleIdentifier ?? ""
            // Ignore AX updates from our own app — user is typing in our dock
            guard currentContextApp != ownBundleId else { return }
            // Ignore updates from unrelated apps — only the source app can invalidate the frozen selection
            guard currentContextApp == sourceId || currentContextApp.isEmpty else { return }
        }

        let hasFileSelection =
            !axContext.selectedFilePaths.isEmpty
            && !isDismissedFinderSelection(axContext.selectedFilePaths)
        let axText = (axContext.selectedText ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let hasTextSelection = axText.count > 15
        let hasCtxSel: Bool = {
            switch currentContext {
            case .filesSelected(let u): return !u.isEmpty && !isDismissedFinderSelection(u)
            case .textSelected(let t): return t.trimmingCharacters(in: .whitespacesAndNewlines).count > 15
            case .url(let s): return !s.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            default: return false
            }
        }()
        let hasClipboard = showGlobalClipboardPill && !globalClipboardText.isEmpty
        if !hasFileSelection && !hasTextSelection && !hasCtxSel && !hasClipboard {
            withAnimation(.spring(response: 0.25, dampingFraction: 0.8)) {
                globalContextActivation = nil
            }
            scheduleDockPillRebuild(query: lastPillQuery, delayNanoseconds: 0)
        }
    }

    // MARK: - Share sheet

    private func presentSharingPicker(items: [Any]) {
        guard !items.isEmpty else { return }
        let picker = NSSharingServicePicker(items: items)
        let coordinator = SharePickerCoordinator {
            self.isSharingSheetActive = false
        }
        picker.delegate = coordinator
        objc_setAssociatedObject(
            picker,
            &SharePickerCoordinator.key,
            coordinator,
            .OBJC_ASSOCIATION_RETAIN_NONATOMIC
        )

        isSharingSheetActive = true
        DispatchQueue.main.async {
            guard let window = NSApp.keyWindow,
                let view = window.contentView
            else {
                self.isSharingSheetActive = false
                return
            }
            let rect = NSRect(x: window.frame.width / 2 - 60, y: 52, width: 120, height: 1)
            picker.show(relativeTo: rect, of: view, preferredEdge: .maxY)
        }
    }

    /// Shows NSSharingServicePicker anchored above the pill row,
    /// using the current AX context (selected files, URL, or text).
    /// Sets shareSheetVisible = true so arrow keys are passed through to the picker.
    private func showShareSheetForContext() {
        var items = ShareIntentRouter.shared.shareItems(for: effectiveAXContextForConversation())
        if items.isEmpty {
            // Fallback: show picker with app URL so at least something appears
            if let app = AppDelegate.shared?.previousFrontmostApp,
                let bid = app.bundleIdentifier,
                let url = NSWorkspace.shared.urlForApplication(withBundleIdentifier: bid)
            {
                items = [url]
            } else {
                return
            }
        }
        presentSharingPicker(items: items)
    }

    private func executeShareIntent(
        _ intent: ShareIntent,
        userMessage: String? = nil
    ) {
        let capturedContext = effectiveAXContextForConversation()
        if let userMessage, !userMessage.isEmpty {
            l2.chatMessages.append(AIChatMessage(role: .user, content: userMessage))
        }
        l2.isLoading = true
        Task {
            let resolution = await ShareIntentRouter.shared.resolve(intent)
            let output = await ShareIntentRouter.shared.execute(
                resolution,
                axContext: capturedContext,
                presentSharingPicker: { items in
                    self.presentSharingPicker(items: items)
                }
            )
            await MainActor.run {
                self.l2.chatMessages.append(AIChatMessage(role: .assistant, content: output))
                self.l2.isLoading = false
            }
        }
    }

    private func executeTransformShareIntent(
        _ intent: ShareIntent,
        userMessage: String
    ) {
        let selectedFiles = effectiveSelectedFileURLsForConversation()
        guard !selectedFiles.isEmpty else {
            l2.chatMessages.append(AIChatMessage(role: .user, content: userMessage))
            l2.chatMessages.append(
                AIChatMessage(
                    role: .assistant,
                    content: "Select a small text or PDF document first, then ask me to summarize and send it.",
                    isError: true
                ))
            return
        }

        if let existingTask = l2.currentTask {
            existingTask.cancel()
            l2.currentTask = nil
            l2.isLoading = false
            l2.activeRequestID = nil
        }

        l2.chatMessages.append(AIChatMessage(role: .user, content: userMessage))
        l2.isLoading = true
        searchState.query = ""
        l2.focusedPillIndex = nil

        l2.currentTask = Task {
            let readable = transformShareReadableContent(from: selectedFiles)
            guard !readable.content.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
                await MainActor.run {
                    l2.chatMessages.append(
                        AIChatMessage(
                            role: .assistant,
                            content: "I couldn't read text from the selected file. This works best with small text, Markdown, source, CSV, RTF, or text-based PDF files.",
                            isError: true
                        ))
                    l2.isLoading = false
                    l2.currentTask = nil
                }
                return
            }

            do {
                let summaryPrompt = transformSharePrompt(
                    userMessage: userMessage,
                    fileSummary: readable.summary,
                    fileContent: readable.content
                )
                let summary = try await sendToAIProviderWithContext(
                    query: summaryPrompt,
                    messageHistory: l2.chatMessages
                ).trimmingCharacters(in: .whitespacesAndNewlines)

                guard !Task.isCancelled else { return }
                let resolution = await ShareIntentRouter.shared.resolve(intent)
                let subject = "Summary of \(readable.primaryFileName)"
                let output = await ShareIntentRouter.shared.executeText(
                    summary,
                    resolution: resolution,
                    subject: subject,
                    presentSharingPicker: { items in
                        self.presentSharingPicker(items: items)
                    }
                )

                await MainActor.run {
                    l2.chatMessages.append(
                        AIChatMessage(role: .assistant, content: "\(output)\n\n\(summary)")
                    )
                    l2.isLoading = false
                    l2.currentTask = nil
                }
            } catch {
                await MainActor.run {
                    l2.chatMessages.append(
                        AIChatMessage(
                            role: .assistant,
                            content: "Sorry, I couldn't summarize and send that: \(error.localizedDescription)",
                            isError: true
                        ))
                    l2.isLoading = false
                    l2.currentTask = nil
                }
            }
        }
    }

    private func transformShareIntent(for query: String) -> ShareIntent? {
        let q = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard !q.isEmpty else { return nil }
        let hasTransformWord = [
            "summary", "summarize", "summarise", "tldr", "tl;dr",
            "explain", "describe", "key points", "short version", "brief"
        ].contains { q.contains($0) }
        let hasDeliveryWord = [
            "send", "share", "message", "messages", "imessage", "text",
            "sms", "mail", "email"
        ].contains { q.contains($0) }
        let referencesSelection = [
            "this file", "selected file", "selection", "this document",
            "selected document", "this pdf", "selected pdf", "this"
        ].contains { q.contains($0) }
        guard hasTransformWord, hasDeliveryWord, referencesSelection else { return nil }
        guard !effectiveSelectedFileURLsForConversation().isEmpty else { return nil }
        return ShareIntentRouter.shared.parse(query)
    }

    private func transformShareReadableContent(from urls: [URL])
        -> (summary: String, content: String, primaryFileName: String)
    {
        let files = Array(urls.prefix(3))
        let analyses = ContextDetector.shared.analyzeFiles(files)
        var chunks: [String] = []
        var summaryLines: [String] = []

        for analysis in analyses {
            summaryLines.append("- \(analysis.url.lastPathComponent) (\(analysis.type), \(analysis.size))")
            guard let content = analysis.content?
                .trimmingCharacters(in: .whitespacesAndNewlines),
                !content.isEmpty
            else { continue }
            chunks.append(
                """
                FILE: \(analysis.url.lastPathComponent)
                CONTENT:
                \(String(content.prefix(6000)))
                """
            )
        }

        return (
            summaryLines.joined(separator: "\n"),
            chunks.joined(separator: "\n\n---\n\n"),
            files.first?.lastPathComponent ?? "selected file"
        )
    }

    private func transformSharePrompt(
        userMessage: String,
        fileSummary: String,
        fileContent: String
    ) -> String {
        """
        The user wants a generated message derived from the selected file, then sent to someone.

        User request:
        \(userMessage)

        Selected file metadata:
        \(fileSummary)

        Selected file text:
        \(fileContent)

        Produce only the message body to send. Keep it short unless the user asked otherwise.
        Do not mention implementation details, file paths, or that you are an AI.
        """
    }

    private func executeCrossAppIntent(
        _ intent: CrossAppIntent,
        userMessage: String,
        unresolvedMessage: String = "❌ Couldn't resolve that. Try: \"send this to [name]\" or \"email this to [name]\""
    ) {
        if let existingTask = l2.currentTask {
            existingTask.cancel()
            l2.currentTask = nil
            l2.isLoading = false
            l2.activeRequestID = nil
        }
        let capturedContext = effectiveAXContextForConversation()
        let actionId = DockActionFeedback.start("Working", subject: intent.targetAppName ?? "", icon: "bolt.fill", tint: .accentColor)
        l2.currentTask = Task {
            guard let resolved = await CrossAppNLHandler.shared.resolve(intent) else {
                await MainActor.run {
                    DockActionFeedback.fail(actionId, label: "Couldn't resolve action")
                    l2.currentTask = nil
                }
                return
            }
            let output = await CrossAppNLHandler.shared.execute(
                resolved,
                axContext: capturedContext,
                presentSharingPicker: { items in
                    self.presentSharingPicker(items: items)
                }
            )
            await MainActor.run {
                let clean = output.replacingOccurrences(of: "✅ ", with: "").replacingOccurrences(of: "❌ ", with: "")
                let success = !output.hasPrefix("❌")
                if success { DockActionFeedback.complete(actionId, label: clean) }
                else { DockActionFeedback.fail(actionId, label: clean) }
                l2.currentTask = nil
                searchState.query = ""
                l2.focusedPillIndex = nil
            }
        }
    }

    private func executeResolvedAppAction(
        _ resolution: L2AppActionResolution,
        userMessage: String
    ) {
        if let existingTask = l2.currentTask {
            existingTask.cancel()
            l2.currentTask = nil
            l2.isLoading = false
            l2.activeRequestID = nil
        }

        let match = resolution.primary
        let capturedContext = effectiveAXContextForConversation()
        let actionId = DockActionFeedback.start(match.action.name, subject: match.adapter.appName, icon: "bolt.fill", tint: .accentColor)
        l2.currentTask = Task {
            AppInteractionStore.shared.record(
                bundleId: match.adapter.bundleId,
                appName: match.adapter.appName,
                query: userMessage,
                kind: match.action.type == .pageJS ? .pageJS : .adapterAction,
                actionId: match.action.id
            )

            let result = await adapterManager.execute(
                match.action,
                context: capturedContext,
                targetBundleId: match.adapter.bundleId,
                query: userMessage
            )

            await MainActor.run {
                let success = result.0
                let detail = result.1.trimmingCharacters(in: .whitespacesAndNewlines)
                let label = success
                    ? (detail.isEmpty ? "\(match.action.name) done" : detail)
                    : "Couldn't run \(match.action.name)"
                if success { DockActionFeedback.complete(actionId, label: label) }
                else { DockActionFeedback.fail(actionId, label: label) }
                l2.currentTask = nil
                searchState.query = ""
                l2.focusedPillIndex = nil
            }
        }
    }

    private func executeGlobalAppLaunch(
        bundleId: String,
        appName: String,
        userMessage: String
    ) {
        let launched = launchApplication(bundleIdentifier: bundleId, appName: appName)
        if launched {
            DockActionFeedback.start("Opening", subject: appName, icon: "arrow.up.right.circle.fill", tint: .accentColor)
        } else {
            let fid = DockActionFeedback.start("Opening", subject: appName, icon: "arrow.up.right.circle.fill", tint: .accentColor)
            DockActionFeedback.fail(fid, label: "Couldn't open \(appName)")
        }
        searchState.query = ""
        l2.focusedPillIndex = nil
    }

    private var isGlobalQueryModeActive: Bool {
        showContextInDock && isGlobalContextActive
    }

    private var effectiveConversationUserContext: UserContext {
        // Global Context: use live AX selection as the authoritative context
        if showContextInDock && isGlobalContextActive {
            let axFiles = axContext.selectedFilePaths.map { URL(fileURLWithPath: $0) }
            if !axFiles.isEmpty { return .filesSelected(axFiles) }
            if let t = axContext.selectedText,
                !t.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            { return .textSelected(t) }
            switch currentContext {
            case .filesSelected, .textSelected, .url, .contactSelected: return currentContext
            default: break
            }
            // Clipboard pill: user explicitly copied content (covers VS Code/Electron/any app)
            if showGlobalClipboardPill && !globalClipboardText.isEmpty {
                if let url = URL(string: globalClipboardText), url.scheme != nil {
                    return .url(globalClipboardText)
                }
                return .textSelected(globalClipboardText)
            }
            return .none
        }

        if showContextInDock {
            let scope = resolveDockScope(for: searchState.query)
            if scope.isExplicitAppScope,
                !scope.scopedBundleId.isEmpty,
                !scope.scopedAppName.isEmpty
            {
                return .appFocused(name: scope.scopedAppName, bundleID: scope.scopedBundleId)
            }
        }

        guard isGlobalQueryModeActive else { return currentContext }
        switch currentContext {
        case .appFocused:
            return .none
        default:
            return currentContext
        }
    }

    private func resolveGlobalActionQuery(_ query: String) -> L2AppActionResolution? {
        let normalizedQuery = normalizedDockPillText(query)
        guard !normalizedQuery.isEmpty else { return nil }

        let queryTokens = Set(dockPillTokens(normalizedQuery))
        var matches: [L2AppActionMatch] = []

        for adapter in AppAdapterManager.shared.adapters where adapter.isEnabled {
            let normalizedAppName = normalizedDockPillText(adapter.appName)

            for action in adapter.actions {
                let normalizedActionName = normalizedDockPillText(action.name)
                let normalizedTriggers = action.triggers.map(normalizedDockPillText)
                let corpora = ([normalizedActionName] + normalizedTriggers).filter { !$0.isEmpty }

                var score = 0.0

                if corpora.contains(normalizedQuery) {
                    score += 155
                }
                if normalizedActionName == normalizedQuery {
                    score += 135
                }
                if corpora.contains(where: { $0.hasPrefix(normalizedQuery) }) {
                    score += 96
                }
                if corpora.contains(where: { $0.contains(normalizedQuery) }) {
                    score += 72
                }

                let actionTokens = Set(corpora.flatMap { dockPillTokens($0) })
                let overlap = queryTokens.intersection(actionTokens).count
                if overlap > 0 {
                    score += Double(overlap * 26)
                }

                if !normalizedAppName.isEmpty && normalizedQuery.contains(normalizedAppName) {
                    score += 24
                }
                if queryTokens.contains(where: { normalizedAppName.contains($0) }) {
                    score += 16
                }

                guard score >= 90 else { continue }

                matches.append(
                    L2AppActionMatch(
                        adapter: adapter,
                        action: action,
                        score: score,
                        matchedAppPhrase: normalizedAppName,
                        matchedActionPhrase: normalizedQuery,
                        usedFrontmostFallback: false
                    )
                )
            }
        }

        let ranked = matches.sorted {
            if $0.score != $1.score { return $0.score > $1.score }
            return $0.action.name.localizedCaseInsensitiveCompare($1.action.name) == .orderedAscending
        }

        guard let primary = ranked.first else { return nil }
        let alternatives = Array(ranked.dropFirst().prefix(3)).filter { $0.score >= primary.score - 20 }
        return L2AppActionResolution(primary: primary, alternatives: alternatives)
    }

    private func globalAIContextBlock() -> String {
        var lines: [String] = ["## Global Context Mode", "Treat the frontmost app as passive context only."]

        let context = effectiveAXContextForConversation()
        if !context.isEmpty {
            lines.append("## Passive Live Context")
            lines.append(context.contextSummary)
        }

        let selectedFiles = effectiveSelectedFileURLsForConversation()
        if !selectedFiles.isEmpty {
            lines.append("## Selected Files")
            for url in selectedFiles.prefix(8) {
                lines.append("- \(url.lastPathComponent)")
            }
        }

        return lines.joined(separator: "\n")
    }

    private func messagesScopedSemanticIntent(for scopedQuery: String) -> CrossAppIntent? {
        let normalized = scopedQuery.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !normalized.isEmpty else { return nil }
        return CrossAppNLHandler.shared.parseMessagesScopedIntent(normalized)
    }

    private func rawDockQuery(matching normalizedQuery: String) -> String {
        let rawQuery = searchState.query.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !rawQuery.isEmpty,
            normalizedDockPillText(rawQuery) == normalizedDockPillText(normalizedQuery)
        else {
            return normalizedQuery
        }
        return rawQuery
    }

    private func stripScopedAlias(
        _ alias: String,
        from rawQuery: String,
        allowPrefixAlias: Bool = false
    ) -> String {
        let trimmed = rawQuery.trimmingCharacters(in: .whitespacesAndNewlines)
        let aliasTokens = alias.split(separator: " ").map { $0.lowercased() }
        let queryTokens = trimmed.split(separator: " ", omittingEmptySubsequences: true)
        guard !aliasTokens.isEmpty, queryTokens.count >= aliasTokens.count else { return trimmed }

        let prefix = queryTokens.prefix(aliasTokens.count).map { $0.lowercased() }
        if prefix == aliasTokens
            || (allowPrefixAlias
                && firstScopedAliasRange(aliasTokens, in: prefix, allowPrefixLastToken: true)?.lowerBound == 0)
        {
            return trimScopedAppFillerWords(
                queryTokens.dropFirst(aliasTokens.count).map(String.init)
            )
        }

        let normalizedTokens = queryTokens.map { normalizedDockPillText(String($0)) }
        guard let range = firstScopedAliasRange(
            aliasTokens,
            in: normalizedTokens,
            allowPrefixLastToken: allowPrefixAlias
        ) else {
            return trimmed
        }
        var remaining = queryTokens.map(String.init)
        remaining.removeSubrange(range)
        return trimScopedAppFillerWords(remaining)
    }

    private func firstScopedAliasRange(
        _ aliasTokens: [String],
        in queryTokens: [String],
        allowPrefixLastToken: Bool = false
    ) -> Range<Int>? {
        guard !aliasTokens.isEmpty, queryTokens.count >= aliasTokens.count else { return nil }
        let maxStart = queryTokens.count - aliasTokens.count
        for start in 0...maxStart {
            let candidate = Array(queryTokens[start..<(start + aliasTokens.count)])
            let matches = candidate.enumerated().allSatisfy { index, token in
                let aliasToken = aliasTokens[index]
                if token == aliasToken { return true }
                let isLastToken = index == aliasTokens.count - 1
                return allowPrefixLastToken
                    && aliasTokens.count > 1
                    && isLastToken
                    && token.count >= 3
                    && aliasToken.hasPrefix(token)
            }
            if matches {
                return start..<(start + aliasTokens.count)
            }
        }
        return nil
    }

    private func trimScopedAppFillerWords(_ tokens: [String]) -> String {
        var words = tokens
        let filler: Set<String> = [
            "app", "open", "go", "goto", "navigate", "launch", "show", "use",
            "please", "the", "a", "an", "to", "in", "on", "for", "with", "into", "using"
        ]
        while let first = words.first,
              filler.contains(normalizedDockPillText(first)) {
            words.removeFirst()
        }
        while let last = words.last,
              filler.contains(normalizedDockPillText(last)) {
            words.removeLast()
        }
        return words.joined(separator: " ").trimmingCharacters(in: .whitespacesAndNewlines)
    }

    private func rawScopedActionQuery(for normalizedQuery: String, scope: DockScopeResolution) -> String {
        let rawQuery = rawDockQuery(matching: normalizedQuery)
        let normalizedRawQuery = normalizedDockPillText(rawQuery)

        let installedScopeMode = contextDockInstalledAppScopeMatching
        let runningOnly = contextDockRunningOnlyAppMatching && !installedScopeMode
        let runningBundleIds = runningOnly ? runningBundleIdsForContextDock() : []

        if scope.isExplicitAppScope,
           let explicitTarget = L2AppActionRouter.shared.appScopeTarget(for: normalizedRawQuery),
            (!runningOnly || runningBundleIds.contains(explicitTarget.bundleId)),
            explicitTarget.bundleId == scope.scopedBundleId
        {
            return stripScopedAlias(
                explicitTarget.matchedAlias,
                from: rawQuery,
                allowPrefixAlias: runningOnly
            )
        }

        if scope.isExplicitAppScope,
           let installedTarget = installedAppMenuTarget(
            for: normalizedRawQuery,
            runningOnly: runningOnly,
            includeAppsWithoutMenuSnapshot: installedScopeMode,
            allowPrefixAlias: installedScopeMode
        ),
            installedTarget.bundleId == scope.scopedBundleId
        {
            return stripScopedAlias(
                installedTarget.matchedAlias,
                from: rawQuery,
                allowPrefixAlias: runningOnly || installedScopeMode
            )
        }

        return rawQuery
    }

    private func messageIntentDisplayText(_ value: String, limit: Int) -> String {
        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
        guard trimmed.count > limit else { return trimmed }
        return String(trimmed.prefix(limit - 1)) + "…"
    }

    private func firstQuotedPhrase(in value: String) -> String? {
        guard let regex = try? NSRegularExpression(pattern: #""([^"]+)""#, options: []) else {
            return nil
        }
        let range = NSRange(value.startIndex..<value.endIndex, in: value)
        guard let match = regex.firstMatch(in: value, options: [], range: range),
            match.numberOfRanges > 1,
            let captureRange = Range(match.range(at: 1), in: value)
        else {
            return nil
        }
        return String(value[captureRange])
    }

    private enum MailSearchTokenKind {
        case generic
        case sender
        case subject
        case attachment
        case date
    }

    private struct MailSearchIntent {
        let query: String
        let tokenKind: MailSearchTokenKind
        let displayLabel: String
    }

    private struct AppFindIntent {
        let query: String
        let targetBundleId: String
        let targetAppName: String
        let userMessage: String
        let preferMailboxSearch: Bool
    }

    private func mailSearchDisplayLabel(
        query: String,
        tokenKind: MailSearchTokenKind
    ) -> String {
        switch tokenKind {
        case .date:
            return query
        case .sender:
            return "from \(query)"
        case .subject:
            return "subject \(query)"
        case .attachment:
            return "attachment \(query)"
        case .generic:
            return query
        }
    }

    private func mailSearchTokenKind(from value: String) -> MailSearchTokenKind {
        switch normalizedDockPillText(value) {
        case "sender":
            return .sender
        case "subject":
            return .subject
        case "attachment":
            return .attachment
        case "date":
            return .date
        default:
            return .generic
        }
    }

    private func resolvedMailMailboxSearchIntent(for rawScopedQuery: String) async -> MailSearchIntent? {
        #if canImport(FoundationModels)
        if #available(macOS 26.0, *) {
            if let generated = try? await generateMailIntent(
                from: rawScopedQuery,
                dateTimeContext: currentDateTimeContextBlock()
            ) {
                let mode = normalizedDockPillText(generated.mode)
                if mode == "question" || mode == "none" {
                    return nil
                }

                let resolvedQuery = generated.searchQuery
                    .trimmingCharacters(in: .whitespacesAndNewlines)
                if !resolvedQuery.isEmpty {
                    let tokenKind = mailSearchTokenKind(from: generated.tokenKind)
                    return MailSearchIntent(
                        query: resolvedQuery,
                        tokenKind: tokenKind,
                        displayLabel: mailSearchDisplayLabel(
                            query: resolvedQuery,
                            tokenKind: tokenKind
                        )
                    )
                }
            }
        }
        #endif

        return shouldExecuteMailMailboxSearch(for: rawScopedQuery)
    }

    private func weekdayNameCandidate(for normalizedQuery: String) -> String? {
        let weekdays = [
            "monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"
        ]
        return weekdays.first(where: { $0.hasPrefix(normalizedQuery) || normalizedQuery.hasPrefix($0) })
    }

    private func mailDateSuggestionCandidates(for query: String) -> [String] {
        let normalized = normalizedDockPillText(query)
        guard !normalized.isEmpty else { return [] }

        var candidates: [String] = []
        let formatter = DateFormatter()
        formatter.locale = Locale.current
        formatter.dateFormat = "EEEE, d MMMM yyyy"
        let calendar = Calendar.current
        let now = Date()

        if let weekday = weekdayNameCandidate(for: normalized) {
            candidates.append(weekday)
            if let weekdayIndex = [
                "sunday": 1, "monday": 2, "tuesday": 3, "wednesday": 4,
                "thursday": 5, "friday": 6, "saturday": 7,
            ][weekday] {
                let currentWeekday = calendar.component(.weekday, from: now)
                let offset = (weekdayIndex - currentWeekday + 7) % 7
                if let date = calendar.date(byAdding: .day, value: offset, to: now) {
                    candidates.append(formatter.string(from: date))
                }
            }
        }

        if ["today", "tod"].contains(where: { normalized.hasPrefix($0) }) {
            candidates.append(formatter.string(from: now))
        } else if ["yesterday", "yest"].contains(where: { normalized.hasPrefix($0) }),
            let date = calendar.date(byAdding: .day, value: -1, to: now)
        {
            candidates.append(formatter.string(from: date))
        } else if ["tomorrow", "tomo"].contains(where: { normalized.hasPrefix($0) }),
            let date = calendar.date(byAdding: .day, value: 1, to: now)
        {
            candidates.append(formatter.string(from: date))
        }

        return Array(NSOrderedSet(array: candidates)) as? [String] ?? candidates
    }

    private func mailSemanticSearchIntent(from rawScopedQuery: String) -> MailSearchIntent? {
        let trimmed = rawScopedQuery.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return nil }

        let normalized = normalizedDockPillText(trimmed)
        let tokens = Set(dockPillTokens(normalized))
        let intentWords: Set<String> = ["search", "find", "lookup", "look", "show"]
        let dateCandidates = mailDateSuggestionCandidates(for: trimmed)
        let explicitSenderIntent = tokens.contains("from") || tokens.contains("sender")
        let explicitSubjectIntent = tokens.contains("subject")
        let explicitAttachmentIntent =
            tokens.contains("attachment") || tokens.contains("attachments")
                || tokens.contains("attach")
        let explicitDateIntent =
            tokens.contains("date") || !dateCandidates.isEmpty

        guard !tokens.isDisjoint(with: intentWords)
            || explicitSenderIntent
            || explicitSubjectIntent
            || explicitAttachmentIntent
            || explicitDateIntent
        else { return nil }

        if let quoted = firstQuotedPhrase(in: trimmed)?
            .trimmingCharacters(in: .whitespacesAndNewlines),
            !quoted.isEmpty
        {
            let tokenKind: MailSearchTokenKind =
                explicitSenderIntent ? .sender
                : explicitSubjectIntent ? .subject
                : explicitAttachmentIntent ? .attachment
                : explicitDateIntent ? .date
                : .generic
            let label: String =
                tokenKind == .date ? quoted
                : tokenKind == .sender ? "from \(quoted)"
                : tokenKind == .subject ? "subject \(quoted)"
                : tokenKind == .attachment ? "attachment \(quoted)"
                : quoted
            return MailSearchIntent(query: quoted, tokenKind: tokenKind, displayLabel: label)
        }

        var cleaned = trimmed
        let patterns = [
            #"(?i)\b(search|find|lookup|look\s+for|show)\b"#,
            #"(?i)\b(mail|mails|email|emails|mailbox|inbox)\b"#,
            #"(?i)\b(sender|from|subject|attachment|attachments|attach|for|about|with|in|date)\b"#,
        ]
        for pattern in patterns {
            cleaned = cleaned.replacingOccurrences(
                of: pattern,
                with: " ",
                options: .regularExpression
            )
        }
        cleaned = cleaned
            .replacingOccurrences(of: #"\s+"#, with: " ", options: .regularExpression)
            .trimmingCharacters(in: .whitespacesAndNewlines)
        guard !cleaned.isEmpty else { return nil }

        let tokenKind: MailSearchTokenKind =
            explicitSenderIntent ? .sender
            : explicitSubjectIntent ? .subject
            : explicitAttachmentIntent ? .attachment
            : explicitDateIntent ? .date
            : .generic
        let label: String =
            tokenKind == .date ? cleaned
            : tokenKind == .sender ? "from \(cleaned)"
            : tokenKind == .subject ? "subject \(cleaned)"
            : tokenKind == .attachment ? "attachment \(cleaned)"
            : cleaned

        return MailSearchIntent(query: cleaned, tokenKind: tokenKind, displayLabel: label)
    }

    private func mailSemanticSearchQuery(from rawScopedQuery: String) -> String? {
        mailSemanticSearchIntent(from: rawScopedQuery)?.query
    }

    private func isQuestionStyleMailQuery(_ rawScopedQuery: String) -> Bool {
        let normalized = normalizedDockPillText(rawScopedQuery)
        guard !normalized.isEmpty else { return false }

        if rawScopedQuery.contains("?") { return true }

        let questionPrefixes = [
            "is", "are", "do", "does", "did", "have", "has", "what", "which", "who", "when",
            "where", "why", "how", "can", "could", "would", "should", "any", "show me",
            "tell me",
        ]
        if questionPrefixes.contains(where: { normalized == $0 || normalized.hasPrefix($0 + " ") }) {
            return true
        }

        return normalized.contains("any mail")
            || normalized.contains("any mails")
            || normalized.contains("there any")
    }

    private func shouldExecuteMailMailboxSearch(for rawScopedQuery: String) -> MailSearchIntent? {
        guard let intent = mailSemanticSearchIntent(from: rawScopedQuery) else { return nil }
        guard !isQuestionStyleMailQuery(rawScopedQuery) else { return nil }
        return intent
    }

    private struct MailQuestionFilters {
        let senderFilter: String
        let subjectFilter: String
        let unreadOnly: Bool
        let relativeDay: String
        let criteriaSummary: [String]
    }

    private func mailFieldFilter(
        from query: String,
        triggers: Set<String>
    ) -> String? {
        let tokens = dockPillTokens(normalizedDockPillText(query))
        guard let triggerIndex = tokens.firstIndex(where: { triggers.contains($0) }) else { return nil }

        let stopWords: Set<String> = [
            "today", "yesterday", "tomorrow", "unread", "read", "mail", "mails", "email",
            "emails", "mailbox", "inbox", "is", "are", "was", "were", "any", "there", "show",
            "find", "search", "lookup", "look", "for", "about", "with", "and", "or", "the",
            "a", "an", "messages", "message", "date",
        ]

        var collected: [String] = []
        for token in tokens.dropFirst(triggerIndex + 1) {
            if stopWords.contains(token) { break }
            collected.append(token)
        }

        let result = collected.joined(separator: " ").trimmingCharacters(in: .whitespacesAndNewlines)
        return result.isEmpty ? nil : result
    }

    private func mailQuestionFilters(for query: String) -> MailQuestionFilters {
        let normalized = normalizedDockPillText(query)
        let senderFilter = mailFieldFilter(from: query, triggers: ["from", "sender"]) ?? ""
        let subjectFilter = mailFieldFilter(from: query, triggers: ["subject"]) ?? ""
        let unreadOnly = normalized.contains("unread")

        let relativeDay: String =
            normalized.contains("today") ? "today"
            : normalized.contains("yesterday") ? "yesterday"
            : ""

        let criteriaSummary: [String] = [
            !senderFilter.isEmpty ? "sender contains “\(senderFilter)”" : nil,
            !subjectFilter.isEmpty ? "subject contains “\(subjectFilter)”" : nil,
            !relativeDay.isEmpty ? "received \(relativeDay)" : nil,
            unreadOnly ? "unread only" : nil,
        ].compactMap { $0 }

        return MailQuestionFilters(
            senderFilter: senderFilter,
            subjectFilter: subjectFilter,
            unreadOnly: unreadOnly,
            relativeDay: relativeDay,
            criteriaSummary: criteriaSummary
        )
    }

    private func answerAttachedMailQuestion(for rawScopedQuery: String) -> String? {
        guard isCurrentMailContextAttached(), isQuestionStyleMailQuery(rawScopedQuery) else { return nil }

        let filters = mailQuestionFilters(for: rawScopedQuery)
        let normalized = normalizedDockPillText(rawScopedQuery)
        let hasUsefulFilters =
            !filters.senderFilter.isEmpty
            || !filters.subjectFilter.isEmpty
            || filters.unreadOnly
            || !filters.relativeDay.isEmpty

        guard hasUsefulFilters || normalized.contains("mail") || normalized.contains("email") else {
            return nil
        }

        guard let snapshot = MailAutomation.mailboxSnapshotData(
            senderContains: filters.senderFilter,
            subjectContains: filters.subjectFilter,
            unreadOnly: filters.unreadOnly,
            relativeDay: filters.relativeDay,
            limit: 12,
            maxScan: 150
        ) else {
            return "Mail context could not be read from the current mailbox."
        }

        let expectsYesNo =
            rawScopedQuery.contains("?")
            || normalized.hasPrefix("is ")
            || normalized.hasPrefix("are ")
            || normalized.hasPrefix("do ")
            || normalized.hasPrefix("does ")
            || normalized.hasPrefix("did ")
            || normalized.hasPrefix("have ")
            || normalized.hasPrefix("has ")
            || normalized.contains("any mail")
            || normalized.contains("any mails")

        let criteriaText = filters.criteriaSummary.joined(separator: ", ")
        let matchCount = snapshot.messages.count

        if matchCount == 0 {
            if expectsYesNo {
                return criteriaText.isEmpty
                    ? "No — I couldn't find matching mail in \(snapshot.mailboxName)."
                    : "No — I couldn't find mail in \(snapshot.mailboxName) matching \(criteriaText)."
            }
            return criteriaText.isEmpty
                ? "No matching mail found in \(snapshot.mailboxName)."
                : "No mail in \(snapshot.mailboxName) matched \(criteriaText)."
        }

        var answer = expectsYesNo
            ? "Yes — found \(matchCount) matching \(matchCount == 1 ? "mail" : "mails") in \(snapshot.mailboxName)"
            : "Found \(matchCount) matching \(matchCount == 1 ? "mail" : "mails") in \(snapshot.mailboxName)"
        if !criteriaText.isEmpty {
            answer += " (\(criteriaText))."
        } else {
            answer += "."
        }

        for message in snapshot.messages.prefix(4) {
            answer += "\n- \(message.subject) — \(message.sender) — \(message.dateText)"
        }
        if matchCount > 4 {
            answer += "\n+ \(matchCount - 4) more"
        }

        return answer
    }

    private func buildAttachedMailContextBlock(for query: String) -> String? {
        let filters = mailQuestionFilters(for: query)
        guard let snapshot = MailAutomation.mailboxSnapshotData(
            senderContains: filters.senderFilter,
            subjectContains: filters.subjectFilter,
            unreadOnly: filters.unreadOnly,
            relativeDay: filters.relativeDay,
            limit: 12,
            maxScan: 150
        ) else {
            return "\n📧 ACTUAL MAIL DATA:\nMail context could not be read.\n"
        }

        var block = "\n📧 ACTUAL MAIL DATA (recent \(snapshot.mailboxName) scan):\n"
        if !filters.criteriaSummary.isEmpty {
            block += "Criteria: " + filters.criteriaSummary.joined(separator: ", ") + "\n"
        }
        block += "Mailbox: \(snapshot.mailboxName)\n"

        if snapshot.messages.isEmpty {
            block += "No matching messages were found in the recent Mail scan.\n"
            return block
        }

        for message in snapshot.messages {
            block += "- \(message.subject) | From: \(message.sender) | \(message.dateText) | Read: \(message.isRead)\n"
        }
        block +=
            "IMPORTANT: Use this ACTUAL mail data to answer mailbox questions. Do not make up email results.\n"
        return block
    }

    private func applicationURL(bundleIdentifier: String, appName: String) -> URL? {
        if let url = NSWorkspace.shared.urlForApplication(withBundleIdentifier: bundleIdentifier) {
            return url
        }
        if let match = allApplications.first(where: { result in
            Bundle(url: URL(fileURLWithPath: result.subtitle))?.bundleIdentifier == bundleIdentifier
        }) {
            return URL(fileURLWithPath: match.subtitle)
        }
        let fallbackDirectories = [
            "/Applications",
            "/System/Applications",
            "/System/Volumes/Preboot/Cryptexes/App/System/Applications",
            "\(NSHomeDirectory())/Applications",
        ]
        for directory in fallbackDirectories {
            let url = URL(fileURLWithPath: directory)
                .appendingPathComponent(appName)
                .appendingPathExtension("app")
            if FileManager.default.fileExists(atPath: url.path) {
                return url
            }
        }
        return nil
    }

    private func activateOrLaunchSemanticApp(bundleIdentifier: String, appName: String) async
        -> NSRunningApplication?
    {
        if let runningApp = NSWorkspace.shared.runningApplications.first(where: {
            $0.bundleIdentifier == bundleIdentifier && !$0.isTerminated
        }) {
            await MainActor.run { runningApp.activate() }
            return runningApp
        }

        guard let appURL = applicationURL(bundleIdentifier: bundleIdentifier, appName: appName)
        else { return nil }

        let configuration = NSWorkspace.OpenConfiguration()
        configuration.activates = true

        do {
            let launchedApp = try await NSWorkspace.shared.openApplication(
                at: appURL,
                configuration: configuration
            )
            return launchedApp
        } catch {
            NSWorkspace.shared.open(appURL)
            for _ in 0..<20 {
                try? await Task.sleep(nanoseconds: 120_000_000)
                if let runningApp = NSWorkspace.shared.runningApplications.first(where: {
                    $0.bundleIdentifier == bundleIdentifier && !$0.isTerminated
                }) {
                    await MainActor.run { runningApp.activate() }
                    return runningApp
                }
            }
            return nil
        }
    }

    private func axStringAttribute(_ element: AXUIElement, _ attribute: CFString) -> String? {
        var ref: CFTypeRef?
        guard AXUIElementCopyAttributeValue(element, attribute, &ref) == .success else { return nil }
        return ref as? String
    }

    private func axStringArrayAttribute(_ element: AXUIElement, _ attribute: CFString) -> [String] {
        var ref: CFTypeRef?
        guard AXUIElementCopyAttributeValue(element, attribute, &ref) == .success else { return [] }
        return ref as? [String] ?? []
    }

    private func axChildElements(_ element: AXUIElement) -> [AXUIElement] {
        var ref: CFTypeRef?
        guard AXUIElementCopyAttributeValue(element, kAXChildrenAttribute as CFString, &ref) == .success,
            let children = ref as? [AXUIElement]
        else { return [] }
        return children
    }

    private func currentFocusedElement(in pid: pid_t) -> AXUIElement? {
        let appElement = AXUIElementCreateApplication(pid)
        var ref: CFTypeRef?
        guard AXUIElementCopyAttributeValue(
            appElement,
            kAXFocusedUIElementAttribute as CFString,
            &ref
        ) == .success, let focused = ref
        else { return nil }
        return unsafeBitCast(focused, to: AXUIElement.self)
    }

    private func isEditableAXElement(_ element: AXUIElement) -> Bool {
        let role = axStringAttribute(element, kAXRoleAttribute as CFString) ?? ""
        return ["AXSearchField", "AXTextField", "AXComboBox", "AXTextArea"].contains(role)
    }

    private func findMailSearchField(in element: AXUIElement, depth: Int = 0) -> AXUIElement? {
        guard depth < 8 else { return nil }

        let role = axStringAttribute(element, kAXRoleAttribute as CFString) ?? ""
        if role == "AXSearchField" {
            return element
        }

        let description = axStringAttribute(element, kAXDescriptionAttribute as CFString) ?? ""
        let title = axStringAttribute(element, kAXTitleAttribute as CFString) ?? ""
        let help = axStringAttribute(element, kAXHelpAttribute as CFString) ?? ""
        let metadata = normalizedDockPillText([description, title, help].joined(separator: " "))

        if isEditableAXElement(element),
            metadata.contains("search") || metadata.contains("mailbox")
        {
            return element
        }

        var firstEditableField: AXUIElement?
        for child in axChildElements(element) {
            if let exact = findMailSearchField(in: child, depth: depth + 1) {
                return exact
            }
            if firstEditableField == nil, isEditableAXElement(child) {
                firstEditableField = child
            }
        }
        return firstEditableField
    }

    private func findGenericSearchField(in element: AXUIElement, depth: Int = 0) -> AXUIElement? {
        guard depth < 9 else { return nil }

        let role = axStringAttribute(element, kAXRoleAttribute as CFString) ?? ""
        if role == "AXSearchField" {
            return element
        }

        let description = axStringAttribute(element, kAXDescriptionAttribute as CFString) ?? ""
        let title = axStringAttribute(element, kAXTitleAttribute as CFString) ?? ""
        let help = axStringAttribute(element, kAXHelpAttribute as CFString) ?? ""
        let placeholder =
            axStringAttribute(element, "AXPlaceholderValue" as CFString) ?? ""
        let metadata = normalizedDockPillText(
            [description, title, help, placeholder].joined(separator: " ")
        )

        if isEditableAXElement(element),
            metadata.contains("search")
                || metadata.contains("find")
                || metadata.contains("filter")
        {
            return element
        }

        var firstEditableField: AXUIElement?
        for child in axChildElements(element) {
            if let exact = findGenericSearchField(in: child, depth: depth + 1) {
                return exact
            }
            if firstEditableField == nil, isEditableAXElement(child) {
                firstEditableField = child
            }
        }
        return firstEditableField
    }

    private func setAXTextValue(_ text: String, on element: AXUIElement) -> Bool {
        let setFocusStatus = AXUIElementSetAttributeValue(
            element,
            kAXFocusedAttribute as CFString,
            kCFBooleanTrue
        )
        _ = setFocusStatus
        guard AXUIElementSetAttributeValue(
            element,
            kAXValueAttribute as CFString,
            text as CFTypeRef
        ) == .success else { return false }

        guard let currentValue = axStringAttribute(element, kAXValueAttribute as CFString) else {
            return false
        }

        let normalizedCurrent = normalizedDockPillText(currentValue)
        let normalizedTarget = normalizedDockPillText(text)
        return normalizedCurrent == normalizedTarget
            || normalizedCurrent.contains(normalizedTarget)
    }

    private func postKeyCode(_ keyCode: CGKeyCode, to pid: pid_t) {
        guard let source = CGEventSource(stateID: .hidSystemState),
            let keyDown = CGEvent(keyboardEventSource: source, virtualKey: keyCode, keyDown: true),
            let keyUp = CGEvent(keyboardEventSource: source, virtualKey: keyCode, keyDown: false)
        else { return }
        keyDown.postToPid(pid)
        keyUp.postToPid(pid)
    }

    private func postModifiedKeyCode(_ keyCode: CGKeyCode, flags: CGEventFlags, to pid: pid_t) {
        guard let source = CGEventSource(stateID: .hidSystemState),
            let keyDown = CGEvent(keyboardEventSource: source, virtualKey: keyCode, keyDown: true),
            let keyUp = CGEvent(keyboardEventSource: source, virtualKey: keyCode, keyDown: false)
        else { return }
        keyDown.flags = flags
        keyUp.flags = flags
        keyDown.postToPid(pid)
        keyUp.postToPid(pid)
    }

    private func postUnicodeText(_ text: String, to pid: pid_t) {
        let utf16 = Array(text.utf16)
        guard !utf16.isEmpty,
            let source = CGEventSource(stateID: .hidSystemState),
            let keyDown = CGEvent(keyboardEventSource: source, virtualKey: 0, keyDown: true),
            let keyUp = CGEvent(keyboardEventSource: source, virtualKey: 0, keyDown: false)
        else { return }
        keyDown.keyboardSetUnicodeString(stringLength: utf16.count, unicodeString: utf16)
        keyUp.keyboardSetUnicodeString(stringLength: utf16.count, unicodeString: utf16)
        keyDown.postToPid(pid)
        keyUp.postToPid(pid)
    }

    private func pasteString(_ text: String, to pid: pid_t) {
        let pasteboard = NSPasteboard.general
        let previousString = pasteboard.string(forType: .string)
        pasteboard.clearContents()
        pasteboard.setString(text, forType: .string)
        postModifiedKeyCode(9, flags: .maskCommand, to: pid)
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.35) {
            pasteboard.clearContents()
            if let previousString {
                pasteboard.setString(previousString, forType: .string)
            }
        }
    }

    private func setFindPasteboardString(_ text: String) {
        let findPasteboard = NSPasteboard(name: NSPasteboard.Name("NSFindPboard"))
        findPasteboard.clearContents()
        findPasteboard.setString(text, forType: .string)
    }

    private func injectSearchQuery(_ query: String, into pid: pid_t, pressReturn: Bool = false) async
        -> Bool
    {
        let trimmed = query.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return false }

        for _ in 0..<16 {
            if let focusedElement = currentFocusedElement(in: pid),
                isEditableAXElement(focusedElement)
            {
                let didPasteValue = await typeMailSearchQuery(
                    trimmed,
                    into: focusedElement,
                    pid: pid
                )
                let didSetAXValue =
                    didPasteValue
                    ? false
                    : setAXTextValue(trimmed, on: focusedElement)
                if didPasteValue || didSetAXValue {
                    if pressReturn { postKeyCode(36, to: pid) }
                    return true
                }
            }

            let appElement = AXUIElementCreateApplication(pid)
            if let searchField = findGenericSearchField(in: appElement) {
                let didPasteValue = await typeMailSearchQuery(trimmed, into: searchField, pid: pid)
                let didSetAXValue =
                    didPasteValue
                    ? false
                    : setAXTextValue(trimmed, on: searchField)
                if didPasteValue || didSetAXValue {
                    if pressReturn { postKeyCode(36, to: pid) }
                    return true
                }
            }

            try? await Task.sleep(nanoseconds: 90_000_000)
        }

        return false
    }

    private func typeMailSearchQuery(_ query: String, into element: AXUIElement, pid: pid_t) async
        -> Bool
    {
        _ = AXUIElementSetAttributeValue(
            element,
            kAXFocusedAttribute as CFString,
            kCFBooleanTrue
        )
        try? await Task.sleep(nanoseconds: 60_000_000)
        postModifiedKeyCode(0, flags: .maskCommand, to: pid)
        try? await Task.sleep(nanoseconds: 40_000_000)
        pasteString(query, to: pid)
        try? await Task.sleep(nanoseconds: 80_000_000)

        if let currentValue = axStringAttribute(element, kAXValueAttribute as CFString) {
            let normalizedCurrent = normalizedDockPillText(currentValue)
            let normalizedTarget = normalizedDockPillText(query)
            return normalizedCurrent == normalizedTarget
                || normalizedCurrent.contains(normalizedTarget)
        }

        return true
    }

    private func axSearchableStrings(for element: AXUIElement) -> [String] {
        [
            axStringAttribute(element, kAXTitleAttribute as CFString),
            axStringAttribute(element, kAXValueAttribute as CFString),
            axStringAttribute(element, kAXDescriptionAttribute as CFString),
            axStringAttribute(element, kAXHelpAttribute as CFString),
        ]
        .compactMap { $0?.trimmingCharacters(in: .whitespacesAndNewlines) }
        .filter { !$0.isEmpty }
    }

    private func axSubtreeSearchableStrings(for element: AXUIElement, depth: Int = 0) -> [String] {
        guard depth < 2 else { return axSearchableStrings(for: element) }

        var results = axSearchableStrings(for: element)
        for child in axChildElements(element).prefix(12) {
            results.append(contentsOf: axSubtreeSearchableStrings(for: child, depth: depth + 1))
        }
        return results
    }

    private func isMailSuggestionActionRole(_ role: String) -> Bool {
        [
            "AXRow",
            "AXGroup",
            "AXButton",
            "AXMenuItem",
            "AXListItem",
            "AXCell",
        ].contains(role)
    }

    private struct MailSuggestionMatcher {
        let tokenKind: MailSearchTokenKind
        let normalizedQuery: String
        let normalizedQueryTokens: [String]
        let normalizedCandidates: [String]
        let normalizedFieldTokens: [String]

        private static func normalize(_ text: String) -> String {
            let lowered = text.lowercased()
            let mapped = lowered.unicodeScalars.map { scalar -> Character in
                if CharacterSet.alphanumerics.contains(scalar)
                    || CharacterSet.whitespacesAndNewlines.contains(scalar)
                {
                    return Character(scalar)
                }
                return " "
            }
            return String(mapped)
                .components(separatedBy: .whitespacesAndNewlines)
                .filter { !$0.isEmpty }
                .joined(separator: " ")
        }

        private static func isActionRole(_ role: String) -> Bool {
            ["AXRow", "AXGroup", "AXButton", "AXMenuItem", "AXListItem", "AXCell"].contains(role)
        }

        init(intent: MailSearchIntent, candidates: [String]) {
            tokenKind = intent.tokenKind
            normalizedQuery = Self.normalize(intent.query)
            normalizedQueryTokens = normalizedQuery
                .split(whereSeparator: \.isWhitespace)
                .map(String.init)
                .filter { !$0.isEmpty }
            normalizedCandidates = candidates.map { Self.normalize($0) }.filter { !$0.isEmpty }

            switch intent.tokenKind {
            case .generic:
                normalizedFieldTokens = []
            case .sender:
                normalizedFieldTokens = ["sender", "contains"]
            case .subject:
                normalizedFieldTokens = ["subject", "contains"]
            case .attachment:
                normalizedFieldTokens = ["attachment", "name", "contains"]
            case .date:
                normalizedFieldTokens = ["date"]
            }
        }

        func score(
            role: String,
            actionNames: [String],
            directStrings: [String],
            subtreeStrings: [String]
        ) -> Int? {
            let normalizedDirect = directStrings.map { Self.normalize($0) }.filter { !$0.isEmpty }
            let normalizedSubtree = subtreeStrings.map { Self.normalize($0) }.filter { !$0.isEmpty }
            let combinedDirect = normalizedDirect.joined(separator: " ")
            let combinedSubtree = normalizedSubtree.joined(separator: " ")

            guard !combinedSubtree.isEmpty else { return nil }

            let exactDirectMatch = normalizedCandidates.contains { candidate in
                combinedDirect == candidate || combinedDirect.contains(candidate)
            }
            let exactSubtreeMatch = normalizedCandidates.contains { candidate in
                combinedSubtree == candidate || combinedSubtree.contains(candidate)
            }

            let tokenMatch: Bool = {
                switch tokenKind {
                case .generic:
                    return false
                case .date:
                    return exactDirectMatch
                        || exactSubtreeMatch
                        || normalizedQueryTokens.contains(where: { combinedSubtree.contains($0) })
                case .sender, .subject, .attachment:
                    let hasFieldTokens = normalizedFieldTokens.allSatisfy { combinedSubtree.contains($0) }
                    let hasQueryTokens =
                        !normalizedQueryTokens.isEmpty
                        && normalizedQueryTokens.allSatisfy { combinedSubtree.contains($0) }
                    return exactDirectMatch || exactSubtreeMatch || (hasFieldTokens && hasQueryTokens)
                }
            }()

            guard tokenMatch else { return nil }

            var score = 0
            if exactDirectMatch { score += 240 }
            if exactSubtreeMatch { score += 180 }
            if Self.isActionRole(role) { score += 120 }
            if role == "AXStaticText" { score -= 240 }
            if role == "AXRow" { score += 80 }
            if role == "AXMenuItem" || role == "AXListItem" || role == "AXCell" { score += 60 }
            if role == "AXGroup" || role == "AXButton" { score += 40 }
            if actionNames.contains(kAXPressAction as String) { score += 30 }
            if actionNames.contains(kAXConfirmAction as String) { score += 15 }
            if combinedDirect.contains(normalizedQuery) { score += 20 }
            if combinedSubtree.contains(normalizedQuery) { score += 10 }
            return score
        }
    }

    private func bestMailSuggestionTarget(
        in element: AXUIElement,
        matcher: MailSuggestionMatcher,
        depth: Int = 0
    ) -> (element: AXUIElement, score: Int)? {
        guard depth < 10 else { return nil }

        let role = axStringAttribute(element, kAXRoleAttribute as CFString) ?? ""
        let actionNames = axStringArrayAttribute(element, "AXActions" as CFString)
        let directStrings = axSearchableStrings(for: element)
        let subtreeStrings =
            isMailSuggestionActionRole(role)
            ? axSubtreeSearchableStrings(for: element)
            : directStrings

        var best: (element: AXUIElement, score: Int)?
        if let score = matcher.score(
            role: role,
            actionNames: actionNames,
            directStrings: directStrings,
            subtreeStrings: subtreeStrings
        ) {
            best = (element, score)
        }

        for child in axChildElements(element) {
            guard let childBest = bestMailSuggestionTarget(
                in: child,
                matcher: matcher,
                depth: depth + 1
            ) else { continue }

            if let currentBest = best {
                if childBest.score > currentBest.score {
                    best = childBest
                }
            } else {
                best = childBest
            }
        }

        return best
    }

    private func pressMailSuggestion(
        in element: AXUIElement,
        matcher: MailSuggestionMatcher,
        depth: Int = 0
    ) -> Bool {
        guard depth == 0 else { return false }
        guard let best = bestMailSuggestionTarget(in: element, matcher: matcher) else { return false }

        if AXUIElementPerformAction(best.element, kAXPressAction as CFString) == .success {
            return true
        }
        if AXUIElementPerformAction(best.element, kAXConfirmAction as CFString) == .success {
            return true
        }

        for child in axChildElements(best.element) {
            if AXUIElementPerformAction(child, kAXPressAction as CFString) == .success {
                return true
            }
            if AXUIElementPerformAction(child, kAXConfirmAction as CFString) == .success {
                return true
            }
        }
        return false
    }

    private func applyMailSearchTokenIntent(_ intent: MailSearchIntent, in pid: pid_t) async -> Bool {
        let candidates: [String] = {
            switch intent.tokenKind {
            case .generic:
                return []
            case .sender:
                return ["Sender contains: \(intent.query)"]
            case .subject:
                return ["Subject contains: \(intent.query)"]
            case .attachment:
                return ["Attachment name contains: \(intent.query)"]
            case .date:
                return mailDateSuggestionCandidates(for: intent.query)
            }
        }()

        guard !candidates.isEmpty else { return true }
        let matcher = MailSuggestionMatcher(intent: intent, candidates: candidates)

        for _ in 0..<12 {
            let appElement = AXUIElementCreateApplication(pid)
            if pressMailSuggestion(in: appElement, matcher: matcher) {
                return true
            }
            try? await Task.sleep(nanoseconds: 90_000_000)
        }

        return false
    }

    private func injectMailSearchQuery(_ query: String, into pid: pid_t) async -> Bool {
        let trimmed = query.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return false }

        for _ in 0..<18 {
            if let focusedElement = currentFocusedElement(in: pid),
                isEditableAXElement(focusedElement)
            {
                let didSetAXValue = setAXTextValue(trimmed, on: focusedElement)
                let didTypeValue =
                    didSetAXValue
                    ? false
                    : await typeMailSearchQuery(trimmed, into: focusedElement, pid: pid)
                if didSetAXValue || didTypeValue {
                    postKeyCode(36, to: pid)
                    return true
                }
            }

            let appElement = AXUIElementCreateApplication(pid)
            if let searchField = findMailSearchField(in: appElement) {
                let didSetAXValue = setAXTextValue(trimmed, on: searchField)
                let didTypeValue =
                    didSetAXValue
                    ? false
                    : await typeMailSearchQuery(trimmed, into: searchField, pid: pid)
                if didSetAXValue || didTypeValue {
                    postKeyCode(36, to: pid)
                    return true
                }
            }

            try? await Task.sleep(nanoseconds: 100_000_000)
        }

        return false
    }

    private func executeMailMailboxSearch(intent: MailSearchIntent, userMessage: String) {
        let searchQuery = intent.query.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !searchQuery.isEmpty else { return }

        if let existingTask = l2.currentTask {
            existingTask.cancel()
            l2.currentTask = nil
            l2.isLoading = false
            l2.activeRequestID = nil
        }

        l2.chatMessages.append(AIChatMessage(role: .user, content: userMessage))
        l2.isLoading = true

        l2.currentTask = Task {
            guard let mailApp = await activateOrLaunchSemanticApp(
                bundleIdentifier: "com.apple.mail",
                appName: "Mail"
            ) else {
                await MainActor.run {
                    l2.chatMessages.append(
                        AIChatMessage(
                            role: .assistant,
                            content: "❌ Couldn't open Mail.",
                            isError: true
                        ))
                    l2.isLoading = false
                    l2.currentTask = nil
                }
                return
            }

            let pid = mailApp.processIdentifier
            try? await Task.sleep(nanoseconds: 220_000_000)

            let liveItems = AXMenuReader.shared.refreshAllMenuItems(for: pid, maxDepth: 6)
            let mailboxSearchPath =
                liveItems.first(where: { item in
                    normalizedDockPillText(item.title) == "mailbox search"
                        || normalizedDockPillText(item.path.joined(separator: " ")) ==
                            "edit find mailbox search"
                })?.path

            var triggeredSearch = false
            if let mailboxSearchPath {
                triggeredSearch = AXMenuReader.shared.clickMenuItem(path: mailboxSearchPath, in: pid)
            }
            if !triggeredSearch {
                AXMenuReader.shared.executeShortcut(char: "f", modifiers: 2, in: pid)
                triggeredSearch = true
            }

            guard triggeredSearch else {
                await MainActor.run {
                    l2.chatMessages.append(
                        AIChatMessage(
                            role: .assistant,
                            content: "❌ Couldn't open Mail search.",
                            isError: true
                        ))
                    l2.isLoading = false
                    l2.currentTask = nil
                }
                return
            }

            let injected = await injectMailSearchQuery(searchQuery, into: pid)
            let appliedToken = injected ? await applyMailSearchTokenIntent(intent, in: pid) : false

            await MainActor.run {
                if injected {
                    l2.chatMessages.append(
                        AIChatMessage(
                            role: .assistant,
                            content: appliedToken && intent.tokenKind != .generic
                                ? "Opened Mailbox Search for \(intent.displayLabel)."
                                : "Opened Mailbox Search for “\(searchQuery)”."
                        ))
                    searchState.query = ""
                    l2.focusedPillIndex = nil
                } else {
                    l2.chatMessages.append(
                        AIChatMessage(
                            role: .assistant,
                            content:
                                "⚠️ Opened Mail search, but couldn't inject the query automatically.",
                            isError: true
                        ))
                }
                l2.isLoading = false
                l2.currentTask = nil
            }
        }
    }

    private func selectedTextPayloadForFindIntent() -> String {
        let context = effectiveAXContextForConversation()
        if let selected = context.selectedText?.trimmingCharacters(in: .whitespacesAndNewlines),
            !selected.isEmpty
        {
            return selected
        }

        if case .textSelected(let text) = currentContext {
            let selected = text.trimmingCharacters(in: .whitespacesAndNewlines)
            if !selected.isEmpty {
                return selected
            }
        }

        return ""
    }

    private func findIntentPayload(from rawScopedQuery: String) -> String {
        let trimmed = rawScopedQuery.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return "" }

        if let quoted = firstQuotedPhrase(in: trimmed)?
            .trimmingCharacters(in: .whitespacesAndNewlines),
            !quoted.isEmpty
        {
            return quoted
        }

        var cleaned = trimmed
        let patterns = [
            #"(?i)\b(search|find|lookup|look\s+for|show|display|view|open)\b"#,
            #"(?i)\b(photos?\s+of|pictures?\s+of|images?\s+of)\b"#,
            #"(?i)^\s*of\s+"#,
            #"(?i)\b(selected|selection|this|that|text)\b"#,
            #"(?i)\b(in|inside|within|for|on|with|using|app|application)\b"#,
        ]
        for pattern in patterns {
            cleaned = cleaned.replacingOccurrences(
                of: pattern,
                with: " ",
                options: .regularExpression
            )
        }
        return cleaned
            .replacingOccurrences(of: #"\s+"#, with: " ", options: .regularExpression)
            .trimmingCharacters(in: .whitespacesAndNewlines)
    }

    private func isFindIntentCommand(_ rawScopedQuery: String, fullQuery: String) -> Bool {
        let raw = normalizedDockPillText(rawScopedQuery)
        let full = normalizedDockPillText(fullQuery)
        let prefixes = ["find", "search", "lookup", "look for", "show", "display", "view", "open"]
        if prefixes.contains(where: { prefix in
            raw == prefix || raw.hasPrefix(prefix + " ")
                || full == prefix || full.hasPrefix(prefix + " ")
        }) { return true }
        // "photos of X", "pictures of X" as standalone pattern
        let mediaPatterns = [#"(?i)^photos?\s+of\b"#, #"(?i)^pictures?\s+of\b"#, #"(?i)^images?\s+of\b"#]
        return mediaPatterns.contains { pat in
            raw.range(of: pat, options: .regularExpression) != nil
                || full.range(of: pat, options: .regularExpression) != nil
        }
    }

    private func resolvedFindIntent(
        for query: String,
        dockScope: DockScopeResolution,
        rawScopedQuery: String
    ) -> AppFindIntent? {
        guard isFindIntentCommand(rawScopedQuery, fullQuery: query) else { return nil }

        let directPayload = findIntentPayload(from: rawScopedQuery)
        let selectedPayload = selectedTextPayloadForFindIntent()
        let searchQuery = directPayload.isEmpty ? selectedPayload : directPayload
        guard !searchQuery.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
            return nil
        }

        let target: (bundleId: String, appName: String)? = {
            if dockScope.isExplicitAppScope,
                !dockScope.scopedBundleId.isEmpty,
                !dockScope.scopedAppName.isEmpty
            {
                return (dockScope.scopedBundleId, dockScope.scopedAppName)
            }

            if let target = l2.targetApp, !target.bundleId.hasPrefix("scope://") {
                return (target.bundleId, target.name)
            }

            if let app = contextTargetApp(),
                let bundleId = app.bundleIdentifier,
                !bundleId.isEmpty,
                bundleId != Bundle.main.bundleIdentifier
            {
                return (bundleId, app.localizedName ?? frontmost.name)
            }

            return nil
        }()

        guard let target else { return nil }
        return AppFindIntent(
            query: searchQuery,
            targetBundleId: target.bundleId,
            targetAppName: target.appName,
            userMessage: query,
            preferMailboxSearch: target.bundleId == "com.apple.mail"
        )
    }

    private func openFindInterface(in pid: pid_t, bundleIdentifier: String) async -> Bool {
        if bundleIdentifier == "com.apple.mail" {
            let liveItems = AXMenuReader.shared.refreshAllMenuItems(for: pid, maxDepth: 6)
            if let mailboxSearchPath = liveItems.first(where: { item in
                normalizedDockPillText(item.title) == "mailbox search"
                    || normalizedDockPillText(item.path.joined(separator: " ")) ==
                        "edit find mailbox search"
            })?.path,
                AXMenuReader.shared.clickMenuItem(path: mailboxSearchPath, in: pid)
            {
                return true
            }
        } else {
            let liveItems = AXMenuReader.shared.refreshAllMenuItems(for: pid, maxDepth: 6)
            if let findPath = liveItems.first(where: { item in
                let title = normalizedDockPillText(item.title)
                let path = normalizedDockPillText(item.path.joined(separator: " "))
                return title == "find"
                    || title == "find..."
                    || path == "edit find find"
                    || path == "edit find find..."
            })?.path,
                AXMenuReader.shared.clickMenuItem(path: findPath, in: pid)
            {
                return true
            }
        }

        AXMenuReader.shared.executeShortcut(char: "f", modifiers: 2, in: pid)
        return true
    }

    private func executeAppFindIntent(_ intent: AppFindIntent) {
        let searchQuery = intent.query.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !searchQuery.isEmpty else { return }

        if intent.preferMailboxSearch {
            let mailIntent = MailSearchIntent(
                query: searchQuery,
                tokenKind: .generic,
                displayLabel: searchQuery
            )
            executeMailMailboxSearch(intent: mailIntent, userMessage: intent.userMessage)
            return
        }

        if let existingTask = l2.currentTask {
            existingTask.cancel()
            l2.currentTask = nil
            l2.isLoading = false
            l2.activeRequestID = nil
        }

        l2.chatMessages.append(AIChatMessage(role: .user, content: intent.userMessage))
        l2.isLoading = true
        let searchActionId = DockActionFeedback.start("Searching", subject: "\(intent.targetAppName) for \"\(searchQuery)\"", icon: "magnifyingglass", tint: .accentColor)

        l2.currentTask = Task {
            guard let app = await activateOrLaunchSemanticApp(
                bundleIdentifier: intent.targetBundleId,
                appName: intent.targetAppName
            ) else {
                await MainActor.run {
                    l2.chatMessages.append(
                        AIChatMessage(
                            role: .assistant,
                            content: "❌ Couldn't open \(intent.targetAppName).",
                            isError: true
                        ))
                    DockActionFeedback.fail(searchActionId, label: "Couldn't open \(intent.targetAppName)")
                    l2.isLoading = false
                    l2.currentTask = nil
                }
                return
            }

            let pid = app.processIdentifier
            try? await Task.sleep(nanoseconds: 180_000_000)
            setFindPasteboardString(searchQuery)
            _ = await openFindInterface(in: pid, bundleIdentifier: intent.targetBundleId)
            try? await Task.sleep(nanoseconds: 160_000_000)
            let injected = await injectSearchQuery(searchQuery, into: pid)

            await MainActor.run {
                if injected {
                    l2.chatMessages.append(
                        AIChatMessage(
                            role: .assistant,
                            content: "Searching \(intent.targetAppName) for \"\(searchQuery)\"."
                        ))
                    DockActionFeedback.complete(searchActionId)
                    searchState.query = ""
                    l2.focusedPillIndex = nil
                    scheduleDockPillRebuild(query: "", delayNanoseconds: 0)
                } else {
                    l2.chatMessages.append(
                        AIChatMessage(
                            role: .assistant,
                            content:
                                "⚠️ Opened Find in \(intent.targetAppName), but couldn't insert the query automatically.",
                            isError: true
                        ))
                    DockActionFeedback.fail(searchActionId, label: "Search field not found")
                }
                l2.isLoading = false
                l2.currentTask = nil
            }
        }
    }

    private func makeMessagesSemanticIntentPill(
        fullQuery: String,
        rawScopedQuery: String,
        scopedBundleId: String,
        scopedAppName: String
    ) -> DockPill? {
        guard let intent = messagesScopedSemanticIntent(for: rawScopedQuery),
            let recipientName = intent.recipientName?.trimmingCharacters(in: .whitespacesAndNewlines),
            let messageBody = intent.messageBody?.trimmingCharacters(in: .whitespacesAndNewlines),
            !recipientName.isEmpty,
            !messageBody.isEmpty
        else { return nil }

        let rawUserQuery = rawDockQuery(matching: fullQuery)
        let bodyLabel = messageIntentDisplayText(messageBody, limit: 36)
        let recipientLabel = messageIntentDisplayText(recipientName, limit: 26)

        var pill = DockPill(
            id: "messages-intent-send-\(normalizedDockPillText(rawScopedQuery))",
            name: "Send \"\(bodyLabel)\" to \(recipientLabel)",
            icon: "message.fill",
            accentColorName: "green",
            badge: "Conversation",
            execute: {
                self.executeCrossAppIntent(
                    intent,
                    userMessage: rawUserQuery,
                    unresolvedMessage: "❌ Couldn't resolve that Messages recipient. Try: message send \"hi\" to [name]"
                )
            }
        )
        pill.sourceBundleId = scopedBundleId
        pill.sourceAppName = scopedAppName
        pill.rankingKind = "semanticIntent"
        pill.trackingIdentifier =
            "messages-intent:\(normalizedDockPillText(recipientName)):\(normalizedDockPillText(messageBody))"
        pill.searchTerms = [
            scopedAppName, "messages", "message", "send", recipientName, messageBody, "conversation"
        ]
        return pill
    }

