    private func makeAppWindowSemanticPill(
        rawScopedQuery: String,
        scopedBundleId: String,
        scopedAppName: String,
        isGlobalScope: Bool
    ) -> DockPill? {
        guard !isGlobalScope,
              !scopedBundleId.isEmpty,
              !scopedBundleId.hasPrefix("cli://"),
              !scopedBundleId.hasPrefix("scope://"),
              !scopedAppName.isEmpty
        else { return nil }

        let normalized = rawScopedQuery
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .lowercased()
        guard !normalized.isEmpty else { return nil }

        let minimizeTerms = [
            "minimize", "minimise", "miniaturize", "miniaturise",
            "minimize window", "minimise window", "hide window"
        ]
        guard minimizeTerms.contains(where: normalized.contains) else { return nil }

        var pill = DockPill(
            id: "window-minimize-\(scopedBundleId)",
            name: "Minimize \(scopedAppName)",
            icon: "minus.square",
            accentColorName: "blue",
            badge: "Window",
            execute: {
                self.minimizeAppWindowsWithoutActivation(
                    bundleIdentifier: scopedBundleId,
                    appName: scopedAppName
                )
            }
        )
        pill.sourceBundleId = scopedBundleId
        pill.sourceAppName = scopedAppName
        pill.rankingKind = "semanticIntent"
        pill.trackingIdentifier = "window-minimize:\(scopedBundleId)"
        pill.searchTerms = [
            scopedAppName, "minimize", "minimise", "miniaturize", "window", "hide window"
        ]
        return pill
    }

    private func makeChatGPTNewChatPill(
        scopedQuery: String,
        scopedBundleId: String,
        scopedAppName: String,
        appPath: String?
    ) -> DockPill? {
        guard scopedBundleId == "com.openai.chat" else { return nil }
        let normalized = normalizedDockPillText(scopedQuery)
        guard !normalized.isEmpty else { return nil }
        let isNewChat =
            normalized == "new chat"
            || normalized == "new conversation"
            || normalized == "start chat"
            || normalized == "start new chat"
            || normalized.contains("new chat")
        guard isNewChat else { return nil }

        var pill = DockPill(
            id: "chatgpt-new-chat",
            name: "New Chat",
            icon: "plus.message",
            accentColorName: "green",
            badge: scopedAppName.isEmpty ? "ChatGPT" : scopedAppName,
            execute: {
                self.executeChatGPTNewChat(appPath: appPath)
            }
        )
        pill.sourceBundleId = scopedBundleId
        pill.sourceAppName = scopedAppName.isEmpty ? "ChatGPT" : scopedAppName
        pill.rankingKind = "semanticIntent"
        pill.trackingIdentifier = "chatgpt:new-chat"
        pill.searchTerms = ["chatgpt", "chat gpt", "new chat", "new conversation", "start chat"]
        return pill
    }

    private func executeChatGPTNewChat(appPath: String?) {
        let menuPath = ["File", "New Chat"]
        if let app = NSWorkspace.shared.runningApplications.first(where: {
            $0.bundleIdentifier == "com.openai.chat" && !$0.isTerminated
        }) {
            executeDockMenuAction(
                sourcePID: app.processIdentifier,
                path: menuPath,
                shortcutChar: nil,
                shortcutModifiers: 0
            )
            return
        }

        guard launchApplication(
            bundleIdentifier: "com.openai.chat",
            appName: "ChatGPT",
            path: appPath
        ) else { return }

        Task { @MainActor in
            try? await Task.sleep(nanoseconds: 900_000_000)
            guard let app = NSWorkspace.shared.runningApplications.first(where: {
                $0.bundleIdentifier == "com.openai.chat" && !$0.isTerminated
            }) else { return }
            executeDockMenuAction(
                sourcePID: app.processIdentifier,
                path: menuPath,
                shortcutChar: nil,
                shortcutModifiers: 0
            )
        }
    }

    private func minimizeAppWindowsWithoutActivation(
        bundleIdentifier: String,
        appName: String
    ) {
        guard let app = NSWorkspace.shared.runningApplications.first(where: {
            $0.bundleIdentifier == bundleIdentifier && !$0.isTerminated
        }) else {
            AppToast.show("\(appName) is not running", icon: "exclamationmark.triangle", tint: .orange)
            return
        }

        let axApp = AXUIElementCreateApplication(app.processIdentifier)
        var windowsRef: CFTypeRef?
        var minimizedCount = 0

        if AXUIElementCopyAttributeValue(axApp, kAXWindowsAttribute as CFString, &windowsRef) == .success,
           let windows = windowsRef as? [AXUIElement]
        {
            for window in windows {
                var currentValue: CFTypeRef?
                if AXUIElementCopyAttributeValue(window, kAXMinimizedAttribute as CFString, &currentValue) == .success,
                   (currentValue as? Bool) == true
                {
                    continue
                }

                if AXUIElementSetAttributeValue(window, kAXMinimizedAttribute as CFString, kCFBooleanTrue) == .success {
                    minimizedCount += 1
                    continue
                }

                var minimizeButtonRef: CFTypeRef?
                if AXUIElementCopyAttributeValue(window, kAXMinimizeButtonAttribute as CFString, &minimizeButtonRef) == .success,
                   let minimizeButton = minimizeButtonRef
                {
                    let button = unsafeBitCast(minimizeButton, to: AXUIElement.self)
                    if AXUIElementPerformAction(button, kAXPressAction as CFString) == .success {
                        minimizedCount += 1
                    }
                }
            }
        }

        if minimizedCount > 0 {
            AppToast.show(
                minimizedCount == 1 ? "Minimized \(appName)" : "Minimized \(minimizedCount) \(appName) windows",
                icon: "minus.square",
                tint: .blue.opacity(0.9)
            )
        } else {
            AppToast.show(
                "No visible \(appName) window to minimize",
                icon: "minus.square",
                tint: .secondary
            )
        }

        resetDockStateAfterAppAction()
        isSearchFieldFocused = true
    }

    private func buildPayloadActionPills(query: String) -> [DockPill] {
        let q = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard !q.isEmpty else { return [] }

        let selectedPaths = effectiveSelectedFileURLsForConversation().map(\.path)
        let selectedText = (axContext.selectedText ?? "").trimmingCharacters(
            in: .whitespacesAndNewlines)
        let currentURL = (axContext.currentURL ?? "").trimmingCharacters(
            in: .whitespacesAndNewlines)
        let windowTitle = (axContext.windowTitle ?? frontmost.name).trimmingCharacters(
            in: .whitespacesAndNewlines)
        let clipboardText = (NSPasteboard.general.string(forType: .string) ?? "")
            .trimmingCharacters(in: .whitespacesAndNewlines)

        let hasFiles = !selectedPaths.isEmpty
        let selectedURLs = selectedPaths.map { URL(fileURLWithPath: $0) }
        let hasText = !selectedText.isEmpty
        let hasURL = !currentURL.isEmpty
        let textPayload = hasText ? selectedText : clipboardText
        let noteBody = [hasText ? selectedText : nil, hasURL ? currentURL : nil]
            .compactMap { $0 }
            .joined(separator: "\n\n")
        let reminderText = !textPayload.isEmpty ? textPayload : windowTitle
        let downloadsPath = FileManager.default.homeDirectoryForCurrentUser.appendingPathComponent(
            "Downloads")

        func matches(_ terms: [String]) -> Bool {
            terms.contains { q.contains($0) || $0.contains(q) }
        }

        var pills: [DockPill] = []

        if hasFiles, let transformIntent = transformShareIntent(for: query) {
            let channelLabel: String = {
                switch transformIntent.channelHint {
                case .messages: return "Messages"
                case .mail: return "Mail"
                case .airDrop: return "AirDrop"
                case .picker: return "Share"
                }
            }()
            let recipient = transformIntent.recipientQuery?
                .trimmingCharacters(in: .whitespacesAndNewlines)
            let name = recipient.map { "Summarize + Send to \($0)" } ?? "Summarize + Send"
            var pill = DockPill(
                id: "payload-transform-share-\(normalizedDockPillText(query))",
                name: name,
                icon: transformIntent.channelHint == .mail ? "envelope" : "message",
                accentColorName: transformIntent.channelHint == .mail ? "blue" : "green",
                badge: channelLabel,
                execute: {
                    self.executeTransformShareIntent(transformIntent, userMessage: query)
                }
            )
            pill.rankingKind = "transformShare"
            pill.searchTerms = ["summarize", "summary", "explain", "send", "message", "mail", "file"]
            pill.trackingIdentifier = "transform-share:\(normalizedDockPillText(query))"
            pills.append(pill)
        }

        if hasText || hasURL, matches(["notes", "note", "quick note", "save note", "capture"]) {
            pills.append(
                DockPill(
                    id: "payload-notes",
                    name: "Save to Notes",
                    icon: "note.text",
                    accentColorName: "yellow",
                    badge: hasText ? "Selection" : "URL",
                    execute: {
                        guard self.settings.allowAutomation else {
                            self.l2.chatMessages.append(
                                AIChatMessage(
                                    role: .assistant,
                                    content: "Automation permission is disabled for Notes actions.",
                                    isError: true))
                            return
                        }
                        let title = windowTitle.isEmpty ? "Context Capture" : windowTitle
                        let ok: Bool
                        if !noteBody.isEmpty {
                            ok = AppleAppsAPI.shared.createNote(
                                title: title, body: noteBody, folder: "Context Dock")
                        } else {
                            ok = false
                        }
                        self.l2.chatMessages.append(
                            AIChatMessage(
                                role: .assistant,
                                content: ok ? "Saved to Notes." : "Failed to save to Notes.",
                                isError: !ok
                            ))
                    }
                ))
        }

        if hasText || hasURL || hasFiles,
            matches(["mail", "email", "compose", "new mail", "send email", "share via mail"])
        {
            pills.append(
                DockPill(
                    id: "payload-mail",
                    name: hasFiles ? "Share via Mail" : "Compose Mail",
                    icon: "envelope",
                    accentColorName: "blue",
                    badge: hasFiles ? "Files" : "Selection",
                    execute: {
                        self.executeShareIntent(
                            ShareIntent(
                                rawQuery: hasFiles ? "share via mail" : "compose mail",
                                channelHint: .mail,
                                recipientQuery: nil
                            )
                        )
                    }
                ))
        }

        if !textPayload.isEmpty || hasURL, matches(["reminder", "remind", "todo", "task"]) {
            pills.append(
                DockPill(
                    id: "payload-reminder",
                    name: "Create Reminder",
                    icon: "checklist",
                    accentColorName: "orange",
                    badge: "Selection",
                    execute: {
                        guard self.settings.allowAutomation else {
                            self.l2.chatMessages.append(
                                AIChatMessage(
                                    role: .assistant,
                                    content:
                                        "Automation permission is disabled for Reminders actions.",
                                    isError: true))
                            return
                        }
                        let ok = AppleAppsAPI.shared.createReminder(title: reminderText)
                        self.l2.chatMessages.append(
                            AIChatMessage(
                                role: .assistant,
                                content: ok ? "Reminder created." : "Failed to create reminder.",
                                isError: !ok
                            ))
                    }
                ))
        }

        if hasText || hasURL || hasFiles,
            matches(["message", "messages", "imessage", "new message", "send message"])
        {
            pills.append(
                DockPill(
                    id: "payload-messages",
                    name: "Send via Messages",
                    icon: "message",
                    accentColorName: "green",
                    badge: hasFiles ? "Files" : "Share",
                    execute: {
                        self.executeShareIntent(
                            ShareIntent(
                                rawQuery: hasFiles ? "send via messages" : "send this via messages",
                                channelHint: .messages,
                                recipientQuery: nil
                            )
                        )
                    }
                ))
        }

        if hasFiles, matches(["downloads", "download", "move to downloads", "send to downloads"]) {
            pills.append(
                DockPill(
                    id: "payload-downloads-move",
                    name: "Move to Downloads",
                    icon: "arrow.down.circle",
                    accentColorName: "teal",
                    badge: "\(selectedPaths.count)",
                    execute: {
                        let fm = FileManager.default
                        try? fm.createDirectory(
                            at: downloadsPath, withIntermediateDirectories: true)
                        var moved = 0
                        for source in selectedURLs {
                            let destination = downloadsPath.appendingPathComponent(
                                source.lastPathComponent)
                            let uniqueDestination = self.uniqueMoveDestination(for: destination)
                            do {
                                try fm.moveItem(at: source, to: uniqueDestination)
                                moved += 1
                            } catch {
                                continue
                            }
                        }
                        let ok = moved > 0
                        self.l2.chatMessages.append(
                            AIChatMessage(
                                role: .assistant,
                                content: ok
                                    ? "Moved \(moved) item\(moved == 1 ? "" : "s") to Downloads."
                                    : "Failed to move items to Downloads.",
                                isError: !ok
                            ))
                    }
                ))
            pills.append(
                DockPill(
                    id: "payload-downloads-open",
                    name: "Open Downloads",
                    icon: "folder",
                    accentColorName: "gray",
                    badge: "Downloads",
                    execute: {
                        NSWorkspace.shared.open(downloadsPath)
                    }
                ))
        }

        if hasFiles, matches(["share", "send", "export"]) {
            pills.append(
                DockPill(
                    id: "payload-share-files",
                    name: "Share Selected Files",
                    icon: "square.and.arrow.up",
                    accentColorName: "blue",
                    badge: "\(selectedPaths.count)",
                    execute: {
                        self.executeShareIntent(
                            ShareIntent(
                                rawQuery: "share selected files",
                                channelHint: .picker,
                                recipientQuery: nil
                            )
                        )
                    }
                ))
        }

        return pills
    }

    private func uniqueMoveDestination(for desiredURL: URL) -> URL {
        let fm = FileManager.default
        guard fm.fileExists(atPath: desiredURL.path) else { return desiredURL }

        let directory = desiredURL.deletingLastPathComponent()
        let baseName = desiredURL.deletingPathExtension().lastPathComponent
        let ext = desiredURL.pathExtension

        for index in 2...500 {
            let candidateName = ext.isEmpty ? "\(baseName) \(index)" : "\(baseName) \(index).\(ext)"
            let candidate = directory.appendingPathComponent(candidateName)
            if !fm.fileExists(atPath: candidate.path) {
                return candidate
            }
        }

        return desiredURL
    }

    private func detectCrossAppQuery(_ q: String) -> (NSRunningApplication, String)? {
        guard !q.isEmpty, let delegate = AppDelegate.shared else { return nil }
        let recentApps = delegate.recentApps.filter { !$0.isTerminated }
        let frontPID = delegate.previousFrontmostApp?.processIdentifier ?? 0
        for app in recentApps {
            guard app.processIdentifier != frontPID else { continue }
            let name = (app.localizedName ?? "").lowercased()
            guard !name.isEmpty else { continue }
            // Require a space after the app name so single-word queries like "centre"
            // never accidentally match a recent app whose name starts with "cent" etc.
            if q.hasPrefix(name + " ") {
                let remainder = String(q.dropFirst(name.count + 1))
                return (app, remainder)
            }
            // Also match shortened names: "safari close tab" matches "Safari Technology Preview"
            let firstWord = name.components(separatedBy: " ").first ?? name
            if firstWord.count >= 3, q.hasPrefix(firstWord + " ") {
                let remainder = String(q.dropFirst(firstWord.count + 1))
                return (app, remainder)
            }
        }
        return nil
    }

    private func installedAppMenuTarget(
        for query: String,
        runningOnly: Bool = false,
        includeAppsWithoutMenuSnapshot: Bool = false,
        allowPrefixAlias: Bool = false
    ) -> InstalledAppMenuTarget? {
        let q = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard q.count >= (runningOnly ? 3 : 2) else { return nil }

        let runningBundleIds: Set<String>? = runningOnly
            ? Set(NSWorkspace.shared.runningApplications.compactMap { $0.bundleIdentifier })
            : nil

        var best: (target: InstalledAppMenuTarget, score: Int)?

        func consider(
            appName: String,
            bundleId: String,
            appPath: String,
            baseScore: Int
        ) {
            let normalizedName = appName.lowercased()
                .replacingOccurrences(of: "[^a-z0-9]+", with: " ", options: .regularExpression)
                .trimmingCharacters(in: .whitespacesAndNewlines)
            guard !normalizedName.isEmpty else { return }

            let aliases = Set(dockPillAppAliases(appName: appName, bundleId: bundleId))

            for alias in aliases where alias.count >= 2 {
                guard let extraction = installedAppActionExtraction(
                    query: q,
                    alias: alias,
                    allowPrefixAlias: runningOnly || allowPrefixAlias
                ) else {
                    continue
                }
                let actionQuery = extraction.actionQuery
                let exactFullNameBonus = alias == normalizedName && !extraction.usedPrefixAlias ? 1_200 : 0
                let exactAliasBonus = extraction.usedPrefixAlias ? 0 : 520
                let positionBonus = extraction.aliasAtStart ? 120 : max(20, 95 - (extraction.aliasStartIndex * 18))
                let score =
                    baseScore
                    + positionBonus
                    + (extraction.usedPrefixAlias ? -220 : 0)
                    + exactAliasBonus
                    + (extraction.aliasTokenCount * 80)
                    + exactFullNameBonus
                    + alias.count
                    + min(actionQuery.count, 24)
                    + (actionQuery.isEmpty ? 25 : 0)
                    + (bundleId == "com.apple.Photos" && alias == "photos" ? 600 : 0)

                let target = InstalledAppMenuTarget(
                    appName: appName,
                    bundleId: bundleId,
                    appPath: appPath,
                    actionQuery: actionQuery,
                    matchedAlias: alias
                )
                if best == nil || score > best!.score {
                    best = (target, score)
                }
            }
        }

        if runningOnly {
            let runningApps = runningRegularApps.isEmpty ? currentRegularRunningApps() : runningRegularApps
            for app in runningApps {
                guard let appName = app.localizedName?.trimmingCharacters(in: .whitespacesAndNewlines),
                      !appName.isEmpty,
                      let bundleId = app.bundleIdentifier,
                      !bundleId.isEmpty
                else { continue }
                let appPath =
                    app.bundleURL?.path
                    ?? installedApplicationResult(bundleIdentifier: bundleId)?.subtitle
                    ?? ""
                consider(
                    appName: appName,
                    bundleId: bundleId,
                    appPath: appPath,
                    baseScore: 128
                )
            }

            return best?.target
        }

        for result in allApplications where result.type == .application {
            let appName = result.title.trimmingCharacters(in: .whitespacesAndNewlines)
            let appPath = result.subtitle
            guard !appName.isEmpty, !appPath.isEmpty else { continue }

            let bundleId = Bundle(url: URL(fileURLWithPath: appPath))?.bundleIdentifier ?? ""
            guard !bundleId.isEmpty else { continue }
            if includeAppsWithoutMenuSnapshot,
               implicitContextDockAppScopeBlockedBundleIds.contains(bundleId) {
                continue
            }
            // In context dock mode: skip apps that aren't currently running
            if let runningBundleIds, !runningBundleIds.contains(bundleId) { continue }
            let hasMenuSnapshot = AppMenuCapabilityCache.shared.hasSnapshot(
                bundleIdentifier: bundleId
            )
            let appKey = settings.appKey(forBundleID: bundleId, appName: appName)
            let hasShortcutSurface = appKey.map {
                !appScopeShortcuts(for: $0, placements: [.quickActions, .contextDock, .both]).isEmpty
            } ?? false
            guard includeAppsWithoutMenuSnapshot || runningOnly || hasMenuSnapshot
                    || hasShortcutSurface || bundleId == "com.openai.chat"
            else {
                continue
            }

            consider(appName: appName, bundleId: bundleId, appPath: appPath, baseScore: 112)
        }

        // System app scopes must work even before the app index/menu snapshot cache is warm.
        // Otherwise natural queries like "new notes" stay in global mode and only Apple-menu
        // matches are visible.
        let builtInAppTargets: [(name: String, bundleId: String, path: String)] = [
            ("Safari", "com.apple.Safari", "/Applications/Safari.app"),
            ("Notes", "com.apple.Notes", "/System/Applications/Notes.app"),
            ("Messages", "com.apple.MobileSMS", "/System/Applications/Messages.app"),
            ("Mail", "com.apple.mail", "/System/Applications/Mail.app"),
            ("Calendar", "com.apple.iCal", "/System/Applications/Calendar.app"),
            ("Reminders", "com.apple.reminders", "/System/Applications/Reminders.app"),
            ("Photos", "com.apple.Photos", "/System/Applications/Photos.app"),
            ("Contacts", "com.apple.AddressBook", "/System/Applications/Contacts.app"),
            ("System Settings", "com.apple.systempreferences", "/System/Applications/System Settings.app")
        ]
        for target in builtInAppTargets {
            if let runningBundleIds, !runningBundleIds.contains(target.bundleId) { continue }
            consider(
                appName: target.name,
                bundleId: target.bundleId,
                appPath: target.path,
                baseScore: 108
            )
        }

        return best?.target
    }

    private func cachedScopedAppMenuPills(
        bundleIdentifier: String,
        appName: String,
        appPath: String?,
        query: String = "",
        maxResults: Int = 24,
        allowLiveRefresh: Bool = true
    ) -> [DockPill] {
        guard !bundleIdentifier.isEmpty else { return [] }
        let trimmedQuery = query.trimmingCharacters(in: .whitespacesAndNewlines)
        let effectiveMaxResults = trimmedQuery.isEmpty ? maxResults : max(maxResults, 2_000)
        let runningApp = NSWorkspace.shared.runningApplications.first {
            $0.bundleIdentifier == bundleIdentifier && !$0.isTerminated
        }
        let liveMatches: [AXMenuItem] = {
            guard allowLiveRefresh, let runningApp else { return [] }
            let pid = runningApp.processIdentifier
            var live = AXMenuReader.shared.cachedAllMenuItems(for: pid, maxDepth: 6)
            if live.isEmpty {
                live = AXMenuReader.shared.refreshAllMenuItems(for: pid, maxDepth: 6)
            }
            guard !live.isEmpty else { return [] }
            for index in live.indices {
                live[index].sourcePID = pid
                live[index].sourceAppName = runningApp.localizedName ?? appName
            }
            AppMenuCapabilityCache.shared.store(items: live, for: runningApp)
            return live
        }()
        let persistentMatches = AppMenuCapabilityCache.shared.menuItems(
            bundleIdentifier: bundleIdentifier,
            appName: runningApp?.localizedName ?? appName,
            processIdentifier: runningApp?.processIdentifier ?? 0,
            query: "",
            maxResults: effectiveMaxResults
        )
        let items = {
            var seen = Set<String>()
            var merged: [AXMenuItem] = []
            for item in liveMatches + persistentMatches {
                let key = item.path.joined(separator: " > ").lowercased()
                guard !key.isEmpty, seen.insert(key).inserted else { continue }
                merged.append(item)
            }
            return merged
        }()
        let filteredItems: [AXMenuItem] = {
            let appItems = items.filter { !isAppleMenuItem($0) }
            guard !trimmedQuery.isEmpty else { return appItems }
            return orderedScopedMenuItemsLikeContextDock(
                appItems.filter {
                    cachedScopedMenuItemMatchesQuery($0, query: trimmedQuery)
                },
                filterQuery: trimmedQuery,
                limit: maxResults
            )
        }()

        return filteredItems.map { item in
            let path = item.path
            let shortcutChar = item.shortcutChar
            let shortcutModifiers = item.shortcutModifiers
            let menuAppPath = appPath
            return makeMenuDockPill(
                id: "cached-all-menu-\(bundleIdentifier)-\(path.joined(separator: ">"))",
                item: item,
                sourceBundleId: bundleIdentifier,
                sourceAppName: appName,
                badge: item.shortcutDisplay,
                trackingIdentifier: "cached-menu:\(bundleIdentifier):\(path.joined(separator: " > ").lowercased())",
                searchTerms: item.path + [appName],
                executeLeaf: {
                    executeCachedMenuAction(
                        bundleIdentifier: bundleIdentifier,
                        appName: appName,
                        appPath: menuAppPath,
                        path: path,
                        shortcutChar: shortcutChar,
                        shortcutModifiers: shortcutModifiers
                    )
                }
            )
        }
    }

    private func cachedScopedMenuItemMatchesQuery(_ item: AXMenuItem, query: String) -> Bool {
        let normalizedQuery = normalizedDockPillText(query)
        guard !normalizedQuery.isEmpty else { return true }

        let title = normalizedDockPillText(item.title)
        let pathParts = item.path.map(normalizedDockPillText).filter { !$0.isEmpty }
        let menuContext = pathParts.dropLast().last ?? pathParts.first ?? ""
        let corpora = ([title, menuContext] + pathParts).filter { !$0.isEmpty }

        if corpora.contains(normalizedQuery) { return true }
        if title.hasPrefix(normalizedQuery) || menuContext.hasPrefix(normalizedQuery) { return true }
        if title.contains(normalizedQuery) || menuContext.contains(normalizedQuery) { return true }
        if pathParts.contains(where: { $0.hasPrefix(normalizedQuery) || $0.contains(normalizedQuery) }) {
            return true
        }

        let queryTokens = Set(dockPillTokens(normalizedQuery))
        guard !queryTokens.isEmpty else { return false }
        let titleTokens = Set(dockPillTokens(title))
        let pathTokens = Set(corpora.flatMap(dockPillTokens))
        if !queryTokens.intersection(titleTokens).isEmpty { return true }
        if !queryTokens.intersection(pathTokens).isEmpty { return true }

        for qt in queryTokens where qt.count >= 4 {
            for ct in pathTokens where ct.count >= 4 {
                if pillEditDistance(qt, ct) <= 2 { return true }
            }
        }
        return false
    }

    private func orderedScopedMenuItemsLikeContextDock(
        _ items: [AXMenuItem],
        filterQuery: String,
        limit: Int
    ) -> [AXMenuItem] {
        let normalizedQuery = normalizedDockPillText(filterQuery)
        guard !normalizedQuery.isEmpty else { return Array(items.prefix(limit)) }

        func score(_ item: AXMenuItem) -> Int {
            let title = normalizedDockPillText(item.title)
            let pathParts = item.path.map(normalizedDockPillText).filter { !$0.isEmpty }
            let menuContext = pathParts.dropLast().last ?? pathParts.first ?? ""
            let path = pathParts.joined(separator: " ")
            var score = Int(rankedTextMatchScore(
                query: normalizedQuery,
                primary: title,
                contexts: [menuContext, path] + pathParts
            ) ?? 0)

            let queryTokens = Set(dockPillTokens(normalizedQuery))
            let titleTokens = Set(dockPillTokens(title))
            let contextTokens = Set(dockPillTokens(menuContext))
            let pathTokens = Set(pathParts.flatMap(dockPillTokens))
            score += queryTokens.intersection(titleTokens).count * 120
            score += queryTokens.intersection(contextTokens).count * 96
            score += queryTokens.intersection(pathTokens).count * 54

            if !item.isEnabled { score -= 60 }
            if menuContext == "services" || menuContext == "open with" {
                score -= 180
            }
            score -= min(item.path.count, 12)
            return score
        }

        return Array(
            items.sorted {
                let lhsScore = score($0)
                let rhsScore = score($1)
                if lhsScore != rhsScore { return lhsScore > rhsScore }
                return $0.path.count < $1.path.count
            }
            .prefix(limit)
        )
    }

    private func scopedSpecialAppPills(
        bundleIdentifier: String,
        appName: String,
        query: String
    ) -> [DockPill] {
        switch bundleIdentifier {
        case "com.apple.systempreferences":
            return buildSystemSettingsPills(
                query: query,
                scopedBundleId: bundleIdentifier,
                scopedAppName: appName
            )
        default:
            return []
        }
    }

    // Warm menu cache for a specific app if it's running but not yet snapshotted.
    // After scraping, updates crossAppMenuItems if that app is the current scope target,
    // then triggers a pill rebuild so results appear without another keystroke.
    private func warmMenuCacheIfNeeded(bundleId: String, appName: String) {
        guard !bundleId.isEmpty else { return }
        let staleThreshold: TimeInterval = 7 * 24 * 3600
        let age = AppMenuCapabilityCache.shared.snapshotAge(bundleIdentifier: bundleId) ?? .infinity
        guard age > staleThreshold else { return }  // fresh snapshot exists — skip
        guard warmingMenuBundleIds.insert(bundleId).inserted else { return }
        guard let app = NSWorkspace.shared.runningApplications.first(where: {
            $0.bundleIdentifier == bundleId && !$0.isTerminated
        }) else {
            warmingMenuBundleIds.remove(bundleId)
            return
        }
        Task.detached(priority: .background) {
            // Defer 2 s so the user finishes typing before we start an AX scan.
            // AX API is globally serialized — an immediate scan blocks main-thread AX reads → input freeze.
            try? await Task.sleep(nanoseconds: 2_000_000_000)
            guard !Task.isCancelled else {
                await MainActor.run { self.warmingMenuBundleIds.remove(bundleId) }
                return
            }
            // Skip if another scan already running (avoid concurrent AX contention).
            guard !AXMenuReader.shared.isScanningMenus else {
                await MainActor.run { self.warmingMenuBundleIds.remove(bundleId) }
                return
            }
            let pid = app.processIdentifier
            var items = AXMenuReader.shared.refreshAllMenuItems(for: pid, maxDepth: 6)
            for i in items.indices {
                items[i].sourcePID = pid
                items[i].sourceAppName = app.localizedName ?? appName
            }
            AppMenuCapabilityCache.shared.store(items: items, for: app)
            await MainActor.run {
                if self.l2.targetApp?.bundleId == bundleId {
                    self.crossAppMenuItems = items
                }
                self.warmingMenuBundleIds.remove(bundleId)
                scheduleDockPillRebuild(query: searchState.query, delayNanoseconds: 0, refreshContext: false)
            }
        }
    }

    private func installedAppActionExtraction(
        query q: String,
        alias: String,
        allowPrefixAlias: Bool = false
    )
        -> (actionQuery: String, aliasAtStart: Bool, aliasTokenCount: Int, usedPrefixAlias: Bool, aliasStartIndex: Int)?
    {
        let aliasTokens = alias.split(separator: " ").map(String.init)
        let queryTokens = q.split(separator: " ", omittingEmptySubsequences: true).map(String.init)
        guard !aliasTokens.isEmpty, queryTokens.count >= aliasTokens.count else { return nil }

        let normalizedQueryTokens = queryTokens.map(normalizedDockPillText)
        let exactRange = firstScopedAliasRange(aliasTokens, in: normalizedQueryTokens)
        let prefixRange = allowPrefixAlias
            ? firstScopedAliasRange(aliasTokens, in: normalizedQueryTokens, allowPrefixLastToken: true)
            : nil
        guard let range = exactRange ?? prefixRange else { return nil }

        var remaining = queryTokens
        remaining.removeSubrange(range)
        let actionQuery = trimScopedAppFillerWords(remaining)
        return (
            actionQuery,
            range.lowerBound == 0,
            aliasTokens.count,
            exactRange == nil,
            range.lowerBound
        )
    }

    private func resolveDockScope(for query: String) -> DockScopeResolution {
        let q = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        if shouldUsePureGlobalAppSearch,
           isGlobalContextActive,
           !hasActiveDockContextSelection,
           l2.targetApp == nil,
           let inlineScope = globalInlineAppScope {
            return DockScopeResolution(
                scopedBundleId: inlineScope.bundleId,
                scopedAppName: inlineScope.appName,
                scopedSearchQuery: q,
                isExplicitAppScope: true,
                isGlobalScope: false
            )
        }

        let installedScopeMode = contextDockInstalledAppScopeMatching
        let runningOnly = contextDockRunningOnlyAppMatching && !installedScopeMode
        let runningBundleIds = runningOnly ? runningBundleIdsForContextDock() : []
        let explicitAppTarget: L2ExplicitAppTarget? = (!isGlobalContextActive || q.isEmpty) ? nil : L2AppActionRouter.shared.appScopeTarget(for: q).flatMap { target -> L2ExplicitAppTarget? in
            if installedScopeMode,
               implicitContextDockAppScopeBlockedBundleIds.contains(target.bundleId) {
                return nil
            }
            return (!runningOnly || runningBundleIds.contains(target.bundleId)) ? target : nil
        }
        let installedMenuTarget =
            (isGlobalContextActive && explicitAppTarget == nil && l2.targetApp == nil)
            ? installedAppMenuTarget(
                for: q,
                runningOnly: false,
                // Use permissive matching so natural app-scope queries like
                // "safari new tab" route into Safari menu search.
                includeAppsWithoutMenuSnapshot: true,
                allowPrefixAlias: true
            )
            : nil
        let isExplicitAppScope =
            l2.targetApp != nil || explicitAppTarget != nil || installedMenuTarget != nil
        let isGlobalScope = isGlobalContextActive && !isExplicitAppScope

        if isGlobalScope {
            return DockScopeResolution(
                scopedBundleId: "",
                scopedAppName: "Global Context",
                scopedSearchQuery: q,
                isExplicitAppScope: false,
                isGlobalScope: true
            )
        }

        let scopedBundleId =
            l2.targetApp?.bundleId
            ?? explicitAppTarget?.bundleId
            ?? installedMenuTarget?.bundleId
            ?? (frontmost.bundleID.isEmpty ? axContext.bundleId : frontmost.bundleID)
        let scopedAppName =
            l2.targetApp?.name
            ?? explicitAppTarget?.appName
            ?? installedMenuTarget?.appName
            ?? contextTargetApp()?.localizedName
            ?? axContext.appName
        let scopedSearchQuery: String = {
            if let actionQuery = explicitAppTarget?.actionQuery ?? installedMenuTarget?.actionQuery {
                return actionQuery
            }
            // In explicit app scope (l2.targetApp set), strip trailing "in [appname]" or
            // "[appname]" from the query so "new tab in safari" → filterQ "new tab".
            if let pinnedTarget = l2.targetApp {
                let appLower = pinnedTarget.name.lowercased()
                for suffix in [" in \(appLower)", " \(appLower)"] {
                    if q.hasSuffix(suffix) {
                        return String(q.dropLast(suffix.count))
                            .trimmingCharacters(in: .whitespaces)
                    }
                }
            }
            return q
        }()

        return DockScopeResolution(
            scopedBundleId: scopedBundleId,
            scopedAppName: scopedAppName,
            scopedSearchQuery: scopedSearchQuery,
            isExplicitAppScope: isExplicitAppScope,
            isGlobalScope: false
        )
    }

    private func isPureScopedAppSelection(for query: String) -> Bool {
        let scope = resolveDockScope(for: query)
        return scope.isExplicitAppScope
            && scope.scopedSearchQuery.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
    }

    private var dockScopeDisplayName: String {
        let scope = resolveDockScope(for: searchState.query)
        if scope.isGlobalScope {
            return "Global Context"
        }
        if scope.isExplicitAppScope {
            let scoped = scope.scopedAppName.trimmingCharacters(in: .whitespacesAndNewlines)
            if !scoped.isEmpty {
                return scoped
            }
        }
        return frontmost.name
    }

    private var dockHeaderDisplayName: String {
        let label = dockScopeDisplayName.trimmingCharacters(in: .whitespacesAndNewlines)
        return label.isEmpty ? "Context" : label
    }

    private var dockScopeGhostPrompt: String {
        let label = dockScopeDisplayName.trimmingCharacters(in: .whitespacesAndNewlines)
        let scopeName = label.isEmpty ? "Context" : label
        let bundleId = resolveDockScope(for: searchState.query).scopedBundleId
        let lowerName = scopeName.lowercased()

        let hints: String
        if bundleId == "com.apple.finder" || lowerName == "finder" {
            hints = attachedFinderFolderSearchPath.isEmpty
                ? "launch apps and home folders, menu cmds"
                : "search this folder, open files, menu cmds"
        } else if AXWebReader.shared.isBrowser(bundleId: bundleId) {
            hints = "tabs, page cmds, menu cmds"
        } else if bundleId == "com.microsoft.VSCode" || lowerName.contains("code") {
            hints = "run tasks, commands, menu cmds"
        } else if bundleId == "com.apple.mail" || lowerName.contains("mail") {
            hints = "mailboxes, compose, search, menu cmds"
        } else if bundleId == "com.apple.MobileSMS" || lowerName.contains("message") {
            hints = "send, search chats, menu cmds"
        } else if bundleId.hasPrefix("cli://") {
            hints = "run commands, inspect help"
        } else {
            let scopedAppKey =
                settings.appKey(forBundleID: bundleId, appName: scopeName)
                ?? settings.autoDetectedAppKey
                ?? ""
            let hasShortcuts = !settings.contextDockShortcuts(for: scopedAppKey).isEmpty
                || !settings.shortcuts(for: scopedAppKey).isEmpty
            let hasAdapters = !bundleId.isEmpty && !adapterManager.actions(for: bundleId).isEmpty
            var parts = [String]()
            if hasShortcuts || hasAdapters { parts.append("app actions") }
            parts.append("menu cmds")
            hints = parts.joined(separator: ", ")
        }

        return "\(scopeName) — \(hints)"
    }

    private func finderDisplayPath(_ path: String) -> String {
        path.replacingOccurrences(of: NSHomeDirectory(), with: "~")
    }

    private func scopedDockWorkspaceKey(bundleIdentifier: String, appName: String) -> String {
        if let mapped = settings.appKey(forBundleID: bundleIdentifier, appName: appName),
            !mapped.isEmpty
        {
            return mapped
        }
        let normalized = appName
            .lowercased()
            .replacingOccurrences(of: " ", with: "_")
            .components(
                separatedBy: CharacterSet.alphanumerics.union(CharacterSet(charactersIn: "_"))
                    .inverted
            )
            .joined()
        return normalized.isEmpty ? bundleIdentifier : normalized
    }

    private var currentL2DockSessionKey: String? {
        guard showContextInDock else { return nil }
        let scope = resolveDockScope(for: searchState.query)
        if scope.isGlobalScope {
            return "dock_global"
        }
        let scopedBundleId = scope.scopedBundleId.trimmingCharacters(in: .whitespacesAndNewlines)
        if !scopedBundleId.isEmpty {
            return "dock_app_\(scopedBundleId)"
        }
        let appName = scope.scopedAppName.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !appName.isEmpty else { return nil }
        return "dock_app_\(scopedDockWorkspaceKey(bundleIdentifier: appName, appName: appName))"
    }

    private func syncL2DockSession(force: Bool = false) {
        let newKey = currentL2DockSessionKey
        guard force || newKey != l2.activeDockSessionKey else { return }

        if let previousKey = l2.activeDockSessionKey {
            AppPanelChatStore.shared.save(l2.chatMessages, for: previousKey)
        }

        l2.activeDockSessionKey = newKey
        l2.currentTask?.cancel()
        l2.currentTask = nil
        l2.isLoading = false
        l2.activeRequestID = nil
        l2.handledApprovalIds = []
        l2.contextExtensions = []
        l2.lastAutoRunExtensionID = nil
        l2.chatMessages = newKey.map { AppPanelChatStore.shared.load(for: $0) } ?? []
        updateL2Results([])
    }

    @discardableResult
    func activateInlineDockAppScope(
        bundleIdentifier: String,
        appName: String,
        queryOverride: String? = nil,
        expand: Bool = true,
        preserveGlobalContext: Bool = false
    ) -> Bool {
        guard !bundleIdentifier.isEmpty, !appName.isEmpty else { return false }

        let targetApp = NSWorkspace.shared.runningApplications.first(where: {
            $0.bundleIdentifier == bundleIdentifier && !$0.isTerminated
        })
        let appURL = applicationURL(bundleIdentifier: bundleIdentifier, appName: appName)
        let appPath = appURL?.path ?? ""
        let icon =
            !appPath.isEmpty
            ? NSWorkspace.shared.icon(forFile: appPath)
            : (
                resolvedApplicationIcon(bundleIdentifier: bundleIdentifier, appName: appName)
                    ?? preparedDockIcon(targetApp?.icon)
            )
        let hasLegacyPanelState =
            searchState.activeSmartQueryKey != nil
            || searchState.contextApp != nil
            || searchState.isInSmartMode
            || !searchState.appPanelAllItems.isEmpty
            || !remPanelChatMessages.isEmpty
        let isNewScope = l2.targetApp?.bundleId != bundleIdentifier
        let shouldSyncSession =
            isNewScope
            || searchState.activeSmartQueryKey != nil
            || searchState.contextApp != nil
        // Reset terminal dismissal when switching to a different app scope
        if isNewScope { l2.terminalDismissed = false }
        let normalizedOverride = queryOverride?
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .lowercased() ?? ""
        let isPureScopeSelection =
            normalizedOverride.isEmpty
            || isPureScopedAppSelection(for: normalizedOverride)

        if let previousKey = searchState.activeSmartQueryKey, hasLegacyPanelState {
            AppPanelChatStore.shared.save(remPanelChatMessages, for: previousKey)
        }

        if hasLegacyPanelState {
            remPanelAITask?.cancel()
            remPanelIsProcessing = false
        }

        withAnimation(.spring(response: 0.22, dampingFraction: 0.84)) {
            if hasLegacyPanelState {
                searchState.contextApp = nil
                searchState.activeSmartQueryKey = nil
                searchState.isInSmartMode = false
                searchState.appPanelAllItems = []
                remPanelChatMessages = []
                clearPinnedResults()
            }
            l2.targetApp = ScopedApp(name: appName, bundleId: bundleIdentifier, icon: icon)
            showContextInDock = true
            showMediaLayer = false
            aiMode.isActive = false
            if !preserveGlobalContext {
                globalContextActivation = nil
            }
            searchState.results = []
            searchState.selectedIndex = nil
            if expand { isSearchBarExpanded = true }
            if expand {
                if livePanelMode != .terminal { livePanelVisible = false }
            }
            if let queryOverride {
                searchState.query = queryOverride
            }
        }

        if let targetApp {
            seedCrossAppMenuCache(for: targetApp)
            loadCrossAppMenu(for: targetApp)
        } else {
            crossAppMenuTargetPID = 0
            crossAppMenuNeedsLiveLoad = false
            // App not running — load from persistent disk cache so command palette still works.
            // Actions route via executeCachedMenuAction (no live PID needed).
            let cached = AppMenuCapabilityCache.shared.menuItems(
                bundleIdentifier: bundleIdentifier,
                appName: appName,
                processIdentifier: 0,
                query: "",
                maxResults: 120
            )
            crossAppMenuItems = cached
        }

        if shouldSyncSession {
            syncL2DockSession(force: true)
        }

        // Pre-warm the scoped terminal PTY so it's ready when a command needs to run.
        // Do NOT open or show the terminal here — it only appears after the user approves a command.
        let hasAnyCLI = !terminalPackageManager.packages(
            forContextBundleId: bundleIdentifier, query: "", maxResults: 1).isEmpty
            || adapterManager.actions(for: bundleIdentifier)
                .contains { $0.type == .cliTool && !($0.cliToolCommand ?? "").trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }
        if hasAnyCLI {
            _ = prepareScopedWorkspaceTerminal()
        }

        l2.focusedPillIndex = nil
        isSearchFieldFocused = true
        // SwiftUI may defer focus assignment during the spring animation above.
        // Two deferred dispatches guarantee the field receives first-responder
        // status after the current run-loop turn and the next render pass.
        DispatchQueue.main.async {
            DispatchQueue.main.async {
                self.isSearchFieldFocused = false
                self.isSearchFieldFocused = true
            }
        }
        return true
    }

    private func activateClipboardScope(queryOverride: String = "") {
        if let previousKey = searchState.activeSmartQueryKey {
            AppPanelChatStore.shared.save(remPanelChatMessages, for: previousKey)
        }
        remPanelAITask?.cancel()
        remPanelIsProcessing = false

        let icon = NSImage(systemSymbolName: "doc.on.clipboard", accessibilityDescription: "Clipboard")
        withAnimation(.spring(response: 0.22, dampingFraction: 0.84)) {
            searchState.contextApp = nil
            searchState.activeSmartQueryKey = "clipboard"
            l2.targetApp = ScopedApp(name: "Clipboard", bundleId: "scope://clipboard", icon: icon)
            showContextInDock = true
            showMediaLayer = false
            aiMode.isActive = false
            globalContextActivation = nil
            searchState.isInSmartMode = false
            searchState.results = []
            searchState.selectedIndex = nil
            clearPinnedResults()
            searchState.appPanelAllItems = clipboardSearchResults()
            remPanelChatMessages = []
            searchState.query = queryOverride
            isSearchBarExpanded = true
            focusedClipboardEntryIndex = nil
            livePanelVisible = false
        }
        l2.focusedPillIndex = nil
        isSearchFieldFocused = true
        updateWindowSize()
    }

    private func scopedWorkspaceIdentity() -> (appName: String, bundleId: String, axContext: AXContext)? {
        if let target = l2.targetApp, !target.bundleId.isEmpty {
            return (
                target.name,
                target.bundleId,
                scopedWorkspaceAXContext(appName: target.name, bundleId: target.bundleId)
            )
        }

        if let ctx = searchState.contextApp {
            let bundleIdFromPath = ctx.appPath.isEmpty ? nil : Bundle(path: ctx.appPath)?.bundleIdentifier
            let bundleIdFromRunningApp = NSWorkspace.shared.runningApplications.first(where: {
                !$0.isTerminated && $0.localizedName == ctx.name
            })?.bundleIdentifier
            let resolvedBundleId = bundleIdFromPath ?? bundleIdFromRunningApp ?? ""
            if !resolvedBundleId.isEmpty {
                return (
                    ctx.name,
                    resolvedBundleId,
                    scopedWorkspaceAXContext(appName: ctx.name, bundleId: resolvedBundleId)
                )
            }
        }

        let meta = smartQueryMeta
        if !meta.appPath.isEmpty, let bundleId = Bundle(path: meta.appPath)?.bundleIdentifier {
            return (
                searchState.contextApp?.name ?? meta.label,
                bundleId,
                scopedWorkspaceAXContext(
                    appName: searchState.contextApp?.name ?? meta.label,
                    bundleId: bundleId
                )
            )
        }

        let fallbackBundleId =
            frontmost.bundleID.isEmpty ? axContext.bundleId : frontmost.bundleID
        let fallbackAppName =
            searchState.contextApp?.name
            ?? (frontmost.name.isEmpty ? axContext.appName : frontmost.name)
        guard !fallbackBundleId.isEmpty, !fallbackAppName.isEmpty else { return nil }
        return (
            fallbackAppName,
            fallbackBundleId,
            scopedWorkspaceAXContext(appName: fallbackAppName, bundleId: fallbackBundleId)
        )
    }

    private func scopedWorkspaceAXContext(appName: String, bundleId: String) -> AXContext {
        if axContext.bundleId == bundleId {
            return effectiveAXContextForConversation()
        }

        let runningApp = NSWorkspace.shared.runningApplications.first(where: {
            $0.bundleIdentifier == bundleId && !$0.isTerminated
        })

        return AXContext(
            appName: appName,
            bundleId: bundleId,
            pid: runningApp?.processIdentifier ?? 0,
            selectedText: nil,
            currentURL: nil,
            windowTitle: nil,
            focusedElementRole: nil,
            selectedFilePaths: effectiveSelectedFileURLsForConversation().map(\.path),
            menuItems: []
        )
    }

    private func prepareScopedWorkspaceTerminal() -> String {
        let consoleKey = activeConsoleKey
        let terminal = panelTerminal(for: consoleKey)
        TerminalAIBridge.shared.terminalController = terminal
        panelShowConsoleMap[consoleKey] = true
        return consoleKey
    }

    private func currentDateTimeContextBlock() -> String {
        let now = Date()
        let formatter = DateFormatter()
        formatter.dateStyle = .full
        formatter.timeStyle = .medium
        let localDateTime = formatter.string(from: now)
        let isoFormatter = ISO8601DateFormatter()
        isoFormatter.timeZone = .current
        let isoDateTime = isoFormatter.string(from: now)
        let timeZoneName = TimeZone.current.identifier

        return """
            CURRENT DATE & TIME:
            - Local: \(localDateTime)
            - ISO 8601: \(isoDateTime)
            - Time Zone: \(timeZoneName)
            Use this exact date/time for relative time references like today, yesterday, tomorrow, recent, and this week.
            """
    }

    private func canonicalExistingURLs(_ urls: [URL]) -> [URL] {
        var seen: Set<String> = []
        return urls.filter { url in
            let path = url.standardizedFileURL.path
            guard !path.isEmpty else { return false }
            guard FileManager.default.fileExists(atPath: path) else { return false }
            return seen.insert(path).inserted
        }
    }

    private func clearFinderFollowUpTargets() {
        finderFollowUpTargetPaths = []
        finderFollowUpFolderPath = ""
        finderFollowUpSourceQuery = ""
    }

    private func rememberFinderFollowUpTargets(
        _ urls: [URL],
        folderPath: String,
        sourceQuery: String = ""
    ) {
        let canonical = canonicalExistingURLs(urls)
        guard !canonical.isEmpty else { return }
        finderFollowUpTargetPaths = canonical.map(\.path)
        finderFollowUpFolderPath = folderPath
        finderFollowUpSourceQuery = sourceQuery
    }

    private func finderFollowUpTargetURLs(for folderPath: String? = nil) -> [URL] {
        guard !finderFollowUpTargetPaths.isEmpty else { return [] }
        if let folderPath,
            !folderPath.isEmpty,
            !finderFollowUpFolderPath.isEmpty,
            finderFollowUpFolderPath != folderPath
        {
            return []
        }
        return canonicalExistingURLs(finderFollowUpTargetPaths.map { URL(fileURLWithPath: $0) })
    }

    private func queryNeedsFinderFollowUpTargets(_ query: String) -> Bool {
        let normalized = normalizedDockPillText(query)
        guard !normalized.isEmpty else { return false }

        let tokens = Set(dockPillTokens(normalized))
        let pronounTerms: Set<String> = [
            "it", "them", "this", "that", "these", "those", "same", "again",
            "selected", "selection", "current"
        ]
        if !tokens.isDisjoint(with: pronounTerms) { return true }

        let actionTerms = [
            "share", "send", "mail", "email", "message", "open", "convert", "export",
            "save", "move", "copy", "duplicate", "rename", "compress", "zip", "print",
            "preview", "reveal", "quick look", "attach", "upload", "delete", "trash",
            "remove", "merge", "split", "extract", "encode", "transcode"
        ]
        let hasActionIntent = actionTerms.contains { normalized.contains($0) }
        let hasExplicitTarget = !finderTargetReferenceQuery(from: normalized).isEmpty
        return hasActionIntent && !hasExplicitTarget
    }

    private func effectiveFinderSelectedFileURLs(for query: String, currentFolderPath: String)
        -> [URL]
    {
        let liveSelection = canonicalExistingURLs(
            axContext.selectedFilePaths.map { URL(fileURLWithPath: $0) }
        )
        if !liveSelection.isEmpty {
            rememberFinderFollowUpTargets(
                liveSelection,
                folderPath: currentFolderPath,
                sourceQuery: query
            )
            return liveSelection
        }

        if case .filesSelected(let urls) = currentContext {
            let contextURLs = canonicalExistingURLs(urls)
            if !contextURLs.isEmpty {
                let normalizedCurrentFolderPath =
                    URL(fileURLWithPath: currentFolderPath).standardizedFileURL.path
                let isStaleAttachedFolderContext =
                    contextURLs.count == 1
                    && contextURLs[0].hasDirectoryPath
                    && contextURLs[0].standardizedFileURL.path == attachedFinderFolderSearchPath
                    && attachedFinderFolderSearchPath != normalizedCurrentFolderPath
                guard !isStaleAttachedFolderContext else { return [] }

                rememberFinderFollowUpTargets(
                    contextURLs,
                    folderPath: currentFolderPath,
                    sourceQuery: query
                )
                return contextURLs
            }
        }

        guard queryNeedsFinderFollowUpTargets(query) else { return [] }
        return finderFollowUpTargetURLs(for: currentFolderPath)
    }

    private func effectiveSelectedFileURLsForConversation() -> [URL] {
        let liveSelection = canonicalExistingURLs(
            axContext.selectedFilePaths.map { URL(fileURLWithPath: $0) }
        )
        if !liveSelection.isEmpty {
            return isDismissedFinderSelection(liveSelection) ? [] : liveSelection
        }

        if case .filesSelected(let urls) = currentContext {
            let contextURLs = canonicalExistingURLs(urls)
            if !contextURLs.isEmpty {
                return isDismissedFinderSelection(contextURLs) ? [] : contextURLs
            }
        }

        guard frontmost.bundleID == "com.apple.finder"
            || contextTargetApp()?.bundleIdentifier == "com.apple.finder"
        else { return [] }

        if isFinderFolderSearchAttached(currentFolderPath: currentFinderFolderPath()) {
            let folderURL = URL(fileURLWithPath: attachedFinderFolderSearchPath)
            if FileManager.default.fileExists(atPath: folderURL.path) {
                return [folderURL]
            }
        }

        return finderFollowUpTargetURLs(for: currentFinderFolderPath())
    }

    private func effectiveAXContextForConversation() -> AXContext {
        var context = axContext
        if context.selectedFilePaths.isEmpty {
            context.selectedFilePaths = effectiveSelectedFileURLsForConversation().map(\.path)
        }
        if (context.currentURL ?? "").trimmingCharacters(in: .whitespacesAndNewlines).isEmpty,
           case .url(let urlString) = currentContext {
            context.currentURL = urlString.trimmingCharacters(in: .whitespacesAndNewlines)
        }
        if (context.selectedText ?? "").trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            if case .textSelected(let text) = currentContext {
                let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
                if !trimmed.isEmpty { context.selectedText = trimmed }
            } else if let frozenSelectionText {
                let trimmed = frozenSelectionText.trimmingCharacters(in: .whitespacesAndNewlines)
                if !trimmed.isEmpty { context.selectedText = trimmed }
            }
        }
        return context
    }

    private func finderTargetReferenceQuery(from query: String) -> String {
        let normalized = normalizedDockPillText(query)
        guard !normalized.isEmpty else { return "" }

        let ignoredWords: Set<String> = [
            "convert", "conversion", "export", "save", "open", "move", "copy", "duplicate",
            "share", "send", "attach", "upload", "rename", "delete", "trash", "remove",
            "reveal", "preview", "print", "merge", "split", "extract", "encode", "compress",
            "zip", "unzip", "transform", "change", "make", "create", "render", "transcode",
            "format", "into", "from", "with", "using", "via", "to", "as", "file", "files",
            "folder", "folders", "document", "documents", "image", "images", "photo", "photos",
            "picture", "pictures", "pdf", "png", "jpg", "jpeg", "webp", "heic", "gif", "tiff",
            "bmp", "selected", "selection", "current", "this", "that", "these", "those",
            "please", "here"
        ]

        let remaining = dockPillTokens(normalized).filter {
            !$0.isEmpty && !ignoredWords.contains($0) && $0.count >= 2
        }
        return remaining.joined(separator: " ")
    }

    private func finderMetadataSummary(for url: URL) -> String {
        let resourceValues =
            (try? url.resourceValues(
                forKeys: [
                    .isDirectoryKey, .localizedTypeDescriptionKey, .contentModificationDateKey,
                    .fileSizeKey,
                ])) ?? URLResourceValues()
        let isDirectory = resourceValues.isDirectory ?? url.hasDirectoryPath
        let typeLabel =
            resourceValues.localizedTypeDescription
            ?? (isDirectory ? "Folder" : (url.pathExtension.isEmpty ? "File" : "\(url.pathExtension.uppercased()) file"))
        let sizeLabel: String = {
            guard !isDirectory else { return "folder" }
            let byteCount = Int64(resourceValues.fileSize ?? 0)
            guard byteCount > 0 else { return "size unknown" }
            return ByteCountFormatter.string(fromByteCount: byteCount, countStyle: .file)
        }()
        let modifiedLabel: String = {
            guard let modified = resourceValues.contentModificationDate else { return "modified unknown" }
            let formatter = RelativeDateTimeFormatter()
            formatter.unitsStyle = .full
            return "modified " + formatter.localizedString(for: modified, relativeTo: Date())
        }()
        return "\(typeLabel) | \(sizeLabel) | \(modifiedLabel) | \(finderDisplayPath(url.path))"
    }

    private func buildFinderFileCatalogBlock(
        currentFolderPath: String,
        selectedFilePaths: [String]
    ) -> String {
        let folderURL = URL(fileURLWithPath: currentFolderPath)
        let fileManager = FileManager.default

        var orderedURLs = selectedFilePaths.map { URL(fileURLWithPath: $0) }
        if let currentItems = try? fileManager.contentsOfDirectory(
            at: folderURL,
            includingPropertiesForKeys: [.isDirectoryKey, .contentModificationDateKey],
            options: [.skipsHiddenFiles, .skipsPackageDescendants]
        ) {
            let sortedItems = currentItems.sorted { lhs, rhs in
                let lhsValues =
                    (try? lhs.resourceValues(forKeys: [.isDirectoryKey, .contentModificationDateKey]))
                    ?? URLResourceValues()
                let rhsValues =
                    (try? rhs.resourceValues(forKeys: [.isDirectoryKey, .contentModificationDateKey]))
                    ?? URLResourceValues()
                let lhsDirectory = lhsValues.isDirectory ?? lhs.hasDirectoryPath
                let rhsDirectory = rhsValues.isDirectory ?? rhs.hasDirectoryPath
                if lhsDirectory != rhsDirectory { return lhsDirectory && !rhsDirectory }
                let lhsDate = lhsValues.contentModificationDate ?? .distantPast
                let rhsDate = rhsValues.contentModificationDate ?? .distantPast
                if lhsDate != rhsDate { return lhsDate > rhsDate }
                return lhs.lastPathComponent.localizedCaseInsensitiveCompare(rhs.lastPathComponent)
                    == .orderedAscending
            }
            orderedURLs.append(contentsOf: sortedItems)
        }

        var seen: Set<String> = []
        let uniqueURLs = orderedURLs.filter { seen.insert($0.path).inserted }
        guard !uniqueURLs.isEmpty else { return "" }

        let limit = min(uniqueURLs.count, 40)
        let lines = uniqueURLs.prefix(limit).map { url in
            "- \(url.lastPathComponent) | \(finderMetadataSummary(for: url))"
        }

        var block = "\nCURRENT FOLDER FILE CATALOG:\n" + lines.joined(separator: "\n")
        if uniqueURLs.count > limit {
            block += "\n- ... and \(uniqueURLs.count - limit) more items in this folder"
        }
        return block
    }

    private func buildFinderTargetSemanticMatches(
        for query: String,
        currentFolderPath: String,
        spotlightEnabled: Bool
    ) async -> [FinderSemanticMatch] {
        let targetQuery = finderTargetReferenceQuery(from: query)
        guard !targetQuery.isEmpty, targetQuery != normalizedDockPillText(query) else { return [] }

        let fastMatches = await buildFastFinderSemanticMatches(
            query: targetQuery,
            currentFolderPath: currentFolderPath
        )
        let spotlightMatches =
            spotlightEnabled && targetQuery.count >= 3
            ? runFinderSpotlightSearch(
                query: targetQuery,
                currentFolderPath: currentFolderPath,
                limit: 8
            )
            : []
        return mergeFinderSemanticMatches(fastMatches, with: spotlightMatches)
    }

    private func buildFinderResolvedTargetContext(
        query: String,
        selectedFilePaths: [String],
        retrievedMatches: [FinderSemanticMatch]
    ) -> (targetURLs: [URL], summaryBlock: String, contentBlock: String) {
        let selectedURLs = selectedFilePaths.map { URL(fileURLWithPath: $0) }
        let candidateURLs: [URL] =
            !selectedURLs.isEmpty
            ? Array(selectedURLs.prefix(5))
            : Array(retrievedMatches.prefix(5).map { URL(fileURLWithPath: $0.path) })

        guard !candidateURLs.isEmpty else {
            return ([], "", "")
        }

        let summaryLines = candidateURLs.map { url in
            "- \(url.lastPathComponent) | \(finderMetadataSummary(for: url))"
        }
        let summaryBlock =
            "\nRESOLVED TARGET FILES FOR THIS QUERY:\n" + summaryLines.joined(separator: "\n")

        let analyzableURLs = candidateURLs.filter {
            let values =
                (try? $0.resourceValues(forKeys: [.isDirectoryKey])) ?? URLResourceValues()
            return !(values.isDirectory ?? $0.hasDirectoryPath)
        }
        let analyzedFiles = ContextDetector.shared.analyzeFiles(Array(analyzableURLs.prefix(2)))
        var contentBlock = ""
        for file in analyzedFiles {
            guard let content = file.content,
                !content.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            else { continue }
            contentBlock +=
                "\n\n### Resolved target content from \(file.url.lastPathComponent):\n```\n\(String(content.prefix(2500)))\n```"
        }

        return (candidateURLs, summaryBlock, contentBlock)
    }

    private func finderSemanticCategoryTokens(_ category: FinderFileCategory) -> Set<String> {
        switch category {
        case .pdf:
            return ["pdf", "pdfs"]
        case .image:
            return ["image", "images", "photo", "photos", "picture", "pictures", "screenshot", "screenshots"]
        case .video:
            return ["video", "videos", "movie", "movies"]
        case .audio:
            return ["audio", "music", "song", "songs", "mp3"]
        case .archive:
            return ["archive", "archives", "zip", "zips", "dmg", "dmgs", "torrent", "torrents"]
        case .app:
            return ["app", "apps", "application", "applications"]
        case .folder:
            return ["folder", "folders", "directory", "directories"]
        case .document:
            return ["document", "documents", "doc", "docs", "text"]
        }
    }

    private func finderExplicitLocationPath(in normalizedQuery: String) -> (path: String, tokens: Set<String>)? {
        let home = FileManager.default.homeDirectoryForCurrentUser
        let locations: [(names: [String], path: URL, tokens: [String])] = [
            (["downloads", "download folder", "download directory"], home.appendingPathComponent("Downloads"), ["downloads", "download"]),
            (["desktop"], home.appendingPathComponent("Desktop"), ["desktop"]),
            (["documents", "documents folder", "docs folder"], home.appendingPathComponent("Documents"), ["documents", "docs"]),
            (["movies", "movies folder", "videos folder"], home.appendingPathComponent("Movies"), ["movies"]),
            (["pictures", "pictures folder", "photos folder"], home.appendingPathComponent("Pictures"), ["pictures", "photos"]),
            (["music", "music folder"], home.appendingPathComponent("Music"), ["music"]),
            (["home", "home folder"], home, ["home"])
        ]

        for location in locations {
            let matched = location.names.contains { name in
                normalizedQuery == name
                    || normalizedQuery.contains(" in \(name)")
                    || normalizedQuery.contains(" inside \(name)")
                    || normalizedQuery.contains(" under \(name)")
                    || normalizedQuery.contains(" from \(name)")
                    || normalizedQuery.contains(" at \(name)")
            }
            if matched {
                return (location.path.standardizedFileURL.path, Set(location.tokens + ["in", "inside", "under", "from"]))
            }
        }

        if normalizedQuery.contains("here") || normalizedQuery.contains("current folder") || normalizedQuery.contains("this folder") {
            return nil
        }
        return nil
    }

    private func finderExplicitSizeBounds(in normalizedQuery: String) -> (min: Int64?, max: Int64?, tokens: Set<String>) {
        var consumed: Set<String> = []

        func bytes(_ value: Double, _ unit: String) -> Int64 {
            let normalizedUnit = unit.lowercased()
            let multiplier: Double
            if normalizedUnit.hasPrefix("g") {
                multiplier = 1_073_741_824
            } else if normalizedUnit.hasPrefix("k") {
                multiplier = 1_024
            } else {
                multiplier = 1_048_576
            }
            return Int64(value * multiplier)
        }

        let patterns: [(pattern: String, isMin: Bool)] = [
            (#"(?:over|above|larger than|bigger than|greater than|more than)\s+([0-9]+(?:\.[0-9]+)?)\s*(kb|k|mb|m|gb|g)"#, true),
            (#"(?:under|below|smaller than|less than)\s+([0-9]+(?:\.[0-9]+)?)\s*(kb|k|mb|m|gb|g)"#, false),
            (#"([0-9]+(?:\.[0-9]+)?)\s*(kb|k|mb|m|gb|g)\s*(?:or )?(?:larger|bigger|plus|\+)"#, true),
            (#"([0-9]+(?:\.[0-9]+)?)\s*(kb|k|mb|m|gb|g)\s*(?:or )?(?:smaller|less|under)"#, false)
        ]

        var minBytes: Int64?
        var maxBytes: Int64?
        for item in patterns {
            guard let regex = try? NSRegularExpression(pattern: item.pattern, options: [.caseInsensitive]) else { continue }
            let range = NSRange(normalizedQuery.startIndex..<normalizedQuery.endIndex, in: normalizedQuery)
            guard let match = regex.firstMatch(in: normalizedQuery, range: range),
                  match.numberOfRanges >= 3,
                  let valueRange = Range(match.range(at: 1), in: normalizedQuery),
                  let unitRange = Range(match.range(at: 2), in: normalizedQuery),
                  let value = Double(normalizedQuery[valueRange]) else { continue }
            let size = bytes(value, String(normalizedQuery[unitRange]))
            if item.isMin {
                minBytes = max(minBytes ?? 0, size)
            } else {
                maxBytes = min(maxBytes ?? Int64.max, size)
            }
            if let fullRange = Range(match.range(at: 0), in: normalizedQuery) {
                consumed.formUnion(dockPillTokens(String(normalizedQuery[fullRange])))
            }
        }

        if minBytes == nil {
            let tokens = Set(dockPillTokens(normalizedQuery))
            if !tokens.isDisjoint(with: ["huge", "largest"]) {
                minBytes = 500 * 1_024 * 1_024
            } else if !tokens.isDisjoint(with: ["large", "larger", "big"]) {
                minBytes = 100 * 1_024 * 1_024
            }
        }
        if maxBytes == nil {
            let tokens = Set(dockPillTokens(normalizedQuery))
            if !tokens.isDisjoint(with: ["small", "tiny", "smallest"]) {
                maxBytes = 1 * 1_024 * 1_024
            }
        }

        return (minBytes, maxBytes, consumed)
    }

    private func finderSemanticProfile(for query: String) -> FinderSemanticQueryProfile {
        let normalized = normalizedDockPillText(query)
        let tokens = dockPillTokens(normalized)
        let category = FinderFileCategory.detect(in: normalized)
        let explicitLocation = finderExplicitLocationPath(in: normalized)
        let explicitSize = finderExplicitSizeBounds(in: normalized)
        let wantsFoldersOnly =
            category == .folder || tokens.contains("folder") || tokens.contains("folders")
                || tokens.contains("directory") || tokens.contains("directories")
        let wantsFilesOnly =
            !wantsFoldersOnly
                && (tokens.contains("file") || tokens.contains("files")
                    || tokens.contains("item") || tokens.contains("items"))
        let wantsRecent =
            tokens.contains("recent") || tokens.contains("latest") || tokens.contains("newest")
        let wantsToday = tokens.contains("today") || tokens.contains("tonight")
        let wantsYesterday = tokens.contains("yesterday")
        let wantsThisWeek = tokens.contains("week") || normalized.contains("this week")
        let wantsLargeFiles =
            tokens.contains("large") || tokens.contains("larger") || tokens.contains("big")
                || tokens.contains("huge") || tokens.contains("largest")
        let wantsSmallFiles =
            tokens.contains("small") || tokens.contains("tiny") || tokens.contains("smallest")

        var semanticTokens: Set<String> = [
            "today", "tonight", "yesterday", "recent", "latest", "newest",
            "this", "week", "here", "current", "folder", "folders", "directory", "directories",
            "file", "files", "item", "items", "modified", "updated", "edited", "changed",
            "large", "larger", "big", "huge", "largest", "small", "tiny", "smallest",
            "any", "all", "show", "list", "find", "search", "display", "check",
            "there", "is", "are", "do", "have", "got", "called", "named", "titled",
            "name", "names", "claled", "with", "matching", "match", "contains",
            "contain", "please", "me", "my", "a", "an", "the", "of", "to", "for"
        ]
        if let category {
            semanticTokens.formUnion(finderSemanticCategoryTokens(category))
        }
        if let explicitLocation {
            semanticTokens.formUnion(explicitLocation.tokens)
        }
        semanticTokens.formUnion(explicitSize.tokens)

        let residualQuery = tokens.filter { !semanticTokens.contains($0) }.joined(separator: " ")
        return FinderSemanticQueryProfile(
            originalQuery: normalized,
            residualQuery: residualQuery,
            category: category,
            wantsFoldersOnly: wantsFoldersOnly,
            wantsFilesOnly: wantsFilesOnly,
            wantsRecent: wantsRecent,
            wantsToday: wantsToday,
            wantsYesterday: wantsYesterday,
            wantsThisWeek: wantsThisWeek,
            wantsLargeFiles: wantsLargeFiles,
            wantsSmallFiles: wantsSmallFiles,
            explicitLocationPath: explicitLocation?.path,
            minSizeBytes: explicitSize.min,
            maxSizeBytes: explicitSize.max
        )
    }

    private func finderSemanticDateInterval(for profile: FinderSemanticQueryProfile, now: Date)
        -> DateInterval?
    {
        let calendar = Calendar.current
        if profile.wantsToday {
            let start = calendar.startOfDay(for: now)
            guard let end = calendar.date(byAdding: .day, value: 1, to: start) else { return nil }
            return DateInterval(start: start, end: end)
        }
        if profile.wantsYesterday {
            let todayStart = calendar.startOfDay(for: now)
            guard
                let start = calendar.date(byAdding: .day, value: -1, to: todayStart)
            else { return nil }
            return DateInterval(start: start, end: todayStart)
        }
        if profile.wantsThisWeek {
            let components = calendar.dateComponents([.yearForWeekOfYear, .weekOfYear], from: now)
            guard
                let start = calendar.date(from: components),
                let end = calendar.date(byAdding: .day, value: 7, to: start)
            else { return nil }
            return DateInterval(start: start, end: end)
        }
        return nil
    }

    private func finderAdvancedSearchRoot(for profile: FinderSemanticQueryProfile, currentFolderPath: String) -> String {
        if let explicitLocationPath = profile.explicitLocationPath {
            return URL(fileURLWithPath: explicitLocationPath).standardizedFileURL.path
        }
        if !attachedFinderFolderSearchPath.isEmpty {
            return URL(fileURLWithPath: attachedFinderFolderSearchPath).standardizedFileURL.path
        }
        return URL(fileURLWithPath: currentFolderPath).standardizedFileURL.path
    }

    private func buildAdvancedFinderDataMatches(
        profile: FinderSemanticQueryProfile,
        currentFolderPath: String,
        limit: Int = 24
    ) -> [FinderSemanticMatch] {
        guard profile.hasAdvancedDataConstraint else { return [] }

        let rootPath = finderAdvancedSearchRoot(for: profile, currentFolderPath: currentFolderPath)
        let now = Date()
        let dateInterval = finderSemanticDateInterval(for: profile, now: now)
        let query = AdvancedFileSearchQuery(
            rootPath: rootPath,
            residualQuery: profile.residualQuery,
            allowedExtensions: profile.category?.fileExtensions,
            includeDirectories: profile.wantsFoldersOnly || profile.category == .folder,
            filesOnly: profile.wantsFilesOnly || (profile.category != nil && profile.category != .folder)
                || profile.wantsLargeFiles || profile.wantsSmallFiles,
            minSizeBytes: profile.minSizeBytes,
            maxSizeBytes: profile.maxSizeBytes,
            modifiedAfter: dateInterval?.start,
            modifiedBefore: dateInterval?.end,
            limit: limit
        )

        let indexedMatches = fileIndexManager.advancedSearch(query).filter { file in
            if profile.wantsFoldersOnly || profile.category == .folder {
                return file.isDirectory
            }
            return true
        }
        if !indexedMatches.isEmpty {
            return indexedMatches.map { file in
                let source = profile.explicitLocationPath == nil ? "Current Folder" : URL(fileURLWithPath: rootPath).lastPathComponent
                let sizeLabel = file.size > 0
                    ? ByteCountFormatter.string(fromByteCount: file.size, countStyle: .file)
                    : "size unknown"
                return FinderSemanticMatch(
                    path: file.path,
                    title: file.name,
                    subtitle: "\(source) • \(sizeLabel) • \(finderDisplayPath(file.path))",
                    isDirectory: file.isDirectory,
                    score: 900 + min(500, Double(file.size) / 1_048_576.0),
                    source: source,
                    searchTerms: [
                        file.name, file.path, source, "finder", "spotlight", "advanced query",
                        profile.originalQuery
                    ],
                    sizeBytes: file.size
                )
            }
        }

        return buildAdvancedFinderDirectoryFallbackMatches(
            profile: profile,
            rootPath: rootPath,
            limit: limit
        )
    }

    private func buildAdvancedFinderDirectoryFallbackMatches(
        profile: FinderSemanticQueryProfile,
        rootPath: String,
        limit: Int
    ) -> [FinderSemanticMatch] {
        let rootURL = URL(fileURLWithPath: rootPath)
        let keys: [URLResourceKey] = [
            .isDirectoryKey, .contentModificationDateKey, .fileSizeKey
        ]
        guard let enumerator = FileManager.default.enumerator(
            at: rootURL,
            includingPropertiesForKeys: keys,
            options: [.skipsHiddenFiles, .skipsPackageDescendants]
        ) else { return [] }

        let now = Date()
        var matches: [FinderSemanticMatch] = []
        for case let url as URL in enumerator {
            guard matches.count < max(limit * 4, 80) else { break }
            let values = (try? url.resourceValues(forKeys: Set(keys))) ?? URLResourceValues()
            guard let semanticBoost = finderSemanticConstraintBoost(
                for: url,
                profile: profile,
                resourceValues: values,
                now: now
            ) else { continue }
            if !profile.residualQuery.isEmpty,
               finderSemanticScore(query: profile.residualQuery, for: url) == nil {
                continue
            }
            let isDirectory = values.isDirectory ?? url.hasDirectoryPath
            let size = Int64(values.fileSize ?? 0)
            let sizeLabel = size > 0
                ? ByteCountFormatter.string(fromByteCount: size, countStyle: .file)
                : (isDirectory ? "folder" : "size unknown")
            let source = URL(fileURLWithPath: rootPath).lastPathComponent
            matches.append(
                FinderSemanticMatch(
                    path: url.standardizedFileURL.path,
                    title: url.lastPathComponent,
                    subtitle: "\(source) • \(sizeLabel) • \(finderDisplayPath(url.path))",
                    isDirectory: isDirectory,
                    score: semanticBoost + min(400, Double(size) / 1_048_576.0),
                    source: source,
                    searchTerms: [url.lastPathComponent, url.path, source, "finder", "advanced query"],
                    sizeBytes: size
                )
            )
        }

        return matches
            .sorted {
                if $0.score != $1.score { return $0.score > $1.score }
                return ($0.sizeBytes ?? 0) > ($1.sizeBytes ?? 0)
            }
            .prefix(limit)
            .map { $0 }
    }

    private func finderSemanticConstraintBoost(
        for url: URL,
        profile: FinderSemanticQueryProfile,
        resourceValues: URLResourceValues,
        now: Date
    ) -> Double? {
        let isDirectory = resourceValues.isDirectory ?? url.hasDirectoryPath

        if profile.wantsFoldersOnly && !isDirectory { return nil }
        if profile.wantsFilesOnly && isDirectory { return nil }
        if let category = profile.category {
            if category == .folder {
                guard isDirectory else { return nil }
            } else if !category.matches(url) {
                return nil
            }
        }

        var score = 0.0
        var matchedAnyConstraint = false

        if profile.wantsFoldersOnly && isDirectory {
            matchedAnyConstraint = true
            score += 140
        }
        if profile.wantsFilesOnly && !isDirectory {
            matchedAnyConstraint = true
            score += 110
        }
        if let category = profile.category {
            matchedAnyConstraint = true
            score += category == .folder ? 150 : 125
        }

        if let interval = finderSemanticDateInterval(for: profile, now: now) {
            guard let modified = resourceValues.contentModificationDate,
                interval.contains(modified)
            else { return nil }
            matchedAnyConstraint = true
            score += profile.wantsToday ? 240 : 220
            let ageHours = max(0, now.timeIntervalSince(modified) / 3600)
            score += max(0, 36 - min(36, ageHours))
        } else if profile.wantsRecent {
            guard let modified = resourceValues.contentModificationDate else { return nil }
            matchedAnyConstraint = true
            let ageHours = max(0, now.timeIntervalSince(modified) / 3600)
            score += max(80, 240 - min(180, ageHours * 4))
        }

        let size = Int64(resourceValues.fileSize ?? 0)
        if profile.wantsLargeFiles {
            guard !isDirectory, size >= 5 * 1_024 * 1_024 else { return nil }
            matchedAnyConstraint = true
            score += 150 + min(180, Double(size) / 1_048_576.0)
        }
        if profile.wantsSmallFiles {
            guard !isDirectory, size > 0, size <= 1 * 1_024 * 1_024 else { return nil }
            matchedAnyConstraint = true
            score += 130 + max(0, 24 - Double(size) / 65_536.0)
        }

        return matchedAnyConstraint ? score : nil
    }

    private func finderSemanticScore(query: String, for url: URL) -> Double? {
        let normalizedQuery = normalizedDockPillText(query)
        guard !normalizedQuery.isEmpty else { return nil }

        let name = normalizedDockPillText(url.lastPathComponent)
        let path = normalizedDockPillText(url.path)
        guard !name.isEmpty || !path.isEmpty else { return nil }

        var bestScore: Double? = nil

        if name == normalizedQuery {
            bestScore = 1100
        } else if name.hasPrefix(normalizedQuery) {
            bestScore = 980 + Double(min(normalizedQuery.count, 12) * 6)
        } else if name.contains(normalizedQuery) {
            bestScore = 900 + Double(min(normalizedQuery.count, 10) * 4)
        }

        if path.contains(normalizedQuery) {
            bestScore = max(bestScore ?? 0, 820 + Double(min(normalizedQuery.count, 12) * 3))
        }

        let queryTerms = dockPillTokens(normalizedQuery).filter { $0.count >= 2 }
        if !queryTerms.isEmpty {
            let matchedTerms = queryTerms.filter { name.contains($0) || path.contains($0) }
            if !matchedTerms.isEmpty {
                bestScore = max(
                    bestScore ?? 0,
                    780 + Double(matchedTerms.count * 42)
                )
            }
        }

        if let fuzzyName = FuzzyMatcher.score(normalizedQuery, against: name) {
            bestScore = max(bestScore ?? 0, fuzzyName)
        }
        if let typoName = finderNameTypoScore(query: normalizedQuery, target: name) {
            bestScore = max(bestScore ?? 0, typoName)
        }
        if bestScore == nil,
            let fuzzyPath = FuzzyMatcher.score(normalizedQuery, against: path)
        {
            bestScore = max(bestScore ?? 0, fuzzyPath * 0.78)
        }

        let isDirectory = (try? url.resourceValues(forKeys: [.isDirectoryKey]).isDirectory) ?? false
        if isDirectory {
            bestScore = (bestScore ?? 0) + 18
        }

        return bestScore
    }

    private func finderNameTypoScore(query: String, target: String) -> Double? {
        let queryTerms = dockPillTokens(query).filter { $0.count >= 3 }
        let targetTerms = dockPillTokens(target).filter { $0.count >= 3 }
        guard !queryTerms.isEmpty, !targetTerms.isEmpty else { return nil }

        var matched = 0
        var score = 0.0
        for q in queryTerms {
            guard let best = targetTerms.map({ levenshteinDistance(q, $0) }).min() else { continue }
            let allowed = max(1, min(3, q.count / 3))
            if best <= allowed {
                matched += 1
                score += 720 + Double(max(0, q.count - best) * 24)
            }
        }
        guard matched > 0 else { return nil }
        return score / Double(queryTerms.count)
    }

    private func levenshteinDistance(_ lhs: String, _ rhs: String) -> Int {
        let a = Array(lhs)
        let b = Array(rhs)
        if a.isEmpty { return b.count }
        if b.isEmpty { return a.count }

        var previous = Array(0...b.count)
        var current = Array(repeating: 0, count: b.count + 1)

        for i in 1...a.count {
            current[0] = i
            for j in 1...b.count {
                let cost = a[i - 1] == b[j - 1] ? 0 : 1
                current[j] = min(
                    previous[j] + 1,
                    current[j - 1] + 1,
                    previous[j - 1] + cost
                )
            }
            swap(&previous, &current)
        }

        return previous[b.count]
    }

    private func mergeFinderSemanticMatches(
        _ base: [FinderSemanticMatch],
        with additional: [FinderSemanticMatch]
    ) -> [FinderSemanticMatch] {
        var merged: [String: FinderSemanticMatch] = [:]
        for match in base + additional {
            if let existing = merged[match.path], existing.score >= match.score {
                continue
            }
            merged[match.path] = match
        }
        return merged.values.sorted { lhs, rhs in
            if lhs.score != rhs.score { return lhs.score > rhs.score }
            if lhs.isDirectory != rhs.isDirectory { return lhs.isDirectory && !rhs.isDirectory }
            return lhs.title.localizedCaseInsensitiveCompare(rhs.title) == .orderedAscending
        }
    }

    private func buildFastFinderSemanticMatches(query: String, currentFolderPath: String) async
        -> [FinderSemanticMatch]
    {
        let normalizedQuery = normalizedDockPillText(query)
        guard !normalizedQuery.isEmpty else { return [] }
        let profile = finderSemanticProfile(for: normalizedQuery)
        let textQuery =
            !profile.residualQuery.isEmpty
            ? profile.residualQuery
            : (profile.hasSemanticConstraint ? "" : normalizedQuery)
        let now = Date()

        var matches: [FinderSemanticMatch] = []
        let fileManager = FileManager.default

        func addMatch(_ url: URL, baseScore: Double, source: String, extraTerms: [String] = []) {
            let resourceValues =
                (try? url.resourceValues(forKeys: [.isDirectoryKey, .contentModificationDateKey, .fileSizeKey]))
                ?? URLResourceValues()
            let textScore =
                !textQuery.isEmpty ? finderSemanticScore(query: textQuery, for: url) : nil
            let semanticBoost = finderSemanticConstraintBoost(
                for: url,
                profile: profile,
                resourceValues: resourceValues,
                now: now
            )

            if !profile.residualQuery.isEmpty, textScore == nil { return }
            if profile.hasSemanticConstraint, semanticBoost == nil { return }
            guard textScore != nil || semanticBoost != nil else { return }

            let isDirectory = resourceValues.isDirectory ?? url.hasDirectoryPath
            matches.append(
                FinderSemanticMatch(
                    path: url.path,
                    title: url.lastPathComponent.isEmpty ? url.path : url.lastPathComponent,
                    subtitle: "\(source) • \(finderDisplayPath(url.path))",
                    isDirectory: isDirectory,
                    score: (textScore ?? 0) + (semanticBoost ?? 0) + baseScore,
                    source: source,
                    searchTerms: extraTerms + [source, url.lastPathComponent, url.path]
                ))
        }

        let folderURL = URL(fileURLWithPath: currentFolderPath)
        let isTemporalOrSizeQuery =
            profile.wantsRecent || profile.wantsToday || profile.wantsYesterday
            || profile.wantsThisWeek || profile.wantsLargeFiles || profile.wantsSmallFiles
        if !isTemporalOrSizeQuery,
            (!profile.hasSemanticConstraint || profile.wantsFoldersOnly || !profile.residualQuery.isEmpty)
        {
            addMatch(folderURL, baseScore: 180, source: "Current Folder", extraTerms: ["finder", "current directory"])
        }

        let selectedURLs = axContext.selectedFilePaths.map { URL(fileURLWithPath: $0) }
        for url in selectedURLs {
            addMatch(url, baseScore: 165, source: "Selected Item", extraTerms: ["finder", "selection"])
        }

        if let currentItems = try? fileManager.contentsOfDirectory(
            at: folderURL,
            includingPropertiesForKeys: [.isDirectoryKey],
            options: [.skipsHiddenFiles, .skipsPackageDescendants]
        ) {
            for url in currentItems {
                addMatch(url, baseScore: 140, source: "Current Folder", extraTerms: ["finder"])
            }
        }

        return mergeFinderSemanticMatches([], with: matches)
    }

    private func runFinderSpotlightSearch(query: String, currentFolderPath: String, limit: Int)
        -> [FinderSemanticMatch]
    {
        let normalizedQuery = normalizedDockPillText(query)
        guard normalizedQuery.count >= 3 else { return [] }
        let profile = finderSemanticProfile(for: normalizedQuery)
        let contentQuery = profile.residualQuery
        guard !contentQuery.isEmpty else { return [] }
        let now = Date()
        let normalizedFolderPath = URL(fileURLWithPath: currentFolderPath).standardizedFileURL.path

        func executeMDFind(arguments: [String], source: String, boost: Double)
            -> [FinderSemanticMatch]
        {
            let task = Process()
            let pipe = Pipe()
            task.executableURL = URL(fileURLWithPath: "/usr/bin/mdfind")
            task.arguments = arguments
            task.standardOutput = pipe
            task.standardError = Pipe()

            do {
                try task.run()
                task.waitUntilExit()
                let data = pipe.fileHandleForReading.readDataToEndOfFile()
                guard let output = String(data: data, encoding: .utf8), !output.isEmpty else {
                    return []
                }

                var results: [FinderSemanticMatch] = []
                for path in output.components(separatedBy: .newlines)
                    .filter({ !$0.isEmpty })
                    .prefix(limit)
                {
                    let url = URL(fileURLWithPath: path)
                    let normalizedPath = url.standardizedFileURL.path
                    let parentPath = url.deletingLastPathComponent().standardizedFileURL.path
                    guard parentPath == normalizedFolderPath else { continue }
                    let resourceValues =
                        (try? url.resourceValues(forKeys: [.isDirectoryKey, .contentModificationDateKey, .fileSizeKey]))
                        ?? URLResourceValues()
                    let isDirectory = resourceValues.isDirectory ?? url.hasDirectoryPath
                    let textScore = finderSemanticScore(query: contentQuery, for: url) ?? 720
                    let semanticBoost = finderSemanticConstraintBoost(
                        for: url,
                        profile: profile,
                        resourceValues: resourceValues,
                        now: now
                    )
                    if profile.hasSemanticConstraint && semanticBoost == nil { continue }
                    results.append(
                        FinderSemanticMatch(
                            path: normalizedPath,
                            title: url.lastPathComponent.isEmpty ? normalizedPath : url.lastPathComponent,
                            subtitle: "\(source) • \(finderDisplayPath(normalizedPath))",
                            isDirectory: isDirectory,
                            score: textScore + (semanticBoost ?? 0) + boost,
                            source: source,
                            searchTerms: [url.lastPathComponent, normalizedPath, source, "content", "finder"]
                        ))
                }
                return results
            } catch {
                return []
            }
        }

        let currentFolderMatches = executeMDFind(
            arguments: ["-onlyin", currentFolderPath, contentQuery],
            source: "Current Folder Content",
            boost: 150
        )
        return currentFolderMatches
    }

    private func finderResultType(for path: String, isDirectory: Bool) -> SearchResult.ResultType {
        if isDirectory { return .folder }
        let ext = URL(fileURLWithPath: path).pathExtension.lowercased()
        if ["pdf", "txt", "md", "rtf", "doc", "docx", "pages", "json", "csv", "xml", "yaml", "yml", "swift", "js", "ts", "py", "sh"].contains(ext) {
            return .document
        }
        return .file
    }

    private func finderSemanticSymbol(for match: FinderSemanticMatch) -> String {
        if match.isDirectory { return "folder" }
        switch URL(fileURLWithPath: match.path).pathExtension.lowercased() {
        case "pdf":
            return "doc.richtext"
        case "png", "jpg", "jpeg", "gif", "heic", "webp", "tiff", "bmp":
            return "photo"
        case "zip", "rar", "7z", "gz", "tar":
            return "archivebox"
        case "mp4", "mov", "m4v", "avi", "mkv":
            return "film"
        case "mp3", "wav", "m4a", "flac":
            return "music.note"
        default:
            return "doc"
        }
    }

    private func finderSemanticAction(for path: String, isDirectory: Bool) -> () -> Void {
        {
            let url = URL(fileURLWithPath: path)
            let folderPath = isDirectory ? url.deletingLastPathComponent().path : url.deletingLastPathComponent().path
            if isFinderCurrentWindowSearchAttached(currentFolderPath: folderPath) {
                recordFinderCurrentFolderLaunch(itemPath: url.path, folderPath: folderPath)
            }
            rememberFinderFollowUpTargets(
                [url],
                folderPath: isDirectory ? url.path : url.deletingLastPathComponent().path,
                sourceQuery: url.lastPathComponent
            )
            NSWorkspace.shared.open(url)
            searchState.query = ""
            l2.focusedPillIndex = nil
        }
    }

    private func makeFinderSemanticSearchResults(from matches: [FinderSemanticMatch]) -> [SearchResult] {
        matches.prefix(24).map { match in
            let icon = NSWorkspace.shared.icon(forFile: match.path)
            icon.size = NSSize(width: 32, height: 32)
            return SearchResult(
                title: match.title,
                subtitle: match.subtitle,
                icon: icon,
                action: finderSemanticAction(for: match.path, isDirectory: match.isDirectory),
                score: match.score,
                type: finderResultType(for: match.path, isDirectory: match.isDirectory),
                filePath: match.path,
                contactData: nil
            )
        }
    }

    private func makeFinderSemanticDockPills(from matches: [FinderSemanticMatch]) -> [DockPill] {
        matches.prefix(8).map { match in
            var pill = DockPill(
                id: "finder-search-\(match.path)",
                name: match.title,
                icon: finderSemanticSymbol(for: match),
                accentColorName: match.isDirectory ? "blue" : "teal",
                badge: match.source,
                execute: finderSemanticAction(for: match.path, isDirectory: match.isDirectory)
            )
            pill.sourceBundleId = "com.apple.finder"
            pill.sourceAppName = "Finder"
            pill.rankingKind = match.source == "Current Folder" ? "finderCurrent" : "finderSearch"
            pill.trackingIdentifier = "finder-search:\(match.path.lowercased())"
            pill.searchTerms = match.searchTerms
            pill.rankingScore = match.score
            return pill
        }
    }

    private func finderSemanticActionTargetURLs() -> [URL] {
        finderSemanticResults
            .compactMap { result -> URL? in
                guard let path = result.filePath, FileManager.default.fileExists(atPath: path) else { return nil }
                return URL(fileURLWithPath: path)
            }
            .prefix(8)
            .map { $0 }
    }

    private func makeFinderSemanticQuickActionPills(query: String) -> [DockPill] {
        let urls = finderSemanticActionTargetURLs()
        guard !urls.isEmpty else { return [] }
        let normalized = normalizedDockPillText(query)
        let firstURL = urls[0]
        let targetLabel = urls.count == 1 ? firstURL.lastPathComponent : "\(urls.count) results"

        var pills: [DockPill] = []

        var preview = DockPill(
            id: "finder-search-preview-\(firstURL.path)",
            name: "Preview \(firstURL.lastPathComponent)",
            icon: "eye",
            accentColorName: "blue",
            badge: "Quick Look",
            execute: {
                quickLookDataSource = QuickLookDataSource(urls: [firstURL])
                searchState.query = ""
                l2.focusedPillIndex = nil
            }
        )
        preview.sourceBundleId = "com.apple.finder"
        preview.sourceAppName = "Finder"
        preview.rankingKind = "finderContext"
        preview.trackingIdentifier = "finder-preview:\(firstURL.path.lowercased())"
        preview.searchTerms = ["preview", "quick look", "finder", firstURL.lastPathComponent, normalized]
        pills.append(preview)

        var reveal = DockPill(
            id: "finder-search-reveal-\(firstURL.path)",
            name: "Reveal \(firstURL.lastPathComponent)",
            icon: "folder",
            accentColorName: "gray",
            badge: "Finder",
            execute: {
                NSWorkspace.shared.activateFileViewerSelecting([firstURL])
                searchState.query = ""
                l2.focusedPillIndex = nil
            }
        )
        reveal.sourceBundleId = "com.apple.finder"
        reveal.sourceAppName = "Finder"
        reveal.rankingKind = "finderContext"
        reveal.trackingIdentifier = "finder-reveal:\(firstURL.path.lowercased())"
        reveal.searchTerms = ["reveal", "show", "finder", firstURL.lastPathComponent, normalized]
        pills.append(reveal)

        if normalized.contains("compress") || normalized.contains("zip") || normalized.contains("archive") || normalized.contains("large") {
            var compress = DockPill(
                id: "finder-search-compress-\(urls.map(\.path).joined(separator: "|").hashValue)",
                name: "Compress \(targetLabel)",
                icon: "archivebox",
                accentColorName: "orange",
                badge: "ZIP",
                execute: {
                    compressFinderSearchResults(urls)
                    searchState.query = ""
                    l2.focusedPillIndex = nil
                }
            )
            compress.sourceBundleId = "com.apple.finder"
            compress.sourceAppName = "Finder"
            compress.rankingKind = "finderContext"
            compress.trackingIdentifier = "finder-compress:\(normalized)"
            compress.searchTerms = ["compress", "zip", "archive", "finder", targetLabel, normalized]
            pills.append(compress)
        }

        if normalized.contains("move") || normalized.contains("organize") {
            var move = DockPill(
                id: "finder-search-move-\(urls.map(\.path).joined(separator: "|").hashValue)",
                name: "Move \(targetLabel)",
                icon: "folder.badge.plus",
                accentColorName: "teal",
                badge: "Choose",
                execute: {
                    moveFinderSearchResultsWithPanel(urls)
                    searchState.query = ""
                    l2.focusedPillIndex = nil
                }
            )
            move.sourceBundleId = "com.apple.finder"
            move.sourceAppName = "Finder"
            move.rankingKind = "finderContext"
            move.trackingIdentifier = "finder-move:\(normalized)"
            move.searchTerms = ["move", "organize", "finder", targetLabel, normalized]
            pills.append(move)
        }

        return pills
    }

    private func compressFinderSearchResults(_ urls: [URL]) {
        let existingURLs = canonicalExistingURLs(urls).filter { !$0.hasDirectoryPath }
        guard !existingURLs.isEmpty else {
            AppToast.show("No files to compress", icon: "exclamationmark.triangle", tint: .orange)
            return
        }
        let parentURL = existingURLs[0].deletingLastPathComponent()
        let archiveBase = existingURLs.count == 1
            ? existingURLs[0].deletingPathExtension().lastPathComponent
            : "Context-Dock Selection"
        let archiveURL = uniqueFinderDestination(
            for: parentURL.appendingPathComponent("\(archiveBase).zip"),
            in: parentURL
        )

        Task.detached(priority: .userInitiated) {
            let process = Process()
            process.executableURL = URL(fileURLWithPath: "/usr/bin/ditto")
            if existingURLs.count == 1 {
                process.arguments = [
                    "-c", "-k", "--sequesterRsrc", "--keepParent",
                    existingURLs[0].path,
                    archiveURL.path
                ]
            } else {
                process.executableURL = URL(fileURLWithPath: "/usr/bin/zip")
                process.currentDirectoryURL = parentURL
                process.arguments = ["-r", archiveURL.path] + existingURLs.map(\.lastPathComponent)
            }
            try? process.run()
            process.waitUntilExit()
            await MainActor.run {
                if process.terminationStatus == 0 {
                    AppToast.show("Created \(archiveURL.lastPathComponent)", icon: "archivebox", tint: .green)
                    rememberFinderFollowUpTargets([archiveURL], folderPath: parentURL.path, sourceQuery: "compress")
                } else {
                    AppToast.show("Compression failed", icon: "exclamationmark.triangle", tint: .orange)
                }
            }
        }
    }

    private func moveFinderSearchResultsWithPanel(_ urls: [URL]) {
        let existingURLs = canonicalExistingURLs(urls)
        guard !existingURLs.isEmpty else { return }
        let panel = NSOpenPanel()
        panel.canChooseFiles = false
        panel.canChooseDirectories = true
        panel.allowsMultipleSelection = false
        panel.prompt = "Move"
        let moveLabel = existingURLs.count == 1
            ? existingURLs[0].lastPathComponent
            : "\(existingURLs.count) Finder results"
        panel.message = "Choose a destination folder for \(moveLabel)."
        guard panel.runModal() == .OK, let destinationFolder = panel.url else { return }

        var moved: [URL] = []
        var failures = 0
        for url in existingURLs {
            let destination = uniqueFinderDestination(
                for: url,
                in: destinationFolder
            )
            do {
                try FileManager.default.moveItem(at: url, to: destination)
                moved.append(destination)
            } catch {
                failures += 1
            }
        }

        if !moved.isEmpty {
            rememberFinderFollowUpTargets(moved, folderPath: destinationFolder.path, sourceQuery: "move")
            AppToast.show("Moved \(moved.count) item\(moved.count == 1 ? "" : "s")", icon: "folder.badge.plus", tint: .green)
        }
        if failures > 0 {
            AppToast.show("Skipped \(failures) item\(failures == 1 ? "" : "s")", icon: "exclamationmark.triangle", tint: .orange)
        }
    }

    private func buildAttachedFinderFolderPills(query: String) -> [DockPill] {
        let semanticQuery = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard !semanticQuery.isEmpty, !semanticQuery.hasPrefix("+") else { return [] }
        guard semanticQuery.count >= 2 else { return [] }
        guard isFinderCurrentWindowSearchAttached() else { return [] }

        let folderPath = URL(fileURLWithPath: attachedFinderFolderSearchPath).standardizedFileURL.path
        let folderURL = URL(fileURLWithPath: folderPath)
        let urls = (try? FileManager.default.contentsOfDirectory(
            at: folderURL,
            includingPropertiesForKeys: [.isDirectoryKey, .contentModificationDateKey, .fileSizeKey],
            options: [.skipsHiddenFiles, .skipsPackageDescendants]
        )) ?? []

        let scored = urls.compactMap { url -> (url: URL, isDirectory: Bool, score: Double)? in
            guard let score = finderSemanticScore(query: semanticQuery, for: url),
                  score >= 120 else { return nil }
            let values = (try? url.resourceValues(forKeys: [.isDirectoryKey])) ?? URLResourceValues()
            return (url, values.isDirectory ?? url.hasDirectoryPath, score)
        }

        return scored
            .sorted {
                if $0.score != $1.score { return $0.score > $1.score }
                if $0.isDirectory != $1.isDirectory { return $0.isDirectory && !$1.isDirectory }
                return $0.url.lastPathComponent.localizedCaseInsensitiveCompare($1.url.lastPathComponent)
                    == .orderedAscending
            }
            .prefix(8)
            .map { item in
                let itemPath = item.url.standardizedFileURL.path
                var pill = DockPill(
                    id: "finder-attached-\(itemPath)",
                    name: item.url.lastPathComponent,
                    icon: item.isDirectory ? "folder.fill" : finderSemanticSymbol(for: FinderSemanticMatch(
                        path: itemPath,
                        title: item.url.lastPathComponent,
                        subtitle: "",
                        isDirectory: item.isDirectory,
                        score: item.score,
                        source: "Current Folder",
                        searchTerms: []
                    )),
                    accentColorName: item.isDirectory ? "blue" : "teal",
                    badge: URL(fileURLWithPath: folderPath).lastPathComponent,
                    execute: {
                        recordFinderCurrentFolderLaunch(itemPath: itemPath, folderPath: folderPath)
                        if item.isDirectory {
                            NSWorkspace.shared.open(item.url)
                        } else {
                            NSWorkspace.shared.open(item.url)
                        }
                        searchState.query = ""
                        l2.focusedPillIndex = nil
                    }
                )
                pill.sourceBundleId = "com.apple.finder"
                pill.sourceAppName = "Finder"
                pill.rankingKind = "finderCurrent"
                pill.trackingIdentifier = finderCurrentFolderTrackingIdentifier(
                    folderPath: folderPath,
                    itemPath: itemPath
                )
                pill.searchTerms = [item.url.lastPathComponent, itemPath, folderPath, "finder", "current folder"]
                pill.rankingScore = item.score
                return pill
            }
    }

    private func applyFinderSemanticMatches(_ matches: [FinderSemanticMatch], query: String) {
        let latestScope = resolveDockScope(for: searchState.query)
        let latestQuery = latestScope.scopedBundleId == "com.apple.finder"
            ? latestScope.scopedSearchQuery.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
            : ""
        guard latestQuery == query else { return }

        finderSemanticQuery = query
        let results = makeFinderSemanticSearchResults(from: matches)
        finderSemanticResults = results
        finderSemanticPills = makeFinderSemanticDockPills(from: matches)
        applyFinderSemanticPanelResults(results)
    }

    private func clearFinderSemanticState() {
        let shouldClearPanelResults =
            !finderSemanticQuery.isEmpty || !finderSemanticResults.isEmpty || isFinderSemanticLoading
        finderSemanticTask?.cancel()
        finderSemanticTask = nil
        isFinderSemanticLoading = false
        finderSemanticQuery = ""
        finderSemanticResults = []
        finderSemanticPills = []
        l2.showResultsPopover = false
        if shouldClearPanelResults {
            applyFinderSemanticPanelResults([])
        }
    }

    // MARK: - Finder Go-To-Folder ("+prefix" mode)

    private func isFinderGoToMode(query: String) -> Bool {
        guard query.hasPrefix("+") else { return false }
        return frontmost.bundleID == "com.apple.finder"
            || l2.targetApp?.bundleId == "com.apple.finder"
            || axContext.bundleId == "com.apple.finder"
    }

    private func updateFinderGoToPills(for query: String) {
        guard isFinderGoToMode(query: query) else {
            if !finderGoToPills.isEmpty { finderGoToPills = [] }
            return
        }
        let pathQuery = String(query.dropFirst()).trimmingCharacters(in: .whitespacesAndNewlines)
        finderGoToPills = buildFinderGoToPills(pathQuery: pathQuery)
        scheduleDockPillRebuild(query: query, delayNanoseconds: 0)
    }

    private func buildFinderGoToPills(pathQuery: String) -> [DockPill] {
        let query = pathQuery.lowercased()
        let fm = FileManager.default
        let home = NSHomeDirectory()
        let desktopOnlyMode = isFinderDesktopOnlyMode

        // Direct absolute-path completion
        if query.hasPrefix("/") {
            if fm.fileExists(atPath: pathQuery) {
                return [makeFinderGoToPill(path: pathQuery)]
            }
            let parent = (pathQuery as NSString).deletingLastPathComponent
            let stem   = (pathQuery as NSString).lastPathComponent.lowercased()
            if let items = try? fm.contentsOfDirectory(atPath: parent) {
                return items
                    .filter { !$0.hasPrefix(".") && $0.lowercased().hasPrefix(stem) }
                    .compactMap { item -> DockPill? in
                        let full = (parent as NSString).appendingPathComponent(item)
                        var isDir: ObjCBool = false
                        guard fm.fileExists(atPath: full, isDirectory: &isDir), isDir.boolValue else { return nil }
                        return makeFinderGoToPill(path: full)
                    }
                    .prefix(8).map { $0 }
            }
            return []
        }

        // Common quick-access locations
        let quickAccess: [(path: String, alias: String?)] = [
            ("\(home)/Desktop",   "desktop"),
            ("\(home)/Documents", "documents"),
            ("\(home)/Downloads", "downloads"),
            ("\(home)/Pictures",  "pictures"),
            ("\(home)/Movies",    "movies"),
            ("\(home)/Music",     "music"),
            ("\(home)/Library/Mobile Documents/com~apple~CloudDocs", "icloud"),
            (home, "home"),
        ]

        var results: [DockPill] = []
        var seen = Set<String>()

        for entry in quickAccess {
            guard fm.fileExists(atPath: entry.path) else { continue }
            let name = URL(fileURLWithPath: entry.path).lastPathComponent.lowercased()
            let alias = entry.alias ?? name
            let matches = query.isEmpty
                || name.hasPrefix(query) || name.contains(query)
                || alias.hasPrefix(query) || alias.contains(query)
            if matches, seen.insert(entry.path).inserted {
                results.append(makeFinderGoToPill(path: entry.path))
            }
        }

        guard !desktopOnlyMode else {
            return Array(results.prefix(8))
        }

        // Current Finder folder's subdirectories
        let finderFolder = currentFinderFolderPath()
        if !finderFolder.isEmpty, let items = try? fm.contentsOfDirectory(atPath: finderFolder) {
            for item in items.sorted() where !item.hasPrefix(".") && results.count < 8 {
                let full = (finderFolder as NSString).appendingPathComponent(item)
                var isDir: ObjCBool = false
                guard fm.fileExists(atPath: full, isDirectory: &isDir), isDir.boolValue else { continue }
                let itemLower = item.lowercased()
                guard query.isEmpty || itemLower.hasPrefix(query) || itemLower.contains(query) else { continue }
                if seen.insert(full).inserted { results.append(makeFinderGoToPill(path: full)) }
            }
        }

        // One level deep inside Desktop + Documents
        for root in ["\(home)/Desktop", "\(home)/Documents"] where results.count < 8 {
            guard let items = try? fm.contentsOfDirectory(atPath: root) else { continue }
            for item in items.sorted() where !item.hasPrefix(".") && results.count < 8 {
                let full = (root as NSString).appendingPathComponent(item)
                var isDir: ObjCBool = false
                guard fm.fileExists(atPath: full, isDirectory: &isDir), isDir.boolValue else { continue }
                let itemLower = item.lowercased()
                guard query.isEmpty || itemLower.hasPrefix(query) || itemLower.contains(query) else { continue }
                if seen.insert(full).inserted { results.append(makeFinderGoToPill(path: full)) }
            }
        }

        return Array(results.prefix(8))
    }

    private func makeFinderGoToPill(path: String) -> DockPill {
        let name = URL(fileURLWithPath: path).lastPathComponent
        var pill = DockPill(
            id: "finder-goto-\(path)",
            name: name.isEmpty ? path : name,
            icon: "folder.fill",
            accentColorName: "blue",
            badge: nil,
            execute: { [self] in navigateFinderToPath(path) }
        )
        pill.sourceBundleId = "com.apple.finder"
        pill.rankingKind = "finderGoTo"
        pill.trackingIdentifier = finderGoToTrackingIdentifier(for: path)
        return pill
    }

    private func finderGoToTrackingIdentifier(for path: String) -> String {
        "finder-goto:\(URL(fileURLWithPath: path).standardizedFileURL.path.lowercased())"
    }

    private func finderCurrentFolderTrackingIdentifier(folderPath: String, itemPath: String) -> String {
        let folder = URL(fileURLWithPath: folderPath).standardizedFileURL.path.lowercased()
        let item = URL(fileURLWithPath: itemPath).standardizedFileURL.path.lowercased()
        return "finder-current:\(folder):\(item)"
    }

    private func recordFinderCurrentFolderLaunch(itemPath: String, folderPath: String) {
        UsageTracker.shared.recordAccess(
            for: finderCurrentFolderTrackingIdentifier(folderPath: folderPath, itemPath: itemPath)
        )
    }

    private var frequentFinderHomeFolderGhostText: String? {
        let home = NSHomeDirectory()
        let candidates = [
            "\(home)/Downloads",
            "\(home)/Documents",
            "\(home)/Pictures",
            "\(home)/Movies",
            "\(home)/Music",
            "\(home)/Desktop",
        ]

        let mostUsedPath = candidates
            .filter { FileManager.default.fileExists(atPath: $0) }
            .max(by: {
                UsageTracker.shared.getAccessCount(for: finderGoToTrackingIdentifier(for: $0))
                    < UsageTracker.shared.getAccessCount(for: finderGoToTrackingIdentifier(for: $1))
            })
        guard let path = mostUsedPath else { return nil }

        guard UsageTracker.shared.getAccessCount(for: finderGoToTrackingIdentifier(for: path)) > 3 else {
            return nil
        }

        return "~/\(URL(fileURLWithPath: path).lastPathComponent)  — type to ask about this folder..."
    }

    private var frequentAttachedFinderItemGhostText: String? {
        guard !attachedFinderFolderSearchPath.isEmpty else { return nil }
        let folderPath = URL(fileURLWithPath: attachedFinderFolderSearchPath).standardizedFileURL.path
        let prefix = "finder-current:\(folderPath.lowercased()):"
        guard let item = UsageTracker.shared.getTopItems(limit: 80)
            .first(where: { entry in
                entry.identifier.hasPrefix(prefix)
                    && UsageTracker.shared.getAccessCount(for: entry.identifier) > 2
            })
        else { return nil }

        let itemPath = String(item.identifier.dropFirst(prefix.count))
        guard FileManager.default.fileExists(atPath: itemPath) else { return nil }
        return "\(URL(fileURLWithPath: itemPath).lastPathComponent)  — type to search this folder..."
    }

    private func navigateFinderToPath(_ path: String) {
        NSWorkspace.shared.selectFile(nil, inFileViewerRootedAtPath: path)
        DispatchQueue.main.async {
            self.searchState.query = ""
            self.finderGoToPills = []
            self.cachedDockPills = self.buildDockPills(query: "")
        }
    }

    private func scheduleFinderSemanticSearchIfNeeded(for query: String) {
        finderSemanticTask?.cancel()

        guard isL2ContextActive, showContextInDock, !isGlobalContextActive, !showMediaLayer else {
            clearFinderSemanticState()
            return
        }

        let scope = resolveDockScope(for: query)
        let currentFolderPath = currentFinderFolderPath()
        guard finderFolderQueryModeActive,
            isFinderFolderSearchAttached(currentFolderPath: currentFolderPath)
        else {
            clearFinderSemanticState()
            return
        }
        let semanticQuery = scope.scopedBundleId == "com.apple.finder"
            ? scope.scopedSearchQuery.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
            : ""
        let profile = finderSemanticProfile(for: semanticQuery)
        guard scope.scopedBundleId == "com.apple.finder" else {
            clearFinderSemanticState()
            return
        }

        guard !semanticQuery.isEmpty else {
            isFinderSemanticLoading = false
            finderSemanticQuery = ""
            finderSemanticResults = []
            finderSemanticPills = []
            l2.showResultsPopover = shouldKeepFinderSearchPopoverVisible(for: query)
            applyFinderSemanticPanelResults([])
            return
        }

        guard semanticQuery.count >= 2 else {
            isFinderSemanticLoading = false
            finderSemanticQuery = ""
            finderSemanticResults = []
            finderSemanticPills = []
            l2.showResultsPopover = shouldKeepFinderSearchPopoverVisible(for: query)
            applyFinderSemanticPanelResults([])
            return
        }

        isFinderSemanticLoading = false
        finderSemanticTask = Task(priority: .userInitiated) {
            try? await Task.sleep(nanoseconds: 180_000_000)
            guard !Task.isCancelled else { return }
            await MainActor.run {
                isFinderSemanticLoading = true
            }

            let advancedMatches = await MainActor.run {
                buildAdvancedFinderDataMatches(
                    profile: profile,
                    currentFolderPath: currentFolderPath,
                    limit: 24
                )
            }
            let fastMatches = await buildFastFinderSemanticMatches(
                query: semanticQuery,
                currentFolderPath: currentFolderPath
            )
            let initialMatches = mergeFinderSemanticMatches(advancedMatches, with: fastMatches)
            guard !Task.isCancelled else { return }
            await MainActor.run {
                applyFinderSemanticMatches(initialMatches, query: semanticQuery)
                isFinderSemanticLoading = false
            }

            let spotlightEnabled = await MainActor.run { settings.enableSpotlightSearch }
            guard spotlightEnabled, semanticQuery.count >= 3 else { return }

            try? await Task.sleep(nanoseconds: 160_000_000)
            guard !Task.isCancelled else { return }

            let spotlightMatches = runFinderSpotlightSearch(
                query: semanticQuery,
                currentFolderPath: currentFolderPath,
                limit: 18
            )
            let merged = mergeFinderSemanticMatches(initialMatches, with: spotlightMatches)
            guard !Task.isCancelled else { return }
            await MainActor.run {
                applyFinderSemanticMatches(merged, query: semanticQuery)
                isFinderSemanticLoading = false
            }
        }
    }

    private func isFinderSearchStyleQuery(_ query: String) -> Bool {
        let normalized = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard !normalized.isEmpty else { return false }

        let analyticalTerms = [
            "summarize", "summary", "explain", "review", "translate", "compare",
            "analyze", "analyse", "why", "how", "read", "rewrite", "draft",
            "rename", "organize", "sort", "clean up", "compress", "zip",
            "convert", "export", "save", "open", "move", "copy", "share", "send",
            "attach", "upload", "delete", "trash", "remove", "duplicate",
            "reveal", "preview", "quick look", "print", "merge", "split",
            "extract", "encode", "transcode"
        ]
        return !analyticalTerms.contains(where: normalized.contains)
    }

    private func finderSubmissionSummary(for query: String, results: [SearchResult]) -> String {
        if results.isEmpty {
            return "No Finder matches for “\(query)”."
        }

        let folderCount = results.filter { $0.type == .folder }.count
        let fileCount = results.count - folderCount
        if folderCount > 0 && fileCount > 0 {
            return "Found \(results.count) Finder matches for “\(query)” across folders and files."
        }
        if folderCount > 0 {
            return "Found \(folderCount) Finder folder match\(folderCount == 1 ? "" : "es") for “\(query)”."
        }
        return "Found \(fileCount) Finder file match\(fileCount == 1 ? "" : "es") for “\(query)”."
    }

    private func executeCachedMenuAction(
        bundleIdentifier: String,
        appName: String,
        appPath: String?,
        path: [String],
        shortcutChar: String?,
        shortcutModifiers: Int
    ) {
        Task.detached(priority: .userInitiated) {
            var targetApp = NSWorkspace.shared.runningApplications.first {
                $0.bundleIdentifier == bundleIdentifier && !$0.isTerminated
            }

            if targetApp == nil {
                let url =
                    NSWorkspace.shared.urlForApplication(withBundleIdentifier: bundleIdentifier)
                    ?? appPath.map(URL.init(fileURLWithPath:))
                if let url {
                    await MainActor.run {
                        AppToast.show("Opening \(appName)", icon: "app.badge", tint: .blue.opacity(0.85))
                    }
                    NSWorkspace.shared.open(url)
                }
            }

            for _ in 0..<30 {
                if let app = NSWorkspace.shared.runningApplications.first(where: {
                    $0.bundleIdentifier == bundleIdentifier && !$0.isTerminated
                }) {
                    targetApp = app
                    break
                }
                try? await Task.sleep(nanoseconds: 120_000_000)
            }

            guard let targetApp else { return }
            let pid = targetApp.processIdentifier
            targetApp.activate(options: [.activateIgnoringOtherApps])
            try? await Task.sleep(nanoseconds: 250_000_000)

            let liveMatch = await waitForExecutableMenuItem(
                path: path,
                app: targetApp,
                in: pid,
                attempts: 18,
                pauseNanoseconds: 140_000_000
            )

            guard let liveMatch else {
                if let ch = shortcutChar, !ch.isEmpty {
                    await MainActor.run {
                        self.executeDockMenuAction(
                            sourcePID: pid,
                            path: path,
                            shortcutChar: ch,
                            shortcutModifiers: shortcutModifiers
                        )
                    }
                    return
                }
                await MainActor.run {
                    AppToast.show(
                        "\(appName) action is not available right now",
                        icon: "exclamationmark.triangle",
                        tint: .orange.opacity(0.9)
                    )
                }
                return
            }

            if !liveMatch.isEnabled {
                // Item is reported disabled — keyboard shortcut bypasses AX disabled state.
                // If no shortcut, attempt AXPress anyway (traverse doesn't check isEnabled).
                await MainActor.run {
                    self.executeDockMenuAction(
                        sourcePID: pid,
                        path: path,
                        shortcutChar: shortcutChar ?? liveMatch.shortcutChar,
                        shortcutModifiers: shortcutModifiers != 0 ? shortcutModifiers : liveMatch.shortcutModifiers
                    )
                }
                return
            }

            AppInteractionStore.shared.record(
                bundleId: bundleIdentifier,
                appName: appName,
                query: liveMatch.title,
                kind: .menuItem,
                actionId: liveMatch.path.joined(separator: " > ")
            )

            await MainActor.run {
                self.executeDockMenuAction(
                    sourcePID: pid,
                    path: liveMatch.path,
                    shortcutChar: shortcutChar ?? liveMatch.shortcutChar,
                    shortcutModifiers: shortcutModifiers != 0 ? shortcutModifiers : liveMatch.shortcutModifiers
                )
            }
        }
    }

    private func waitForExecutableMenuItem(
        path: [String],
        app: NSRunningApplication,
        in pid: pid_t,
        attempts: Int,
        pauseNanoseconds: UInt64
    ) async -> AXMenuItem? {
        guard !path.isEmpty else { return nil }

        for attempt in 0..<attempts {
            let liveItems = AXMenuReader.shared.refreshAllMenuItems(for: pid, maxDepth: 6)
            if !liveItems.isEmpty {
                AppMenuCapabilityCache.shared.store(items: liveItems, for: app)
            }
            if let match = liveItems.first(where: { menuPathMatches($0, targetPath: path) }) {
                return match
            }

            AXMenuReader.shared.invalidateCache(for: pid)

            if attempt < attempts - 1 {
                try? await Task.sleep(nanoseconds: pauseNanoseconds)
            }
        }

        return nil
    }

    private func menuPathMatches(_ item: AXMenuItem, targetPath: [String]) -> Bool {
        let normalizedTarget = normalizedMenuPathForMatching(targetPath)
        let normalizedItem = normalizedMenuPathForMatching(item.path)

        if normalizedItem == normalizedTarget {
            return true
        }

        if item.isAppleMenu {
            let strippedTarget = normalizedTarget.filter { $0 != "apple" }
            if !strippedTarget.isEmpty && normalizedItem == strippedTarget {
                return true
            }
        }

        return false
    }

    private func isVolatileSelectionMenuPath(_ path: [String]) -> Bool {
        let normalized = normalizedMenuPathForMatching(path)
        guard !normalized.isEmpty else { return false }
        let joined = normalized.joined(separator: " ")
        let volatileExact: Set<String> = [
            "compress",
            "duplicate",
            "make alias",
            "quick look",
            "print",
            "rename",
            "move to bin",
            "move to trash",
            "delete immediately",
            "open with",
            "share",
            "tags"
        ]
        let leaf = normalized.last ?? ""
        if volatileExact.contains(leaf) || normalized.contains("open with") { return true }
        return joined.contains("selected")
            || joined.contains("selection")
            || joined.contains("extract")
    }

    private func normalizedMenuPathForMatching(_ path: [String]) -> [String] {
        path.map {
            $0
                .folding(options: [.diacriticInsensitive, .caseInsensitive], locale: .current)
                .lowercased()
                .trimmingCharacters(in: .whitespacesAndNewlines)
        }
        .filter { !$0.isEmpty }
    }

    /// Detect whether the current query targets a cross-app and trigger menu loading if needed.
    /// Safe to call from `.onChange` handlers (outside view body evaluation).
    private func triggerCrossAppMenuLoadIfNeeded(for query: String) {
        let q = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard !q.isEmpty else { return }
        if let target = L2AppActionRouter.shared.appScopeTarget(for: q),
            !target.actionQuery.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty,
            let app = NSWorkspace.shared.runningApplications.first(where: {
                $0.bundleIdentifier == target.bundleId
            })
        {
            loadCrossAppMenu(for: app)
            return
        }
        if settings.crossAppPills,
            let (app, actionQuery) = detectCrossAppQuery(q),
            !actionQuery.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
        {
            loadCrossAppMenu(for: app)
        }
    }

    private func seedCrossAppMenuCache(for app: NSRunningApplication) {
        let pid = app.processIdentifier
        let appName = app.localizedName ?? ""
        var cachedItems = AppMenuCapabilityCache.shared.menuItems(for: app, maxResults: 120)
        for index in cachedItems.indices {
            cachedItems[index].sourcePID = pid
            cachedItems[index].sourceAppName = appName
        }

        crossAppMenuTargetPID = pid
        crossAppMenuNeedsLiveLoad = true
        crossAppMenuItems = cachedItems
    }

    /// Load menu items for a target app into crossAppMenuItems from the persistent cache.
    /// Live AX scraping is deferred by warmMenuCacheIfNeeded so typing stays responsive.
    private func loadCrossAppMenu(for app: NSRunningApplication) {
        let pid = app.processIdentifier
        guard pid != 0 else { return }
        guard pid != crossAppMenuTargetPID || crossAppMenuNeedsLiveLoad else { return }
        // Defer state mutations to avoid modifying @State during view update (body evaluation).
        DispatchQueue.main.async {
            crossAppMenuTargetPID = pid
            crossAppMenuNeedsLiveLoad = false
            crossAppMenuTask?.cancel()
            crossAppMenuTask = Task.detached(priority: .userInitiated) {
                let name = app.localizedName ?? ""
                var items = AppMenuCapabilityCache.shared.menuItems(for: app, maxResults: 120)
                for i in items.indices {
                    items[i].sourcePID = pid
                    items[i].sourceAppName = name
                }
                await MainActor.run {
                    guard self.crossAppMenuTargetPID == pid else { return }
                    self.crossAppMenuItems = items
                    self.warmMenuCacheIfNeeded(bundleId: app.bundleIdentifier ?? "", appName: name)
                }
            }
        }
    }

    private func distributedMenuItems(_ items: [AXMenuItem], limit: Int) -> [AXMenuItem] {
        guard limit > 0, !items.isEmpty else { return [] }

        var buckets: [String: [AXMenuItem]] = [:]
        var rootOrder: [String] = []

        for item in items {
            let root = item.path.first ?? item.title
            if buckets[root] == nil {
                buckets[root] = []
                rootOrder.append(root)
            }
            buckets[root, default: []].append(item)
        }

        for root in rootOrder {
            buckets[root]?.sort {
                if $0.path.count != $1.path.count { return $0.path.count < $1.path.count }
                return $0.title.localizedCaseInsensitiveCompare($1.title) == .orderedAscending
            }
        }

        var distributed: [AXMenuItem] = []
        var didAppend = true
        while distributed.count < limit && didAppend {
            didAppend = false
            for root in rootOrder where distributed.count < limit {
                guard var bucket = buckets[root], !bucket.isEmpty else { continue }
                distributed.append(bucket.removeFirst())
                buckets[root] = bucket
                didAppend = true
            }
        }

        return distributed
    }

    private func orderedScopedMenuMatches(_ items: [AXMenuItem], filterQuery: String, limit: Int)
        -> [AXMenuItem]
    {
        guard !items.isEmpty else { return [] }
        let normalizedFilter = filterQuery.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        if normalizedFilter.isEmpty {
            return distributedMenuItems(items, limit: limit)
        }

        return Array(
            items.sorted {
                let aScore = rankedTextMatchScore(
                    query: normalizedFilter,
                    primary: $0.title,
                    contexts: [$0.path.dropLast().last ?? "", $0.path.joined(separator: " ")]
                ) ?? 0
                let bScore = rankedTextMatchScore(
                    query: normalizedFilter,
                    primary: $1.title,
                    contexts: [$1.path.dropLast().last ?? "", $1.path.joined(separator: " ")]
                ) ?? 0
                if aScore != bScore { return aScore > bScore }
                if $0.path.count != $1.path.count { return $0.path.count < $1.path.count }
                return $0.title.localizedCaseInsensitiveCompare($1.title) == .orderedAscending
            }
            .prefix(limit)
        )
    }

    private func scheduleDockPillRebuild(
        query: String,
        delayNanoseconds: UInt64 = 55_000_000,
        refreshContext: Bool = true
    ) {
        dockPillBuildTask?.cancel()
        pendingDockPillQuery = query
        dockPillBuildTask = Task { @MainActor in
            try? await Task.sleep(nanoseconds: delayNanoseconds)
            guard !Task.isCancelled else {
                if pendingDockPillQuery == query { pendingDockPillQuery = nil }
                return
            }
            // Skip the AX IPC call when the user is typing — selection context doesn't
            // change while typing, and the call blocks the main thread causing hitches.
            let shouldRefresh = refreshContext && query.isEmpty
            if shouldRefresh {
                refreshFinderSelectionContextFromFinder()
                guard !Task.isCancelled else {
                    if pendingDockPillQuery == query { pendingDockPillQuery = nil }
                    return
                }
            }
            cachedDockPills = buildDockPills(query: query)
            lastPillQuery = query
            if pendingDockPillQuery == query { pendingDockPillQuery = nil }
            dockPillBuildTask = nil
        }
    }

    /// Build the ordered list of visible pills for the current dock state.
    /// This is the single source of truth for both rendering and keyboard navigation.
    func buildDockPills(query q: String) -> [DockPill] {
        // When a submenu parent is locked, the dropdown handles child display directly —
        // skip all pill logic so no app/file/other pills compete with it.
        if lockedSubmenuParent != nil { return [] }

        // AI-found menu action: show as a focused pill instead of in the chat result sheet
        if q.isEmpty, let proposal = pendingAIMenuProposal {
            let path = proposal.path
            let sc = proposal.shortcutChar
            let mod = proposal.shortcutModifiers
            let pid = proposal.sourcePID
            let bId = proposal.sourceBundleId
            let aName = proposal.sourceAppName
            var pill = DockPill(
                id: "ai-proposal-\(proposal.fullPathLabel)",
                name: proposal.title,
                icon: "cursorarrow.click",
                accentColorName: "blue",
                badge: aName.isEmpty ? nil : aName,
                execute: {
                    self.pendingAIMenuProposal = nil
                    self.executeDockMenuAction(
                        sourcePID: pid,
                        path: path,
                        shortcutChar: sc,
                        shortcutModifiers: mod
                    )
                }
            )
            pill.menuItemImage = proposal.menuImage
            pill.menuItemName = proposal.title
            pill.sourceBundleId = bId
            pill.sourceAppName = aName
            pill.rankingKind = "menu"
            return [pill]
        }

        // "youtube on web" / "browse tamilgun" / "web X" → immediate web-search pill
        if let searchTerm = L2AppActionRouter.shared.extractWebSearchQuery(from: q) {
            let browserName = L2AppActionRouter.defaultBrowserName()
            var pill = DockPill(
                id: "web-search-\(searchTerm)",
                name: "Search \"\(searchTerm)\" on Web",
                icon: "globe",
                accentColorName: "blue",
                badge: browserName,
                execute: { L2AppActionRouter.openWebSearch(searchTerm) }
            )
            pill.rankingKind = "webSearch"
            pill.searchTerms = [searchTerm, "web", "search", browserName]
            pill.trackingIdentifier = "web-search:\(searchTerm)"
            return [pill]
        }

        var pills: [DockPill] = []
        pills.append(contentsOf: buildGlobalSelectionSharePills(query: q))
        // Safari page-level command pills (search, click, open) — appear before AX menu items
        pills.append(contentsOf: buildSafariCommandPills(query: q))
        // System Settings pane deep-links (Wallpaper, Wi-Fi, etc.) — sidebar isn't menu-scanned
        pills.append(contentsOf: buildSystemSettingsPills(query: q))
        let scope = resolveDockScope(for: q)
        let rawScopedSearchQuery = rawScopedActionQuery(for: q, scope: scope)
        let installedScopeMode = contextDockInstalledAppScopeMatching
        let runningOnly = contextDockRunningOnlyAppMatching && !installedScopeMode
        let runningBundleIds = runningOnly ? runningBundleIdsForContextDock() : []
        let explicitAppTarget: L2ExplicitAppTarget? = (!isGlobalContextActive || q.isEmpty) ? nil : L2AppActionRouter.shared.appScopeTarget(for: q).flatMap { target -> L2ExplicitAppTarget? in
            if installedScopeMode,
               implicitContextDockAppScopeBlockedBundleIds.contains(target.bundleId) {
                return nil
            }
            return (!runningOnly || runningBundleIds.contains(target.bundleId)) ? target : nil
        }
        let inlineInstalledMenuTarget: InstalledAppMenuTarget? =
            (shouldUsePureGlobalAppSearch && isGlobalContextActive && l2.targetApp == nil)
            ? globalInlineAppScope.map {
                InstalledAppMenuTarget(
                    appName: $0.appName,
                    bundleId: $0.bundleId,
                    appPath: $0.appPath,
                    actionQuery: q,
                    matchedAlias: $0.matchedAlias
                )
            }
            : nil
        let installedMenuTarget: InstalledAppMenuTarget? = {
            if let target = inlineInstalledMenuTarget { return target }
            guard isGlobalContextActive, explicitAppTarget == nil, l2.targetApp == nil else { return nil }
            let target = installedAppMenuTarget(
                for: q,
                runningOnly: false,
                includeAppsWithoutMenuSnapshot: true,
                allowPrefixAlias: true
            )
            // In pure global app search, a bare app name (e.g. "terminal") means "launch this app",
            // not "show all its menus". Empty actionQuery → skip installedMenuTarget so unrelated
            // menus don't flood the results list.
            if shouldUsePureGlobalAppSearch, target?.actionQuery.isEmpty == true { return nil }
            return target
        }()
        let isExplicitAppScope = scope.isExplicitAppScope
        let isGlobalScope = scope.isGlobalScope
        let allowAppleMenuItems = isGlobalContextActive
        let scopedBundleId = scope.scopedBundleId
        let scopedAppName = scope.scopedAppName
        let scopedSearchQuery = scope.scopedSearchQuery
        let isFinderScopedDock =
            !isGlobalScope
            && (!isExplicitAppScope || scopedBundleId == "com.apple.finder")
            && (scopedBundleId == "com.apple.finder"
                || frontmost.bundleID == "com.apple.finder"
                || axContext.bundleId == "com.apple.finder")
        let finderFolderAttachedForDock =
            isFinderScopedDock
            && finderFolderQueryModeActive
            && isFinderFolderSearchAttached(currentFolderPath: currentFinderFolderPath())
        let rawPayloadActionPills = buildPayloadActionPills(query: q)
        let rawFinderFilePills =
            isFinderScopedDock
            ? buildFinderFilePills(query: q) : []
        let rawFinderHomeFolderPills =
            isFinderScopedDock
            ? buildFinderHomeFolderPills(query: scopedSearchQuery.isEmpty ? q : scopedSearchQuery) : []
        let finderHomeSearchQuery = (scopedSearchQuery.isEmpty ? q : scopedSearchQuery)
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let shouldShowFinderHomeSearchOnly =
            isFinderScopedDock
            && !finderFolderAttachedForDock
            && !finderHomeSearchQuery.isEmpty
            && !rawFinderHomeFolderPills.isEmpty
            && effectiveFinderSelectionURLsForPills().isEmpty
        let rawAttachedFinderFolderPills =
            isFinderScopedDock
            ? buildAttachedFinderFolderPills(query: scopedSearchQuery.isEmpty ? q : scopedSearchQuery) : []
        let finderFileTitleSet = Set(rawFinderFilePills.map { normalizedDockPillText($0.name) })
        let rawFinderSelectionMenuPills =
            isFinderScopedDock && !finderFolderAttachedForDock
            ? buildFinderSelectionMenuPills(query: q, excludingTitles: finderFileTitleSet) : []
        let payloadActionPills: [DockPill] = {
            guard isExplicitAppScope, !scopedSearchQuery.isEmpty else {
                return rawPayloadActionPills
            }
            let payloadIntentWords = [
                "send", "share", "message", "messages", "imessage", "sms",
                "mail", "email", "note", "notes", "reminder", "remind",
                "download", "downloads"
            ]
            let isPayloadIntent = payloadIntentWords.contains { scopedSearchQuery.contains($0) }
            return isPayloadIntent ? rawPayloadActionPills : []
        }()
        let crossAppPills = !isExplicitAppScope ? buildCrossAppPills(query: q) : []
        let semanticFinderPills: [DockPill] = {
            guard !shouldUseFinderSearchPopover(for: q) else { return [] }
            guard finderFolderAttachedForDock else { return [] }
            guard scopedBundleId == "com.apple.finder"
                || frontmost.bundleID == "com.apple.finder"
                || axContext.bundleId == "com.apple.finder" else { return [] }
            // "+prefix" go-to-folder mode: show path completion pills
            if isFinderGoToMode(query: q) { return finderGoToPills }
            let semanticQuery = scopedSearchQuery
                .trimmingCharacters(in: .whitespacesAndNewlines)
                .lowercased()
            let semanticProfile = finderSemanticProfile(for: semanticQuery)
            guard !semanticQuery.isEmpty, finderSemanticQuery == semanticQuery else { return [] }
            guard semanticProfile.explicitLocationPath == nil else { return [] }
            return finderSemanticPills
        }()
        let semanticFinderQuickActionPills: [DockPill] = {
            guard !semanticFinderPills.isEmpty else { return [] }
            let semanticQuery = scopedSearchQuery
                .trimmingCharacters(in: .whitespacesAndNewlines)
                .lowercased()
            return makeFinderSemanticQuickActionPills(query: semanticQuery)
        }()
        if shouldShowFinderHomeSearchOnly {
            return rankDockPills(
                rawFinderHomeFolderPills,
                rawQuery: q,
                rankingQuery: finderHomeSearchQuery,
                scopedBundleId: scopedBundleId,
                scopedAppName: scopedAppName,
                isExplicitAppScope: isExplicitAppScope
            )
        }
        if finderFolderAttachedForDock {
            return rankDockPills(
                rawFinderFilePills
                    + rawFinderHomeFolderPills
                    + rawAttachedFinderFolderPills
                    + semanticFinderPills
                    + semanticFinderQuickActionPills,
                rawQuery: q,
                rankingQuery: scopedSearchQuery.isEmpty ? q : scopedSearchQuery,
                scopedBundleId: scopedBundleId,
                scopedAppName: scopedAppName,
                isExplicitAppScope: isExplicitAppScope
            )
        }
        let messagesSemanticIntentPill =
            scopedBundleId == "com.apple.MobileSMS"
            ? makeMessagesSemanticIntentPill(
                fullQuery: q,
                rawScopedQuery: rawScopedSearchQuery,
                scopedBundleId: scopedBundleId,
                scopedAppName: scopedAppName
            )
            : nil
        let mailSemanticSearchPill =
            scopedBundleId == "com.apple.mail"
            ? makeMailSemanticSearchPill(
                fullQuery: q,
                rawScopedQuery: rawScopedSearchQuery,
                scopedBundleId: scopedBundleId,
                scopedAppName: scopedAppName
            )
            : nil
        let appWindowSemanticPill = makeAppWindowSemanticPill(
            rawScopedQuery: rawScopedSearchQuery,
            scopedBundleId: scopedBundleId,
            scopedAppName: scopedAppName,
            isGlobalScope: isGlobalScope
        )
        let chatGPTNewChatPill = makeChatGPTNewChatPill(
            scopedQuery: scopedSearchQuery,
            scopedBundleId: scopedBundleId,
            scopedAppName: scopedAppName,
            appPath: installedMenuTarget?.appPath
        )
        let hasStrongContextQuery = !payloadActionPills.isEmpty
        let shouldSuppressMenuForContext = finderFolderAttachedForDock
        let activeBundleId = isGlobalScope ? "" : scopedBundleId
        let scopedAppKey =
            isGlobalScope
            ? ""
            : (
                searchState.activeSmartQueryKey
                ?? settings.appKey(forBundleID: scopedBundleId, appName: scopedAppName)
                ?? settings.autoDetectedAppKey
                ?? ""
            )
        let allQuickActions =
            isGlobalScope
            ? []
            : appScopeShortcuts(
                for: scopedAppKey,
                placements: [.quickActions, .contextDock, .both]
            )
        let userScriptExtensions =
            isGlobalScope || scopedAppKey.isEmpty
            ? [AppToolExtension]()
            : appPillScriptExtensions(for: scopedAppKey, query: scopedSearchQuery)
        let cliPackages: [TerminalPackage] = {
            guard !isGlobalScope, !scopedBundleId.isEmpty else { return [] }
            // For cli:// adapter scopes, directly surface the matching package by command name.
            if scopedBundleId.hasPrefix("cli://") {
                let cmd = String(scopedBundleId.dropFirst("cli://".count))
                    .trimmingCharacters(in: .whitespacesAndNewlines)
                if let pkg = terminalPackageManager.packages.first(where: {
                    $0.isEnabled && $0.command.caseInsensitiveCompare(cmd) == .orderedSame
                }) {
                    if scopedSearchQuery.isEmpty { return [pkg] }
                    let q2 = scopedSearchQuery.lowercased()
                    let matches = pkg.command.lowercased().contains(q2)
                        || pkg.name.lowercased().contains(q2)
                        || pkg.subcommands.contains { $0.lowercased().hasPrefix(q2) }
                    return matches ? [pkg] : []
                }
                return []
            }
            return terminalPackageManager.packages(
                forContextBundleId: scopedBundleId,
                query: scopedSearchQuery,
                maxResults: q.isEmpty ? 6 : 4
            )
        }()
        let adapterActions =
            isGlobalScope || scopedBundleId.isEmpty
            ? [AdapterAction]()
            : (
                q.isEmpty
                ? adapterManager.actions(for: scopedBundleId)
                : adapterManager.actions(for: scopedBundleId, query: scopedSearchQuery)
            )
        let adapterCLICommands = Set<String>(
            adapterActions.compactMap { action in
                guard action.type == .cliTool else { return nil }
                let command = action.cliToolCommand?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
                return command.isEmpty ? nil : command.lowercased()
            }
        )
        let visibleCLIPackages = cliPackages.filter { package in
            !adapterCLICommands.contains(package.command.lowercased())
        }
        let visibleAdapterActions = adapterActions
        let allAppTools = {
            guard !isGlobalScope else { return [L2Extension]() }
            guard !scopedAppName.isEmpty || !scopedBundleId.isEmpty else {
                return frontmostAppL2Extensions
            }
            return l2Extensions(forAppName: scopedAppName, bundleID: scopedBundleId)
        }()
        let allCtxExts =
            isExplicitAppScope
            ? scopedContextExtensions(
                query: scopedSearchQuery, appName: scopedAppName, bundleId: scopedBundleId)
            : l2.contextExtensions
        let quickActions =
            q.isEmpty
            ? allQuickActions
            : allQuickActions.filter { $0.name.lowercased().contains(scopedSearchQuery) }
        let appTools =
            q.isEmpty
            ? allAppTools
            : allAppTools.filter {
                $0.displayName.lowercased().contains(scopedSearchQuery)
                    || $0.toolName.lowercased().contains(scopedSearchQuery)
            }
        let ctxExts =
            q.isEmpty
            ? allCtxExts
            : allCtxExts.filter { $0.ilExtension.name.lowercased().contains(scopedSearchQuery) }
        let scopedAppLaunchPill: DockPill? = {
            // No "Open" pill for cli:// adapters — they're not launchable apps
            guard !scopedBundleId.hasPrefix("cli://") else { return nil }
            guard isExplicitAppScope, !q.isEmpty, !scopedBundleId.isEmpty, !scopedAppName.isEmpty,
                scopedSearchQuery.isEmpty
            else { return nil }

            var pill = DockPill(
                id: "launch-\(scopedBundleId)",
                name: "Open \(scopedAppName)",
                icon: "app.badge",
                accentColorName: "blue",
                badge: nil,
                execute: {
                    _ = launchApplication(
                        bundleIdentifier: scopedBundleId,
                        appName: scopedAppName,
                        path: installedMenuTarget?.appPath
                    )
                }
            )
            pill.rankingKind = "appLaunch"
            pill.sourceBundleId = scopedBundleId
            pill.sourceAppName = scopedAppName
            pill.trackingIdentifier = "app-launch:\(scopedBundleId)"
            pill.searchTerms = [scopedAppName, "open", "launch", "app"]
            return pill
        }()

        let favs = settings.favouriteMenuPills(for: activeBundleId)
        let isScopedToOtherApp =
            isExplicitAppScope && !scopedBundleId.isEmpty && scopedBundleId != frontmost.bundleID
        let useSeededMenuPills =
            q.isEmpty && !liveMenuItems.isEmpty && !shouldSuppressMenuForContext
            && !isScopedToOtherApp

        if isGlobalContextActive && hasActiveDockContextSelection {
            pills.append(contentsOf: crossAppPills)
        }

        if useSeededMenuPills && !hasStrongContextQuery {
            let seedItems = Array(
                liveMenuItems
                    .filter { !$0.title.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }
                    .filter { allowAppleMenuItems || !isAppleMenuItem($0) }
                    .prefix(16)
            )

            for item in seedItems {
                let path = item.path
                let sourcePID =
                    item.sourcePID != 0
                    ? item.sourcePID
                    : (AppDelegate.shared?.previousFrontmostApp?.processIdentifier ?? 0)
                let shortcutChar = item.shortcutChar
                let shortcutMods = item.shortcutModifiers
                let pill = makeMenuDockPill(
                    id: "menu-seed-\(item.id)",
                    item: item,
                    sourceBundleId: activeBundleId,
                    sourceAppName: scopedAppName,
                    badge: item.shortcutDisplay,
                    trackingIdentifier: "menu-seed:\(activeBundleId):\(path.joined(separator: " > ").lowercased())",
                    searchTerms: item.path + [scopedAppName],
                    executeLeaf: {
                        guard sourcePID != 0 else { return }
                        self.executeDockMenuAction(
                            sourcePID: sourcePID,
                            path: path,
                            shortcutChar: shortcutChar,
                            shortcutModifiers: shortcutMods
                        )
                    }
                )
                pills.append(pill)
            }
        }

        // Submenu drill-down: when query matches a non-leaf menu item, surface its leaf
        // children as direct-action pills ranked before everything else.
        if let subCtx = submenuGhostContext {
            let frontPID = AppDelegate.shared?.previousFrontmostApp?.processIdentifier ?? 0
            let visibleChildren =
                allowAppleMenuItems
                ? subCtx.children
                : subCtx.children.filter { !isAppleMenuItem($0) }
            for child in visibleChildren {
                let path = child.path
                let pid  = child.sourcePID != 0 ? child.sourcePID : frontPID
                let sc   = child.shortcutChar
                let mod  = child.shortcutModifiers
                var pill = DockPill(
                    id: "submenu-child-\(child.id)",
                    name: child.title,
                    icon: menuSymbol(for: child),
                    accentColorName: "blue",
                    badge: subCtx.parent.title,
                    execute: {
                        guard pid != 0 else { return }
                        self.executeDockMenuAction(
                            sourcePID: pid, path: path,
                            shortcutChar: sc, shortcutModifiers: mod
                        )
                    }
                )
                pill.menuItemImage = resolvedMenuIcon(for: child)
                pill.menuItemName  = child.title
                pill.menuContext   = subCtx.parent.title
                pill.sourceBundleId = activeBundleId
                pill.sourceAppName  = scopedAppName
                pill.rankingKind    = "submenuChild"
                pill.isEnabled      = true
                pill.rankingScore   = 1_000  // pin above everything else
                pills.append(pill)
            }
        }

        if let scopedAppLaunchPill {
            pills.append(scopedAppLaunchPill)
        }

        if let messagesSemanticIntentPill {
            pills.append(messagesSemanticIntentPill)
        }

        if let mailSemanticSearchPill {
            pills.append(mailSemanticSearchPill)
        }

        if let appWindowSemanticPill {
            pills.append(appWindowSemanticPill)
        }

        if let chatGPTNewChatPill {
            pills.append(chatGPTNewChatPill)
        }

        pills.append(contentsOf: rawFinderFilePills.map { pill in
            var enriched = pill
            if enriched.rankingKind.isEmpty {
                enriched.rankingKind = "finderSelection"
            }
            enriched.sourceBundleId = enriched.sourceBundleId.isEmpty ? "com.apple.finder" : enriched.sourceBundleId
            enriched.sourceAppName = enriched.sourceAppName.isEmpty ? "Finder" : enriched.sourceAppName
            if enriched.searchTerms.isEmpty {
                enriched.searchTerms = [enriched.name, enriched.badge ?? "", "finder", "files"]
            }
            if enriched.trackingIdentifier.isEmpty {
                enriched.trackingIdentifier = "finder-selection:\(normalizedDockPillText(enriched.name))"
            }
            return enriched
        })

        pills.append(contentsOf: rawFinderSelectionMenuPills)

        pills.append(contentsOf: rawFinderHomeFolderPills)

        pills.append(contentsOf: rawAttachedFinderFolderPills)

        pills.append(contentsOf: semanticFinderPills)

        pills.append(contentsOf: semanticFinderQuickActionPills)

        pills.append(contentsOf: payloadActionPills.map { pill in
            var enriched = pill
            if enriched.rankingKind.isEmpty {
                enriched.rankingKind = "payload"
            }
            if enriched.searchTerms.isEmpty {
                enriched.searchTerms = [enriched.name, enriched.badge ?? ""]
            }
            if enriched.trackingIdentifier.isEmpty {
                enriched.trackingIdentifier = "payload:\(normalizedDockPillText(enriched.name))"
            }
            return enriched
        })

        let dedupeMenuItems: ([AXMenuItem]) -> [AXMenuItem] = { items in
            var seen = Set<String>()
            var deduped: [AXMenuItem] = []
            for item in items {
                let key = item.path.joined(separator: " > ").lowercased()
                guard !key.isEmpty, !seen.contains(key) else { continue }
                seen.insert(key)
                deduped.append(item)
            }
            return deduped
        }

        let persistentMenuMatches: (NSRunningApplication, String, Int) -> [AXMenuItem] = {
            app, query, limit in
            AppMenuCapabilityCache.shared.menuItems(for: app, query: query, maxResults: limit)
        }
        let persistentClosedAppMatches: (String, String, String, Int) -> [AXMenuItem] = {
            bundleId, appName, query, limit in
            AppMenuCapabilityCache.shared.menuItems(
                bundleIdentifier: bundleId,
                appName: appName,
                processIdentifier: 0,
                query: query,
                maxResults: limit
            )
        }
        let menuItemsAllowedForCurrentScope: ([AXMenuItem]) -> [AXMenuItem] = { items in
            guard !allowAppleMenuItems else { return items }
            return items.filter { !isAppleMenuItem($0) }
        }
        let menuItemMatchesQuery: (AXMenuItem, String) -> Bool = { item, query in
            let normalizedQuery = normalizedDockPillText(query)
            guard !normalizedQuery.isEmpty else { return true }
            let corpora = ([item.title] + item.path)
                .map(normalizedDockPillText)
                .filter { !$0.isEmpty }
            if corpora.contains(normalizedQuery) { return true }
            if corpora.contains(where: { $0.hasPrefix(normalizedQuery) || $0.contains(normalizedQuery) }) {
                return true
            }

            let queryTokens = Set(dockPillTokens(normalizedQuery))
            guard !queryTokens.isEmpty else { return false }
            let corpusTokens = Set(corpora.flatMap(dockPillTokens))
            if !queryTokens.intersection(corpusTokens).isEmpty { return true }

            for qt in queryTokens where qt.count >= 4 {
                for ct in corpusTokens where ct.count >= 4 {
                    if pillEditDistance(qt, ct) <= 2 { return true }
                }
            }
            return false
        }
        let pureScopeMenuLimit = 10
        let pureScopeCandidateLimit = 12
        let scopedRunningMenuMatches:
            (NSRunningApplication, String, Bool) -> [AXMenuItem] = { app, filterQ, preferCached in
                let pid = app.processIdentifier
                let cachedMatches = crossAppMenuItems.filter { item in
                    item.sourcePID == pid
                        && menuItemMatchesQuery(item, filterQ)
                }
                let persistentMatches = persistentMenuMatches(
                    app,
                    filterQ,
                    preferCached ? pureScopeCandidateLimit : 24
                )
                let matches = dedupeMenuItems(
                    menuItemsAllowedForCurrentScope(cachedMatches + persistentMatches)
                )
                return orderedScopedMenuMatches(
                    matches,
                    filterQuery: filterQ,
                    limit: preferCached ? pureScopeMenuLimit : 16
                )
            }
        let scopedClosedMenuMatches:
            (String, String, String, Bool) -> [AXMenuItem] = { bundleId, appName, filterQ, preferCached in
                let matches = dedupeMenuItems(
                    menuItemsAllowedForCurrentScope(
                        persistentClosedAppMatches(
                            bundleId,
                            appName,
                            filterQ,
                            preferCached ? pureScopeCandidateLimit : 24
                        )
                    )
                )
                return orderedScopedMenuMatches(
                    matches,
                    filterQuery: filterQ,
                    limit: preferCached ? pureScopeMenuLimit : 16
                )
            }

        // Live menu items: primary (frontmost app) + optional cross-app when query targets another app
        let menuMatches: [AXMenuItem] = {
            if let installedMenuTarget {
                let filterQ = installedMenuTarget.actionQuery
                let preferCached = isExplicitAppScope && filterQ.isEmpty
                let targetApp = NSWorkspace.shared.runningApplications.first(where: {
                    $0.bundleIdentifier == installedMenuTarget.bundleId && !$0.isTerminated
                })
                if let targetApp {
                    return scopedRunningMenuMatches(targetApp, filterQ, preferCached)
                }
                return scopedClosedMenuMatches(
                    installedMenuTarget.bundleId,
                    installedMenuTarget.appName,
                    filterQ,
                    preferCached
                )
            }
            if let pinnedTarget = l2.targetApp,
                let targetApp = NSWorkspace.shared.runningApplications.first(where: {
                    $0.bundleIdentifier == pinnedTarget.bundleId
                })
            {
                let filterQ = scopedSearchQuery
                return scopedRunningMenuMatches(
                    targetApp,
                    filterQ,
                    isExplicitAppScope && filterQ.isEmpty
                )
            }
            if let pinnedTarget = l2.targetApp {
                let matches = scopedClosedMenuMatches(
                    pinnedTarget.bundleId,
                    pinnedTarget.name,
                    scopedSearchQuery,
                    isExplicitAppScope && scopedSearchQuery.isEmpty
                )
                if !matches.isEmpty {
                    return matches
                }
            }
            if let explicitAppTarget,
                let targetApp = NSWorkspace.shared.runningApplications.first(where: {
                    $0.bundleIdentifier == explicitAppTarget.bundleId
                })
            {
                let filterQ = explicitAppTarget.actionQuery
                return scopedRunningMenuMatches(
                    targetApp,
                    filterQ,
                    isExplicitAppScope && filterQ.isEmpty
                )
            }
            if let explicitAppTarget {
                let filterQ = explicitAppTarget.actionQuery
                let matches = scopedClosedMenuMatches(
                    explicitAppTarget.bundleId,
                    explicitAppTarget.appName,
                    filterQ,
                    isExplicitAppScope && filterQ.isEmpty
                )
                if !matches.isEmpty {
                    return matches
                }
            }
            // Check if query starts with a known app name → cross-app mode (requires Cross-App Connect)
            if settings.crossAppPills, let (targetApp, actionQuery) = detectCrossAppQuery(q) {
                let filterQ = actionQuery.isEmpty ? q : actionQuery
                let candidateLimit = filterQ.isEmpty ? 80 : 24
                let cachedMatches = crossAppMenuItems.filter { item in
                    item.sourcePID == targetApp.processIdentifier
                        && menuItemMatchesQuery(item, filterQ)
                }
                let matches = dedupeMenuItems(
                    menuItemsAllowedForCurrentScope(
                        cachedMatches + persistentMenuMatches(targetApp, filterQ, candidateLimit)
                    )
                )
                return orderedScopedMenuMatches(matches, filterQuery: filterQ, limit: 16)
            }
            // Default: frontmost app's real menu items first — query-time AX search is primary.
            let cachedMatches = liveMenuItems.filter { item in
                menuItemMatchesQuery(item, q)
            }
            let persistentMatches: [AXMenuItem] = {
                guard let app = AppDelegate.shared?.previousFrontmostApp else { return [] }
                return persistentMenuMatches(app, q, 24)
            }()
            let matches = dedupeMenuItems(
                menuItemsAllowedForCurrentScope(cachedMatches + persistentMatches)
            )
            return Array(
                matches.sorted {
                    let aFav = favs.contains($0.title) ? 0 : 1
                    let bFav = favs.contains($1.title) ? 0 : 1
                    if aFav != bFav { return aFav < bFav }
                    let aTitle = $0.title.lowercased().hasPrefix(q) ? 0 : 1
                    let bTitle = $1.title.lowercased().hasPrefix(q) ? 0 : 1
                    if aTitle != bTitle { return aTitle < bTitle }
                    return $0.path.count < $1.path.count
                }.prefix(16))
        }()

        // Context-reactive pills — menu items that just became enabled after a selection change.
        // Only shown when the user hasn't typed a query (they'd surface via menuMatches otherwise).
        if q.isEmpty && !shouldSuppressMenuForContext && menuMatches.isEmpty
            && !contextMenuPills.isEmpty
        {
            for item in menuItemsAllowedForCurrentScope(contextMenuPills) {
                let path = item.path
                let sourcePID =
                    item.sourcePID != 0
                    ? item.sourcePID
                    : (AppDelegate.shared?.previousFrontmostApp?.processIdentifier ?? 0)
                let sc = item.shortcutChar
                let mod = item.shortcutModifiers
                let badge: String? =
                    item.shortcutDisplay ?? (path.count >= 2 ? path[path.count - 2] : nil)
                let pill = makeMenuDockPill(
                    id: "ctx-menu-\(item.id)",
                    item: item,
                    sourceBundleId: scopedBundleId,
                    sourceAppName: scopedAppName,
                    accentColorName: "blue",
                    badge: badge,
                    trackingIdentifier: "ctx-menu:\(scopedBundleId):\(path.joined(separator: " > ").lowercased())",
                    searchTerms: item.path + [scopedAppName],
                    executeLeaf: {
                        guard sourcePID != 0 else { return }
                        self.executeDockMenuAction(
                            sourcePID: sourcePID,
                            path: path,
                            shortcutChar: sc,
                            shortcutModifiers: mod
                        )
                    }
                )
                pills.append(pill)
            }
        }

        let visibleMenuMatches: [AXMenuItem] = {
            if shouldSuppressMenuForContext { return [] }
            return hasStrongContextQuery ? Array(menuMatches.prefix(6)) : menuMatches
        }()

        for result in ctxExts {
            let ext = result.ilExtension
            let ctx = currentContext
            var pill = DockPill(
                id: "ctx-\(ext.id)", name: ext.name,
                icon: ext.icon, accentColorName: "teal", badge: nil,
                execute: { Task { await executeL2Extension(ext, context: ctx) } })
            pill.rankingKind = "contextExtension"
            pill.sourceBundleId = scopedBundleId
            pill.sourceAppName = scopedAppName
            pill.trackingIdentifier = "ctxext:\(ext.id)"
            pill.searchTerms = [ext.name]
            pills.append(pill)
        }

        for sc in quickActions {
            var pill = DockPill(
                id: "qa-\(sc.id)", name: sc.name,
                icon: sc.iconName, accentColorName: nil, badge: nil,
                execute: { executeAppShortcut(sc) })
            pill.rankingKind = "quickAction"
            pill.sourceBundleId = scopedBundleId
            pill.sourceAppName = scopedAppName
            pill.trackingIdentifier = "quick:\(sc.id)"
            pill.searchTerms = [sc.name]
            pills.append(pill)
        }
        for ext in userScriptExtensions {
            let icon = ext.scriptLanguage?.systemImage ?? "terminal"
            let displayName = ext.toolName.replacingOccurrences(of: "-", with: " ").capitalized
            var pill = DockPill(
                id: "usr-script-\(ext.id.uuidString)",
                name: displayName,
                icon: icon,
                accentColorName: "green",
                badge: "Script",
                execute: { executeAppToolExtension(ext, launchQuery: scopedSearchQuery) }
            )
            pill.rankingKind = "userExtension"
            pill.sourceBundleId = scopedBundleId
            pill.sourceAppName = scopedAppName
            pill.trackingIdentifier = "userext:\(scopedAppKey):\(ext.id.uuidString)"
            pill.searchTerms = [displayName, ext.toolName, ext.aiHint] + ext.profile.capabilities + ext.profile.exampleCommands
            pills.append(pill)
        }
        for package in visibleCLIPackages {
            let isTUI = TerminalAIBridge.shared.isTUICommand(package.command)
            let icon = isTUI ? "terminal.fill" : "chevron.left.forwardslash.chevron.right"
            let displayName = package.name.isEmpty ? package.command : package.name
            var pill = DockPill(
                id: "cli-\(scopedBundleId)-\(package.command)",
                name: displayName,
                icon: icon,
                accentColorName: "green",
                badge: "CLI",
                execute: { openCLIToolPanel(for: package) }
            )
            pill.rankingKind = "cliTool"
            pill.sourceBundleId = scopedBundleId
            pill.sourceAppName = scopedAppName
            pill.trackingIdentifier = "cli:\(scopedBundleId):\(package.command)"
            pill.searchTerms =
                [displayName, package.command, package.description]
                + package.keywords
                + package.subcommands
                + package.taskCategories
                + Array(package.usageExamples.prefix(3))
            pills.append(pill)

            for sub in package.subcommands.prefix(4) {
                let fullCmd = "\(package.command) \(sub)"
                var subPill = DockPill(
                    id: "cli-sub-\(scopedBundleId)-\(fullCmd)",
                    name: sub,
                    icon: icon,
                    accentColorName: "green",
                    badge: package.command,
                    execute: { attachCLIToolToCurrentDock(command: fullCmd, package: package, runImmediately: true) }
                )
                subPill.rankingKind = "cliTool"
                subPill.sourceBundleId = scopedBundleId
                subPill.sourceAppName = scopedAppName
                subPill.trackingIdentifier = "cli-sub:\(scopedBundleId):\(fullCmd)"
                subPill.searchTerms = [sub, fullCmd, displayName, package.command]
                pills.append(subPill)
            }
        }
        for tool in appTools {
            var pill = DockPill(
                id: "tool-\(tool.toolName)", name: tool.displayName,
                icon: tool.icon, accentColorName: "indigo", badge: nil,
                execute: {
                    l2.chatMessages.append(AIChatMessage(role: .user, content: tool.displayName))
                    l2.isLoading = true
                    Task {
                        let (ok, out) = await L2ExtensionManager.shared.execute(
                            toolName: tool.toolName, arguments: [:])
                        await MainActor.run {
                            let msg =
                                ok
                                ? (out.isEmpty ? "✅ \(tool.displayName) done." : out)
                                : "❌ \(tool.displayName) failed: \(out)"
                            l2.chatMessages.append(AIChatMessage(role: .assistant, content: msg))
                            l2.isLoading = false
                        }
                    }
                })
            pill.rankingKind = "tool"
            pill.sourceBundleId = scopedBundleId
            pill.sourceAppName = scopedAppName
            pill.trackingIdentifier = "tool:\(scopedBundleId):\(tool.toolName)"
            pill.searchTerms = [tool.displayName, tool.toolName]
            pills.append(pill)
        }
        for action in visibleAdapterActions {
            let cliCommand =
                action.cliToolCommand?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
            let pillName =
                action.type == .cliTool && !cliCommand.isEmpty
                ? cliCommand
                : action.name
            var pill = DockPill(
                id: "adapter-\(scopedBundleId)-\(action.id)",
                name: pillName,
                icon: action.icon,
                accentColorName: action.accentColor ?? "blue",
                badge: action.type == .menubar ? "Custom" : (action.type == .cliTool ? "CLI" : action.type.displayName),
                execute: {
                    if action.type == .cliTool, !cliCommand.isEmpty
                    {
                        attachCLIToolToCurrentDock(
                            command: cliCommand,
                            bundleIdentifier: scopedBundleId,
                            appName: scopedAppName
                        )
                        return
                    }
                    let capturedContext = effectiveAXContextForConversation()
                    Task {
                        AppInteractionStore.shared.record(
                            bundleId: scopedBundleId,
                            appName: scopedAppName,
                            query: scopedSearchQuery.isEmpty ? action.name : scopedSearchQuery,
                            kind: action.type == .pageJS ? .pageJS : .adapterAction,
                            actionId: action.id
                        )
                        let result = await adapterManager.execute(
                            action,
                            context: capturedContext,
                            targetBundleId: scopedBundleId,
                            query: scopedSearchQuery
                        )
                        await MainActor.run {
                            if action.type == .aiPrompt, result.0, !result.1.isEmpty {
                                searchState.query = result.1
                                isSearchFieldFocused = true
                            }
                        }
                    }
                })
            pill.rankingKind = action.type == .cliTool ? "cliTool" : "adapter"
            pill.sourceBundleId = scopedBundleId
            pill.sourceAppName = scopedAppName
            pill.trackingIdentifier = "adapter:\(scopedBundleId):\(action.id)"
            pill.searchTerms =
                [action.name, pillName, action.description, action.type.displayName, cliCommand]
                + action.triggers
            pills.append(pill)

            // For CLI tool adapter actions, also emit subcommand pills so the user
            // gets the same scannable help-command pills as standalone CLI packages.
            if action.type == .cliTool, !cliCommand.isEmpty,
               let pkg = terminalPackageManager.packages.first(where: {
                   $0.command.caseInsensitiveCompare(cliCommand) == .orderedSame
               })
            {
                for sub in pkg.subcommands.prefix(5) {
                    let fullCmd = "\(cliCommand) \(sub)"
                    var subPill = DockPill(
                        id: "adapter-sub-\(scopedBundleId)-\(fullCmd)",
                        name: sub,
                        icon: action.icon,
                        accentColorName: action.accentColor ?? "green",
                        badge: cliCommand,
                        execute: {
                            attachCLIToolToCurrentDock(
                                command: fullCmd,
                                package: pkg,
                                runImmediately: true
                            )
                        }
                    )
                    subPill.rankingKind = "cliTool"
                    subPill.sourceBundleId = scopedBundleId
                    subPill.sourceAppName = scopedAppName
                    subPill.trackingIdentifier = "adapter-sub:\(scopedBundleId):\(fullCmd)"
                    subPill.searchTerms = [sub, fullCmd, action.name, cliCommand] + pkg.keywords
                    pills.append(subPill)
                }
            }
        }

        if !useSeededMenuPills || hasStrongContextQuery {
            for item in visibleMenuMatches {
                let path = item.path
                let menuBundleId = activeBundleId
                let menuAppName = item.sourceAppName.isEmpty ? scopedAppName : item.sourceAppName
                let menuAppPath =
                    installedMenuTarget?.bundleId == menuBundleId
                    ? installedMenuTarget?.appPath
                    : allApplications.first { result in
                        Bundle(url: URL(fileURLWithPath: result.subtitle))?.bundleIdentifier
                            == menuBundleId
                    }?.subtitle
                let sourcePID =
                    item.sourcePID != 0
                    ? item.sourcePID
                    : (menuBundleId.isEmpty
                        ? (AppDelegate.shared?.previousFrontmostApp?.processIdentifier ?? 0)
                        : 0)
                // Only show source badge for cross-app items; Apple menu items are universal — no badge
                let isFrontmost =
                    sourcePID == (AppDelegate.shared?.previousFrontmostApp?.processIdentifier ?? 0)
                let pillBadge: String? = {
                    if isAppleMenuItem(item) { return nil }  // universal — no app badge
                    if !item.sourceAppName.isEmpty && !isFrontmost {
                        return item.sourceAppName  // cross-app badge
                    }
                    return path.count >= 2 ? path[path.count - 2] : nil  // parent menu name
                }()
                let shortcutChar = item.shortcutChar
                let shortcutMods = item.shortcutModifiers
                let shortcutHint = item.shortcutDisplay

                let isFav = favs.contains(item.title)
                var pill = makeMenuDockPill(
                    id: "menu-\(item.id)",
                    item: item,
                    sourceBundleId: menuBundleId,
                    sourceAppName: menuAppName,
                    accentColorName: isFav ? "yellow" : "gray",
                    badge: shortcutHint ?? pillBadge,
                    trackingIdentifier: "menu:\(menuBundleId):\(path.joined(separator: " > ").lowercased())",
                    searchTerms: item.path + [menuAppName],
                    executeLeaf: {
                        AppInteractionStore.shared.record(
                            bundleId: menuBundleId,
                            appName: menuAppName,
                            query: item.title,
                            kind: .menuItem,
                            actionId: path.joined(separator: " > ")
                        )
                        if sourcePID == 0, !menuBundleId.isEmpty {
                            executeCachedMenuAction(
                                bundleIdentifier: menuBundleId,
                                appName: menuAppName,
                                appPath: menuAppPath,
                                path: path,
                                shortcutChar: shortcutChar,
                                shortcutModifiers: shortcutMods
                            )
                            return
                        }
                        guard sourcePID != 0 else { return }
                        self.executeDockMenuAction(
                            sourcePID: sourcePID,
                            path: path,
                            shortcutChar: shortcutChar,
                            shortcutModifiers: shortcutMods
                        )
                    })
                pill.isFavourited = isFav
                if item.children.isEmpty, sourcePID != 0, item.title.lowercased().hasPrefix("share") {
                    pill = DockPill(
                        id: pill.id, name: pill.name,
                        icon: "square.and.arrow.up",
                        accentColorName: "blue",
                        badge: pill.badge,
                        execute: { showShareSheetForContext() })
                    pill.isShareAction = true
                    pill.isFavourited = isFav
                    pill.menuItemName = item.title
                    pill.sourceBundleId = menuBundleId
                    pill.sourceAppName = menuAppName
                    pill.menuContext = menuContextLabel(from: item.path)
                    pill.rankingKind = "menu"
                    pill.trackingIdentifier =
                        "menu:\(menuBundleId):\(path.joined(separator: " > ").lowercased())"
                    pill.searchTerms = item.path + [menuAppName, "share"]
                }
                pills.append(pill)
            }
        }
        if !isExplicitAppScope {
            if !(isGlobalContextActive && hasActiveDockContextSelection) {
                pills += crossAppPills
            }
        }
        let resolvedRulePills = AXTriggerRuleEngine.shared.evaluate(context: axContext)
        if !isExplicitAppScope {
            let filteredRulePills =
                q.isEmpty
                ? resolvedRulePills : resolvedRulePills.filter { $0.name.lowercased().contains(q) }
            pills += filteredRulePills.map { r in
                DockPill(
                    id: r.id, name: r.name, icon: r.icon, accentColorName: r.accentColor,
                    badge: nil, execute: r.execute)
            }
        }

        let rankingQuery = isExplicitAppScope ? scopedSearchQuery : q
        let ranked = rankDockPills(
            pills,
            rawQuery: q,
            rankingQuery: rankingQuery,
            scopedBundleId: scopedBundleId,
            scopedAppName: scopedAppName,
            isExplicitAppScope: isExplicitAppScope
        )
        // Treat menu enabled state as advisory. Some apps lazily validate menus only when
        // their native menu opens, so AX can report a runnable action as disabled.
        let enabled = ranked.filter { pill in
            if isStaleAvailabilityMenuPill(pill) { return true }
            if !q.isEmpty,
               (pill.rankingKind == "menu" || pill.rankingKind == "finderMenu"),
               dockPillHasQuerySignal(
                    pill,
                    query: rankingQuery,
                    rawQuery: q,
                    scopedBundleId: scopedBundleId,
                    scopedAppName: scopedAppName
               ) {
                return true
            }
            return pill.isEnabled || pill.rankingKind.isEmpty || pill.rankingKind == "appLaunch"
                || pill.rankingKind == "finderSelection" || pill.rankingKind == "payload"
                || pill.rankingKind == "cliTool" || pill.rankingKind == "tool"
                || pill.rankingKind == "userExtension" || pill.rankingKind == "submenuChild"
                || pill.rankingKind == "submenuParent"
        }

        // When global context has an active file/folder/text selection and no explicit app scope,
        // keep the Finder/menu surface broad. The selection state should feel like the native
        // menu bar after selecting a file: File/Edit/View/Go/Window/Help commands stay available,
        // while app launch/recent-app rows are still removed by the selection-scoped filter.
        guard isGlobalContextActive && hasActiveDockContextSelection && !isExplicitAppScope else {
            return enabled
        }
        return selectionScopedDockPills(enabled)
    }

    // MARK: - System Settings Deep-Link Pills

    private func buildGlobalAppleMenuFallbackPills(query q: String) -> [DockPill] {
        let normalizedQuery = normalizedDockPillText(q)
        guard !normalizedQuery.isEmpty else { return [] }

        typealias AppleCommand = (name: String, aliases: [String], icon: String, action: () -> Void)
        let commands: [AppleCommand] = [
            ("About This Mac", ["about", "mac", "about this mac"], "laptopcomputer", {
                clickAppleMenuItem(named: "About This Mac")
            }),
            ("System Settings...", ["settings", "system settings", "preferences", "system preferences"], "gearshape", {
                NSWorkspace.shared.open(URL(fileURLWithPath: "/System/Applications/System Settings.app"))
            }),
            ("App Store...", ["app store", "updates", "software"], "app.badge", {
                NSWorkspace.shared.open(URL(fileURLWithPath: "/System/Applications/App Store.app"))
            }),
            ("Recent Items", ["recent", "recent items"], "clock.arrow.circlepath", {
                clickAppleMenuItem(named: "Recent Items")
            }),
            ("Force Quit...", ["force quit", "quit app", "force"], "exclamationmark.octagon", {
                clickAppleMenuItem(named: "Force Quit...")
            }),
            ("Sleep", ["sleep", "slee", "standby"], "moon", {
                runAppleMenuScript(#"tell application "System Events" to sleep"#)
            }),
            ("Restart...", ["restart", "reboot"], "arrow.clockwise.circle", {
                clickAppleMenuItem(named: "Restart...")
            }),
            ("Shut Down...", ["shutdown", "shut down", "power off"], "power", {
                clickAppleMenuItem(named: "Shut Down...")
            }),
            ("Lock Screen", ["lock", "lock screen"], "lock", {
                runAppleMenuScript(#"tell application "System Events" to keystroke "q" using {control down, command down}"#)
            }),
            ("Log Out...", ["log out", "logout", "sign out"], "rectangle.portrait.and.arrow.right", {
                clickAppleMenuItem(named: "Log Out...")
            })
        ]

        return commands.compactMap { command -> DockPill? in
            let haystack = ([command.name] + command.aliases)
                .map(normalizedDockPillText)
                .joined(separator: " ")
            let tokenMatch = normalizedQuery
                .split(separator: " ")
                .allSatisfy { haystack.contains($0) }
            guard haystack.contains(normalizedQuery) || tokenMatch else { return nil }

            var pill = DockPill(
                id: "apple-menu-fallback-\(normalizedDockPillText(command.name))",
                name: command.name,
                icon: command.icon,
                accentColorName: "gray",
                badge: "Apple Menu",
                execute: command.action
            )
            pill.menuContext = "Apple Menu"
            pill.rankingKind = "menu"
            pill.sourceAppName = "Apple Menu"
            pill.searchTerms = [command.name] + command.aliases
            pill.trackingIdentifier = "apple-menu:\(normalizedDockPillText(command.name))"
            pill.rankingScore = command.name.lowercased().hasPrefix(normalizedQuery) ? 600 : 420
            return pill
        }
    }

    private func clickAppleMenuItem(named itemName: String) {
        let escaped = itemName.replacingOccurrences(of: "\"", with: "\\\"")
        let script = """
        tell application "System Events"
            set frontProc to first application process whose frontmost is true
            click menu item "\(escaped)" of menu 1 of menu bar item 1 of menu bar 1 of frontProc
        end tell
        """
        runAppleMenuScript(script)
    }

    private func runAppleMenuScript(_ source: String) {
        Task.detached(priority: .userInitiated) {
            var error: NSDictionary?
            NSAppleScript(source: source)?.executeAndReturnError(&error)
            if let error {
                await MainActor.run {
                    AppToast.show(
                        error[NSAppleScript.errorMessage] as? String ?? "Apple menu action unavailable",
                        icon: "exclamationmark.triangle",
                        tint: .orange.opacity(0.9)
                    )
                }
            }
        }
    }

    /// When System Settings is frontmost, emit pills for every pane so the user can navigate
    /// directly via query (e.g. "wallpaper", "wifi", "bluetooth") without relying on menu items.
    private func buildSystemSettingsPills(
        query q: String,
        scopedBundleId: String? = nil,
        scopedAppName: String? = nil
    ) -> [DockPill] {
        guard frontmost.bundleID == "com.apple.systempreferences"
               || l2.targetApp?.bundleId == "com.apple.systempreferences"
               || scopedBundleId == "com.apple.systempreferences"
        else { return [] }

        typealias Pane = (name: String, terms: [String], url: String, icon: String)
        let panes: [Pane] = [
            ("Wallpaper",         ["background", "desktop", "display background", "wallpapper"],
             "x-apple.systempreferences:com.apple.Desktop-Settings.extension", "photo.on.rectangle"),
            ("Wi-Fi",             ["wifi", "network", "internet", "wireless", "wlan"],
             "x-apple.systempreferences:com.apple.Network-Settings.extension", "wifi"),
            ("Bluetooth",         ["bluetooth", "bt", "airdrop"],
             "x-apple.systempreferences:com.apple.BluetoothSettings", "bluetooth"),
            ("Display",           ["screen", "resolution", "brightness", "retina", "monitor"],
             "x-apple.systempreferences:com.apple.Display-Settings.extension", "display"),
            ("Notifications",     ["notification", "alerts", "banners", "badges", "do not disturb"],
             "x-apple.systempreferences:com.apple.Notifications-Settings.extension", "bell.badge"),
            ("Sound",             ["audio", "volume", "speakers", "microphone", "mute", "output", "input"],
             "x-apple.systempreferences:com.apple.Sound-Settings.extension", "speaker.wave.2"),
            ("Focus",             ["focus", "do not disturb", "dnd", "quiet hours"],
             "x-apple.systempreferences:com.apple.Focus-Settings.extension", "moon"),
            ("Appearance",        ["dark mode", "light mode", "accent", "theme", "sidebar", "interface"],
             "x-apple.systempreferences:com.apple.Appearance-Settings.extension", "paintbrush"),
            ("Accessibility",     ["accessibility", "zoom", "voiceover", "voice over", "captions", "a11y"],
             "x-apple.systempreferences:com.apple.Accessibility-Settings.extension", "accessibility"),
            ("Privacy & Security",["privacy", "security", "permissions", "access", "firewall", "location"],
             "x-apple.systempreferences:com.apple.settings.PrivacySecurity.extension", "lock.shield"),
            ("Lock Screen",       ["lock", "screensaver", "sleep", "password", "login screen"],
             "x-apple.systempreferences:com.apple.Lock-Screen-Settings.extension", "lock"),
            ("Keyboard",          ["keyboard", "typing", "shortcuts", "function keys", "dictation", "fn"],
             "x-apple.systempreferences:com.apple.Keyboard-Settings.extension", "keyboard"),
            ("Mouse",             ["mouse", "scroll", "click", "pointer", "cursor", "tracking"],
             "x-apple.systempreferences:com.apple.Mouse-Settings.extension", "cursorarrow"),
            ("Trackpad",          ["trackpad", "gesture", "swipe", "pinch", "tap"],
             "x-apple.systempreferences:com.apple.Trackpad-Settings.extension", "hand.point.up"),
            ("Battery",           ["battery", "power", "energy", "charging", "low power"],
             "x-apple.systempreferences:com.apple.Battery-Settings.extension", "battery.100"),
            ("Software Update",   ["update", "macos update", "os update", "upgrade"],
             "x-apple.systempreferences:com.apple.Software-Update-Settings.extension", "arrow.down.circle"),
            ("iCloud",            ["icloud", "cloud", "sync", "apple id", "account"],
             "x-apple.systempreferences:com.apple.Internet-Settings.extension", "icloud"),
            ("General",           ["general", "sharing", "storage", "airdrop", "handoff"],
             "x-apple.systempreferences:com.apple.GeneralSettings.extension", "gearshape"),
            ("Users & Groups",    ["user", "account", "group", "login", "password", "guest"],
             "x-apple.systempreferences:com.apple.Users-Groups-Settings.extension", "person.2"),
            ("Date & Time",       ["date", "time", "clock", "timezone", "24 hour"],
             "x-apple.systempreferences:com.apple.Date-Time-Settings.extension", "clock"),
        ]

        return panes.map { pane in
            let urlStr = pane.url
            var pill = DockPill(
                id: "syspref:\(urlStr)",
                name: pane.name,
                icon: pane.icon,
                accentColorName: "blue",
                badge: nil,
                execute: {
                    if let u = URL(string: urlStr) { NSWorkspace.shared.open(u) }
                }
            )
            pill.rankingKind = "quickAction"
            pill.sourceBundleId = "com.apple.systempreferences"
            pill.sourceAppName = scopedAppName ?? "System Settings"
            pill.searchTerms = [pane.name.lowercased()] + pane.terms
            return pill
        }
    }

    // MARK: - Safari Command Pills

    /// Builds DockPill items for page-level Safari commands (search, click, open, highlight, etc.).
    /// Menu items (Show Next Tab, Pin Tab, etc.) are skipped here — the AX system already shows them.
    private func buildSafariCommandPills(query q: String) -> [DockPill] {
        guard !q.isEmpty else { return [] }
        let isSafariActive = frontmost.bundleID == "com.apple.Safari"
            || SafariBrowserBridge.shared.safariContextIfFresh() != nil
        guard isSafariActive else { return [] }
        guard let cmd = SafariCommandBridge.shared.parseIntent(q) else { return [] }
        // AX menu system already shows menu items as pills — skip duplicates
        if case .menuItem = cmd { return [] }

        let (pillName, pillIcon) = safariCommandPillDisplay(cmd, rawQuery: q)
        let capturedQ = q
        var pill = DockPill(
            id: "safari-cmd-\(q.lowercased().prefix(40))",
            name: pillName,
            icon: pillIcon,
            accentColorName: "blue",
            badge: "Safari",
            execute: {
                Task {
                    let result = await SafariCommandBridge.shared.execute(cmd)
                    await MainActor.run {
                        if self.l2.chatMessages.last?.content != capturedQ {
                            self.l2.chatMessages.append(AIChatMessage(role: .user, content: capturedQ))
                        }
                        self.l2.chatMessages.append(AIChatMessage(role: .assistant, content: "🌐 \(result)"))
                        self.searchState.query = ""
                        if !self.isSearchBarExpanded {
                            withAnimation(.spring(response: 0.3, dampingFraction: 0.8)) {
                                self.isSearchBarExpanded = true
                            }
                            self.updateWindowSize()
                        }
                    }
                }
            }
        )
        pill.rankingKind = "safariCommand"
        pill.sourceBundleId = "com.apple.Safari"
        pill.sourceAppName = "Safari"
        pill.searchTerms = [pillName, q, "safari"]
        pill.trackingIdentifier = "safari-cmd:\(q.lowercased().prefix(40))"
        return [pill]
    }

    private func safariCommandPillDisplay(_ cmd: SafariCommand, rawQuery: String) -> (name: String, icon: String) {
        switch cmd {
        case .menuItem(_, let item):
            return (item, "menubar.rectangle")
        case .openTab(let url):
            return ("Open \(url)", "safari")
        case .searchNewTab(let query, let engine):
            return ("Search \"\(query)\" — \(engine.rawValue.capitalized)", "magnifyingglass")
        case .closeCurrentTab:
            return ("Close Tab", "xmark.circle")
        case .runPageJS:
            let isPlay = rawQuery.lowercased().hasPrefix("play ") || rawQuery.lowercased().hasPrefix("watch ")
            let term = rawQuery
                .replacingOccurrences(of: "^(click|tap|press|play|watch|open video)\\s+", with: "", options: .regularExpression)
                .replacingOccurrences(of: " from this page", with: "")
                .replacingOccurrences(of: " on this page", with: "")
                .trimmingCharacters(in: .whitespacesAndNewlines)
            if isPlay {
                return ("Play \"\(term)\"", "play.circle")
            }
            return ("Click \"\(term)\"", "cursorarrow.click.2")
        case .highlightText(let text):
            return ("Highlight \"\(text)\"", "highlighter")
        case .scrollToSelector(let css):
            return ("Scroll to \(css)", "arrow.down.to.line")
        case .scrapeSelector(let css, _):
            return ("Scrape \(css)", "doc.text.magnifyingglass")
        case .extractPrices:
            return ("Extract Prices", "tag")
        case .fillField(let sel, _):
            return ("Fill \(sel)", "pencil.line")
        case .clickElement(let sel):
            return ("Click \(sel)", "cursorarrow.click")
        case .answerInfo:
            return ("Safari Info", "info.circle")
        }
    }

    /// Execute the currently focused pill. Only call when l2.focusedPillIndex is non-nil.
    /// Clears the input field afterwards so the dock is ready for the next command.
    func executeFirstOrFocusedPill() {
        let q = searchState.query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        let pills = buildDockPills(query: q)
        guard let idx = l2.focusedPillIndex, idx < pills.count else { return }
        let pill =
            pills[idx].isSeparator
            ? pills.first(where: { !$0.isSeparator }) ?? pills[idx]
            : pills[idx]
        executeDockPill(pill)
        // Clear input and focus so dock returns to default state
        searchState.query = ""
        l2.focusedPillIndex = nil
    }

    private func executeDockPill(_ pill: DockPill) {
        UsageTracker.shared.recordAccess(for: defaultDockPillTrackingIdentifier(pill))
        pill.execute()
    }

    private func isStaleAvailabilityMenuPill(_ pill: DockPill) -> Bool {
        pill.rankingKind == "menu" || pill.rankingKind == "finderMenu"
    }

    private func directAppActionQuery(for query: String) -> String? {
        let q = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard !q.isEmpty else { return nil }
        guard isGlobalContextActive || l2.targetApp != nil else { return nil }
        guard !(isGlobalContextActive && hasActiveDockContextSelection) else { return nil }
        if let target = L2AppActionRouter.shared.explicitAppTarget(for: q) {
            return target.actionQuery
        }
        if let target = installedAppMenuTarget(
            for: q,
            includeAppsWithoutMenuSnapshot: contextDockInstalledAppScopeMatching,
            allowPrefixAlias: contextDockInstalledAppScopeMatching
        ) {
            return target.actionQuery
        }
        if let partial = l2.appCompletion ?? bestL2PartialAppCompletion(for: q),
            !partial.actionQuery.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
        {
            return partial.actionQuery
        }
        if l2.targetApp != nil {
            return q
        }
        return nil
    }

    @discardableResult
    private func focusFirstDockPillIfAvailable(for query: String) -> Bool {
        let normalizedQuery = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        let pillQuery = shouldUseFinderSearchPopover(for: normalizedQuery) ? "" : normalizedQuery
        let pills = buildDockPills(query: pillQuery)
        guard let firstVisibleIndex = pills.firstIndex(where: { !$0.isSeparator }) else {
            return false
        }

        l2.pillNavViaKeyboard = true
        l2.focusedPillIndex = firstVisibleIndex
        return true
    }

    private func isDirectAppActionQuery(_ actionQuery: String) -> Bool {
        let normalized = actionQuery
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .lowercased()
            .replacingOccurrences(of: "[^a-z0-9]+", with: " ", options: .regularExpression)
            .trimmingCharacters(in: .whitespacesAndNewlines)
        guard !normalized.isEmpty else { return false }
        let tokens = normalized.split(separator: " ")
        return (1...2).contains(tokens.count)
    }

    @discardableResult
    private func executeFocusedOrDirectAppPillIfNeeded() -> Bool {
        let q = searchState.query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        let pills = buildDockPills(query: q)
        guard !pills.isEmpty else { return false }

        if let idx = l2.focusedPillIndex, idx < pills.count {
            executeFirstOrFocusedPill()
            return true
        }

        guard let actionQuery = directAppActionQuery(for: q),
            isDirectAppActionQuery(actionQuery)
        else {
            return false
        }

        let defaultPill = pills.first(where: { !$0.isSeparator })
        let isPureScopedSelection: Bool = {
            guard let target = l2.targetApp else { return false }
            let aliases = dockPillAppAliases(appName: target.name, bundleId: target.bundleId)
            return aliases.contains(q)
        }()
        let pill =
            isPureScopedSelection
            ? (pills.first(where: { !$0.isSeparator && $0.rankingKind != "appLaunch" }) ?? defaultPill)
            : defaultPill
        guard let pill else { return false }

        let scope = resolveDockScope(for: q)
        let isScopedCLIQuery =
            pill.rankingKind == "cliTool"
            && scope.isExplicitAppScope
            && !scope.scopedSearchQuery.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
        if isScopedCLIQuery {
            return false
        }

        executeDockPill(pill)
        searchState.query = ""
        l2.focusedPillIndex = nil
        return true
    }

    @discardableResult
    private func executeFirstAttachedFinderFolderResultIfNeeded() -> Bool {
        let q = searchState.query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard !finderFolderQueryModeActive else { return false }
        guard !q.isEmpty, isFinderCurrentWindowSearchAttached() else { return false }
        let pills = buildDockPills(query: q)
        guard let pill = pills.first(where: {
            !$0.isSeparator
                && $0.sourceBundleId == "com.apple.finder"
                && ($0.rankingKind == "finderCurrent" || $0.rankingKind == "finderSearch")
        }) else { return false }

        pill.execute()
        l2.focusedPillIndex = nil
        return true
    }

    private func firstMatchingFinderFolderPill(for rawQuery: String? = nil) -> DockPill? {
        let q = (rawQuery ?? searchState.query)
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .lowercased()
        guard !q.isEmpty else { return nil }

        let pills = buildDockPills(query: q)
        let finderFolderKinds: Set<String> = ["finderGoTo", "finderCurrent", "finderSearch"]
        return pills.first(where: { pill in
            guard !pill.isSeparator else { return false }
            guard pill.sourceBundleId == "com.apple.finder" else { return false }
            guard finderFolderKinds.contains(pill.rankingKind) else { return false }
            guard pill.icon.localizedCaseInsensitiveContains("folder") else { return false }

            let name = pill.name
                .trimmingCharacters(in: .whitespacesAndNewlines)
                .lowercased()
            return name.hasPrefix(q) || name.contains(q)
        })
    }

    @discardableResult
    private func executeFirstMatchingFinderFolderPillIfNeeded() -> Bool {
        guard let pill = firstMatchingFinderFolderPill() else { return false }
        executeDockPill(pill)
        searchState.query = ""
        l2.focusedPillIndex = nil
        return true
    }

    @ViewBuilder
    private var l2UnifiedDockRow: some View {
        let q =
            isL2ContextActive
            ? searchState.query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased() : ""
        let pureGlobalAppSearch = shouldUsePureGlobalAppSearch
        let finderSearchPopoverActive = shouldUseFinderSearchPopover(for: q)
        let pillQuery = finderSearchPopoverActive ? "" : q
        let pills = pureGlobalAppSearch ? [] : currentVisibleDockPills(for: pillQuery)
        let explicitAppTarget =
            pillQuery.isEmpty ? nil : L2AppActionRouter.shared.appScopeTarget(for: pillQuery)

        VStack(alignment: .leading, spacing: 0) {

            // Active selection = files/text/URL right now (not stale clipboard)
            let hasActiveContextSelection = hasActiveDockContextSelection
            let hasAnySelection: Bool =
                hasActiveContextSelection || (showGlobalClipboardPill && !globalClipboardText.isEmpty)
            let globalAppMatches = currentGlobalAppMatches(for: q)
            let genericAppListQuery = isGenericApplicationListQuery(q)
            let preferFrontmostMenuResults =
                !genericAppListQuery
                && globalAppMatches.isEmpty
                && !q.isEmpty
                && isGlobalContextActive
                && !hasActiveContextSelection
                && l2.targetApp == nil
                && pills.contains { pill in
                    guard !pill.isSeparator else { return false }
                    return pill.rankingKind == "menu" || pill.rankingKind == "finderMenu"
                }
            let inlineGlobalScope =
                isGlobalContextActive && !hasActiveContextSelection && l2.targetApp == nil
                ? activeGlobalInlineDockScope(for: q)
                : nil
            let inlineGlobalAppScopeActive = inlineGlobalScope?.isExplicitAppScope == true
            let effectiveAppScope = inlineGlobalAppScopeActive
            let displayedGlobalAppMatches =
                effectiveAppScope
                ? []
                : globalAppMatches
            let scopedMenuListContext: (appName: String, actionQuery: String)? = {
                if let scope = inlineGlobalScope, scope.isExplicitAppScope {
                    return (scope.scopedAppName, scope.scopedSearchQuery)
                }
                return nil
            }()
            // Single source of truth for menus and cross-app groups.
            // globalGroupedListNavigationState already applies the strict filter and handles all
            // modes (frontmost, explicit app scope, cross-app). Using it here ensures the view
            // and keyboard navigation always operate on identical data.
            let globalNavState: GlobalGroupedListNavigationState? =
                (pureGlobalAppSearch || effectiveAppScope) && !q.isEmpty
                ? globalGroupedListNavigationState(for: q) : nil
            // Flatten frontmost groups back to pills so globalAppSearchListView can re-group
            // (it uses groupMenuPillsByTitle internally for chip display logic).
            let globalMenuPills: [DockPill] = globalNavState?.menuGroups.flatMap(\.allPills) ?? []
            let globalCrossAppGroups: [AppMenuGroup] = globalNavState?.appMenuGroups ?? []
            let globalNavIsScopedAppMenus =
                globalNavState?.appResults.isEmpty == true
                && !(globalNavState?.appMenuGroups.isEmpty ?? true)
            // In global context, only hide app pills when there's a real active selection (not just clipboard)
            let showPinnedRow = q.isEmpty
                && l2.targetApp == nil
                && (pills.isEmpty || (isGlobalContextActive && !hasActiveContextSelection))
            // When files/folders/text are actively selected, show their context actions —
            // not app launchers. App search only shows when there is no active selection.
            let showGlobalAppSearch =
                (pureGlobalAppSearch && !q.isEmpty && !preferFrontmostMenuResults) || effectiveAppScope
            // Placeholder hint: show "Open [App] to enable menu search" when the scoped app
            // has no cached menus and isn't currently running.
            let scopedAppLaunchHint: (bundleId: String, appName: String, appPath: String?)? = {
                let (bundleId, appName): (String, String) = {
                    if let scope = inlineGlobalScope, scope.isExplicitAppScope {
                        return (scope.scopedBundleId, scope.scopedAppName)
                    }
                    return ("", "")
                }()
                guard !bundleId.isEmpty, globalMenuPills.isEmpty else { return nil }
                guard !AppMenuCapabilityCache.shared.hasSnapshot(bundleIdentifier: bundleId) else {
                    return nil
                }
                let isRunning = NSWorkspace.shared.runningApplications.contains {
                    $0.bundleIdentifier == bundleId && !$0.isTerminated
                }
                guard !isRunning else { return nil }
                let path = allApplications.first {
                    Bundle(url: URL(fileURLWithPath: $0.subtitle))?.bundleIdentifier == bundleId
                }?.subtitle ?? NSWorkspace.shared.urlForApplication(withBundleIdentifier: bundleId)?.path
                return (bundleId, appName, path)
            }()

            HStack(spacing: 6) {
                // Submenu locked mode: show vertical child suggestion list instead of pills
                if let locked = lockedSubmenuParent, let subCtx = submenuGhostContext {
                    submenuDropdownView(parent: locked, children: subCtx.children, prefix: subCtx.childPrefix)
                        .transition(.asymmetric(
                            insertion: .opacity.combined(with: .scale(scale: 0.97, anchor: settings.effectiveDockAtBottom ? .bottom : .top)),
                            removal: .opacity.combined(with: .scale(scale: 0.97, anchor: settings.effectiveDockAtBottom ? .bottom : .top))
                        ))
                } else if showGlobalAppSearch {
                    globalAppSearchListView(
                        query: q,
                        matches: globalNavIsScopedAppMenus ? [] : displayedGlobalAppMatches,
                        menuPills: globalMenuPills,
                        appMenuGroups: globalCrossAppGroups,
                        launchHint: scopedAppLaunchHint,
                        scopedMenuAppName: scopedMenuListContext?.appName,
                        scopedMenuActionQuery: scopedMenuListContext?.actionQuery ?? "",
                        menuFirst: intentFavorsMenu(q) && (!globalMenuPills.isEmpty || !globalCrossAppGroups.isEmpty)
                    )
                        .transition(.opacity.combined(with: .scale(scale: 0.98)))
                } else if showPinnedRow {
                    pinnedAndRecentAppsRow
                        .transition(.opacity.combined(with: .scale(scale: 0.98)))
                } else {
                    dockPillListView(pills: pills)
                }
            }
            .animation(.spring(response: 0.2, dampingFraction: 0.8), value: hasAnySelection)
        }
        .padding(.horizontal, 2)
        .animation(
            .spring(response: 0.22, dampingFraction: 0.85), value: explicitAppTarget?.bundleId
        )
        .onChange(of: pillQuery) { newQuery in
            l2.focusedPillIndex = nil
            focusedAppPillIndex = nil
            if shouldUsePureGlobalAppSearch, !newQuery.isEmpty, allApplications.isEmpty, !searchState.isLoadingApps {
                loadApplicationsInBackground()
            }
            if shouldUsePureGlobalAppSearch {
                l2.appCompletion = nil
                l2.showResultsPopover = false
                if globalInlineAppScope == nil {
                    scheduleGlobalAppMatchRebuild(query: newQuery, delayNanoseconds: 0)
                } else {
                    scheduleGlobalGroupedListRebuild(query: newQuery, delayNanoseconds: 18_000_000)
                }
                // If query resolves to a running app with no cached menus, warm on the fly
                if !newQuery.isEmpty {
                    let scope = resolveDockScope(for: newQuery)
                    if scope.isExplicitAppScope {
                        warmMenuCacheIfNeeded(bundleId: scope.scopedBundleId, appName: scope.scopedAppName)
                    }
                }
                return
            }
            if newQuery != lastPillQuery {
                scheduleDockPillRebuild(
                    query: newQuery,
                    delayNanoseconds: 20_000_000,
                    refreshContext: false
                )
            }
        }
        .onAppear {
            if shouldUsePureGlobalAppSearch, !pillQuery.isEmpty, allApplications.isEmpty, !searchState.isLoadingApps {
                loadApplicationsInBackground()
            }
            if shouldUsePureGlobalAppSearch {
                if globalInlineAppScope == nil {
                    scheduleGlobalAppMatchRebuild(query: pillQuery, delayNanoseconds: 0)
                } else {
                    scheduleGlobalGroupedListRebuild(query: pillQuery, delayNanoseconds: 0)
                }
                return
            }
            scheduleDockPillRebuild(query: pillQuery, delayNanoseconds: 0)
        }
        .gesture(
            DragGesture(minimumDistance: 20)
                .onEnded { value in
                    let dy = value.translation.height
                    let dx = value.translation.width

                    guard abs(dy) > abs(dx) else { return }
                    guard !isExplicitAppScopeLocked else { return }

                    if dy > 30 {
                        // Swipe DOWN → Global Context (manual, should not auto-return)
                        if !isGlobalContextActive {
                            withAnimation(.spring(response: 0.25, dampingFraction: 0.8)) {
                                globalContextActivation = GlobalContextActivation(autoActivated: false)
                            }
                            scheduleDockPillRebuild(query: lastPillQuery, delayNanoseconds: 0)
                        }
                    } else if dy < -30 {
                        // Swipe UP
                        if isGlobalContextActive {
                            // Exit Global Context → return to Context Dock
                            dismissContextAndReturnToDock()
                        } else if !showMediaLayer && settings.enableLayer3 {
                            // Context Dock → Media Dock
                            Task {
                                await mediaObserver.refreshNowPlaying()
                                withAnimation(.spring(response: 0.3, dampingFraction: 0.75)) {
                                    showContextInDock = true
                                    showMediaLayer = true
                                }
                                if searchState.query.isEmpty && !isSearchFieldFocused {
                                    startCollapseTimer()
                                }
                            }
                        }
                    }
                }
        )
    }

    /// Compact pill shown in place of the search input while app-pill navigation is active.
    /// Looks exactly like a regular app pill: [icon | separator | label]
    @ViewBuilder
    private var searchAsPillView: some View {
        Button(action: {
            withAnimation(.spring(response: 0.22, dampingFraction: 0.80)) {
                focusedAppPillIndex = nil
                l2.focusedPillIndex = nil
                l2.pillNavViaKeyboard = false
            }
            DispatchQueue.main.async { isSearchFieldFocused = true }
        }) {
            Group {
                if isGlobalContextActive {
                    if let selIcon = activeSelectionIcon {
                        Image(systemName: selIcon)
                            .font(.system(size: 15, weight: .semibold))
                            .foregroundStyle(Color.purple.opacity(0.90))
                    } else {
                        ContextDockGlyph(size: 20, opacity: 0.75)
                    }
                } else if let appIcon = l2.targetApp?.icon ?? frontmost.icon {
                    // Show frontmost app icon as the anchor
                    Image(nsImage: appIcon)
                        .resizable()
                        .aspectRatio(contentMode: .fit)
                        .frame(width: 26, height: 26)
                        .clipShape(RoundedRectangle(cornerRadius: 6))
                        .opacity(0.9)
                } else {
                    Image(systemName: "magnifyingglass")
                        .font(.system(size: 15, weight: .semibold))
                        .foregroundStyle(.secondary.opacity(0.75))
                }
            }
            .frame(width: 44, height: 40)
            .background {
                ZStack {
                    Capsule().fill(.ultraThinMaterial)
                    Capsule().fill(LinearGradient(
                        colors: [.white.opacity(0.08), .white.opacity(0.02)],
                        startPoint: .top, endPoint: .bottom))
                    Capsule().strokeBorder(Color.white.opacity(0.14), lineWidth: 0.75)
                }
            }
        }
        .buttonStyle(.plain)
        .help("Tap to restore search")
    }

    // Inline ghost label shown in the search bar when a selection is active in global context
    private var activeSelectionPromptText: String? {
        let files = effectiveFinderSelectionURLsForPills()
        if files.count > 1 {
            return "Selection — what would you like to do…"
        }
        if let label = frozenSelectionText ?? activeSelectionLabel {
            return "\(label)  —  type to act…"
        }
        return nil
    }

    private var activeSelectionLabel: String? {
        let axFiles = isDismissedFinderSelection(axContext.selectedFilePaths)
            ? []
            : axContext.selectedFilePaths.map { URL(fileURLWithPath: $0) }
        if !axFiles.isEmpty {
            return axFiles.count == 1 ? axFiles[0].lastPathComponent : "\(axFiles.count) files selected"
        }
        if let t = axContext.selectedText?.trimmingCharacters(in: .whitespacesAndNewlines), !t.isEmpty {
            return String(t.prefix(50))
        }
        if showGlobalClipboardPill, !globalClipboardText.isEmpty {
            let entry = clipboardHistory.first
            return entry?.preview ?? String(globalClipboardText.prefix(50))
        }
        switch currentContext {
        case .filesSelected(let urls) where !urls.isEmpty && !isDismissedFinderSelection(urls):
            return urls.count == 1 ? urls[0].lastPathComponent : "\(urls.count) files"
        case .textSelected(let t) where !t.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty:
            return String(t.prefix(50))
        case .url(let u) where !u.isEmpty:
            return URL(string: u)?.host ?? String(u.prefix(50))
        default: return nil
        }
    }

    // SF Symbol that represents the type of the current selection
    private var activeSelectionIcon: String? {
        let axFiles = isDismissedFinderSelection(axContext.selectedFilePaths)
            ? []
            : axContext.selectedFilePaths.map { URL(fileURLWithPath: $0) }
        if !axFiles.isEmpty {
            return axFiles.count == 1 ? fileIcon(for: axFiles[0].pathExtension.lowercased()) : "doc.on.doc.fill"
        }
        if let t = axContext.selectedText?.trimmingCharacters(in: .whitespacesAndNewlines), !t.isEmpty {
            return "text.cursor"
        }
        if showGlobalClipboardPill, !globalClipboardText.isEmpty {
            return clipboardHistory.first?.icon ?? "doc.on.clipboard"
        }
        switch currentContext {
        case .filesSelected(let urls) where !urls.isEmpty && !isDismissedFinderSelection(urls):
            return urls.count == 1 ? fileIcon(for: urls[0].pathExtension.lowercased()) : "doc.on.doc.fill"
        case .textSelected: return "text.cursor"
        case .url: return "link"
        default: return nil
        }
    }

    private func finderInputSymbolForSearchText() -> String? {
        guard showContextInDock, !isGlobalContextActive, !aiMode.isActive else { return nil }

        let query = searchState.query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard !query.isEmpty else { return nil }
        guard !query.hasPrefix("+") else { return nil }

        if let pill = firstMatchingFinderFolderPill(for: query) {
            return pill.icon.contains("folder") ? "folder.fill" : pill.icon
        }

        return nil
    }

    private func menuInputIconForSearchText(hasAppMatch: Bool) -> (image: NSImage?, symbol: String)? {
        guard !hasAppMatch else { return nil }
        guard showContextInDock, !isGlobalContextActive, !aiMode.isActive else { return nil }

        let query = searchState.query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard query.count >= 2 else { return nil }

        guard let pill = cachedDockPills.first(where: {
            !$0.isSeparator
                && ($0.rankingKind == "menu" || $0.rankingKind == "finderMenu")
                && ($0.name.lowercased().hasPrefix(query) || $0.name.lowercased().contains(query))
        }) else { return nil }

        return (pill.menuItemImage, pill.icon)
    }

    // Execute a cross-app ghost suggestion in its source app (shortcut-first, menu-click fallback).
    // Extracted so the type checker sees a simple call instead of nested async closures.
    private func executeLearnedGhostAction(
        bundleID: String, path: [String], shortcutChar: String?, shortcutModifiers: Int
    ) {
        Task {
            // Step 1: Ensure the app is running — launch if needed and wait up to 8s.
            var app = NSWorkspace.shared.runningApplications.first(where: {
                $0.bundleIdentifier == bundleID && !$0.isTerminated
            })
            if app == nil {
                // Launch the app and wait for it to appear in runningApplications
                if let appURL = NSWorkspace.shared.urlForApplication(withBundleIdentifier: bundleID) {
                    let config = NSWorkspace.OpenConfiguration()
                    config.activates = false
                    _ = try? await NSWorkspace.shared.openApplication(at: appURL, configuration: config)
                }
                // Poll up to 8 seconds for the app to register
                for _ in 0..<40 {
                    try? await Task.sleep(nanoseconds: 200_000_000)
                    if let running = NSWorkspace.shared.runningApplications.first(where: {
                        $0.bundleIdentifier == bundleID && !$0.isTerminated
                    }) {
                        app = running
                        break
                    }
                }
            }
            guard let app else { return }

            let pid = app.processIdentifier

            // Step 2: Unminimize any minimized windows via AX before activating.
            await MainActor.run {
                let axApp = AXUIElementCreateApplication(pid)
                var windowsRef: CFTypeRef?
                if AXUIElementCopyAttributeValue(axApp, kAXWindowsAttribute as CFString, &windowsRef) == .success,
                   let windows = windowsRef as? [AXUIElement]
                {
                    for win in windows {
                        var minimized: CFTypeRef?
                        if AXUIElementCopyAttributeValue(win, kAXMinimizedAttribute as CFString, &minimized) == .success,
                           (minimized as? Bool) == true
                        {
                            AXUIElementSetAttributeValue(win, kAXMinimizedAttribute as CFString, kCFBooleanFalse)
                        }
                    }
                }
                if app.isHidden { app.unhide() }
            }

            // Step 3: Activate app and wait for it to become frontmost.
            await MainActor.run {
                AppDelegate.shared?.launcherWindow?.resignKey()
                app.activate(options: [.activateIgnoringOtherApps])
            }
            await AXActionResolver.waitForActivation(of: app)
            // Extra settle time for freshly launched / unminimized apps
            try? await Task.sleep(nanoseconds: 150_000_000)

            // Step 4: Execute — shortcut first, fall back to AX menu click.
            let sc = shortcutChar?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
            if !sc.isEmpty {
                let sent = AXMenuReader.shared.executeShortcut(char: sc, modifiers: shortcutModifiers, in: pid)
                if sent { return }
            }
            AXActionResolver.shared.execute(menuPath: path, in: app)
        }
    }

    /// Cross-app menus grouped by source app — primary implementation.
    /// Scans running regular apps with cached menu snapshots, returns one group per app.
    /// Apps sorted by usage score; only matching menu items included (strict contains filter).
    private func crossAppMenuGroups(for query: String, limit: Int = 12) -> [AppMenuGroup] {
        guard !query.isEmpty,
              settings.enableLearnedGhostSuggestions,
              isGlobalContextActive,
              !hasActiveDockContextSelection,
              globalInlineAppScope == nil
        else { return [] }
        let lower = query.lowercased()
        let ownBundleId = Bundle.main.bundleIdentifier ?? ""
        let usageScores = AppUsageLearner.shared
        let runningApps = NSWorkspace.shared.runningApplications
            .filter { app in
                guard let bid = app.bundleIdentifier else { return false }
                return app.activationPolicy == .regular
                    && !app.isTerminated
                    && bid != frontmost.bundleID
                    && bid != ownBundleId
                    && AppMenuCapabilityCache.shared.hasSnapshot(bundleIdentifier: bid)
            }
        let runningBundleIds = Set(runningApps.compactMap(\.bundleIdentifier))

        // Non-running apps that have cached menu snapshots — shown with slightly lower priority.
        struct NonRunningApp { let bundleID: String; let name: String; let icon: NSImage? }
        let nonRunningApps: [NonRunningApp] = AppMenuCapabilityCache.shared.allCachedBundleIdentifiers()
            .filter { bid in
                !runningBundleIds.contains(bid)
                    && bid != frontmost.bundleID
                    && bid != ownBundleId
            }
            .compactMap { bid -> NonRunningApp? in
                guard let appURL = NSWorkspace.shared.urlForApplication(withBundleIdentifier: bid) else { return nil }
                let name = Bundle(url: appURL)?.object(forInfoDictionaryKey: "CFBundleName") as? String
                    ?? appURL.deletingPathExtension().lastPathComponent
                let icon = NSWorkspace.shared.icon(forFile: appURL.path)
                return NonRunningApp(bundleID: bid, name: name, icon: icon)
            }
            .sorted {
                usageScores.score(forBundleID: $0.bundleID) > usageScores.score(forBundleID: $1.bundleID)
            }

        let allApps = runningApps
            .sorted { usageScores.score(forBundleID: $0.bundleIdentifier ?? "") > usageScores.score(forBundleID: $1.bundleIdentifier ?? "") }

        let perAppCap = lower.count == 1 ? 3 : (lower.count == 2 ? 4 : 6)
        var groups: [AppMenuGroup] = []
        var totalPills = 0

        // Running apps first
        for app in allApps {
            guard let bundleID = app.bundleIdentifier, totalPills < limit else { break }
            let appName = app.localizedName ?? ""
            let remaining = min(perAppCap, limit - totalPills)
            let rawItems = AppMenuCapabilityCache.shared.menuItems(
                bundleIdentifier: bundleID, appName: appName, query: lower, maxResults: remaining
            )
            var pills: [DockPill] = []
            for item in rawItems {
                let nameLower = item.title.lowercased()
                guard nameLower.hasPrefix(lower) || nameLower.contains(lower),
                      item.title.count >= query.count else { continue }
                let bid = bundleID, path = item.path, sc = item.shortcutChar, mod = item.shortcutModifiers
                var pill = DockPill(
                    id: "xapp-\(bundleID)-\(item.title)",
                    name: item.title,
                    icon: "menubar.rectangle",
                    accentColorName: nil,
                    badge: item.shortcutDisplay,
                    execute: { [self] in
                        executeLearnedGhostAction(bundleID: bid, path: path, shortcutChar: sc, shortcutModifiers: mod)
                    }
                )
                pill.sourceBundleId = bundleID
                pill.sourceAppName  = appName
                pill.rankingKind    = "menu"
                pill.rankingScore = rankedTextMatchScore(
                    query: lower,
                    primary: item.title,
                    contexts: [item.path.dropLast().last ?? "", item.path.joined(separator: " ")]
                ) ?? 0
                pills.append(pill)
            }
            guard !pills.isEmpty else { continue }
            groups.append(AppMenuGroup(
                id: bundleID,
                appName: appName,
                icon: app.icon,
                pills: pills.sorted {
                    if $0.rankingScore != $1.rankingScore { return $0.rankingScore > $1.rankingScore }
                    return $0.name.localizedCaseInsensitiveCompare($1.name) == .orderedAscending
                }
            ))
            totalPills += pills.count
        }

        // Non-running apps with cached snapshots — launch-on-demand via executeLearnedGhostAction.
        for nrApp in nonRunningApps {
            guard totalPills < limit else { break }
            let bundleID = nrApp.bundleID
            let appName = nrApp.name
            let remaining = min(perAppCap, limit - totalPills)
            let rawItems = AppMenuCapabilityCache.shared.menuItems(
                bundleIdentifier: bundleID, appName: appName, query: lower, maxResults: remaining
            )
            var pills: [DockPill] = []
            for item in rawItems {
                let nameLower = item.title.lowercased()
                guard nameLower.hasPrefix(lower) || nameLower.contains(lower),
                      item.title.count >= query.count else { continue }
                let path = item.path, sc = item.shortcutChar, mod = item.shortcutModifiers
                var pill = DockPill(
                    id: "xapp-\(bundleID)-\(item.title)",
                    name: item.title,
                    icon: "menubar.rectangle",
                    accentColorName: nil,
                    badge: item.shortcutDisplay,
                    execute: { [self] in
                        executeLearnedGhostAction(bundleID: bundleID, path: path, shortcutChar: sc, shortcutModifiers: mod)
                    }
                )
                pill.sourceBundleId = bundleID
                pill.sourceAppName  = appName
                pill.rankingKind    = "menu"
                pill.rankingScore = rankedTextMatchScore(
                    query: lower,
                    primary: item.title,
                    contexts: [item.path.dropLast().last ?? "", item.path.joined(separator: " ")]
                ) ?? 0
                pills.append(pill)
            }
            guard !pills.isEmpty else { continue }
            groups.append(AppMenuGroup(
                id: bundleID,
                appName: appName,
                icon: nrApp.icon,
                pills: pills.sorted {
                    if $0.rankingScore != $1.rankingScore { return $0.rankingScore > $1.rankingScore }
                    return $0.name.localizedCaseInsensitiveCompare($1.name) == .orderedAscending
                }
            ))
            totalPills += pills.count
        }

        return groups
    }

    /// Flat cross-app pills — delegates to `crossAppMenuGroups` and flattens.
    /// Used for ghost completion and legacy callers that need a flat list.
    private func crossAppMenuPills(for query: String, limit: Int = 8) -> [DockPill] {
        crossAppMenuGroups(for: query, limit: limit).flatMap(\.pills)
    }

    // Top-ranked pill whose name starts with the current searchState.query — used for inline ghost completion
    private var ghostPillCompletion: DockPill? {
        guard !aiMode.isActive else { return nil }
        guard lockedSubmenuParent == nil else { return nil }
        guard !searchState.query.isEmpty else { return nil }
        guard !(isL2ContextActive && l2.targetApp == nil && l2.appCompletion != nil) else { return nil }
        let lower = searchState.query.lowercased()

        // Frontmost-scoped sources: cached pills + frontmost menu cache.
        // Skip in pure global app search — not frontmost-scoped there.
        if !shouldUsePureGlobalAppSearch {
            if let match = cachedDockPills.first(where: {
                guard !$0.isSeparator,
                      $0.name.lowercased().hasPrefix(lower),
                      $0.name.count > searchState.query.count
                else { return false }

                // In global context: only allow pills scoped to explicit targetApp.
                // Never surface frontmost-scoped pills — global context is app-agnostic.
                if isGlobalContextActive {
                    guard let targetId = l2.targetApp?.bundleId, !targetId.isEmpty else { return false }
                    return $0.sourceBundleId == targetId
                }
                if isL2ContextActive {
                    let expectedBundleId = l2.targetApp?.bundleId ?? frontmost.bundleID
                    guard !expectedBundleId.isEmpty else { return false }
                    return $0.sourceBundleId == expectedBundleId
                }
                return true
            }) { return match }

            // Frontmost menu cache ghost only in L2/frontmost-scoped mode.
            // Global context is app-agnostic — suppress to prevent per-app inconsistency.
            if !frontmost.bundleID.isEmpty && !isGlobalContextActive {
                let frontItems = AppMenuCapabilityCache.shared.menuItems(
                    bundleIdentifier: frontmost.bundleID, appName: "", query: lower, maxResults: 1
                )
                if let item = frontItems.first,
                   item.title.lowercased().hasPrefix(lower),
                   item.title.count > searchState.query.count {
                    let capturedBID  = frontmost.bundleID
                    let capturedPath = item.path
                    let capturedSC   = item.shortcutChar
                    let capturedMod  = item.shortcutModifiers
                    let capturedPID  = AppDelegate.shared?.previousFrontmostApp?.processIdentifier ?? 0
                    return DockPill(
                        id: "frontmost-ghost-\(capturedBID)-\(item.title)",
                        name: item.title,
                        icon: "menubar.rectangle",
                        accentColorName: nil,
                        badge: item.shortcutDisplay,
                        execute: { [self] in
                            self.executeDockMenuAction(
                                sourcePID: capturedPID, path: capturedPath,
                                shortcutChar: capturedSC, shortcutModifiers: capturedMod
                            )
                        }
                    )
                }
            }
        }

        // Cross-app: valid in global context (no selection) and pure L1.
        // Blocked in L2 frontmost-scoped mode (dock scoped to frontmost app).
        guard !isL2ContextActive || isGlobalContextActive else { return nil }
        return crossAppMenuPills(for: lower, limit: 1).first
    }

    /// When searchState.query is an exact match for a non-leaf menu item (submenu parent), optionally
    /// followed by a space + child prefix letter(s), returns the parent item, the typed child
    /// prefix, and the filtered leaf children. Drives submenu ghost text + instant child pills.
    ///
    /// Examples:
    ///   "sort by"   → parent=Sort By, prefix="",  children=[Attachments,Date,Flags,…]
    ///   "sort by d" → parent=Sort By, prefix="d",  children=[Date]
    ///   "file"      → parent=File,    prefix="",  children=[New Message,…]
    private var submenuGhostContext: (parent: AXMenuItem, childPrefix: String, children: [AXMenuItem])? {
        // Locked mode: parent is fixed, searchState.query is the child filter prefix
        if let locked = lockedSubmenuParent {
            var leaves: [AXMenuItem] = []
            for child in locked.children {
                if child.isLeaf { leaves.append(child) }
                else { leaves.append(contentsOf: child.children.filter(\.isLeaf)) }
            }
            leaves = leaves.filter { $0.isEnabled }
            guard !leaves.isEmpty else { return nil }
            let prefix = normalizedDockPillText(searchState.query.trimmingCharacters(in: .whitespaces))
            let filtered = prefix.isEmpty ? leaves : leaves.filter { normalizedDockPillText($0.title).hasPrefix(prefix) }
            return (locked, prefix, prefix.isEmpty ? leaves : filtered)
        }

        guard !liveMenuItems.isEmpty else { return nil }
        let raw = searchState.query.trimmingCharacters(in: .whitespaces)
        guard !raw.isEmpty else { return nil }
        let tokens = raw.components(separatedBy: " ").filter { !$0.isEmpty }
        guard !tokens.isEmpty else { return nil }

        // Try from longest prefix downward: "sort by d" tries parent="sort by" before "sort"
        for splitAt in stride(from: tokens.count, through: 1, by: -1) {
            let parentQ = normalizedDockPillText(tokens.prefix(splitAt).joined(separator: " "))
            guard !parentQ.isEmpty else { continue }
            guard let parent = liveMenuItems.first(where: {
                !$0.isLeaf && normalizedDockPillText($0.title) == parentQ
            }) else { continue }

            // Collect enabled leaf children (direct leaves + one level deeper)
            var leafChildren: [AXMenuItem] = []
            for child in parent.children {
                if child.isLeaf { leafChildren.append(child) }
                else { leafChildren.append(contentsOf: child.children.filter(\.isLeaf)) }
            }
            leafChildren = leafChildren.filter { $0.isEnabled }
            guard !leafChildren.isEmpty else { continue }

            let childPrefix = tokens.count > splitAt
                ? normalizedDockPillText(tokens.dropFirst(splitAt).joined(separator: " "))
                : ""
            let filtered = childPrefix.isEmpty ? leafChildren
                : leafChildren.filter { normalizedDockPillText($0.title).hasPrefix(childPrefix) }

            if childPrefix.isEmpty || !filtered.isEmpty {
                return (parent, childPrefix, childPrefix.isEmpty ? leafChildren : filtered)
            }
        }
        return nil
    }

    @ViewBuilder
    private var selectionContextChip: some View {
        // Prefer live AX state (axContext) for immediate updates; fall back to currentContext
        let axFiles = isDismissedFinderSelection(axContext.selectedFilePaths)
            ? []
            : axContext.selectedFilePaths.map { URL(fileURLWithPath: $0) }
        let axText = axContext.selectedText?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""

        if !axFiles.isEmpty {
            let label = axFiles.count == 1
                ? axFiles[0].lastPathComponent
                : "\(axFiles.count) files"
            let icon = axFiles.count == 1
                ? fileIcon(for: axFiles[0].pathExtension.lowercased())
                : "doc.on.doc.fill"
            selectionChipView(icon: icon, label: label, onDismiss: dismissContextAndReturnToDock)
        } else if !axText.isEmpty {
            let snippet = String(axText.prefix(40))
            selectionChipView(icon: "text.cursor",
                              label: "\"\(snippet)\(axText.count > 40 ? "…" : "")\"",
                              onDismiss: dismissContextAndReturnToDock)
        } else if showGlobalClipboardPill && !globalClipboardText.isEmpty {
            clipboardPocketPill
        } else {
            switch currentContext {
            case .filesSelected(let urls) where !urls.isEmpty:
                let label = urls.count == 1 ? urls[0].lastPathComponent : "\(urls.count) files"
                let icon = urls.count == 1
                    ? fileIcon(for: urls[0].pathExtension.lowercased()) : "doc.on.doc.fill"
                selectionChipView(icon: icon, label: label, onDismiss: dismissContextAndReturnToDock)
            case .textSelected(let text)
            where !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty:
                let t = text.trimmingCharacters(in: .whitespacesAndNewlines)
                selectionChipView(icon: "text.cursor",
                                  label: "\"\(String(t.prefix(40)))\(t.count > 40 ? "…" : "")\"",
                                  onDismiss: dismissContextAndReturnToDock)
            case .url(let urlStr) where !urlStr.isEmpty:
                selectionChipView(icon: "link",
                                  label: URL(string: urlStr)?.host ?? String(urlStr.prefix(40)),
                                  onDismiss: dismissContextAndReturnToDock)
            default:
                EmptyView()
            }
        }
    }

    /// Clears the active global context and returns to the frontmost app's Context-Dock scope.
    private func dismissContextAndReturnToDock() {
        let dismissedFinderPaths: [String] = {
            if !axContext.selectedFilePaths.isEmpty {
                return axContext.selectedFilePaths
            }
            if case .filesSelected(let urls) = currentContext {
                return urls.map(\.path)
            }
            return []
        }()
        if !dismissedFinderPaths.isEmpty {
            dismissedFinderSelectionSignature = finderSelectionSignature(dismissedFinderPaths)
        }
        withAnimation(.spring(response: 0.2, dampingFraction: 0.8)) {
            currentContext = .none
            globalContextActivation = nil
            axContext = .empty
        }
        scheduleDockPillRebuild(query: lastPillQuery, delayNanoseconds: 0)
        setFrontmostAppContextOnly(reason: "dismiss context chip")
    }

    @ViewBuilder
    private func selectionChipView(icon: String, label: String, onDismiss: @escaping () -> Void) -> some View {
        HStack(spacing: 4) {
            Image(systemName: icon)
                .font(.system(size: 10, weight: .semibold))
                .foregroundStyle(Color.green.opacity(0.85))
            Text(label)
                .font(.system(size: 11, weight: .medium))
                .foregroundStyle(Color.primary.opacity(0.75))
                .lineLimit(1)
                .frame(maxWidth: 130)
            Button(action: onDismiss) {
                Image(systemName: "minus")
                    .font(.system(size: 8, weight: .bold))
                    .foregroundStyle(.secondary)
            }
            .buttonStyle(.plain)
        }
        .padding(.horizontal, 9)
        .padding(.vertical, 5)
        .background(Color.green.opacity(0.10), in: Capsule())
        .overlay(Capsule().strokeBorder(Color.green.opacity(0.25), lineWidth: 0.5))
        .transition(.scale(scale: 0.85).combined(with: .opacity))
    }

