    // MARK: - Floating Selection Pill (always in dock when a selection is active)
    @ViewBuilder
    private var selectionFloatingPill: some View {
        let axFiles = axContext.selectedFilePaths.map { URL(fileURLWithPath: $0) }
        let axText = axContext.selectedText?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""

        let info: (icon: String, label: String)? = {
            if !axFiles.isEmpty {
                let lbl = axFiles.count == 1 ? axFiles[0].lastPathComponent : "\(axFiles.count) files"
                let ico = axFiles.count == 1 ? fileIcon(for: axFiles[0].pathExtension.lowercased()) : "doc.on.doc.fill"
                return (ico, lbl)
            } else if !axText.isEmpty {
                return ("text.cursor", String(axText.prefix(28)))
            } else {
                switch currentContext {
                case .filesSelected(let urls) where !urls.isEmpty:
                    let lbl = urls.count == 1 ? urls[0].lastPathComponent : "\(urls.count) files"
                    let ico = urls.count == 1 ? fileIcon(for: urls[0].pathExtension.lowercased()) : "doc.on.doc.fill"
                    return (ico, lbl)
                case .textSelected(let t) where !t.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty:
                    return ("text.cursor", String(t.trimmingCharacters(in: .whitespacesAndNewlines).prefix(28)))
                case .url(let s) where !s.isEmpty:
                    return ("link", URL(string: s)?.host ?? String(s.prefix(28)))
                default: return nil
                }
            }
        }()

        if let inf = info {
            HStack(spacing: 4) {
                Image(systemName: inf.icon)
                    .font(.system(size: 10, weight: .semibold))
                    .foregroundStyle(Color.green.opacity(0.85))
                Text(inf.label)
                    .font(.system(size: 10, weight: .medium))
                    .foregroundStyle(Color.primary.opacity(0.72))
                    .lineLimit(1)
                    .frame(maxWidth: 90)
                Button(action: dismissContextAndReturnToDock) {
                    Image(systemName: "minus")
                        .font(.system(size: 8, weight: .bold))
                        .foregroundStyle(.secondary)
                }
                .buttonStyle(.plain)
                .help("Clear selection")
            }
            .padding(.horizontal, 8)
            .padding(.vertical, 5)
            .background(Color.green.opacity(0.10), in: Capsule())
            .overlay(Capsule().strokeBorder(Color.green.opacity(0.25), lineWidth: 0.5))
            .transition(.scale(scale: 0.85).combined(with: .opacity))
        }
    }

    // MARK: - Clipboard history sorted by frontmost app relevance
    private func relevantClipboardHistory() -> [ClipboardEntry] {
        let isBrowser = ["com.apple.Safari", "com.google.Chrome", "org.mozilla.firefox",
                         "com.microsoft.edgemac", "com.brave.Browser"].contains(frontmost.bundleID)
        let isFinder = frontmost.bundleID == "com.apple.finder"

        if isBrowser {
            return clipboardHistory.sorted { a, b in
                if a.isURL && !b.isURL { return true }
                if !a.isURL && b.isURL { return false }
                return a.timestamp > b.timestamp
            }
        } else if isFinder {
            return clipboardHistory.sorted { a, b in
                if a.isFilePath && !b.isFilePath { return true }
                if !a.isFilePath && b.isFilePath { return false }
                return a.timestamp > b.timestamp
            }
        }
        return clipboardHistory
    }

    // MARK: - Floating Clipboard Icon Pill (always in dock, compact — scales with dockIconSize)
    @ViewBuilder
    private var clipboardFloatingIconPill: some View {
        let hasContent = showGlobalClipboardPill && !globalClipboardText.isEmpty
        let showDropTarget = clipboardDropTargetVisible && !hasContent
        let count = clipboardHistory.count
        let sorted = relevantClipboardHistory()
        let limit = settings.clipboardHistoryLimit
        let pillH = CGFloat(settings.dockIconSize) * 0.909

        if hasContent && !isSearchBarExpanded && clipboardHistoryExpanded && !sorted.isEmpty {
            // Inline expanded: compact horizontal row of clipboard item chips
            HStack(spacing: 4) {
                ForEach(Array(sorted.prefix(min(limit, 10)).enumerated()), id: \.offset) { _, entry in
                    Button {
                        copyClipboardEntryToPasteboard(entry)
                        withAnimation { clipboardHistoryExpanded = false }
                    } label: {
                        HStack(spacing: 3) {
                            Image(systemName: entry.icon)
                                .font(.system(size: 9, weight: .semibold))
                                .foregroundStyle(entry.isURL ? Color.blue.opacity(0.9) : Color.indigo.opacity(0.9))
                            Text(entry.preview)
                                .font(.system(size: 9, weight: .medium))
                                .foregroundStyle(Color.primary.opacity(0.75))
                                .lineLimit(1)
                                .frame(maxWidth: 64)
                        }
                        .padding(.horizontal, 6)
                        .padding(.vertical, 4)
                        .background(.ultraThinMaterial, in: Capsule())
                        .overlay(Capsule().strokeBorder(Color.indigo.opacity(0.20), lineWidth: 0.5))
                    }
                    .buttonStyle(.plain)
                    .help(entry.text)
                }

                // Collapse button
                Button {
                    withAnimation(.spring(response: 0.22, dampingFraction: 0.78)) {
                        clipboardHistoryExpanded = false
                    }
                } label: {
                    Image(systemName: "chevron.down")
                        .font(.system(size: 9, weight: .bold))
                        .foregroundStyle(Color.indigo.opacity(0.7))
                        .frame(width: 24, height: 28)
                        .background(.ultraThinMaterial, in: Capsule())
                }
                .buttonStyle(.plain)
                .help("Collapse clipboard")
            }
            .transition(.scale(scale: 0.9, anchor: .leading).combined(with: .opacity))
            .animation(.spring(response: 0.25, dampingFraction: 0.78), value: clipboardHistoryExpanded)
        } else if showDropTarget {
            Button {
                withAnimation(.spring(response: 0.22, dampingFraction: 0.78)) {
                    showClipboardHistory.toggle()
                }
            } label: {
                ZStack(alignment: .topTrailing) {
                    Image(systemName: "tray.and.arrow.down")
                        .font(.system(size: 15, weight: .semibold))
                        .foregroundStyle(Color.purple.opacity(0.90))
                }
                .frame(width: pillH * 1.1, height: pillH)
                .background {
                    ZStack {
                        Capsule().fill(.ultraThinMaterial)
                        Capsule().fill(
                            clipboardDropTargeted
                                ? Color.purple.opacity(0.18)
                                : Color.purple.opacity(0.08)
                        )
                        Capsule().strokeBorder(
                            clipboardDropTargeted
                                ? Color.purple.opacity(0.45)
                                : Color.purple.opacity(0.26),
                            lineWidth: 0.75)
                    }
                }
                .animation(.spring(response: 0.25, dampingFraction: 0.72), value: pillH)
            }
            .buttonStyle(.plain)
            .popover(isPresented: $showClipboardHistory, arrowEdge: .bottom) {
                clipboardHistorySheet
            }
            .onDrop(of: [.fileURL, .text, .plainText, .url], isTargeted: $clipboardDropTargeted) { providers in
                handleClipboardIconDrop(providers)
            }
            .help("Drop here to pin for later")
            .animation(.spring(response: 0.22, dampingFraction: 0.78), value: hasContent)
            .animation(.spring(response: 0.22, dampingFraction: 0.78), value: count)
            .animation(.spring(response: 0.22, dampingFraction: 0.78), value: clipboardDropTargeted)
        } else {
            EmptyView()
        }
    }

    private var clipboardHistorySheet: some View {
        VStack(spacing: 0) {
            HStack {
                Label("Clipboard", systemImage: "doc.on.clipboard")
                    .font(.system(size: 12, weight: .semibold))
                    .foregroundStyle(.primary)
                Spacer()
                Button {
                    withAnimation {
                        clipboardHistory.removeAll()
                        showGlobalClipboardPill = false
                        globalClipboardText = ""
                        showClipboardHistory = false
                        dismissContextAndReturnToDock()
                    }
                } label: {
                    Image(systemName: "trash")
                        .font(.system(size: 11))
                        .foregroundStyle(.secondary)
                }
                .buttonStyle(.plain)
            }
            .padding(.horizontal, 14)
            .padding(.vertical, 10)

            Divider()

            ScrollView {
                LazyVStack(spacing: 0) {
                    let shown = relevantClipboardHistory().prefix(settings.clipboardHistoryLimit)
                    ForEach(Array(shown)) { entry in
                        clipboardHistoryRow(entry)
                        if entry.id != shown.last?.id {
                            Divider().padding(.leading, 38)
                        }
                    }
                }
            }
            .frame(maxHeight: 260)
        }
        .frame(width: 280)
        .background(.regularMaterial)
    }

    private func clipboardHistoryRow(_ entry: ClipboardEntry) -> some View {
        clipboardHistoryRowContent(entry)
            .padding(.horizontal, 12)
            .padding(.vertical, 8)
            .contentShape(Rectangle())
            .onTapGesture {
                globalClipboardText = entry.text
                withAnimation { showClipboardHistory = false }
            }
            .background(Color.primary.opacity(0.001))
    }

    private func clipboardHistoryRowContent(_ entry: ClipboardEntry) -> some View {
        HStack(spacing: 10) {
            ZStack(alignment: .bottomTrailing) {
                if let imageData = entry.imageData, let image = NSImage(data: imageData) {
                    Image(nsImage: image)
                        .resizable()
                        .aspectRatio(contentMode: .fill)
                        .frame(width: 28, height: 28)
                        .clipShape(RoundedRectangle(cornerRadius: 7))
                } else if let sourceIcon = clipboardSourceIcon(for: entry) {
                    Image(nsImage: sourceIcon)
                        .resizable()
                        .aspectRatio(contentMode: .fit)
                        .frame(width: 28, height: 28)
                        .clipShape(RoundedRectangle(cornerRadius: 7))
                } else {
                    Image(systemName: entry.icon)
                        .font(.system(size: 13, weight: .medium))
                        .foregroundStyle(entry.isURL ? Color.blue : Color.indigo)
                        .frame(width: 28, height: 28)
                        .background((entry.isURL ? Color.blue : Color.indigo).opacity(0.1),
                                     in: RoundedRectangle(cornerRadius: 7))
                }
                if entry.fileCount > 1 {
                    Text("\(min(entry.fileCount, 99))")
                        .font(.system(size: 7, weight: .bold))
                        .foregroundStyle(.white)
                        .padding(.horizontal, 3)
                        .padding(.vertical, 1)
                        .background(Color.indigo, in: Capsule())
                        .offset(x: 4, y: 3)
                }
            }

            VStack(alignment: .leading, spacing: 1) {
                Text(entry.preview)
                    .font(.system(size: 12, weight: .medium))
                    .foregroundStyle(.primary)
                    .lineLimit(1)
                Text(clipboardEntrySubtitle(entry))
                    .font(.system(size: 10))
                    .foregroundStyle(.tertiary)
            }

            Spacer()

            Button {
                copyClipboardEntryToPasteboard(entry)
                withAnimation { showClipboardHistory = false }
            } label: {
                Image(systemName: "doc.on.doc")
                    .font(.system(size: 11))
                    .foregroundStyle(.secondary)
            }
            .buttonStyle(.plain)
            .help("Copy to clipboard")
        }
    }

    private func clipboardSourceIcon(for entry: ClipboardEntry) -> NSImage? {
        if !entry.sourceBundleId.isEmpty,
           let url = NSWorkspace.shared.urlForApplication(withBundleIdentifier: entry.sourceBundleId) {
            return NSWorkspace.shared.icon(forFile: url.path)
        }
        return nil
    }

    private func clipboardEntrySubtitle(_ entry: ClipboardEntry) -> String {
        var parts: [String] = []
        if !entry.sourceAppName.isEmpty {
            parts.append("Copied from \(entry.sourceAppName)")
        }
        if entry.fileCount > 0 {
            parts.append(entry.fileCount == 1 ? "1 file" : "\(entry.fileCount) files")
        }
        let formatter = RelativeDateTimeFormatter()
        formatter.unitsStyle = .short
        let age = formatter.localizedString(for: entry.timestamp, relativeTo: Date())
        parts.append(age)
        return parts.joined(separator: " • ")
    }

    private func copyClipboardEntryToPasteboard(_ entry: ClipboardEntry) {
        let pasteboard = NSPasteboard.general
        pasteboard.clearContents()
        if let imageData = entry.imageData,
           let image = NSImage(data: imageData) {
            pasteboard.writeObjects([image])
        } else if !entry.filePaths.isEmpty {
            let urls = entry.filePaths.map { URL(fileURLWithPath: $0) }
            pasteboard.writeObjects(urls as [NSURL])
            pasteboard.setString(entry.filePaths.joined(separator: "\n"), forType: .string)
        } else {
            pasteboard.setString(entry.text, forType: .string)
        }
    }

    private func revealClipboardDropTarget() {
        withAnimation(.spring(response: 0.22, dampingFraction: 0.78)) {
            clipboardDropTargetVisible = true
        }
    }

    private func hideClipboardDropTargetIfEmpty() {
        guard !showGlobalClipboardPill || globalClipboardText.isEmpty else { return }
        withAnimation(.spring(response: 0.22, dampingFraction: 0.82)) {
            clipboardDropTargetVisible = false
            clipboardDropTargeted = false
        }
    }

    private func handleClipboardIconDrop(_ providers: [NSItemProvider]) -> Bool {
        clipboardDropTargetVisible = true
        let fileProviders = providers.filter {
            $0.hasItemConformingToTypeIdentifier(UTType.fileURL.identifier)
        }
        let textProviders = providers.filter {
            $0.hasItemConformingToTypeIdentifier(UTType.utf8PlainText.identifier)
                || $0.hasItemConformingToTypeIdentifier(UTType.plainText.identifier)
                || $0.hasItemConformingToTypeIdentifier(UTType.text.identifier)
                || $0.canLoadObject(ofClass: NSString.self)
        }
        let urlProviders = providers.filter {
            $0.hasItemConformingToTypeIdentifier(UTType.url.identifier)
                || $0.canLoadObject(ofClass: NSURL.self)
        }
        guard !fileProviders.isEmpty || !textProviders.isEmpty || !urlProviders.isEmpty else {
            hideClipboardDropTargetIfEmpty()
            return false
        }

        let group = DispatchGroup()
        let lock = NSLock()
        var paths: [String] = []
        var texts: [String] = []

        for provider in fileProviders {
            group.enter()
            provider.loadItem(forTypeIdentifier: UTType.fileURL.identifier, options: nil) { item, _ in
                defer { group.leave() }
                let url: URL? = {
                    if let data = item as? Data {
                        return URL(dataRepresentation: data, relativeTo: nil)
                    }
                    if let url = item as? URL {
                        return url
                    }
                    if let nsurl = item as? NSURL {
                        return nsurl as URL
                    }
                    return nil
                }()
                guard let url, url.isFileURL else { return }
                lock.lock()
                paths.append(url.path)
                lock.unlock()
            }
        }

        for provider in urlProviders where !provider.hasItemConformingToTypeIdentifier(UTType.fileURL.identifier) {
            group.enter()
            provider.loadItem(forTypeIdentifier: UTType.url.identifier, options: nil) { item, _ in
                defer { group.leave() }
                let value: String? = {
                    if let data = item as? Data {
                        return String(data: data, encoding: .utf8)
                    }
                    if let url = item as? URL {
                        return url.absoluteString
                    }
                    if let nsurl = item as? NSURL {
                        return nsurl.absoluteString
                    }
                    if let string = item as? String {
                        return string
                    }
                    return nil
                }()
                guard let value, !value.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return }
                lock.lock()
                texts.append(value)
                lock.unlock()
            }
        }

        for provider in textProviders {
            group.enter()
            if provider.canLoadObject(ofClass: NSString.self) {
                provider.loadObject(ofClass: NSString.self) { object, _ in
                    defer { group.leave() }
                    let value = (object as? String)?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
                    guard !value.isEmpty else { return }
                    lock.lock()
                    texts.append(value)
                    lock.unlock()
                }
            } else {
                provider.loadItem(forTypeIdentifier: UTType.plainText.identifier, options: nil) { item, _ in
                    defer { group.leave() }
                    let value: String? = {
                        if let data = item as? Data { return String(data: data, encoding: .utf8) }
                        if let string = item as? String { return string }
                        if let nsString = item as? NSString { return nsString as String }
                        return nil
                    }()
                    let trimmed = value?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
                    guard !trimmed.isEmpty else { return }
                    lock.lock()
                    texts.append(trimmed)
                    lock.unlock()
                }
            }
        }

        group.notify(queue: .main) {
            let uniquePaths = Array(NSOrderedSet(array: paths)) as? [String] ?? paths
            let uniqueTexts = Array(NSOrderedSet(array: texts)) as? [String] ?? texts
            if !uniquePaths.isEmpty {
                addClipboardEntry(text: uniquePaths.joined(separator: "\n"), filePaths: uniquePaths)
            } else if let text = uniqueTexts.first, !text.isEmpty {
                addClipboardEntry(text: text, filePaths: [])
            } else {
                hideClipboardDropTargetIfEmpty()
            }
        }

        return true
    }

    private func clipboardSearchResults() -> [SearchResult] {
        relevantClipboardHistory().map { entry in
            SearchResult(
                title: entry.preview,
                subtitle: clipboardEntrySubtitle(entry),
                icon: clipboardEntryImage(for: entry),
                action: {
                    copyClipboardEntryToPasteboard(entry)
                },
                score: 100,
                type: entry.fileCount > 0 ? .file : .document,
                filePath: entry.filePaths.first,
                contactData: nil
            )
        }
    }

    private func clipboardEntryImage(for entry: ClipboardEntry) -> NSImage? {
        if let imageData = entry.imageData, let image = NSImage(data: imageData) {
            return image
        }
        if entry.filePaths.count == 1 {
            return NSWorkspace.shared.icon(forFile: entry.filePaths[0])
        }
        return NSImage(systemSymbolName: entry.icon, accessibilityDescription: entry.preview)
    }

    @ViewBuilder
    private var clipboardScopeView: some View {
        VStack(spacing: 0) {
            HStack(spacing: 8) {
                Text("Clipboard Items")
                    .font(.system(size: 10, weight: .semibold))
                    .foregroundStyle(.secondary)
                    .textCase(.uppercase)
                    .tracking(0.4)
                Spacer()
                Text("\(relevantClipboardHistory().count)")
                    .font(.system(size: 10))
                    .foregroundStyle(.tertiary)
                Button {
                    withAnimation(.spring(response: 0.22, dampingFraction: 0.8)) {
                        clipboardScopeShowsGrid.toggle()
                    }
                } label: {
                    Image(systemName: clipboardScopeShowsGrid ? "list.bullet" : "square.grid.2x2")
                        .font(.system(size: 11, weight: .semibold))
                        .foregroundStyle(.secondary)
                }
                .buttonStyle(.plain)
                .help(clipboardScopeShowsGrid ? "List view" : "Grid view")
            }
            .padding(.horizontal, 10)
            .padding(.vertical, 8)
            .background(Color.accentColor.opacity(0.06))

            Divider()

            let entries = filteredClipboardEntriesForScope()
            if entries.isEmpty {
                VStack(spacing: 8) {
                    Image(systemName: "doc.on.clipboard")
                        .font(.system(size: 28))
                        .foregroundStyle(.tertiary)
                    Text("Clipboard is empty")
                        .font(.system(size: 12, weight: .medium))
                        .foregroundStyle(.secondary)
                }
                .frame(maxWidth: .infinity, maxHeight: .infinity)
            } else if clipboardScopeShowsGrid {
                ScrollView {
                    LazyVGrid(
                        columns: [
                            GridItem(.adaptive(minimum: 110, maximum: 150), spacing: 8)
                        ],
                        spacing: 8
                    ) {
                        ForEach(Array(entries.enumerated()), id: \.element.id) { index, entry in
                            clipboardScopeGridItem(entry, index: index)
                        }
                    }
                    .padding(10)
                }
            } else {
                ScrollView {
                    LazyVStack(spacing: 0) {
                        ForEach(Array(entries.enumerated()), id: \.element.id) { index, entry in
                            clipboardScopeListItem(entry, index: index)
                            if entry.id != entries.last?.id {
                                Divider().padding(.leading, 46)
                            }
                        }
                    }
                    .padding(.vertical, 4)
                }
            }
        }
    }

    private func filteredClipboardEntriesForScope() -> [ClipboardEntry] {
        let q = searchState.query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        let entries = relevantClipboardHistory()
        guard !q.isEmpty, q != "clip", q != "clipboard" else { return entries }
        return entries.filter {
            $0.preview.lowercased().contains(q)
                || $0.text.lowercased().contains(q)
                || clipboardEntrySubtitle($0).lowercased().contains(q)
        }
    }

    private func navigateClipboardScope(direction: Int) {
        let entries = filteredClipboardEntriesForScope()
        guard !entries.isEmpty else {
            focusedClipboardEntryIndex = nil
            return
        }

        let current = focusedClipboardEntryIndex ?? (direction < 0 ? entries.count : -1)
        let next = min(max(current + direction, 0), entries.count - 1)
        focusedClipboardEntryIndex = next
        searchState.selectedIndex = nil
    }

    private func quickLookFocusedClipboardEntry() {
        let entries = filteredClipboardEntriesForScope()
        guard let index = focusedClipboardEntryIndex, entries.indices.contains(index) else { return }
        quickLookClipboardEntry(entries[index])
    }

    private func quickLookClipboardEntry(_ entry: ClipboardEntry) {
        guard let url = quickLookURL(for: entry) else {
            openClipboardEntry(entry)
            return
        }

        guard let panel = QLPreviewPanel.shared() else { return }
        if panel.isVisible,
           let currentDataSource = quickLookDataSource,
           currentDataSource.urls.first == url {
            panel.orderOut(nil)
            quickLookDataSource = nil
            return
        }

        let dataSource = QuickLookDataSource(urls: [url])
        quickLookDataSource = dataSource
        panel.dataSource = dataSource
        panel.delegate = dataSource
        panel.reloadData()
        if !panel.isVisible {
            panel.makeKeyAndOrderFront(nil)
        }
    }

    private func quickLookURL(for entry: ClipboardEntry) -> URL? {
        if let path = entry.filePaths.first, FileManager.default.fileExists(atPath: path) {
            return URL(fileURLWithPath: path)
        }

        let directory = FileManager.default.temporaryDirectory
            .appendingPathComponent("ContextDockClipboardQuickLook", isDirectory: true)
        try? FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)

        if let imageData = entry.imageData {
            let url = directory.appendingPathComponent("\(entry.id.uuidString).tiff")
            try? imageData.write(to: url, options: .atomic)
            return url
        }

        if let url = URL(string: entry.text), url.scheme != nil {
            let previewURL = directory.appendingPathComponent("\(entry.id.uuidString).webloc")
            let body = """
            <?xml version="1.0" encoding="UTF-8"?>
            <!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
            <plist version="1.0"><dict><key>URL</key><string>\(url.absoluteString)</string></dict></plist>
            """
            try? body.write(to: previewURL, atomically: true, encoding: .utf8)
            return previewURL
        }

        let previewURL = directory.appendingPathComponent("\(entry.id.uuidString).txt")
        try? entry.text.write(to: previewURL, atomically: true, encoding: .utf8)
        return previewURL
    }

    private func openClipboardEntry(_ entry: ClipboardEntry) {
        if !entry.filePaths.isEmpty {
            NSWorkspace.shared.activateFileViewerSelecting(entry.filePaths.map { URL(fileURLWithPath: $0) })
        } else if let url = URL(string: entry.text), url.scheme != nil {
            NSWorkspace.shared.open(url)
        } else {
            copyClipboardEntryToPasteboard(entry)
        }
    }

    @ViewBuilder
    private func clipboardScopeListItem(_ entry: ClipboardEntry, index: Int) -> some View {
        let focused = focusedClipboardEntryIndex == index
        Button {
            openClipboardEntry(entry)
        } label: {
            clipboardHistoryRowContent(entry)
                .padding(.horizontal, 12)
                .padding(.vertical, 8)
                .contentShape(Rectangle())
                .background(
                    focused
                    ? Color.accentColor.opacity(0.14)
                    : Color.clear
                )
        }
        .buttonStyle(.plain)
        .onHover { hovering in
            if hovering { focusedClipboardEntryIndex = index }
        }
    }

    @ViewBuilder
    private func clipboardScopeGridItem(_ entry: ClipboardEntry, index: Int) -> some View {
        let focused = focusedClipboardEntryIndex == index
        Button {
            openClipboardEntry(entry)
        } label: {
            VStack(alignment: .leading, spacing: 7) {
                ZStack {
                    RoundedRectangle(cornerRadius: 8, style: .continuous)
                        .fill(Color.primary.opacity(0.06))
                    if let imageData = entry.imageData, let image = NSImage(data: imageData) {
                        Image(nsImage: image)
                            .resizable()
                            .aspectRatio(contentMode: .fill)
                            .clipShape(RoundedRectangle(cornerRadius: 8, style: .continuous))
                    } else {
                        Image(systemName: entry.icon)
                            .font(.system(size: 24, weight: .medium))
                            .foregroundStyle(entry.isURL ? Color.blue : Color.indigo)
                    }
                }
                .frame(height: 74)
                Text(entry.preview)
                    .font(.system(size: 11, weight: .medium))
                    .lineLimit(2)
                Text(clipboardEntrySubtitle(entry))
                    .font(.system(size: 9))
                    .foregroundStyle(.tertiary)
                    .lineLimit(1)
            }
            .padding(8)
            .background(
                focused ? Color.accentColor.opacity(0.14) : Color.primary.opacity(0.035),
                in: RoundedRectangle(cornerRadius: 8, style: .continuous)
            )
            .overlay(
                RoundedRectangle(cornerRadius: 8, style: .continuous)
                    .strokeBorder(focused ? Color.accentColor.opacity(0.45) : Color.clear, lineWidth: 1)
            )
        }
        .buttonStyle(.plain)
        .onHover { hovering in
            if hovering { focusedClipboardEntryIndex = index }
        }
    }

    @ViewBuilder
    private func pillScrollRowItem(pill: DockPill, index: Int) -> some View {
        let base = unifiedPillButton(pill: pill, index: index)
            .id("pill-\(index)")
            .transition(.scale(scale: 0.8).combined(with: .opacity))
        let scaled = base
            .scaleEffect(dockMagnificationScale(for: index), anchor: .bottom)
            .animation(.spring(response: 0.18, dampingFraction: 0.65), value: hoveredDockPillIndex)
        scaled.scrollTransition(.interactive, axis: .horizontal) { effect, phase in
            effect
                .rotation3DEffect(
                    .degrees(phase.value * 22),
                    axis: (x: 0, y: 1, z: 0),
                    perspective: 0.45
                )
                .scaleEffect(max(0.78, 1 - abs(phase.value) * 0.18))
                .opacity(max(0.45, 1 - abs(phase.value) * 0.38))
        }
    }

    @ViewBuilder
    private func dockPillScrollRow(pills: [DockPill], appQuery: String = "") -> some View {
        // Filtered app icons: pinned + running apps whose name starts with or contains the query.
        // Suppressed in global context with an active selection — queries filter context pills there.
        let filteredApps: [(icon: NSImage?, label: String, bundleId: String?, isRunning: Bool, action: () -> Void)] = {
            guard !appQuery.isEmpty, !isExplicitAppScope, !isGlobalContextActive else { return [] }
            let q = appQuery.lowercased()
            var seen = Set<String>()
            var results: [(icon: NSImage?, label: String, bundleId: String?, isRunning: Bool, action: () -> Void)] = []
            // Pinned apps
            for app in settings.pinnedApps where app.type == .application {
                let name = app.name.lowercased()
                guard name.hasPrefix(q) || (q.count >= 2 && name.contains(q)) else { continue }
                let key = app.bundleIdentifier ?? app.path
                guard seen.insert(key).inserted else { continue }
                let isRunning = runningApp(for: app) != nil
                let icon = resolvedPinnedIcon(for: app)
                let captured = app
                results.append((icon: icon, label: app.name, bundleId: app.bundleIdentifier, isRunning: isRunning, action: { launchPinnedApp(captured) }))
                if results.count >= 5 { break }
            }
            // Running apps not already in pinned
            for app in runningRegularApps where results.count < 5 {
                guard let name = app.localizedName else { continue }
                let lname = name.lowercased()
                guard lname.hasPrefix(q) || (q.count >= 2 && lname.contains(q)) else { continue }
                let key = app.bundleIdentifier ?? "\(app.processIdentifier)"
                guard seen.insert(key).inserted else { continue }
                let icon = resolvedRunningAppIcon(for: app)
                let captured = app
                results.append((icon: icon, label: name, bundleId: app.bundleIdentifier, isRunning: true, action: { activateRunningAppFromDock(captured) }))
            }
            return results
        }()

        Group {
        if let focIdx = l2.focusedPillIndex, !pills.isEmpty, focIdx < pills.count {
            // ── Cascade: at 820pt show prev2+prev+focused+next; at 640pt show prev+focused+next ──
            let leftSlots = visibleDockWidth >= 750 ? 2 : 1
            let prev2: Int? = leftSlots >= 2 ? {
                let i = focIdx - 2
                guard i >= 0, !pills[i].isSeparator else { return nil }
                return i
            }() : nil
            let prev1: Int? = {
                let i = focIdx - 1
                guard i >= 0, !pills[i].isSeparator else { return nil }
                return i
            }()
            let next1: Int? = {
                let i = focIdx + 1
                guard i < pills.count, !pills[i].isSeparator else { return nil }
                return i
            }()
            HStack(spacing: 6) {
                // Prev2 (only on wide dock)
                if let p2 = prev2 {
                    unifiedPillButton(pill: pills[p2], index: p2)
                        .transition(.asymmetric(
                            insertion: .opacity.combined(with: .scale(scale: 0.9)),
                            removal: .opacity.combined(with: .scale(scale: 0.9))))
                }
                // Prev
                if let p1 = prev1 {
                    unifiedPillButton(pill: pills[p1], index: p1)
                        .transition(.asymmetric(
                            insertion: .opacity.combined(with: .scale(scale: 0.9)),
                            removal: .opacity.combined(with: .scale(scale: 0.9))))
                }
                // Focused — expanded bright pill, fills remaining space
                unifiedPillButton(pill: pills[focIdx], index: focIdx, isExpanded: true)
                    .frame(maxWidth: .infinity)
                    .transition(.opacity)
                // Next
                if let n1 = next1 {
                    unifiedPillButton(pill: pills[n1], index: n1)
                        .transition(.asymmetric(
                            insertion: .opacity.combined(with: .scale(scale: 0.9)),
                            removal: .opacity.combined(with: .scale(scale: 0.9))))
                }
            }
            .animation(.spring(response: 0.22, dampingFraction: 0.78), value: focIdx)
        } else {
            // ── Normal scrollable row ─────────────────────────────────────────────
            ScrollViewReader { proxy in
                ScrollView(.horizontal, showsIndicators: false) {
                    LazyHStack(spacing: 6) {
                        if !pills.isEmpty {
                            ForEach(Array(pills.enumerated()), id: \.element.id) { idx, pill in
                                pillScrollRowItem(pill: pill, index: idx)
                            }
                        } else {
                            Spacer(minLength: 0)
                        }
                    }
                }
                .onChange(of: l2.focusedPillIndex) { newIndex in
                    guard l2.pillNavViaKeyboard, let idx = newIndex else { return }
                    withAnimation(.spring(response: 0.25, dampingFraction: 0.82)) {
                        proxy.scrollTo("pill-\(idx)", anchor: .center)
                    }
                    if idx < pills.count, pills[idx].isShareAction {
                        showShareSheetForContext()
                    }
                }
            }
        }  // end else
        }  // end Group
        .onHover { hovering in
            isHoveringPillRow = hovering
            if !hovering { pillScrollAccumulator = 0 }
        }
    }

    // MARK: - List view (Spotlight / Raycast-style vertical result sheet)

    private func dockPillListView(pills: [DockPill]) -> some View {
        let visiblePills = Array(pills.prefix(maxListViewDockPills))
        return ScrollViewReader { proxy in
            ScrollView(.vertical, showsIndicators: false) {
                LazyVStack(spacing: 2) {
                    ForEach(Array(visiblePills.enumerated()), id: \.element.id) { idx, pill in
                        if pill.isSeparator {
                            if !pill.name.isEmpty {
                                HStack {
                                    Text(pill.name.uppercased())
                                        .font(.system(size: 10, weight: .semibold, design: .rounded))
                                        .foregroundStyle(.tertiary)
                                        .tracking(0.7)
                                    Spacer()
                                }
                                .padding(.horizontal, 12)
                                .padding(.top, idx == 0 ? 2 : 8)
                                .padding(.bottom, 1)
                            }
                        } else {
                            pillListRow(pill: pill, index: idx)
                                .id("pill-list-\(idx)")
                        }
                    }
                }
                .padding(6)
                .animation(.easeInOut(duration: 0.15), value: visiblePills.map(\.id))
            }
            .frame(height: listViewVisibleHeight)
            .clipShape(RoundedRectangle(cornerRadius: 14, style: .continuous))
            .onChange(of: l2.focusedPillIndex) { newIndex in
                guard l2.pillNavViaKeyboard, let idx = newIndex else { return }
                withAnimation(.spring(response: 0.22, dampingFraction: 0.82)) {
                    proxy.scrollTo("pill-list-\(idx)", anchor: .center)
                }
            }
        }
    }

    // Liquid glass floating suggestion panel — appears below input like the macOS autocomplete popover.
    @ViewBuilder
    private func submenuDropdownView(parent: AXMenuItem, children: [AXMenuItem], prefix: String) -> some View {
        ScrollViewReader { proxy in
            ScrollView(.vertical, showsIndicators: false) {
                VStack(alignment: .leading, spacing: 0) {
                    // "Sort By" section header
                    Text(parent.title)
                        .font(.system(size: 11, weight: .semibold))
                        .foregroundStyle(.secondary)
                        .padding(.horizontal, 16)
                        .padding(.top, 12)
                        .padding(.bottom, 4)

                    ForEach(Array(children.enumerated()), id: \.element.id) { idx, child in
                        let isHov = listViewHoveredIndex == (10000 + idx)
                        let isKeyFocused = l2.focusedPillIndex == idx
                        let isActive = isHov || isKeyFocused

                        Button {
                            let frontPID = AppDelegate.shared?.previousFrontmostApp?.processIdentifier ?? 0
                            let pid  = child.sourcePID != 0 ? child.sourcePID : frontPID
                            let path = child.path
                            let sc   = child.shortcutChar
                            let mod  = child.shortcutModifiers
                            searchState.query = ""
                            lockedSubmenuParent = nil
                            executeDockMenuAction(sourcePID: pid, path: path, shortcutChar: sc, shortcutModifiers: mod)
                        } label: {
                            HStack(spacing: 10) {
                                // Prefix bold: typed part in accentColor, rest in primary
                                if !prefix.isEmpty,
                                   child.title.lowercased().hasPrefix(prefix) {
                                    let boldPart = String(child.title.prefix(prefix.count))
                                    let restPart = String(child.title.dropFirst(prefix.count))
                                    HStack(spacing: 0) {
                                        Text(boldPart)
                                            .font(.system(size: 14, weight: .bold))
                                            .foregroundStyle(Color.accentColor)
                                        Text(restPart)
                                            .font(.system(size: 14, weight: .regular))
                                            .foregroundStyle(Color(nsColor: .labelColor))
                                    }
                                } else {
                                    Text(child.title)
                                        .font(.system(size: 14, weight: .regular))
                                        .foregroundStyle(Color(nsColor: .labelColor))
                                }
                                Spacer()
                                if let sc = child.shortcutDisplay, !sc.isEmpty {
                                    Text(sc)
                                        .font(.system(size: 11, weight: .medium))
                                        .foregroundStyle(.secondary.opacity(0.55))
                                        .padding(.horizontal, 5)
                                        .padding(.vertical, 2)
                                        .background(
                                            .regularMaterial,
                                            in: RoundedRectangle(cornerRadius: 4)
                                        )
                                }
                            }
                            .padding(.horizontal, 12)
                            .padding(.vertical, 8)
                            .background(
                                isActive
                                    ? Color(nsColor: .labelColor).opacity(0.07)
                                    : Color.clear,
                                in: RoundedRectangle(cornerRadius: 8, style: .continuous)
                            )
                            .contentShape(Rectangle())
                        }
                        .buttonStyle(.plain)
                        .onHover { h in listViewHoveredIndex = h ? (10000 + idx) : nil }
                        .padding(.horizontal, 6)
                        .id("submenu-drop-\(idx)")
                    }
                    .padding(.bottom, 8)
                }
            }
            .frame(maxWidth: .infinity, maxHeight: 280)
            .background(.regularMaterial)
            .clipShape(RoundedRectangle(cornerRadius: 16, style: .continuous))
            .overlay(
                RoundedRectangle(cornerRadius: 16, style: .continuous)
                    .strokeBorder(.white.opacity(0.14), lineWidth: 0.5)
            )
            .shadow(color: .black.opacity(0.18), radius: 20, x: 0, y: 8)
            .onChange(of: l2.focusedPillIndex) { newIndex in
                guard let idx = newIndex else { return }
                withAnimation(.spring(response: 0.2, dampingFraction: 0.85)) {
                    proxy.scrollTo("submenu-drop-\(idx)", anchor: .center)
                }
            }
        }
        .transition(.asymmetric(
            insertion: .opacity.combined(with: .scale(
                scale: 0.95,
                anchor: settings.effectiveDockAtBottom ? .bottom : .top)
            ),
            removal: .opacity.combined(with: .scale(
                scale: 0.95,
                anchor: settings.effectiveDockAtBottom ? .bottom : .top)
            )
        ))
    }

