    @ViewBuilder
    private func pillListRow(pill: DockPill, index: Int) -> some View {
        let accent = accentColor(for: pill.accentColorName)
        let isKeyboardFocused = l2.focusedPillIndex == index
        let isHov = listViewHoveredIndex == index
        let isActive = isKeyboardFocused || isHov
        let isDisabled = !pill.isEnabled && !isStaleAvailabilityMenuPill(pill)
        let subtitle = (pill.menuContext?.isEmpty == false) ? pill.menuContext! : (pill.badge ?? "Run")

        Button {
            guard !isDisabled else { return }
            let q = searchState.query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
            executeDockPill(pill)
            searchState.query = ""
            l2.focusedPillIndex = nil
            listViewHoveredIndex = nil
            // Teach intent: user picked a menu action for this query
            if !q.isEmpty { AppUsageLearner.shared.recordQueryIntent(query: q, wasMenu: true) }
        } label: {
            HStack(spacing: 11) {
                // Icon badge
                ZStack {
                    RoundedRectangle(cornerRadius: 8)
                        .fill(accent.opacity(isDisabled ? 0.07 : (isActive ? 0.24 : 0.12)))
                        .frame(width: 44, height: 44)
                    if let img = pill.menuItemImage {
                        Image(nsImage: img)
                            .resizable()
                            .interpolation(.medium)
                            .aspectRatio(contentMode: .fit)
                            .frame(width: 25, height: 25)
                            .opacity(isDisabled ? 0.35 : 1.0)
                    } else {
                        Image(systemName: pill.icon)
                            .font(.system(size: 18, weight: .semibold))
                            .foregroundStyle((isDisabled ? accent.opacity(0.30) : (isActive ? accent : accent.opacity(0.80))))
                    }
                }

                // Name + context
                VStack(alignment: .leading, spacing: 2) {
                    Text(pill.name)
                        .font(.system(size: 16, weight: .semibold))
                        .foregroundStyle(isDisabled ? .tertiary : .primary)
                        .lineLimit(1)
                    HStack(spacing: 5) {
                        Text(subtitle)
                            .font(.system(size: 13, weight: .medium))
                            .foregroundStyle(.secondary)
                            .lineLimit(1)
                        if isDisabled {
                            Text("Unavailable")
                                .font(.system(size: 11, weight: .medium))
                                .foregroundStyle(.tertiary)
                                .padding(.horizontal, 5)
                                .padding(.vertical, 2)
                                .background(Color.secondary.opacity(0.10))
                                .clipShape(RoundedRectangle(cornerRadius: 4))
                        }
                    }
                }

                Spacer(minLength: 0)

                // Source app + return badge
                if isActive {
                    HStack(spacing: 5) {
                        if !pill.sourceAppName.isEmpty {
                            Text(pill.sourceAppName)
                                .font(.system(size: 11))
                                .foregroundStyle(.secondary.opacity(0.55))
                                .lineLimit(1)
                        }
                        Image(systemName: "return")
                            .font(.system(size: 10, weight: .medium))
                            .foregroundStyle(.secondary.opacity(0.45))
                            .padding(.horizontal, 5)
                            .padding(.vertical, 3)
                            .background(Color.secondary.opacity(0.09))
                            .clipShape(RoundedRectangle(cornerRadius: 5))
                    }
                }
            }
            .frame(height: 58)
            .padding(.horizontal, 10)
            .background {
                ZStack {
                    if isKeyboardFocused {
                        RoundedRectangle(cornerRadius: 12, style: .continuous)
                            .fill(Color.accentColor.opacity(0.22))
                        RoundedRectangle(cornerRadius: 12, style: .continuous)
                            .fill(Color.white.opacity(0.10))
                        RoundedRectangle(cornerRadius: 12, style: .continuous)
                            .strokeBorder(Color.accentColor.opacity(0.45), lineWidth: 1)
                    } else if isHov {
                        RoundedRectangle(cornerRadius: 12, style: .continuous)
                            .fill(Color.primary.opacity(0.08))
                    }
                }
            }
            .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        .opacity(isDisabled ? 0.45 : 1.0)
        .onHover { hovering in
            listViewHoveredIndex = hovering ? index : nil
            if hovering { l2.pillNavViaKeyboard = false }
        }
    }

    @ViewBuilder
    private func groupedMenuPillRow(group: MenuPillGroup, index: Int) -> some View {
        let primary = group.primaryPill
        let accent = accentColor(for: primary.accentColorName)
        let isKeyboardFocused = l2.focusedPillIndex == index
        let isHov = listViewHoveredIndex == index
        let isActive = isKeyboardFocused || isHov
        let subtitle = (primary.menuContext?.isEmpty == false) ? primary.menuContext! : (primary.badge ?? "")

        HStack(spacing: 11) {
            // Icon badge
            ZStack {
                RoundedRectangle(cornerRadius: 8)
                    .fill(accent.opacity(isActive ? 0.24 : 0.12))
                    .frame(width: 44, height: 44)
                if let img = primary.menuItemImage {
                    Image(nsImage: img)
                        .resizable().interpolation(.medium)
                        .aspectRatio(contentMode: .fit)
                        .frame(width: 25, height: 25)
                } else {
                    Image(systemName: primary.icon)
                        .font(.system(size: 18, weight: .semibold))
                        .foregroundStyle(isActive ? accent : accent.opacity(0.80))
                }
            }

            // Action name + parent menu
            VStack(alignment: .leading, spacing: 2) {
                Text(primary.name)
                    .font(.system(size: 16, weight: .semibold))
                    .foregroundStyle(.primary)
                    .lineLimit(1)
                if !subtitle.isEmpty {
                    Text(subtitle)
                        .font(.system(size: 13, weight: .medium))
                        .foregroundStyle(.secondary)
                        .lineLimit(1)
                }
            }

            Spacer(minLength: 8)

            // App chips — one per source app, tappable
            ScrollView(.horizontal, showsIndicators: false) {
                HStack(spacing: 5) {
                    ForEach(group.allPills) { pill in
                        Button {
                            let q = searchState.query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
                            executeDockPill(pill)
                            searchState.query = ""
                            l2.focusedPillIndex = nil
                            listViewHoveredIndex = nil
                            if !q.isEmpty { AppUsageLearner.shared.recordQueryIntent(query: q, wasMenu: true) }
                        } label: {
                            HStack(spacing: 4) {
                                if !pill.sourceBundleId.isEmpty,
                                   let appURL = NSWorkspace.shared.urlForApplication(withBundleIdentifier: pill.sourceBundleId) {
                                    let appIcon = NSWorkspace.shared.icon(forFile: appURL.path)
                                    Image(nsImage: appIcon)
                                        .resizable().aspectRatio(contentMode: .fit)
                                        .frame(width: 14, height: 14)
                                        .clipShape(RoundedRectangle(cornerRadius: 3))
                                }
                                Text(pill.sourceAppName.isEmpty ? pill.name : pill.sourceAppName)
                                    .font(.system(size: 11, weight: .medium))
                                    .foregroundStyle(.primary.opacity(0.85))
                                    .lineLimit(1)
                                if let sc = pill.badge, !sc.isEmpty {
                                    Text(sc)
                                        .font(.system(size: 10, weight: .light))
                                        .foregroundStyle(.secondary)
                                }
                            }
                            .padding(.horizontal, 7)
                            .padding(.vertical, 4)
                            .background(Color.primary.opacity(isActive ? 0.12 : 0.07))
                            .clipShape(RoundedRectangle(cornerRadius: 6))
                        }
                        .buttonStyle(.plain)
                    }
                }
            }
            .frame(maxWidth: 260)
        }
        .frame(height: 58)
        .padding(.horizontal, 10)
        .background {
            ZStack {
                if isKeyboardFocused {
                    RoundedRectangle(cornerRadius: 12, style: .continuous)
                        .fill(Color.accentColor.opacity(0.22))
                    RoundedRectangle(cornerRadius: 12, style: .continuous)
                        .fill(Color.white.opacity(0.10))
                    RoundedRectangle(cornerRadius: 12, style: .continuous)
                        .strokeBorder(Color.accentColor.opacity(0.45), lineWidth: 1)
                } else if isHov {
                    RoundedRectangle(cornerRadius: 12, style: .continuous)
                        .fill(Color.primary.opacity(0.08))
                }
            }
        }
        .contentShape(Rectangle())
        .onHover { hovering in
            listViewHoveredIndex = hovering ? index : nil
            if hovering { l2.pillNavViaKeyboard = false }
        }
        .onTapGesture {
            // Tap on the row (not a chip) executes the primary pill
            let q = searchState.query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
            executeDockPill(primary)
            searchState.query = ""
            l2.focusedPillIndex = nil
            listViewHoveredIndex = nil
            if !q.isEmpty { AppUsageLearner.shared.recordQueryIntent(query: q, wasMenu: true) }
        }
    }

    @ViewBuilder
    private var pinnedAppsListView: some View {
        let searchQuery = searchState.query.trimmingCharacters(in: .whitespaces).lowercased()
        let inGlobalAutoFocus = isGlobalContextActive && settings.showRunningAppsInBar
        let basePinned = inGlobalAutoFocus
            ? settings.pinnedApps.filter { $0.bundleIdentifier != frontmost.bundleID }
            : settings.pinnedApps
        let visiblePinned = searchQuery.isEmpty
            ? basePinned
            : basePinned.filter { $0.name.lowercased().contains(searchQuery) }
        let pinnedBundleIds = Set(settings.pinnedApps.compactMap { $0.bundleIdentifier })
        let visibleRunning: [NSRunningApplication] = {
            guard settings.showRunningAppsInBar else { return [] }
            let source = runningRegularApps.isEmpty ? currentRegularRunningApps() : runningRegularApps
            var seen = Set<String>()
            return source.filter { app in
                guard app.bundleIdentifier != Bundle.main.bundleIdentifier else { return false }
                if inGlobalAutoFocus, app.bundleIdentifier == frontmost.bundleID { return false }
                if let bid = app.bundleIdentifier, pinnedBundleIds.contains(bid) { return false }
                if let path = app.bundleURL?.path,
                   Set(settings.pinnedApps.map { $0.path }).contains(path) { return false }
                if !searchQuery.isEmpty,
                   !(app.localizedName ?? "").lowercased().contains(searchQuery) { return false }
                let key = app.bundleIdentifier ?? app.bundleURL?.path ?? "\(app.processIdentifier)"
                return seen.insert(key).inserted
            }
        }()

        ScrollView(.vertical, showsIndicators: false) {
            LazyVStack(spacing: 2) {
                ForEach(Array(visiblePinned.enumerated()), id: \.element.id) { idx, app in
                    let isRunning = runningApp(for: app) != nil
                    appListRow(
                        icon: resolvedPinnedIcon(for: app),
                        name: app.name,
                        subtitle: isRunning ? "Running" : "Launch",
                        index: idx,
                        action: {
                            launchPinnedApp(app)
                            if isGlobalContextActive {
                                scheduleContextDockTransition(bundleId: app.bundleIdentifier, appName: app.name)
                            }
                        }
                    )
                    .id("app-list-\(idx)")
                }
                if !visiblePinned.isEmpty && !visibleRunning.isEmpty {
                    Divider().padding(.horizontal, 8).padding(.vertical, 2)
                }
                ForEach(Array(visibleRunning.enumerated()), id: \.element.processIdentifier) { offset, app in
                    let idx = visiblePinned.count + offset
                    appListRow(
                        icon: resolvedRunningAppIcon(for: app),
                        name: app.localizedName ?? "App",
                        subtitle: "Running",
                        index: idx,
                        action: {
                            activateRunningAppFromDock(app)
                            if isGlobalContextActive {
                                scheduleContextDockTransition(bundleId: app.bundleIdentifier, appName: app.localizedName ?? "App")
                            }
                        }
                    )
                    .id("app-list-\(idx)")
                }
            }
            .padding(6)
        }
        .frame(maxHeight: 320)
        .background {
            ZStack {
                RoundedRectangle(cornerRadius: 18, style: .continuous)
                    .fill(.ultraThinMaterial)
                RoundedRectangle(cornerRadius: 18, style: .continuous)
                    .fill(
                        LinearGradient(
                            colors: [.white.opacity(0.16), .white.opacity(0.035)],
                            startPoint: .topLeading,
                            endPoint: .bottomTrailing
                        )
                    )
            }
        }
        .clipShape(RoundedRectangle(cornerRadius: 18, style: .continuous))
        .overlay {
            RoundedRectangle(cornerRadius: 18, style: .continuous)
                .strokeBorder(
                    LinearGradient(
                        colors: [.white.opacity(0.34), .white.opacity(0.08)],
                        startPoint: .topLeading,
                        endPoint: .bottomTrailing
                    ),
                    lineWidth: 1
                )
        }
        .shadow(color: .black.opacity(0.24), radius: 24, x: 0, y: 10)
        .transition(.opacity)
    }

    @ViewBuilder
    private func appListRow(
        icon: NSImage?,
        name: String,
        subtitle: String,
        index: Int,
        quitAction: (() -> Void)? = nil,
        action: @escaping () -> Void
    ) -> some View {
        let isKeyboardFocused = focusedAppPillIndex == index
        let isHov = hoveredAppPillIndex == index
        let isActive = isKeyboardFocused || isHov

        Button(action: action) {
            HStack(spacing: 11) {
                // App icon
                Group {
                    if let img = icon {
                        Image(nsImage: img)
                            .resizable()
                            .interpolation(.high)
                            .aspectRatio(contentMode: .fit)
                            .frame(width: 44, height: 44)
                            .clipShape(RoundedRectangle(cornerRadius: 10, style: .continuous))
                    } else {
                        RoundedRectangle(cornerRadius: 10, style: .continuous)
                            .fill(Color.secondary.opacity(0.15))
                            .frame(width: 44, height: 44)
                    }
                }
                .scaleEffect(isActive ? 1.05 : 1.0)
                .animation(.spring(response: 0.22, dampingFraction: 0.75), value: isActive)

                // Name + subtitle
                VStack(alignment: .leading, spacing: 2) {
                    Text(name)
                        .font(.system(size: 16, weight: .semibold))
                        .foregroundStyle(.primary)
                        .lineLimit(1)
                    Text(subtitle)
                        .font(.system(size: 13, weight: .medium))
                        .foregroundStyle(.secondary)
                        .lineLimit(1)
                }

                Spacer(minLength: 0)

                if isActive {
                    HStack(spacing: 6) {
                        if let quitAction {
                            Button(role: .destructive) {
                                quitAction()
                            } label: {
                                HStack(spacing: 5) {
                                    Text("⌫")
                                        .font(.system(size: 10, weight: .bold))
                                    Text("Quit")
                                        .font(.system(size: 11, weight: .semibold))
                                    Image(systemName: "rectangle.portrait.and.arrow.right")
                                        .font(.system(size: 10, weight: .semibold))
                                }
                                .foregroundStyle(.primary.opacity(0.78))
                                .padding(.leading, 9)
                                .padding(.trailing, 7)
                                .padding(.vertical, 6)
                                .background {
                                    Capsule(style: .continuous)
                                        .fill(.black.opacity(0.22))
                                        .overlay(
                                            Capsule(style: .continuous)
                                                .strokeBorder(.white.opacity(0.18), lineWidth: 0.7)
                                        )
                                }
                            }
                            .buttonStyle(.plain)
                        }

                        Image(systemName: "return")
                            .font(.system(size: 10, weight: .medium))
                            .foregroundStyle(.secondary.opacity(0.45))
                            .padding(.horizontal, 5)
                            .padding(.vertical, 3)
                            .background(Color.secondary.opacity(0.09))
                            .clipShape(RoundedRectangle(cornerRadius: 5))
                    }
                    .transition(.opacity.combined(with: .move(edge: .trailing)))
                }
            }
            .frame(height: 58)
            .padding(.horizontal, 10)
            .background {
                RoundedRectangle(cornerRadius: 12, style: .continuous)
                    .fill(isKeyboardFocused ? Color.accentColor.opacity(0.18) : Color.primary.opacity(isHov ? 0.075 : 0))
                    .animation(.spring(response: 0.2, dampingFraction: 0.75), value: isActive)
            }
            .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        .onHover { hovering in
            withAnimation(.spring(response: 0.18, dampingFraction: 0.75)) {
                hoveredAppPillIndex = hovering ? index : nil
            }
        }
    }

    private var isExplicitAppScope: Bool {
        resolveDockScope(for: searchState.query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()).isExplicitAppScope
    }

    private var shouldShowL2UnifiedDockRow: Bool {
        guard showContextInDock, !aiMode.isActive else { return false }
        let q = searchState.query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        if isGlobalContextActive {
            if q.isEmpty {
                return settings.showRunningAppsInBar || !settings.pinnedApps.isEmpty
            }
            if shouldUsePureGlobalAppSearch {
                return true
            }
            let visiblePills = currentVisibleDockPills(for: q)
            return visiblePills.contains { !$0.isSeparator }
        }
        guard !q.isEmpty else { return false }
        let visiblePills = currentVisibleDockPills(for: q)
        return visiblePills.contains { !$0.isSeparator }
    }

    /// Single pill button with focus highlight for keyboard navigation.
    @ViewBuilder
    private func unifiedPillButton(pill: DockPill, index: Int, isExpanded: Bool = false, isCompact: Bool = false) -> some View {
        if pill.isSeparator {
            // Render as a thin vertical divider with optional app-name label
            HStack(spacing: 3) {
                Rectangle()
                    .fill(Color.secondary.opacity(0.25))
                    .frame(width: 1, height: 16)
                if !pill.name.isEmpty {
                    Text(pill.name)
                        .font(.system(size: 9, weight: .medium))
                        .foregroundStyle(.tertiary)
                        .lineLimit(1)
                }
            }
            .padding(.horizontal, 2)
        } else {
            let accent = accentColor(for: pill.accentColorName)
            let focused = l2.focusedPillIndex == index
            let iconSize: CGFloat = isExpanded ? 24 : (isCompact ? 10 : 14)
            let textSize: CGFloat = isExpanded ? 14 : (isCompact ? 10 : 12)
            let hPad: CGFloat = isExpanded ? 12 : (isCompact ? 8 : 12)
            let vPad: CGFloat = isExpanded ? 0 : (isCompact ? 4 : 7)
            Button {
                executeDockPill(pill)
                searchState.query = ""
                l2.focusedPillIndex = nil
            } label: {
                HStack(spacing: isExpanded ? 0 : (isCompact ? 4 : 6)) {
                    if let img = pill.menuItemImage {
                        Image(nsImage: img)
                            .resizable()
                            .interpolation(.high)
                            .aspectRatio(contentMode: .fit)
                            .frame(width: iconSize, height: iconSize)
                            .opacity(focused ? 1.0 : 0.88)
                    } else {
                        Image(systemName: pill.icon)
                            .font(.system(size: isExpanded ? iconSize * 0.72 : (isCompact ? 9 : 11), weight: .semibold))
                            .foregroundStyle(focused ? accent : accent.opacity(0.88))
                            .frame(width: isExpanded ? iconSize : nil, height: isExpanded ? iconSize : nil)
                    }
                    if isExpanded {
                        Rectangle()
                            .fill(Color.white.opacity(0.16))
                            .frame(width: 1, height: 28)
                            .padding(.horizontal, 10)
                        VStack(alignment: .leading, spacing: 1) {
                            Text(pill.name)
                                .font(.system(size: textSize, weight: .semibold))
                                .foregroundStyle(Color.primary)
                                .lineLimit(1)
                            if let ctx = pill.menuContext {
                                Text(ctx)
                                    .font(.system(size: 9, weight: .medium))
                                    .foregroundStyle(.secondary.opacity(0.65))
                                    .lineLimit(1)
                            }
                        }
                        Spacer(minLength: 0)
                        Image(systemName: "return")
                            .font(.system(size: 11, weight: .medium))
                            .foregroundStyle(.secondary.opacity(0.55))
                    } else {
                        Text(pill.name)
                            .font(.system(size: textSize, weight: .medium))
                            .foregroundStyle(Color.primary.opacity(focused ? 1.0 : 0.88))
                            .lineLimit(1)
                        // Badge (shortcut): only in normal scroll row
                        if let badge = pill.badge, l2.focusedPillIndex == nil {
                            Text(badge)
                                .font(.system(size: 9, weight: .medium))
                                .foregroundStyle(.secondary)
                                .lineLimit(1)
                                .fixedSize(horizontal: true, vertical: false)
                                .padding(.horizontal, 4).padding(.vertical, 1)
                                .background(.white.opacity(0.08), in: Capsule())
                        }
                    }
                }
                .frame(maxWidth: isExpanded ? .infinity : nil)
                .frame(height: isExpanded ? 44 : nil)
                .padding(.horizontal, hPad).padding(.vertical, vPad)
                // Match context dock input field: ultraThinMaterial + white gradient border
                .background {
                    if focused {
                        ZStack {
                            Capsule().fill(.ultraThinMaterial)
                            Capsule().fill(
                                LinearGradient(
                                    colors: [.white.opacity(0.28), .white.opacity(0.06)],
                                    startPoint: .top, endPoint: .bottom)
                            )
                            Capsule().strokeBorder(
                                LinearGradient(
                                    colors: [.white.opacity(0.65), .white.opacity(0.06)],
                                    startPoint: .topLeading, endPoint: .bottomTrailing),
                                lineWidth: 1.5)
                            Capsule()
                                .strokeBorder(Color.white.opacity(0.75), lineWidth: 1.5)
                                .blur(radius: 3)
                        }
                    } else {
                        ZStack {
                            Capsule().fill(.ultraThinMaterial)
                            Capsule().fill(
                                LinearGradient(
                                    colors: [.white.opacity(0.14), .white.opacity(0.02)],
                                    startPoint: .top, endPoint: .bottom)
                            )
                            Capsule().strokeBorder(
                                LinearGradient(
                                    colors: [.white.opacity(0.32), .white.opacity(0.06)],
                                    startPoint: .topLeading, endPoint: .bottomTrailing),
                                lineWidth: 0.75)
                        }
                    }
                }
                .shadow(
                    color: focused ? .white.opacity(0.22) : .clear,
                    radius: focused ? 10 : 0, y: focused ? -1 : 0)
                .animation(.spring(response: 0.18, dampingFraction: 0.75), value: focused)
            }
            .buttonStyle(.plain)
            .help(pill.name)
            .onHover { hovering in
                if !l2.pillNavViaKeyboard {
                    l2.focusedPillIndex = hovering ? index : nil
                }
                hoveredDockPillIndex = hovering ? index : nil
            }
            // Right-click context menu — shows Favourite / Unfavourite for menu item pills
            .contextMenu {
                if !pill.menuItemName.isEmpty, !pill.sourceBundleId.isEmpty {
                    Button {
                        settings.toggleFavouriteMenuPill(
                            pill.menuItemName, for: pill.sourceBundleId)
                    } label: {
                        Label(
                            pill.isFavourited ? "Remove from Favourites" : "Add to Favourites",
                            systemImage: pill.isFavourited ? "star.slash" : "star"
                        )
                    }
                }
            }
        }  // end else (non-separator)
    }

    /// Resolve an optional color name string into a SwiftUI Color.
    private func accentColor(for name: String?) -> SwiftUI.Color {
        switch name?.lowercased() {
        case "blue": return .blue
        case "red": return .red
        case "green": return .green
        case "orange": return .orange
        case "yellow": return .yellow
        case "purple": return .purple
        case "indigo": return .indigo
        case "teal": return .teal
        case "pink": return .pink
        case "gray", "grey": return .secondary
        default: return Color.accentColor
        }
    }

    /// Best-effort icon for a menu item. AXImage covers most items; Services items need name lookup.
    private func resolvedMenuIcon(for item: AXMenuItem) -> NSImage? {
        if let img = item.image { return img }
        let isService = item.path.contains(where: { $0 == "Services" })
        guard isService else { return nil }
        let cacheKey = item.path.joined(separator: " > ")
        return MenuIconMemoryCache.shared.image(for: cacheKey) {
            resolveUncachedServiceMenuIcon(for: item)
        }
    }

    private func resolveUncachedServiceMenuIcon(for item: AXMenuItem) -> NSImage? {
        let name = item.title.lowercased()
        // 1. Running app whose display name matches
        if let app = NSWorkspace.shared.runningApplications.first(where: {
            ($0.localizedName ?? "").lowercased() == name && !($0.isTerminated)
        }) { return app.icon }
        // 2. Walk common app directories
        let dirs = ["/Applications", "/System/Applications", "\(NSHomeDirectory())/Applications"]
        for dir in dirs {
            let appPath = "\(dir)/\(item.title).app"
            if FileManager.default.fileExists(atPath: appPath) {
                return NSWorkspace.shared.icon(forFile: appPath)
            }
        }
        // 3. Workflow bundle in ~/Library/Services (Automator quick actions)
        let workflowPath = "\(NSHomeDirectory())/Library/Services/\(item.title).workflow"
        if FileManager.default.fileExists(atPath: workflowPath) {
            return NSWorkspace.shared.icon(forFile: workflowPath)
        }
        // 4. Shortcuts-provided service → Shortcuts.app icon
        if let url = NSWorkspace.shared.urlForApplication(withBundleIdentifier: "com.apple.shortcuts") {
            return NSWorkspace.shared.icon(forFile: url.path)
        }
        return nil
    }

    private func menuSymbol(for item: AXMenuItem) -> String {
        let title = normalizedDockPillText(item.title)
        let pathParts = item.path.map(normalizedDockPillText)
        let path = pathParts.joined(separator: " ")
        let parent = pathParts.dropLast().last ?? pathParts.first ?? ""

        if item.isAppleMenu || item.path.first?.lowercased() == "apple" {
            if title.contains("about this mac") { return "laptopcomputer" }
            if title.contains("system settings") || title.contains("system preferences") { return "gearshape" }
            if title.contains("app store") { return "app.badge" }
            if title.contains("recent") { return "clock.arrow.circlepath" }
            if title.contains("force quit") { return "xmark.octagon" }
            if title == "sleep" || title.contains("sleep") { return "minus.circle" }
            if title.contains("restart") { return "arrow.clockwise" }
            if title.contains("shut down") || title.contains("shutdown") { return "power" }
            if title.contains("lock screen") { return "lock" }
            if title.contains("log out") { return "person.crop.circle.badge.xmark" }
            return "apple.logo"
        }

        if title == "close" || title.hasPrefix("close ") { return "xmark" }
        if title.contains("quit") { return "xmark.circle" }
        if title.contains("hide") { return "eye.slash" }
        if title.contains("show all") { return "eye" }

        if path.hasPrefix("window") || path.contains(" window ") || parent == "window" {
            if title.contains("minimi") { return "minus.rectangle" }
            if title == "zoom" || title.contains("zoom") { return "arrow.up.left.and.arrow.down.right" }
            if title == "fill" || title.contains("fill") { return "rectangle.inset.filled" }
            if title == "centre" || title == "center" { return "rectangle.inset.filled" }
            if title.contains("move") && title.contains("resize") { return "arrow.up.left.and.arrow.down.right" }
            if title.contains("full-screen") || title.contains("full screen") { return "rectangle.split.2x1" }
            if title.contains("cycle") { return "square.stack.3d.up" }
            if title.contains("bring all") { return "square.3.layers.3d.top.filled" }
            if title.contains("previous tab") { return "arrow.left.square" }
            if title.contains("next tab") { return "arrow.right.square" }
            if title.contains("merge") { return "rectangle.3.group" }
            if title.contains("download") { return "macwindow" }
            return "macwindow"
        }

        if parent == "file" || path.hasPrefix("file ") {
            if title.contains("new") && title.contains("tab") { return "plus.square.on.square" }
            if title.contains("new") && title.contains("window") { return "macwindow" }
            if title == "new" || title.hasPrefix("new ") { return "plus.square" }
            if title.contains("open recent") { return "clock.arrow.circlepath" }
            if title.contains("open") { return "folder" }
            if title.contains("save as") { return "square.and.arrow.down.on.square" }
            if title.contains("save") { return "square.and.arrow.down" }
            if title.contains("export") { return "square.and.arrow.up" }
            if title.contains("import") { return "square.and.arrow.down" }
            if title.contains("print") { return "printer" }
            if title.contains("share") { return "square.and.arrow.up" }
            if title.contains("close") { return "xmark" }
            return "doc"
        }

        if parent == "edit" || path.hasPrefix("edit ") {
            if title.contains("undo") { return "arrow.uturn.backward" }
            if title.contains("redo") { return "arrow.uturn.forward" }
            if title.contains("cut") { return "scissors" }
            if title.contains("copy") { return "doc.on.doc" }
            if title.contains("paste") { return "clipboard" }
            if title.contains("select all") { return "checkmark.circle" }
            if title.contains("find") || title.contains("search") { return "magnifyingglass" }
            if title.contains("spelling") || title.contains("grammar") { return "textformat.abc" }
            if title.contains("substitution") { return "textformat" }
            if title.contains("transform") { return "textformat.alt" }
            if title.contains("dictation") { return "mic" }
            if title.contains("emoji") { return "face.smiling" }
            return "pencil"
        }

        if parent == "view" || path.hasPrefix("view ") {
            if title.contains("sidebar") { return "sidebar.left" }
            if title.contains("toolbar") { return "menubar.rectangle" }
            if title.contains("tab bar") { return "rectangle.topthird.inset.filled" }
            if title.contains("status") { return "rectangle.bottomthird.inset.filled" }
            if title.contains("actual size") { return "magnifyingglass" }
            if title.contains("zoom in") { return "plus.magnifyingglass" }
            if title.contains("zoom out") { return "minus.magnifyingglass" }
            if title.contains("enter full screen") || title.contains("full screen") { return "arrow.up.left.and.arrow.down.right" }
            if title.contains("reload") || title.contains("refresh") { return "arrow.clockwise" }
            return "eye"
        }

        if title.contains("recent") || path.contains("recent") { return "clock.arrow.circlepath" }
        if title.contains("history") || path.contains("history") { return "clock.arrow.circlepath" }
        if title.contains("search") || title.contains("find") { return "magnifyingglass" }
        if title.contains("favourite") || title.contains("favorite")
            || path.contains("favourite") || path.contains("favorite")
            || title.contains("bookmark") || path.contains("bookmark") {
            return "bookmark"
        }
        if title.contains("reading list") { return "eyeglasses" }
        if title.contains("download") { return "arrow.down.circle" }
        if title.contains("desktop") { return "menubar.rectangle" }
        if title.contains("document") { return "doc.text" }
        if title.contains("home") { return "house" }
        if title.contains("library") { return "building.columns" }
        if title.contains("computer") { return "desktopcomputer" }
        if title.contains("airdrop") { return "antenna.radiowaves.left.and.right" }
        if title.contains("network") { return "network" }
        if title.contains("icloud") { return "icloud" }
        if title.contains("application") { return "app.badge" }
        if title.contains("utilit") { return "wrench.and.screwdriver" }
        if title.contains("folder") || path.contains("go ") { return "folder.fill" }

        if title.contains("back") { return "chevron.backward" }
        if title.contains("forward") { return "chevron.forward" }
        if title.contains("reload") || title.contains("refresh") { return "arrow.clockwise" }
        if title.contains("stop") { return "xmark.octagon" }
        if title.contains("reader") { return "doc.plaintext" }
        if title.contains("privacy") { return "hand.raised" }
        if title.contains("security") { return "lock.shield" }
        if title.contains("extension") { return "puzzlepiece" }
        if title.contains("password") { return "key" }
        if title.contains("address") || title.contains("location") { return "location" }
        if title.contains("map") || title.contains("directions") { return "map" }
        if title.contains("route") { return "map" }
        if title.contains("play") { return "play" }
        if title.contains("pause") { return "pause" }
        if title.contains("mute") { return "speaker.slash" }
        if title.contains("volume") { return "speaker.wave.2" }
        if title.contains("mail") || title.contains("email") { return "envelope" }
        if title.contains("message") { return "message" }
        if title.contains("call") { return "phone" }
        if title.contains("calendar") || title.contains("event") { return "calendar" }
        if title.contains("reminder") { return "checklist" }
        if title.contains("note") { return "note.text" }

        if title.contains("open with") { return "chevron.right.square" }
        if title.contains("open") { return "arrow.up.right.square" }
        if title.contains("bin") || title.contains("trash") { return "trash" }
        if title.contains("info") { return "info.circle" }
        if title.contains("rename") { return "pencil" }
        if title.contains("compress") || title.contains("archive") { return "archivebox" }
        if title.contains("duplicate") { return "plus.square.on.square" }
        if title.contains("alias") { return "arrow.triangle.branch" }
        if title.contains("quick look") { return "eye" }
        if title.contains("copy") { return "doc.on.doc" }
        if title.contains("share") { return "square.and.arrow.up" }
        if title.contains("tag") { return "tag" }
        if title.contains("service") { return "gearshape.2" }
        if title.contains("quick action") { return "bolt" }

        switch parent {
        case "file": return "doc"
        case "edit": return "pencil"
        case "view": return "eye"
        case "go": return "arrowshape.turn.up.right"
        case "bookmarks": return "bookmark"
        case "history": return "clock.arrow.circlepath"
        case "develop": return "hammer"
        case "help": return "questionmark.circle"
        case "services": return "gearshape.2"
        default: break
        }

        return "menubar.rectangle"
    }

    private func resolvedBundleId(for pid: pid_t, fallbackBundleId: String) -> String {
        if pid != 0,
            let bundleId = NSWorkspace.shared.runningApplications.first(
                where: { $0.processIdentifier == pid && !$0.isTerminated }
            )?.bundleIdentifier,
            !bundleId.isEmpty
        {
            return bundleId
        }
        return fallbackBundleId
    }

    /// Smart pills generated from the live AX context snapshot.
    /// These complement user-configured pills with zero-config, always-relevant actions.
    @ViewBuilder
    private var axSmartPills: some View {
        let ax = axContext
        if !ax.isEmpty {
            // Separator before smart pills
            Rectangle().fill(.secondary.opacity(0.2)).frame(width: 1, height: 20)

            // Copy URL — shown when a browser URL is detected
            if let url = ax.currentURL {
                Button {
                    NSPasteboard.general.clearContents()
                    NSPasteboard.general.setString(url, forType: .string)
                } label: {
                    HStack(spacing: 5) {
                        Image(systemName: "link").font(.system(size: 10, weight: .semibold))
                            .foregroundStyle(.teal)
                        Text("Copy URL").font(.system(size: 11, weight: .medium)).lineLimit(1)
                    }
                    .padding(.horizontal, 10).padding(.vertical, 5)
                    .background(.regularMaterial, in: Capsule())
                    .overlay(Capsule().strokeBorder(.teal.opacity(0.3), lineWidth: 0.5))
                }
                .buttonStyle(.plain).help(url)
                .transition(.scale(scale: 0.8).combined(with: .opacity))

                // Ask About Page — send URL to AI
                Button {
                    guard !isExplicitAppScopeLocked else { return }
                    let prompt = "What is this page about? URL: \(url)"
                    searchState.query = prompt
                    aiMode.isActive = true
                    showContextInDock = false
                    submitAIQuery()
                } label: {
                    HStack(spacing: 5) {
                        Image(systemName: "sparkles").font(.system(size: 10, weight: .semibold))
                            .foregroundStyle(.indigo)
                        Text("Ask About Page").font(.system(size: 11, weight: .medium)).lineLimit(1)
                    }
                    .padding(.horizontal, 10).padding(.vertical, 5)
                    .background(.regularMaterial, in: Capsule())
                    .overlay(Capsule().strokeBorder(.indigo.opacity(0.3), lineWidth: 0.5))
                }
                .buttonStyle(.plain).help("Ask AI about this page")
                .transition(.scale(scale: 0.8).combined(with: .opacity))
            }

            // Copy Selection — shown when text is selected in the frontmost app
            if let sel = ax.selectedText, !sel.isEmpty {
                Button {
                    NSPasteboard.general.clearContents()
                    NSPasteboard.general.setString(sel, forType: .string)
                } label: {
                    HStack(spacing: 5) {
                        Image(systemName: "text.cursor").font(.system(size: 10, weight: .semibold))
                            .foregroundStyle(.orange)
                        Text("Copy Selection").font(.system(size: 11, weight: .medium)).lineLimit(1)
                    }
                    .padding(.horizontal, 10).padding(.vertical, 5)
                    .background(.regularMaterial, in: Capsule())
                    .overlay(Capsule().strokeBorder(.orange.opacity(0.3), lineWidth: 0.5))
                }
                .buttonStyle(.plain).help(sel.count > 60 ? String(sel.prefix(60)) + "…" : sel)
                .transition(.scale(scale: 0.8).combined(with: .opacity))

                // Ask About Selection
                Button {
                    guard !isExplicitAppScopeLocked else { return }
                    let text = sel.count > 500 ? String(sel.prefix(500)) : sel
                    searchState.query = "Explain: \(text)"
                    aiMode.isActive = true
                    showContextInDock = false
                    submitAIQuery()
                } label: {
                    HStack(spacing: 5) {
                        Image(systemName: "sparkles").font(.system(size: 10, weight: .semibold))
                            .foregroundStyle(.indigo)
                        Text("Ask About Selection").font(.system(size: 11, weight: .medium))
                            .lineLimit(1)
                    }
                    .padding(.horizontal, 10).padding(.vertical, 5)
                    .background(.regularMaterial, in: Capsule())
                    .overlay(Capsule().strokeBorder(.indigo.opacity(0.3), lineWidth: 0.5))
                }
                .buttonStyle(.plain)
                .transition(.scale(scale: 0.8).combined(with: .opacity))
            }
        }
    }

    // MARK: - App Shortcuts Dock Row — shown when a smart query (calendar/notes…) or folder is active
    @ViewBuilder
    private var appShortcutsInDock: some View {
        let key = searchState.activeSmartQueryKey ?? folderSmartKey
        // contextPanelActions() already includes user shortcuts when searchState.contextApp != nil,
        // so only pull shortcuts directly for built-in key panels (no searchState.contextApp)
        let contextActions = contextPanelActions()
        let hasSearchCtx = searchState.contextApp != nil
        let extraShortcuts: [AppShortcut] =
            hasSearchCtx
            ? []
            : {
                // Merge quick-actions and context-dock shortcuts, deduplicated by name
                var seen = Set<String>()
                let quick = settings.shortcuts(for: key)
                let dock = settings.contextDockShortcuts(for: key)
                for s in quick { seen.insert(s.name) }
                return quick + dock.filter { seen.insert($0.name).inserted }
            }()

        // Context: is there a selected file or text right now?
        let hasFileSelection: Bool =
            folderPreviewSelectedFile != nil
            || (searchState.selectedIndex.map {
                $0 < searchState.results.count && searchState.results[$0].filePath != nil
            } ?? false)
            || !axContext.selectedFilePaths.isEmpty
            || {
                switch currentContext {
                case .filesSelected(let urls): return !urls.isEmpty
                default: return false
                }
            }()
        let hasTextSelection: Bool =
            !(axContext.selectedText?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ?? true)
            || {
                switch currentContext {
                case .textSelected(let text):
                    return !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                default:
                    return false
                }
            }()

        // Filter context-sensitive shortcuts: hide shell/$1 actions when nothing is selected
        let visibleShortcuts = extraShortcuts.filter { sc in
            guard sc.actionType == .shellCommand || sc.actionType == .appleScript else {
                return true
            }
            let v = sc.actionValue
            let needsFile =
                v.contains("$1") || v.contains("$2") || v.contains("$SELECTED_FILES")
                || v.contains("$SELECTED_FILE")
            let needsText = v.contains("$SELECTED_TEXT")
            if needsFile && !hasFileSelection { return false }
            if needsText && !hasTextSelection { return false }
            return true
        }

        let showHint = contextActions.isEmpty && visibleShortcuts.isEmpty

        return ScrollView(.horizontal, showsIndicators: false) {
            HStack(spacing: 8) {
                ForEach(contextActions) { action in
                    dockPillButton(icon: action.icon, label: action.label, action: action.action)
                }
                ForEach(visibleShortcuts) { sc in
                    dockPillButton(icon: sc.iconName, label: sc.name) { executeAppShortcut(sc) }
                }
                if showHint {
                    Text("No quick actions — add some in Settings › App Shortcuts")
                        .font(.caption)
                        .foregroundStyle(.secondary)
                        .padding(.horizontal, 8)
                }
            }
            .padding(.horizontal, 6)
            .padding(.vertical, 4)
        }
    }

    /// Floating pill-shaped dock button used for all quick actions.
    @ViewBuilder
    private func dockPillButton(icon: String, label: String, action: @escaping () -> Void)
        -> some View
    {
        Button(action: action) {
            HStack(spacing: 5) {
                Image(systemName: icon)
                    .font(.system(size: 12, weight: .semibold))
                Text(label)
                    .font(.system(size: 12, weight: .medium))
                    .lineLimit(1)
            }
            .foregroundStyle(.primary)
            .padding(.horizontal, 11)
            .padding(.vertical, 6)
            .background(.regularMaterial, in: Capsule())
            .overlay(Capsule().strokeBorder(.primary.opacity(0.08), lineWidth: 0.5))
        }
        .buttonStyle(.plain)
        .help(label)
    }

    /// Key used when a folder is open but no app smart query is active
    private var folderSmartKey: String {
        if let path = folderPreviewPath {
            let name = URL(fileURLWithPath: path).lastPathComponent.lowercased()
            if name == "downloads" { return "downloads" }
        }
        return ""
    }

    private func executeAppShortcut(_ sc: AppShortcut) {
        // ── Gather context ───────────────────────────────────────────────
        // Selected file(s): folder preview selection first, then highlighted search result
        var selectedFilePaths: [String] = []
        if let previewFile = folderPreviewSelectedFile, !previewFile.isEmpty {
            selectedFilePaths = [previewFile]
        } else if let idx = searchState.selectedIndex, idx < searchState.results.count,
            let path = searchState.results[idx].filePath, !path.isEmpty
        {
            selectedFilePaths = [path]
        }
        // Also pick up any multi-selection from Finder if no in-app selection
        if selectedFilePaths.isEmpty {
            selectedFilePaths = ContextDetector.shared.getFinderSelectedFiles().map { $0.path }
        }

        // Use the app that was frontmost BEFORE ILauncher activated — never ILauncher itself.
        let prevApp = AppDelegate.shared?.previousFrontmostApp

        // Selected text: accessibility API on the pre-ILauncher frontmost app
        let selectedText: String = {
            guard let app = prevApp else { return "" }
            return ContextDetector.shared.getSelectedText(from: app) ?? ""
        }()

        // ── Substitution helper ──────────────────────────────────────────
        func inject(_ value: String) -> String {
            var result = value
            // $1..$N — individual file paths
            for (i, path) in selectedFilePaths.enumerated() {
                let escaped = path.replacingOccurrences(of: "'", with: "'\\''")
                result = result.replacingOccurrences(of: "$\(i + 1)", with: escaped)
            }
            // $SELECTED_FILES — space-separated list of all paths (shell-quoted)
            let allEscaped = selectedFilePaths.map {
                "'\($0.replacingOccurrences(of: "'", with: "\\'"))'"
            }.joined(separator: " ")
            result = result.replacingOccurrences(of: "$SELECTED_FILES", with: allEscaped)
            // $SELECTED_TEXT — text selected in frontmost app
            let textEscaped = selectedText.replacingOccurrences(of: "'", with: "'\\''")
            result = result.replacingOccurrences(of: "$SELECTED_TEXT", with: textEscaped)
            // $FRONTMOST_APP — name of the app that was active before ILauncher opened
            let frontmostName = prevApp?.localizedName ?? ""
            result = result.replacingOccurrences(of: "$FRONTMOST_APP", with: frontmostName)
            // $FRONTMOST_BUNDLE — bundle identifier of the pre-ILauncher app
            let frontmostBundle = prevApp?.bundleIdentifier ?? ""
            result = result.replacingOccurrences(of: "$FRONTMOST_BUNDLE", with: frontmostBundle)
            // AX-read context variables ─────────────────────────────────────────
            // $CURRENT_URL — URL currently open in the frontmost browser/app window
            let axURL = axContext.currentURL ?? ""
            result = result.replacingOccurrences(of: "$CURRENT_URL", with: axURL)
            // $WINDOW_TITLE — title of the frontmost window
            let axTitle = axContext.windowTitle ?? ""
            result = result.replacingOccurrences(of: "$WINDOW_TITLE", with: axTitle)
            // $AX_SELECTED_TEXT — selected text read via AX API (more reliable than clipboard)
            let axSel = axContext.selectedText ?? ""
            result = result.replacingOccurrences(of: "$AX_SELECTED_TEXT", with: axSel)
            return result
        }

        switch sc.actionType {
        case .openURL:
            if let url = URL(string: inject(sc.actionValue)) { NSWorkspace.shared.open(url) }
        case .openFile:
            NSWorkspace.shared.openApplication(
                at: URL(fileURLWithPath: sc.actionValue),
                configuration: NSWorkspace.OpenConfiguration())
        case .shellCommand:
            let cmd = inject(sc.actionValue)
            let ck = activeConsoleKey
            // Always create panel terminal if needed, open drawer, run command in real PTY
            let panelTerm = panelTerminal(for: ck)
            panelShowConsoleMap[ck] = true
            panelTerm.sendCommand(cmd)
            // Give the terminal focus so output is visible and interactive
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.15) {
                panelTerm.terminalView.window?.makeFirstResponder(panelTerm.terminalView)
            }
        case .appleScript:
            if let script = NSAppleScript(source: inject(sc.actionValue)) {
                script.executeAndReturnError(nil)
            }
        case .jxa:
            // JXA runs via osascript -l JavaScript, passing selected file + text as argv
            let scriptCode = sc.actionValue
            let ck = activeConsoleKey
            let file1 = selectedFilePaths.first ?? ""
            let selText = selectedText
            Task.detached {
                // Write script to a temp file so we can pass it cleanly
                let tmp = FileManager.default.temporaryDirectory
                    .appendingPathComponent("ilauncher_jxa_\(UUID().uuidString).js")
                try? scriptCode.write(to: tmp, atomically: true, encoding: .utf8)
                defer { try? FileManager.default.removeItem(at: tmp) }
                let proc = Process()
                proc.executableURL = URL(fileURLWithPath: "/usr/bin/osascript")
                var args = ["-l", "JavaScript", tmp.path]
                if !file1.isEmpty { args.append(file1) }
                if !selText.isEmpty { args.append(selText) }
                proc.arguments = args
                let pipe = Pipe()
                proc.standardOutput = pipe
                proc.standardError = pipe
                try? proc.run()
                proc.waitUntilExit()
                let out =
                    String(data: pipe.fileHandleForReading.readDataToEndOfFile(), encoding: .utf8)
                    ?? ""
                // Show JXA output in the panel terminal drawer
                await MainActor.run {
                    self.panelShowConsoleMap[ck] = true
                    for line in out.components(separatedBy: "\n") where !line.isEmpty {
                        self.panelConsoleLinesMap[ck, default: []].append(
                            (line: line, isCommand: false))
                    }
                }
            }
        case .scriptFile:
            // Delegate to AXTriggerRuleEngine which handles all script file execution + notifications
            let envVars: [String: String] = [
                "CD_APP_NAME": frontmost.name,
                "CD_BUNDLE_ID": frontmost.bundleID,
                "CD_WINDOW_TITLE": axContext.windowTitle ?? "",
                "CD_SELECTED_TEXT": axContext.selectedText ?? selectedText,
                "CD_URL": axContext.currentURL ?? "",
                "CD_FILE": axContext.selectedFilePaths.first ?? selectedFilePaths.first ?? "",
                "CD_CLIPBOARD": NSPasteboard.general.string(forType: .string) ?? "",
            ]
            AXTriggerRuleEngine.shared.run(
                type: .scriptFile, value: sc.actionValue, envVars: envVars)
        case .menuItem:
            let envVars: [String: String] = [
                "CD_APP_NAME": frontmost.name,
                "CD_BUNDLE_ID": frontmost.bundleID,
                "CD_WINDOW_TITLE": axContext.windowTitle ?? "",
                "CD_SELECTED_TEXT": axContext.selectedText ?? selectedText,
                "CD_URL": axContext.currentURL ?? "",
                "CD_FILE": axContext.selectedFilePaths.first ?? selectedFilePaths.first ?? "",
                "CD_CLIPBOARD": NSPasteboard.general.string(forType: .string) ?? "",
            ]
            AXTriggerRuleEngine.shared.run(type: .menuItem, value: sc.actionValue, envVars: envVars)
        }
    }

    private func shellQuote(_ value: String) -> String {
        "'" + value.replacingOccurrences(of: "'", with: "'\\''") + "'"
    }

    private func appPillScriptExtensions(for appKey: String, query: String) -> [AppToolExtension] {
        settings.pillScriptExtensions(for: appKey, query: query, maxCount: query.isEmpty ? 6 : 4)
    }

    private func executeAppToolExtension(_ ext: AppToolExtension, launchQuery: String = "") {
        guard ext.kind == .script,
              let lang = ext.scriptLanguage,
              !ext.toolPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
            return
        }

        let queryText = launchQuery.trimmingCharacters(in: .whitespacesAndNewlines)
        let selectedFile: String = {
            if let previewFile = folderPreviewSelectedFile, !previewFile.isEmpty { return previewFile }
            if let idx = searchState.selectedIndex, idx < searchState.results.count,
               let path = searchState.results[idx].filePath, !path.isEmpty {
                return path
            }
            if let finderSelected = ContextDetector.shared.getFinderSelectedFiles().first?.path, !finderSelected.isEmpty {
                return finderSelected
            }
            if let axSelected = axContext.selectedFilePaths.first, !axSelected.isEmpty {
                return axSelected
            }
            return ""
        }()

        let fallbackQuery = axContext.selectedText?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let effectiveQuery = queryText.isEmpty ? fallbackQuery : queryText
        let command = [
            lang.runCommand(scriptPath: ext.toolPath),
            shellQuote(selectedFile),
            shellQuote(effectiveQuery)
        ].joined(separator: " ")

        let ck = activeConsoleKey
        let panelTerm = panelTerminal(for: ck)
        panelShowConsoleMap[ck] = true
        panelTerm.sendCommand(command)
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.15) {
            panelTerm.terminalView.window?.makeFirstResponder(panelTerm.terminalView)
        }
    }

    // MARK: - File-Type Extensions Dock Row — shown when a file result is highlighted
    private var selectedResultHasFileTypeExtensions: Bool {
        // True if we have context-based extensions for the selected file/result
        // (context extensions already handle file-type matching via their trigger system)
        guard let idx = searchState.selectedIndex, idx < searchState.results.count else {
            return !l2.contextExtensions.isEmpty
                && !l2.contextExtensions.filter {
                    switch $0.matchReason {
                    case .fileTypeMatch: return true
                    default: return false
                    }
                }.isEmpty
        }
        let result = searchState.results[idx]
        return (result.type == .file || result.type == .document) && !l2.contextExtensions.isEmpty
    }

    /// Shortcuts relevant to the currently highlighted search result's file type
    private var fileTypeShortcutsForSelection: [AppShortcut] {
        // File selected inside folder preview takes priority
        if let selectedFile = folderPreviewSelectedFile, !selectedFile.isEmpty {
            let ext = URL(fileURLWithPath: selectedFile).pathExtension.lowercased()
            return fileTypeShortcuts(for: ext)
        }
        guard let idx = searchState.selectedIndex,
            idx < searchState.results.count
        else { return [] }
        let result = searchState.results[idx]
        guard result.type == .file || result.type == .document else { return [] }
        let ext =
            (result.filePath.map { URL(fileURLWithPath: $0).pathExtension.lowercased() }) ?? ""
        return fileTypeShortcuts(for: ext)
    }

    /// Name of the currently selected file in the folder preview (for display)
    private var selectedFolderFileName: String? {
        guard let path = folderPreviewSelectedFile, !path.isEmpty else { return nil }
        return URL(fileURLWithPath: path).lastPathComponent
    }

    private func fileTypeShortcuts(for ext: String) -> [AppShortcut] {
        // Map common file extensions to app shortcut keys
        // Users can define their own shortcuts for these keys in Settings › App Shortcuts
        let key: String
        switch ext {
        case "pdf": key = "pdf"
        case "jpg", "jpeg", "png", "heic", "gif", "webp", "tiff": key = "image"
        case "mp4", "mov", "avi", "mkv", "m4v": key = "video"
        case "mp3", "aac", "flac", "wav", "m4a": key = "audio"
        case "zip", "rar", "7z", "tar", "gz": key = "archive"
        case "doc", "docx", "pages": key = "document"
        case "xls", "xlsx", "numbers", "csv": key = "spreadsheet"
        case "ppt", "pptx", "key": key = "presentation"
        case "swift", "py", "js", "ts", "rb", "go", "rs", "kt": key = "code"
        default: return []
        }
        return settings.shortcuts(for: key)
    }

    /// Unified context-based dock row shown when a file/result is selected.
    /// Uses the scoring system from LayeredExtensionManager — no hardcoded AppShortcut file-type mapping.
    @ViewBuilder
    private var fileTypeExtensionsInDock: some View {
        if l2.contextExtensions.isEmpty {
            pinnedAppsRow
        } else {
            ScrollView(.horizontal, showsIndicators: false) {
                HStack(spacing: 8) {
                    // File name chip (folder preview only)
                    if let fileName = selectedFolderFileName {
                        let ext = URL(fileURLWithPath: folderPreviewSelectedFile ?? "")
                            .pathExtension.lowercased()
                        HStack(spacing: 5) {
                            Image(systemName: fileIcon(for: ext))
                                .font(.system(size: 11))
                                .foregroundStyle(.secondary)
                            Text(fileName)
                                .font(.system(size: 11, weight: .medium))
                                .foregroundStyle(.secondary)
                                .lineLimit(1)
                                .frame(maxWidth: 120)
                        }
                        .padding(.horizontal, 9)
                        .padding(.vertical, 5)
                        .background(.secondary.opacity(0.12), in: Capsule())
                    }

                    // Context-based action pills — auto-scored by file type, app, selection
                    ForEach(l2.contextExtensions, id: \.ilExtension.id) { result in
                        L2ExtensionChipButton(
                            extensionResult: result,
                            currentContext: currentContext,
                            onExecute: executeL2Extension
                        )
                    }
                }
                .padding(.horizontal, 4)
            }
        }
    }

    // Shared condition: whether any results panel should be visible.
    private var hasResultsToShow: Bool {
        guard !showMediaLayer else { return false }
        return !searchState.results.isEmpty
            || (!searchState.query.isEmpty && !isL2ContextActive)
            || (aiMode.isActive && (!aiMode.messages.isEmpty || aiMode.isLoading || aiMode.streamingId != nil))
            || showFolderPreview
            || (showContextInDock && (!l2.chatMessages.isEmpty || l2.isLoading))
            || searchState.contextApp != nil
            || searchState.activeSmartQueryKey != nil
            || shouldShowFinderSearchResultsPanel(for: searchState.query)
    }

    private var shouldShowFrontmostContextChip: Bool {
        showContextInDock
            && !isGlobalContextActive
            && settings.enableFrontmostDetection
            && l2.targetApp == nil
            && globalInlineAppScope == nil
            && !showMediaLayer
            && !aiMode.isActive
            && !frontmost.name.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            && frontmost.icon != nil
    }

    // Results card: its own glass container, visually detached from the dock bar.
    @ViewBuilder
    private var resultsCard: some View {
        resultsContentView
            .frame(minHeight: 0, maxHeight: aiMode.isActive ? 500 : (showFolderPreview ? 600 : (l1ResultsReservedHeight > 0 ? l1ResultsReservedHeight : 450)))
            .frame(width: resultsPanelWidth, alignment: .leading)
            .background(alignment: .leading) {
                GlassBackground(cornerRadius: 20, isDark: isEffectiveDark)
                    .frame(width: resultsPanelWidth)
            }
            .mask(alignment: .leading) {
                RoundedRectangle(cornerRadius: 20, style: .continuous)
                    .frame(width: resultsPanelWidth)
            }
    }

    @ViewBuilder
    private var resultsCardAlignedToSearchInput: some View {
        HStack(spacing: 0) {
            Color.clear
                .frame(width: resultsPanelLeadingInset)
            resultsCard
            Spacer(minLength: 0)
        }
        .frame(width: calculatedWidth, alignment: .leading)
    }

    @ViewBuilder
    private var floatingAppLogoButton: some View {
        if shouldShowFloatingAppLogo {
            ZStack(alignment: .topTrailing) {
                DLogoButton(
                    action: {
                        withAnimation(.spring(response: 0.3, dampingFraction: 0.75)) {
                            showNotificationDock.toggle()
                            if showNotificationDock { notifDockTab = 0 }
                        }
                    },
                    isPresented: $showNotificationDock,
                    hasUnread: notificationManager.unreadCount > 0,
                    profileImage: userProfileImage
                ) {
                    NotificationDockView(
                        selectedTab: $notifDockTab,
                        profileImage: userProfileImage,
                        onClose: {
                            withAnimation(.spring(response: 0.25, dampingFraction: 0.85)) {
                                showNotificationDock = false
                            }
                        },
                        onOpenSettings: { openSettings() }
                    )
                    .frame(width: notificationDockPopoverWidth)
                    .ifLet(resolvedColorScheme) { view, scheme in
                        view.environment(\.colorScheme, scheme)
                    }
                    .presentationBackground(.clear)
                }
                .help(
                    showNotificationDock
                        ? "Close Notifications"
                        : notificationManager.unreadCount > 0
                            ? "\(notificationManager.unreadCount) unread notification(s)"
                            : "Notifications")

                if notificationManager.unreadCount > 0 {
                    ZStack {
                        Circle().fill(Color.red).frame(width: 14, height: 14)
                        Text(notificationManager.unreadCount > 9 ? "9+" : "\(notificationManager.unreadCount)")
                            .font(.system(size: 8, weight: .bold))
                            .foregroundStyle(.white)
                    }
                    .offset(x: 4, y: -4)
                }
            }
        }
    }

    // Dock bar card: always wrapped in the unified glass card so the NSTextField
    // never changes view-identity (and never loses focus) when pills appear/disappear.
    private func dockCard(inDockMode: Bool) -> some View {
        unifiedListDockCard(inDockMode: inDockMode)
    }

    @ViewBuilder
    private func unifiedListDockCard(inDockMode: Bool) -> some View {
        VStack(spacing: 0) {
            dockBaseView(inDockMode: inDockMode)
                .frame(width: visibleDockWidth, alignment: .leading)

            if usesVerticalListDockLayout {
                Rectangle()
                    .fill(Color.white.opacity(isEffectiveDark ? 0.12 : 0.16))
                    .frame(height: 1)
                    .padding(.horizontal, 18)

                l2UnifiedDockRow
                    .frame(width: visibleDockWidth, alignment: .leading)
                    .fixedSize(horizontal: false, vertical: true)
                    .padding(.top, 8)
                    .padding(.bottom, 10)
            }
        }
        .frame(width: visibleDockWidth, alignment: .leading)
        .background(alignment: .topLeading) {
            if usesVerticalListDockLayout {
                GlassBackground(cornerRadius: 28, isDark: isEffectiveDark)
                    .frame(width: visibleDockWidth)
            }
        }
        .mask(alignment: .topLeading) {
            if usesVerticalListDockLayout {
                RoundedRectangle(cornerRadius: 28, style: .continuous)
                    .frame(width: visibleDockWidth)
            } else {
                Rectangle()
            }
        }
        .overlay(alignment: .topLeading) {
            if usesVerticalListDockLayout {
                RoundedRectangle(cornerRadius: 28, style: .continuous)
                    .strokeBorder(
                        LinearGradient(
                            colors: [.white.opacity(0.42), .white.opacity(0.08)],
                            startPoint: .topLeading,
                            endPoint: .bottomTrailing
                        ),
                        lineWidth: 1
                    )
                    .frame(width: visibleDockWidth)
            }
        }
        .shadow(color: usesVerticalListDockLayout ? .black.opacity(0.18) : .clear, radius: 24, x: 0, y: 12)
    }

    private var panelGapBelowSearchBar: CGFloat {
        searchState.activeSmartQueryKey == "clipboard" ? 2
            : (usesVerticalListDockLayout && !searchState.results.isEmpty ? 4 : 6)
    }

    private var searchBarSection: some View {
        Group {
            if settings.effectiveDockAtBottom {
                // Dock at bottom: results float above, dock bar anchored at bottom.
                VStack(spacing: panelGapBelowSearchBar) {
                    if hasResultsToShow {
                        resultsCardAlignedToSearchInput
                            .transition(.asymmetric(
                                insertion: .opacity.combined(with: .scale(scale: 0.96, anchor: .bottom)),
                                removal:   .opacity.combined(with: .scale(scale: 0.96, anchor: .bottom))
                            ))
                    }
                    // Clipboard floats left of the main dock pill — liquid-drop separation
                    HStack(alignment: .bottom, spacing: 8) {
                        clipboardFloatingIconPill
                            .transition(.scale(scale: 0.7, anchor: .bottomTrailing).combined(with: .opacity))
                        dockCard(inDockMode: true)
                            .onDrop(of: [.fileURL, .text, .plainText, .url], isTargeted: $clipboardDropTargeted) { providers in
                                handleClipboardIconDrop(providers)
                            }
                            .onHover { hovering in
                                if hovering && clipboardDropTargetVisible { revealClipboardDropTarget() }
                            }
                        floatingAppLogoButton
                    }
                }
            } else {
                // Dock at top: dock bar anchored at top, results float below.
                VStack(spacing: panelGapBelowSearchBar) {
                    HStack(alignment: .bottom, spacing: 8) {
                        clipboardFloatingIconPill
                            .transition(.scale(scale: 0.7, anchor: .bottomTrailing).combined(with: .opacity))
                        dockCard(inDockMode: false)
                            .onDrop(of: [.fileURL, .text, .plainText, .url], isTargeted: $clipboardDropTargeted) { providers in
                                handleClipboardIconDrop(providers)
                            }
                            .onHover { hovering in
                                if hovering && clipboardDropTargetVisible { revealClipboardDropTarget() }
                            }
                        floatingAppLogoButton
                    }
                    if hasResultsToShow {
                        resultsCardAlignedToSearchInput
                            .transition(.asymmetric(
                                insertion: .opacity.combined(with: .scale(scale: 0.96, anchor: .top)),
                                removal:   .opacity.combined(with: .scale(scale: 0.96, anchor: .top))
                            ))
                    }
                }
            }
        }
        .animation(.spring(response: 0.28, dampingFraction: 0.72), value: showGlobalClipboardPill)
        .animation(.spring(response: 0.25, dampingFraction: 0.8), value: hasResultsToShow)
        .ifLet(resolvedColorScheme) { view, scheme in
            view.environment(\.colorScheme, scheme)
        }
    }

    // MARK: - Dock Base View (always visible, doesn't move)
    @ViewBuilder
    private func dockBaseView(inDockMode: Bool) -> some View {
        let outerVerticalPadding: CGFloat = 6
        let inputVerticalPadding: CGFloat = 6
        let pinnedRowHeight: CGFloat = CGFloat(settings.dockIconSize) + 4
        let inputPillHeight: CGFloat = CGFloat(settings.dockIconSize) + 8

        VStack(spacing: 0) {
            HStack(spacing: 12) {
                // Left slot: full search input OR icon-only anchor during app/action pill keyboard nav
                // In list view mode the pill list is a separate panel below the search bar,
                // so nav focus should never collapse the search bar to an icon.
                let actionPillNavActive = l2.focusedPillIndex != nil && showContextInDock && !isGlobalContextActive && !aiMode.isActive && !usesVerticalListDockLayout
                let globalAppNavActive  = focusedAppPillIndex != nil && isGlobalContextActive && !aiMode.isActive && !usesVerticalListDockLayout
                let pillNavActive = actionPillNavActive || globalAppNavActive
                if pillNavActive {
                    searchAsPillView
                }
                if !pillNavActive && !showMediaLayer {
                HStack(spacing: 10) {
                    // Search icon
                    if aiMode.isActive {
                        Menu {
                            ForEach(AIProvider.allCases) { provider in
                                Button(action: {
                                    settings.selectedAIProvider = provider
                                }) {
                                    HStack {
                                        Image(systemName: provider.iconName)
                                        Text(provider.shortName)
                                        Spacer()
                                        if settings.selectedAIProvider == provider {
                                            Image(systemName: "checkmark")
                                        }
                                    }
                                }
                            }

                            Divider()

                            Button("AI Settings...") {
                                openSettings()
                            }
                        } label: {
                            Image(systemName: settings.selectedAIProvider.iconName)
                                .foregroundStyle(providerColor)
                                .font(.system(size: 16, weight: .medium))
                        }
                        .menuStyle(.borderlessButton)
                        .fixedSize()
                        .onHover { hovering in
                            isHoveringSearchIcon = hovering
                            if hovering {
                                expandSearchBar()
                            } else {
                                // Start collapse timer when stopping hover (if no input and not focused)
                                if searchState.query.isEmpty && !isSearchFieldFocused {
                                    startCollapseTimer()
                                }
                            }
                        }
                        .help("Select AI Provider")
                    } else {
                        Button(action: {
                            withAnimation(.spring(response: 0.3, dampingFraction: 0.75)) {
                                expandSearchBar()
                            }
                            updateWindowSize()
                        }) {
                            // Globe on L3, app icon on L2 (target override or frontmost), magnifying glass on L1
                            if showMediaLayer {
                                // Media layer: show album art, or player app icon, or music note
                                let mediaIcon: NSImage? = mediaObserver.artworkImage
                                    ?? mediaObserver.appIcon
                                    ?? NSWorkspace.shared.runningApplications
                                        .first(where: { ($0.localizedName ?? "") == mediaObserver.appName })?.icon
                                if let icon = mediaIcon {
                                    Image(nsImage: icon)
                                        .resizable()
                                        .aspectRatio(contentMode: .fill)
                                        .frame(width: 28, height: 28)
                                        .clipShape(RoundedRectangle(cornerRadius: mediaObserver.artworkImage != nil ? 6 : 7))
                                        .opacity(isHoveringSearchIcon ? 1.0 : 0.9)
                                        .transition(.scale(scale: 0.7).combined(with: .opacity))
                                        .id("media-\(mediaObserver.appName)")
                                } else {
                                    Image(systemName: "music.note")
                                        .foregroundStyle(.secondary.opacity(isHoveringSearchIcon ? 0.8 : 0.6))
                                        .font(.system(size: 16, weight: .medium))
                                        .frame(width: 24, height: 24)
                                }
                            } else if showContextInDock && settings.enableFrontmostDetection {
                                // l2.targetApp overrides frontmost icon after Tab completion
                                let topGlobalAppResult = topGlobalAppResultForInputPreview()
                                let scopedGlobalAppIcon = globalScopedAppIcon(for: searchState.query)
                                let preferFrontmostMenuIcon =
                                    hasFrontmostMenuPillsInCurrentCache(for: searchState.query)
                                let typedAppIcon =
                                    (scopedGlobalAppIcon != nil || (shouldUsePureGlobalAppSearch && !preferFrontmostMenuIcon) || hasActiveDockContextSelection)
                                    ? nil : typedL2AppIcon(for: searchState.query)
                                // In Finder desktop-only mode (no window open) treat icon as nil → globe
                                let displayIcon = scopedGlobalAppIcon?.icon ?? topGlobalAppResult?.icon ?? l2.targetApp?.icon ?? typedAppIcon?.icon ?? frontmost.icon
                                let menuIcon = menuInputIconForSearchText(
                                    hasAppMatch: scopedGlobalAppIcon != nil || topGlobalAppResult != nil || l2.targetApp != nil || typedAppIcon != nil
                                )
                                if isGlobalContextActive && !preferFrontmostMenuIcon && l2.targetApp == nil && typedAppIcon == nil && topGlobalAppResult == nil && scopedGlobalAppIcon == nil {
                                    if let selIcon = activeSelectionIcon {
                                        // Active selection: icon mirrors the content type (file, text, link, clipboard)
                                        Image(systemName: selIcon)
                                            .foregroundStyle(Color.purple.opacity(isHoveringSearchIcon ? 1.0 : 0.88))
                                            .font(.system(size: 16, weight: .semibold))
                                            .frame(width: 24, height: 24)
                                            .transition(.scale(scale: 0.8).combined(with: .opacity))
                                            .id(selIcon)
                                            .animation(.spring(response: 0.22, dampingFraction: 0.75), value: selIcon)
                                    } else {
                                        // No selection — Context Dock glyph
                                        ContextDockGlyph(size: 27, opacity: 1.0)
                                            .frame(width: 28, height: 28)
                                            .id("context-dock-input-logo")
                                    }
                                } else if let finderSymbol = finderInputSymbolForSearchText() {
                                    Image(systemName: finderSymbol)
                                        .foregroundStyle(Color.accentColor.opacity(isHoveringSearchIcon ? 1.0 : 0.85))
                                        .font(.system(size: 17, weight: .semibold))
                                        .frame(width: 24, height: 24)
                                        .transition(.scale(scale: 0.8).combined(with: .opacity))
                                        .id("finder-input-\(finderSymbol)")
                                        .animation(.spring(response: 0.22, dampingFraction: 0.75), value: finderSymbol)
                                } else if let menuIcon {
                                    if let image = menuIcon.image {
                                        Image(nsImage: image)
                                            .resizable()
                                            .interpolation(.high)
                                            .aspectRatio(contentMode: .fit)
                                            .frame(width: 24, height: 24)
                                            .opacity(isHoveringSearchIcon ? 1.0 : 0.9)
                                            .transition(.scale(scale: 0.7).combined(with: .opacity))
                                            .id("menu-input-image-\(menuIcon.symbol)")
                                    } else {
                                        Image(systemName: menuIcon.symbol)
                                            .foregroundStyle(Color.accentColor.opacity(isHoveringSearchIcon ? 1.0 : 0.85))
                                            .font(.system(size: 17, weight: .semibold))
                                            .frame(width: 24, height: 24)
                                            .transition(.scale(scale: 0.8).combined(with: .opacity))
                                            .id("menu-input-\(menuIcon.symbol)")
                                    }
                                } else if let appIcon = displayIcon {
                                    // 28 pt icon in context dock — matches expanded appPillButton
                                    let iconSize: CGFloat = showContextInDock ? 28 : 20
                                    Image(nsImage: appIcon)
                                        .resizable()
                                        .aspectRatio(contentMode: .fit)
                                        .frame(width: iconSize, height: iconSize)
                                        .clipShape(RoundedRectangle(cornerRadius: showContextInDock ? 7 : 4))
                                        .opacity(isHoveringSearchIcon ? 1.0 : 0.9)
                                        .transition(.scale(scale: 0.7).combined(with: .opacity))
                                        .id(
                                            scopedGlobalAppIcon?.bundleId ?? l2.targetApp?.bundleId ?? typedAppIcon?.bundleId
                                                ?? frontmost.bundleID
                                        )
                                } else {
                                    Image(systemName: "magnifyingglass")
                                        .foregroundStyle(
                                            .secondary.opacity(isHoveringSearchIcon ? 0.8 : 0.5)
                                        )
                                        .font(.system(size: 18, weight: .semibold))
                                        .frame(width: 24, height: 24)
                                }
                            } else {
                                Image(systemName: "magnifyingglass")
                                    .foregroundStyle(
                                        .secondary.opacity(isHoveringSearchIcon ? 0.8 : 0.5)
                                    )
                                    .font(.system(size: 18, weight: .semibold))
                                    .frame(width: 24, height: 24)
                            }
                        }
                        .buttonStyle(.plain)
                        .onHover { hovering in
                            isHoveringSearchIcon = hovering
                            if hovering && !suppressHoverExpand {
                                expandSearchBar()
                            }
                        }
                        .help(
                            isGlobalContextActive
                                ? "Switch to frontmost app context"
                                : "Switch to Global Context"
                        )
                        // Hide standalone icon when a context/scope chip owns the left slot.
                        .opacity((l2.targetApp != nil || globalInlineAppScope != nil || shouldShowFrontmostContextChip) && showContextInDock ? 0 : 1)
                        .frame(width: (l2.targetApp != nil || globalInlineAppScope != nil || shouldShowFrontmostContextChip) && showContextInDock ? 0 : nil)
                    }

                    // Spotlight-style app context chip — shown after Tab/→ on app result
                    if let ctx = searchState.contextApp, !showContextInDock {
                        HStack(spacing: 5) {
                            if let icon = ctx.icon {
                                Image(nsImage: icon)
                                    .resizable()
                                    .aspectRatio(contentMode: .fit)
                                    .frame(width: 16, height: 16)
                                    .clipShape(RoundedRectangle(cornerRadius: 3))
                            }
                            Text(ctx.name)
                                .font(.system(size: 13, weight: .medium))
                                .foregroundStyle(.primary)
                                .lineLimit(1)
                            Button(action: { clearSearchContext() }) {
                                Image(systemName: "xmark.circle.fill")
                                    .font(.system(size: 11))
                                    .foregroundStyle(.secondary.opacity(0.7))
                            }
                            .buttonStyle(.plain)
                        }
                        .padding(.horizontal, 8)
                        .padding(.vertical, 4)
                        .background(
                            Color.accentColor.opacity(0.12),
                            in: RoundedRectangle(cornerRadius: 7, style: .continuous)
                        )
                        .overlay(
                            RoundedRectangle(cornerRadius: 7, style: .continuous)
                                .strokeBorder(Color.accentColor.opacity(0.2), lineWidth: 0.5)
                        )
                    }

                    // Soft frontmost context chip — same visual language as app scope,
                    // but not locked. Frontmost app changes still update this chip.
                    if shouldShowFrontmostContextChip, let icon = frontmost.icon {
                        let accent = icon.dominantSwiftUIColor
                        let chipTextColor: SwiftUI.Color = systemColorScheme == .dark
                            ? SwiftUI.Color.white.opacity(0.94)
                            : SwiftUI.Color.black.opacity(0.82)
                        HStack(spacing: 6) {
                            Image(nsImage: icon)
                                .resizable()
                                .aspectRatio(contentMode: .fit)
                                .frame(width: 18, height: 18)
                                .clipShape(RoundedRectangle(cornerRadius: 4, style: .continuous))
                            Text(frontmost.name)
                                .font(.system(size: 15, weight: .semibold))
                                .foregroundStyle(chipTextColor)
                                .lineLimit(1)
                        }
                        .padding(.leading, 8)
                        .padding(.trailing, isHoveringFrontmostContextChip ? 9 : 8)
                        .padding(.vertical, 4)
                        .background(.regularMaterial, in: Capsule(style: .continuous))
                        .background(accent.opacity(systemColorScheme == .dark ? 0.20 : 0.12), in: Capsule(style: .continuous))
                        .overlay(
                            Capsule(style: .continuous)
                                .strokeBorder(accent.opacity(systemColorScheme == .dark ? 0.36 : 0.24), lineWidth: 0.8)
                        )
                        .shadow(color: accent.opacity(systemColorScheme == .dark ? 0.20 : 0.12), radius: 7, x: 0, y: 2)
                        .help("Frontmost app context")
                        .onTapGesture {
                            if !frontmost.bundleID.isEmpty {
                                _ = activateInlineDockAppScope(
                                    bundleIdentifier: frontmost.bundleID,
                                    appName: frontmost.name,
                                    queryOverride: searchState.query,
                                    expand: true,
                                    preserveGlobalContext: isGlobalContextActive
                                )
                            }
                        }
                        .onHover { hovering in
                            withAnimation(.spring(response: 0.18, dampingFraction: 0.82)) {
                                isHoveringFrontmostContextChip = hovering
                            }
                        }
                        .transition(.scale(scale: 0.86, anchor: .leading).combined(with: .opacity))
                    }

                    // Pinned L2 scope badge — full capsule matching global inline scope style.
                    if let target = l2.targetApp, showContextInDock {
                        let scopeIcon: NSImage = target.icon
                            ?? NSWorkspace.shared.icon(forFile: NSWorkspace.shared.urlForApplication(withBundleIdentifier: target.bundleId)?.path ?? "")
                        let accent = target.bundleId.hasPrefix("scope://") ? SwiftUI.Color.accentColor : scopeIcon.dominantSwiftUIColor
                        let chipTextColor: SwiftUI.Color = systemColorScheme == .dark
                            ? SwiftUI.Color.white.opacity(0.94)
                            : SwiftUI.Color.black.opacity(0.82)
                        HStack(spacing: 6) {
                            if target.bundleId == "scope://clipboard" {
                                Image(systemName: "doc.on.clipboard")
                                    .font(.system(size: 14, weight: .semibold))
                                    .foregroundStyle(Color.accentColor)
                                    .frame(width: 18, height: 18)
                            } else {
                                Image(nsImage: scopeIcon)
                                    .resizable()
                                    .aspectRatio(contentMode: .fit)
                                    .frame(width: 18, height: 18)
                                    .clipShape(RoundedRectangle(cornerRadius: 4, style: .continuous))
                            }
                            Text(target.name)
                                .font(.system(size: 15, weight: .semibold))
                                .foregroundStyle(chipTextColor)
                                .lineLimit(1)
                            Button {
                                exitL2DockScope()
                            } label: {
                                Image(systemName: "minus")
                                    .font(.system(size: 9, weight: .bold))
                                    .foregroundStyle(chipTextColor)
                                    .frame(width: 16, height: 16)
                                    .background(chipTextColor.opacity(systemColorScheme == .dark ? 0.14 : 0.10), in: Circle())
                            }
                            .buttonStyle(.plain)
                            .help("Remove app scope")
                            .opacity(isHoveringL2ScopeChip ? 1 : 0.72)
                        }
                        .padding(.leading, 8)
                        .padding(.trailing, isHoveringL2ScopeChip ? 8 : 6)
                        .padding(.vertical, 4)
                        .background(.regularMaterial, in: Capsule(style: .continuous))
                        .background(accent.opacity(systemColorScheme == .dark ? 0.28 : 0.18), in: Capsule(style: .continuous))
                        .overlay(
                            Capsule(style: .continuous)
                                .strokeBorder(accent.opacity(systemColorScheme == .dark ? 0.48 : 0.34), lineWidth: 0.8)
                        )
                        .shadow(color: accent.opacity(systemColorScheme == .dark ? 0.28 : 0.16), radius: 8, x: 0, y: 2)
                        .onHover { hovering in
                            withAnimation(.spring(response: 0.18, dampingFraction: 0.82)) {
                                isHoveringL2ScopeChip = hovering
                            }
                        }
                        .transition(.scale(scale: 0.86, anchor: .leading).combined(with: .opacity))
                    }

                    if let inlineScope = globalInlineAppScope,
                       shouldUsePureGlobalAppSearch,
                       isGlobalContextActive,
                       showContextInDock {
                        let icon = FileManager.default.fileExists(atPath: inlineScope.appPath)
                            ? NSWorkspace.shared.icon(forFile: inlineScope.appPath)
                            : NSWorkspace.shared.icon(forFile: NSWorkspace.shared.urlForApplication(withBundleIdentifier: inlineScope.bundleId)?.path ?? "")
                        let accent = icon.dominantSwiftUIColor
                        let chipTextColor: SwiftUI.Color = systemColorScheme == .dark
                            ? SwiftUI.Color.white.opacity(0.94)
                            : SwiftUI.Color.black.opacity(0.82)
                        HStack(spacing: 6) {
                            Image(nsImage: icon)
                                .resizable()
                                .aspectRatio(contentMode: .fit)
                                .frame(width: 18, height: 18)
                                .clipShape(RoundedRectangle(cornerRadius: 4, style: .continuous))
                            Text(inlineScope.appName)
                                .font(.system(size: 15, weight: .semibold))
                                .foregroundStyle(chipTextColor)
                                .lineLimit(1)
                            Button {
                                withAnimation(.spring(response: 0.2, dampingFraction: 0.82)) {
                                    clearGlobalInlineAppScope(preserveQuery: true)
                                }
                            } label: {
                                Image(systemName: "minus")
                                    .font(.system(size: 9, weight: .bold))
                                    .foregroundStyle(chipTextColor)
                                    .frame(width: 16, height: 16)
                                    .background(chipTextColor.opacity(systemColorScheme == .dark ? 0.14 : 0.10), in: Circle())
                            }
                            .buttonStyle(.plain)
                            .help("Remove app scope")
                            .opacity(isHoveringGlobalInlineScopeChip ? 1 : 0.72)
                        }
                        .padding(.leading, 8)
                        .padding(.trailing, isHoveringGlobalInlineScopeChip ? 8 : 6)
                        .padding(.vertical, 4)
                        .background(.regularMaterial, in: Capsule(style: .continuous))
                        .background(accent.opacity(systemColorScheme == .dark ? 0.28 : 0.18), in: Capsule(style: .continuous))
                        .overlay(
                            Capsule(style: .continuous)
                                .strokeBorder(accent.opacity(systemColorScheme == .dark ? 0.48 : 0.34), lineWidth: 0.8)
                        )
                        .shadow(color: accent.opacity(systemColorScheme == .dark ? 0.28 : 0.16), radius: 8, x: 0, y: 2)
                        .onHover { hovering in
                            withAnimation(.spring(response: 0.18, dampingFraction: 0.82)) {
                                isHoveringGlobalInlineScopeChip = hovering
                            }
                        }
                        .transition(.scale(scale: 0.86, anchor: .leading).combined(with: .opacity))
                    }

                    // Submenu parent chip — liquid glass capsule matching the dock bar style
                    if let locked = lockedSubmenuParent, showContextInDock {
                        HStack(spacing: 0) {
                            Text(locked.title)
                                .font(.system(size: 13, weight: .semibold))
                                .foregroundStyle(Color(nsColor: .labelColor))
                                .lineLimit(1)
                                .padding(.leading, 10)
                                .padding(.trailing, 6)
                            // Dark circle with › (mirrors the "Get started ›" reference)
                            ZStack {
                                Circle()
                                    .fill(Color(nsColor: .labelColor).opacity(0.88))
                                    .frame(width: 20, height: 20)
                                Image(systemName: "chevron.right")
                                    .font(.system(size: 8, weight: .bold))
                                    .foregroundStyle(Color(nsColor: .windowBackgroundColor))
                            }
                            .padding(.trailing, 4)
                        }
                        .frame(height: 30)
                        .background(.regularMaterial, in: Capsule())
                        .overlay(
                            Capsule()
                                .strokeBorder(.white.opacity(0.18), lineWidth: 0.5)
                        )
                        .shadow(color: .black.opacity(0.12), radius: 4, x: 0, y: 2)
                        .onTapGesture {
                            withAnimation(.spring(response: 0.2, dampingFraction: 0.8)) {
                                lockedSubmenuParent = nil
                            }
                        }
                        .transition(.scale(scale: 0.82, anchor: .leading).combined(with: .opacity))
                        .animation(.spring(response: 0.22, dampingFraction: 0.8), value: locked.title)
                    }

                    // Vertical separator between icon and text — mirrors expanded appPillButton
                    // Separator and text field are hidden when a context pill is keyboard-focused
                    // (the input shrinks to icon-only to give pills more room)
                    if showContextInDock && !isGlobalContextActive && l2.targetApp == nil && !shouldShowFrontmostContextChip && !aiMode.isActive
                        && l2.focusedPillIndex == nil {
                        Rectangle()
                            .fill(Color.white.opacity(0.16))
                            .frame(width: 1, height: 28)
                    }

                    // Text field - visible when expanded AND no pill is keyboard-focused AND media layer is off.
                    // List view keeps the search header stable even while keyboard focus moves through results.
                    if (isSearchBarExpanded || usesVerticalListDockLayout)
                        && (l2.focusedPillIndex == nil || usesVerticalListDockLayout)
                        && !showMediaLayer
                    {
                        let selectedResult: SearchResult? = {
                            guard let idx = searchState.selectedIndex, idx < searchState.results.count,
                                !aiMode.isActive, !isL2ContextActive, searchState.activeSmartQueryKey == nil, searchState.contextApp == nil
                            else { return nil }
                            return searchState.results[idx]
                        }()
                        let focusedDockPill = focusedDockPillForInputPreview()
                        let focusedGlobalAppResult = focusedGlobalAppResultForInputPreview()
                        let topGlobalAppResult = topGlobalAppResultForInputPreview()
                        // Spotlight-style: show result name in bar whenever a result is selected (even while typing)
                        let showingResultPreview =
                            focusedDockPill != nil || focusedGlobalAppResult != nil
                            || topGlobalAppResult != nil || selectedResult != nil

                        ZStack(alignment: .leading) {
                            // Selected result preview (Spotlight-style: "Visual Studio Code.app — Open")
                            if let pill = focusedDockPill {
                                let title = pill.name
                                let typed = searchState.query
                                let isPrefixMatch = title.lowercased().hasPrefix(typed.lowercased())

                                HStack(spacing: 0) {
                                    if isPrefixMatch && !typed.isEmpty {
                                        Text(typed)
                                            .font(.system(size: 15))
                                            .foregroundStyle(.clear)
                                        Text(String(title.dropFirst(typed.count)))
                                            .font(.system(size: 15))
                                            .foregroundStyle(.secondary.opacity(0.45))
                                            .lineLimit(1)
                                    } else {
                                        Text(title)
                                            .font(.system(size: 15, weight: .medium))
                                            .foregroundStyle(.primary)
                                            .lineLimit(1)
                                    }
                                    if let badge = pill.badge, !badge.isEmpty {
                                        Text("  \(badge)")
                                            .font(.system(size: 15))
                                            .foregroundStyle(.secondary.opacity(0.25))
                                    }
                                    Text("  — ↵")
                                        .font(.system(size: 15))
                                        .foregroundStyle(.secondary.opacity(0.25))
                                }
                            } else if let result = focusedGlobalAppResult {
                                let title = result.title
                                let typed = searchState.query
                                let isPrefixMatch = title.lowercased().hasPrefix(typed.lowercased())

                                HStack(spacing: 0) {
                                    if isPrefixMatch && !typed.isEmpty {
                                        Text(typed)
                                            .font(.system(size: 15))
                                            .foregroundStyle(.clear)
                                        Text(String(title.dropFirst(typed.count)))
                                            .font(.system(size: 15))
                                            .foregroundStyle(.secondary.opacity(0.45))
                                            .lineLimit(1)
                                    } else {
                                        Text(title)
                                            .font(.system(size: 15, weight: .medium))
                                            .foregroundStyle(.primary)
                                            .lineLimit(1)
                                    }
                                    Text("  —  \(selectedResultAction(result))")
                                        .font(.system(size: 15))
                                        .foregroundStyle(.secondary.opacity(0.35))
                                }
                            } else if let result = topGlobalAppResult,
                                      result.title.lowercased().hasPrefix(searchState.query.lowercased()),
                                      !searchState.query.isEmpty
                            {
                                // Prefix match only: show typed (invisible) + grey completion + action
                                let title = result.title
                                let typed = searchState.query
                                HStack(spacing: 0) {
                                    Text(typed)
                                        .font(.system(size: 15))
                                        .foregroundStyle(.clear)
                                    Text(String(title.dropFirst(typed.count)))
                                        .font(.system(size: 15))
                                        .foregroundStyle(.secondary.opacity(0.45))
                                        .lineLimit(1)
                                    Text("  —  \(selectedResultAction(result))")
                                        .font(.system(size: 15))
                                        .foregroundStyle(.secondary.opacity(0.35))
                                }
                            } else if let result = selectedResult {
                                // Intelligent inline completion:
                                // • Prefix match  → show typed text (invisible spacer) + greyed remainder + action
                                // • Fuzzy match   → show full result name + action
                                let title = result.title
                                let typed = searchState.query
                                let isPrefixMatch = title.lowercased().hasPrefix(typed.lowercased())

                                HStack(spacing: 0) {
                                    if isPrefixMatch && !typed.isEmpty {
                                        // Typed portion — invisible spacer so grey completion aligns after cursor
                                        Text(typed)
                                            .font(.system(size: 15))
                                            .foregroundStyle(.clear)
                                        // Grey completion (the "remaining" part)
                                        Text(String(title.dropFirst(typed.count)))
                                            .font(.system(size: 15))
                                            .foregroundStyle(.secondary.opacity(0.45))
                                            .lineLimit(1)
                                    } else {
                                        // Fuzzy match — show full name in primary color
                                        Text(title)
                                            .font(.system(size: 15, weight: .medium))
                                            .foregroundStyle(.primary)
                                            .lineLimit(1)
                                    }
                                    // Action hint
                                    Text("  —  \(selectedResultAction(result))")
                                        .font(.system(size: 15))
                                        .foregroundStyle(.secondary.opacity(0.35))
                                }
                            } else if !shouldUsePureGlobalAppSearch,
                                !hasActiveDockContextSelection,
                                isL2ContextActive, l2.targetApp == nil,
                                let completion = l2.appCompletion,
                                !completion.ghost.isEmpty,
                                completion.actionQuery.trimmingCharacters(
                                    in: .whitespacesAndNewlines
                                ).isEmpty,
                                !searchState.query.isEmpty,
                                !searchState.query.contains(" ")
                            {
                                // L2 partial app autocomplete ghost text: "sa" → "sa[fari]  — Tab"
                                HStack(spacing: 0) {
                                    Text(searchState.query)
                                        .font(.system(size: 15))
                                        .foregroundStyle(.clear)  // invisible spacer — aligns with real TextField cursor
                                    Text(completion.ghost)
                                        .font(.system(size: 15))
                                        .foregroundStyle(.secondary.opacity(0.4))
                                        .lineLimit(1)
                                    Text("  — Tab")
                                        .font(.system(size: 15))
                                        .foregroundStyle(.secondary.opacity(0.25))
                                }
                            } else if let subCtx = submenuGhostContext,
                                      let firstChild = subCtx.children.first,
                                      (lockedSubmenuParent != nil || !searchState.query.isEmpty)
                            {
                                // Locked mode: show child prefix completion → "d[ate]  — →"
                                // Unlocked mode: "sort by"   → "sort by  ›  Date  — →"
                                //                "sort by d"  → "sort by d[ate]  — →"
                                HStack(spacing: 0) {
                                    if lockedSubmenuParent != nil {
                                        // Parent is shown as chip — just complete the child prefix
                                        if !searchState.query.isEmpty {
                                            Text(searchState.query)
                                                .font(.system(size: 15))
                                                .foregroundStyle(.clear)
                                        }
                                        let suffix = String(
                                            firstChild.title.dropFirst(
                                                min(subCtx.childPrefix.count, firstChild.title.count)
                                            )
                                        )
                                        if !suffix.isEmpty {
                                            Text(suffix)
                                                .font(.system(size: 15))
                                                .foregroundStyle(.secondary.opacity(0.35))
                                                .lineLimit(1)
                                        }
                                    } else {
                                        Text(searchState.query)
                                            .font(.system(size: 15))
                                            .foregroundStyle(.clear)
                                        if subCtx.childPrefix.isEmpty {
                                            Text("  ›  \(firstChild.title)")
                                                .font(.system(size: 15))
                                                .foregroundStyle(.secondary.opacity(0.35))
                                                .lineLimit(1)
                                        } else {
                                            let suffix = String(
                                                firstChild.title.dropFirst(
                                                    min(subCtx.childPrefix.count, firstChild.title.count)
                                                )
                                            )
                                            if !suffix.isEmpty {
                                                Text(suffix)
                                                    .font(.system(size: 15))
                                                    .foregroundStyle(.secondary.opacity(0.35))
                                                    .lineLimit(1)
                                            }
                                        }
                                    }
                                    Text("  — →")
                                        .font(.system(size: 15))
                                        .foregroundStyle(.secondary.opacity(0.2))
                                }
                            } else if let ghost = ghostPillCompletion, !searchState.query.isEmpty {
                                // Pill ghost completion: "slee" → "slee[p]  — ↵"
                                HStack(spacing: 0) {
                                    Text(searchState.query)
                                        .font(.system(size: 15))
                                        .foregroundStyle(.clear)
                                    Text(String(ghost.name.dropFirst(searchState.query.count)))
                                        .font(.system(size: 15))
                                        .foregroundStyle(.secondary.opacity(0.35))
                                        .lineLimit(1)
                                    if let badge = ghost.badge, !badge.isEmpty {
                                        Text("  \(badge)")
                                            .font(.system(size: 15))
                                            .foregroundStyle(.secondary.opacity(0.2))
                                    }
                                    Text("  — ↵")
                                        .font(.system(size: 15))
                                        .foregroundStyle(.secondary.opacity(0.2))
                                }
                            } else if searchState.query.isEmpty {
                                // Normal placeholders (always visible when field is empty)
                                if lockedSubmenuParent != nil {
                                    Text("filter…")
                                        .foregroundStyle(.secondary.opacity(0.4))
                                        .font(.system(size: 15, weight: .regular))
                                } else if aiMode.isActive {
                                    Text("Ask \(settings.selectedAIProvider.shortName)...")
                                        .foregroundStyle(.secondary.opacity(0.5))
                                        .font(.system(size: 15, weight: .regular))
                                } else if isGlobalContextActive,
                                   let prompt = activeSelectionPromptText {
                                    if searchState.contextApp == nil, l2.targetApp == nil {
                                        Text(prompt)
                                            .foregroundStyle(.secondary.opacity(0.34))
                                            .font(.system(size: 12, weight: .medium))
                                            .lineLimit(1)
                                            .truncationMode(.middle)
                                    } else {
                                        // Chip hidden by another chip — show label in ghost text
                                        HStack(spacing: 0) {
                                            Text(prompt)
                                                .foregroundStyle(.secondary.opacity(0.5))
                                                .font(.system(size: 15, weight: .regular))
                                                .lineLimit(1)
                                                .truncationMode(.middle)
                                        }
                                    }
                                } else if let ctx = searchState.contextApp {
                                    // Context panel (file, folder, app, contact, etc.)
                                    Text(
                                        remPanelIsProcessing
                                            ? "Processing…" : "Ask AI about \(ctx.name)…"
                                    )
                                    .foregroundStyle(.secondary.opacity(0.5))
                                    .font(.system(size: 15, weight: .regular))
                                    .lineLimit(1)
                                    .truncationMode(.tail)
                                } else if let key = searchState.activeSmartQueryKey {
                                    // Built-in panel (reminders, calendar, notes, etc.)
                                    let label =
                                        settings.customAppEntries.first(where: { $0.key == key })?
                                        .label ?? key.capitalized
                                    Text(
                                        key == "clipboard"
                                            ? "Search Clipboard…"
                                            : (remPanelIsProcessing
                                                ? "Processing…" : "Ask AI about \(label)…")
                                    )
                                    .foregroundStyle(.secondary.opacity(0.5))
                                    .font(.system(size: 15, weight: .regular))
                                    .lineLimit(1)
                                    .truncationMode(.tail)
                                } else if isFinderDesktopOnlyMode,
                                    attachedFinderFolderSearchPath.isEmpty
                                {
                                    // Finder desktop mode: show capability hint, not the Desktop pseudo-folder.
                                    Text(dockScopeGhostPrompt)
                                        .foregroundStyle(.secondary.opacity(0.55))
                                        .font(.system(size: 15, weight: .medium))
                                        .lineLimit(1)
                                        .truncationMode(.tail)
                                } else if !attachedFinderFolderSearchPath.isEmpty,
                                    frontmost.bundleID == "com.apple.finder"
                                {
                                    // Finder folder attached as AI context scope
                                    let folderName = URL(fileURLWithPath: attachedFinderFolderSearchPath).lastPathComponent
                                    HStack(spacing: 0) {
                                        Text(folderName.isEmpty ? "Current Folder" : folderName)
                                            .foregroundStyle(.secondary.opacity(0.5))
                                            .font(.system(size: 15, weight: .medium))
                                            .lineLimit(1)
                                        Text("  — type to search and ask about this folder…")
                                            .foregroundStyle(.secondary.opacity(0.25))
                                            .font(.system(size: 15, weight: .regular))
                                            .lineLimit(1)
                                    }
                                } else if isGlobalContextActive {
                                    // Global context: "Global Context" as ghost placeholder
                                    Text("Global Context")
                                        .foregroundStyle(.secondary.opacity(0.55))
                                        .font(.system(size: 15, weight: .medium))
                                        .lineLimit(1)
                                } else if showContextInDock
                                    && !dockScopeDisplayName.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                                {
                                    // Context dock: app name + capability hints.
                                    Text(dockScopeGhostPrompt)
                                        .foregroundStyle(.primary.opacity(0.75))
                                        .font(.system(size: 15, weight: .semibold))
                                        .lineLimit(1)
                                        .truncationMode(.tail)
                                } else {
                                    Text("Context-Dock")
                                    .foregroundStyle(.secondary.opacity(0.5))
                                    .font(.system(size: 15, weight: .regular))
                                }
                            }

                            TextField("", text: $searchState.query)
                                .textFieldStyle(.plain)
                                .font(.system(size: 15))
                                .foregroundStyle(Color.primary)
                                .focused($isSearchFieldFocused)
                                .focusEffectDisabled()
                                .background(FocusRingSuppressor())
                                // For prefix match: TextField stays visible (shows typed text + cursor).
                                // For fuzzy match or empty: hide it so the full result name shows cleanly.
                                .opacity(
                                    {
                                        if let pill = focusedDockPill {
                                            let isPrefixMatch = pill.name.lowercased().hasPrefix(
                                                searchState.query.lowercased())
                                            return (isPrefixMatch && !searchState.query.isEmpty) ? 1 : 0
                                        }
                                        if let result = focusedGlobalAppResult {
                                            let isPrefixMatch = result.title.lowercased().hasPrefix(
                                                searchState.query.lowercased())
                                            return (isPrefixMatch && !searchState.query.isEmpty) ? 1 : 0
                                        }
                                        if let result = topGlobalAppResult {
                                            // Only hide TextField for prefix match (ghost shows completion).
                                            // For fuzzy match the TextField stays visible so typed text shows.
                                            let isPrefixMatch = result.title.lowercased().hasPrefix(
                                                searchState.query.lowercased())
                                            return (isPrefixMatch && !searchState.query.isEmpty) ? 1 : 1
                                        }
                                        if let result = selectedResult {
                                            let isPrefixMatch = result.title.lowercased().hasPrefix(
                                                searchState.query.lowercased())
                                            return (isPrefixMatch && !searchState.query.isEmpty) ? 1 : 0
                                        }
                                        return 1
                                    }()
                                )
                                .onChange(of: searchState.query) { oldValue, newValue in
                                    if searchState.activeSmartQueryKey == "clipboard" {
                                        focusedClipboardEntryIndex = nil
                                    }
                                    // Typing dismisses any pending AI-found menu proposal
                                    if !newValue.isEmpty, pendingAIMenuProposal != nil {
                                        pendingAIMenuProposal = nil
                                    }
                                    // In L2 context dock mode, pills filter in the pill row —
                                    // do NOT run L1 search (which would expand the window with results).
                                    if !aiMode.isActive && !showContextInDock {
                                        performSearch()
                                    }
                                    // When a submenu parent is locked, skip all app-scope detection —
                                    // input is purely a child filter, not an app name.
                                    if isL2ContextActive && lockedSubmenuParent == nil {
                                        let q = newValue
                                            .trimmingCharacters(in: .whitespacesAndNewlines)
                                            .lowercased()
                                        if shouldUsePureGlobalAppSearch {
                                            l2.appCompletion = nil
                                            l2.showResultsPopover = false
                                            focusedAppPillIndex = nil
                                            l2.focusedPillIndex = nil
                                            if !q.isEmpty, allApplications.isEmpty, !searchState.isLoadingApps {
                                                loadApplicationsInBackground()
                                            }
                                            if globalInlineAppScope == nil {
                                                scheduleGlobalAppMatchRebuild(query: q, delayNanoseconds: 0)
                                            } else {
                                                scheduleGlobalGroupedListRebuild(query: q, delayNanoseconds: 18_000_000)
                                            }
                                            resetCollapseTimer()
                                            return
                                        }
                                        if globalInlineAppScope != nil {
                                            clearGlobalInlineAppScope(preserveQuery: true)
                                        }
                                        let finderFolderSearchActive =
                                            isFinderFolderSearchModeEnabled(for: newValue)
                                            || (finderFolderQueryModeActive
                                                && isFinderFolderSearchAttached())
                                        if finderFolderSearchActive {
                                            l2.appCompletion = nil
                                            l2.showResultsPopover = false
                                        } else {
                                            l2.showResultsPopover = false
                                            if !isGlobalContextActive {
                                                triggerCrossAppMenuLoadIfNeeded(for: newValue)
                                            }
                                        }
                                        scheduleFinderSemanticSearchIfNeeded(for: newValue)
                                        updateFinderGoToPills(for: newValue)
                                        let finderSearchPopoverActive = shouldUseFinderSearchPopover(for: q)
                                        let pillQuery = finderSearchPopoverActive ? "" : q
                                        scheduleDockPillRebuild(
                                            query: pillQuery,
                                            delayNanoseconds: settings.useListViewForPills ? 20_000_000 : 55_000_000,
                                            refreshContext: false
                                        )
                                        if usesVerticalListDockLayout {
                                            DispatchQueue.main.async {
                                                reclaimSearchInputFocus()
                                            }
                                        }
                                    }
                                    // Update partial app autocomplete for L2 (skip when submenu locked
                                    // or when files/text/folders are actively selected).
                                    if isL2ContextActive && isGlobalContextActive && lockedSubmenuParent == nil
                                        && !hasActiveDockContextSelection {
                                        let trimmed = newValue.trimmingCharacters(in: .whitespaces)
                                        let installedScopeMode = contextDockInstalledAppScopeMatching
                                        let dockOnlyMode = contextDockRunningOnlyAppMatching && !installedScopeMode
                                        if shouldUseFinderSearchPopover(for: trimmed) {
                                            l2.appCompletion = nil
                                        } else if trimmed.isEmpty
                                            || {
                                                guard let target = L2AppActionRouter.shared.appScopeTarget(for: trimmed) else {
                                                    return false
                                                }
                                                return !dockOnlyMode || runningBundleIdsForContextDock().contains(target.bundleId)
                                            }()
                                            || installedAppMenuTarget(
                                                for: trimmed,
                                                runningOnly: dockOnlyMode,
                                                includeAppsWithoutMenuSnapshot: installedScopeMode,
                                                allowPrefixAlias: installedScopeMode
                                            ) != nil
                                        {
                                            l2.appCompletion = nil
                                        } else {
                                            l2.appCompletion = bestL2PartialAppCompletion(
                                                for: trimmed, runningOnly: dockOnlyMode
                                            )
                                        }
                                        if let target = l2.targetApp, !trimmed.isEmpty {
                                            if let otherTarget = L2AppActionRouter.shared.appScopeTarget(
                                                for: trimmed.lowercased()),
                                                otherTarget.bundleId != target.bundleId
                                            {
                                                withAnimation(.easeInOut(duration: 0.15)) {
                                                    l2.targetApp = nil
                                                }
                                                if searchState.contextApp?.resultType == .application {
                                                    clearSearchContext(preserveQuery: true)
                                                }
                                            }
                                        }
                                    } else if lockedSubmenuParent != nil
                                        || (isL2ContextActive && (!isGlobalContextActive || hasActiveDockContextSelection)) {
                                        // Locked: clear any stale app completion
                                        l2.appCompletion = nil
                                    }
                                    if isL2ContextActive || aiMode.isActive {
                                        scheduleBrowserContextWarmup(reason: "query changed")
                                    }
                                    resetCollapseTimer()
                                }
                                .onChange(of: isSearchFieldFocused) { oldValue, newValue in
                                    if newValue {
                                        collapseTimer?.cancel()
                                    } else {
                                        if searchState.query.isEmpty && !usesVerticalListDockLayout {
                                            startCollapseTimer()
                                        }
                                    }
                                }
                                .onSubmit {
                                    if isL2ContextActive {
                                        dismissMediaLayer()
                                        let trimmed = searchState.query.trimmingCharacters(
                                            in: .whitespacesAndNewlines
                                        )
                                        if shouldUseFinderSearchPopover(for: trimmed) {
                                            if let firstResult = finderSemanticResults.first {
                                                executeFinderFolderSearchResult(firstResult)
                                            }
                                            return
                                        }
                                        if l2.focusedPillIndex != nil,
                                            executeFocusedOrDirectAppPillIfNeeded()
                                        {
                                            return
                                        }
                                        if executeFirstMatchingFinderFolderPillIfNeeded() {
                                            return
                                        }
                                        if executeFirstAttachedFinderFolderResultIfNeeded() {
                                            return
                                        }
                                        if launchTypedAppMatchIfNeeded() {
                                            return
                                        }
                                        guard !trimmed.isEmpty else { return }
                                        if executeFocusedOrDirectAppPillIfNeeded() {
                                            return
                                        }
                                        handleL2Query(trimmed)
                                    } else if aiMode.isActive {
                                        if launchTypedAppMatchIfNeeded() {
                                            return
                                        }
                                        let q = searchState.query.trimmingCharacters(
                                            in: .whitespacesAndNewlines
                                        )
                                        if q.count > 3 {
                                            submitAIQuery()
                                        }
                                    } else if searchState.activeSmartQueryKey == "clipboard" {
                                        if focusedClipboardEntryIndex != nil {
                                            quickLookFocusedClipboardEntry()
                                        } else {
                                            navigateClipboardScope(direction: 1)
                                        }
                                    } else if searchState.activeSmartQueryKey != nil || searchState.contextApp != nil {
                                        let q = searchState.query.trimmingCharacters(
                                            in: .whitespacesAndNewlines
                                        )
                                        guard !q.isEmpty else { return }
                                        handleRemPanelQuery()
                                    } else {
                                        executeSelectedResult()
                                    }
                                }
                        }
                        .transition(.opacity.combined(with: .scale(scale: 0.95, anchor: .leading)))

                        // Trailing area: result icon OR clear OR AI controls OR dismiss OR context dock
                        if let result = selectedResult {
                            // Spotlight-style: show result icon on the right while a result is selected
                            if let icon = result.icon {
                                Image(nsImage: icon)
                                    .resizable()
                                    .aspectRatio(contentMode: .fit)
                                    .frame(width: 28, height: 28)
                                    .clipShape(
                                        RoundedRectangle(cornerRadius: 6, style: .continuous)
                                    )
                                    .shadow(radius: 2)
                            }
                        } else if aiMode.isActive {
                            aiModeControls
                        } else if !searchState.query.isEmpty {
                            Button(action: {
                                searchState.query = ""
                                searchState.results = []
                                searchState.selectedIndex = nil
                            }) {
                                Image(systemName: "xmark.circle.fill")
                                    .foregroundStyle(.secondary.opacity(0.5))
                                    .font(.system(size: 14))
                            }
                            .buttonStyle(.plain)
                            .help("Clear")
                        } else if isGlobalContextActive, activeSelectionLabel != nil {
                            // (-) dismiss: clears the active selection and returns to dock context
                            Button {
                                withAnimation(.spring(response: 0.22, dampingFraction: 0.8)) {
                                    showGlobalClipboardPill = false
                                    globalClipboardText = ""
                                    dismissContextAndReturnToDock()
                                }
                            } label: {
                                Image(systemName: "minus.circle.fill")
                                    .foregroundStyle(.secondary.opacity(0.55))
                                    .font(.system(size: 14))
                            }
                            .buttonStyle(.plain)
                            .help("Dismiss selection")
                        } else if isGlobalContextActive {
                            // Global context: + connects to the frontmost app's context dock
                            if settings.enableFrontmostDetection,
                               let icon = frontmost.icon,
                               !frontmost.name.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                                Button {
                                    withAnimation(.spring(response: 0.28, dampingFraction: 0.78)) {
                                        globalContextActivation = nil
                                        showContextInDock = true
                                    }
                                } label: {
                                    HStack(spacing: 5) {
                                        Image(nsImage: icon)
                                            .resizable()
                                            .aspectRatio(contentMode: .fit)
                                            .frame(width: 16, height: 16)
                                            .clipShape(RoundedRectangle(cornerRadius: 4, style: .continuous))
                                        Text(frontmost.name)
                                            .font(.system(size: 12, weight: .semibold))
                                            .foregroundStyle(.secondary.opacity(0.82))
                                            .lineLimit(1)
                                            .frame(maxWidth: 96)
                                    }
                                    .padding(.leading, 7)
                                    .padding(.trailing, 8)
                                    .padding(.vertical, 4)
                                    .background(.regularMaterial, in: Capsule(style: .continuous))
                                    .overlay(
                                        Capsule(style: .continuous)
                                            .strokeBorder(icon.dominantSwiftUIColor.opacity(systemColorScheme == .dark ? 0.34 : 0.24), lineWidth: 0.7)
                                    )
                                }
                                .buttonStyle(.plain)
                                .help("Connect to \(frontmost.name)")
                            }
                            Button {
                                withAnimation(.spring(response: 0.28, dampingFraction: 0.78)) {
                                    globalContextActivation = nil
                                    showContextInDock = true
                                }
                            } label: {
                                Image(systemName: "plus")
                                    .font(.system(size: 12, weight: .semibold))
                                    .foregroundStyle(.secondary.opacity(0.65))
                                    .frame(width: 22, height: 22)
                                    .background(Color.white.opacity(0.08), in: Circle())
                            }
                            .buttonStyle(.plain)
                            .help("Connect to Desktop")
                            Image(systemName: "return")
                                .font(.system(size: 11, weight: .medium))
                                .foregroundStyle(.secondary.opacity(0.55))
                        } else if showContextInDock {
                            // Context dock: optional action button (+ for Finder, tabs for Safari)
                            // followed by the ↵ return hint — both always visible at the same time
                            if l2.targetApp == nil,
                                frontmost.bundleID == "com.apple.finder",
                                canAttachCurrentFinderFolderToConversation
                            {
                                addFinderFolderButton
                            } else if l2.targetApp == nil,
                                AXWebReader.shared.isBrowser(bundleId: frontmost.bundleID)
                            {
                                safariTabsButton
                            }
                            Image(systemName: "return")
                                .font(.system(size: 11, weight: .medium))
                                .foregroundStyle(.secondary.opacity(0.55))
                        }
                    }
                }
                .padding(.horizontal, ((isSearchBarExpanded || usesVerticalListDockLayout) && (l2.focusedPillIndex == nil || usesVerticalListDockLayout) && !showMediaLayer) ? 12 : 8)
                .padding(.vertical, inputVerticalPadding)
                .frame(maxWidth: ((isSearchBarExpanded || usesVerticalListDockLayout) && (l2.focusedPillIndex == nil || usesVerticalListDockLayout) && !showMediaLayer) ? .infinity : 44)
                .frame(height: inputPillHeight)
                .background {
                    // Context dock: keep app scope readable without turning the
                    // search capsule into a saturated app-colored panel.
                    let inContextDock = (showContextInDock || isGlobalContextActive || aiMode.isActive) && !usesVerticalListDockLayout
                    let typedMatch =
                        hasActiveDockContextSelection || shouldUsePureGlobalAppSearch
                        ? nil : typedL2AppIcon(for: searchState.query)
                    let inAppScope = (l2.targetApp != nil || typedMatch != nil) && showContextInDock
                    let scopeColor: SwiftUI.Color =
                        l2.targetApp?.icon?.dominantSwiftUIColor
                        ?? typedMatch?.icon.dominantSwiftUIColor
                        ?? frontmost.icon?.dominantSwiftUIColor
                        ?? .white
                    ZStack {
                        if usesVerticalListDockLayout {
                            Color.clear
                        } else if inContextDock {
                            // Capsule pill — identical shape to expanded appPillButton
                            Capsule()
                                .fill(.ultraThinMaterial)
                            Capsule()
                                .fill(
                                    LinearGradient(
                                        colors: [
                                            Color.white.opacity(inAppScope ? 0.24 : 0.22),
                                            Color.white.opacity(inAppScope ? 0.05 : 0.04)
                                        ],
                                        startPoint: .top,
                                        endPoint: .bottom
                                    )
                                )
                            // App-color tint
                            Capsule()
                                .fill(
                                    LinearGradient(
                                        colors: [
                                            scopeColor.opacity(inAppScope ? 0.08 : 0.10),
                                            scopeColor.opacity(inAppScope ? 0.015 : 0.02)
                                        ],
                                        startPoint: .topLeading,
                                        endPoint: .bottomTrailing
                                    )
                                )
                            // Bright gradient border — matches expanded pill (0.65 → 0.06)
                            Capsule()
                                .strokeBorder(
                                    LinearGradient(
                                        colors: [.white.opacity(0.65), .white.opacity(0.06)],
                                        startPoint: .topLeading,
                                        endPoint: .bottomTrailing
                                    ),
                                    lineWidth: 1.5
                                )
                            // Glow ring — mirrors expanded pill focus ring
                            Capsule()
                                .strokeBorder(Color.white.opacity(0.75), lineWidth: 1.5)
                                .blur(radius: 3)
                        } else {
                            // Non-context-dock: plain dark rounded rect
                            RoundedRectangle(cornerRadius: 12, style: .continuous)
                                .fill(Color.black.opacity(0.18))
                            RoundedRectangle(cornerRadius: 12, style: .continuous)
                                .strokeBorder(
                                    LinearGradient(
                                        colors: [Color.white.opacity(0.08), Color.white.opacity(0.04)],
                                        startPoint: .topLeading,
                                        endPoint: .bottomTrailing
                                    ),
                                    lineWidth: 0.75
                                )
                        }
                    }
                    .animation(.spring(response: 0.28, dampingFraction: 0.75), value: inContextDock)
                    .animation(.easeInOut(duration: 0.25), value: inAppScope)
                    .animation(.easeInOut(duration: 0.3), value: frontmost.bundleID)
                }
                .onHover { hovering in
                    isHoveringInputField = hovering

                    // Auto-shrink when mouse leaves input field (if no text and not focused)
                    if !hovering && searchState.query.isEmpty && !isSearchFieldFocused && !usesVerticalListDockLayout {
                        startCollapseTimer()
                    }
                }
                .animation(.spring(response: 0.28, dampingFraction: 0.72), value: isSearchBarExpanded)
                } // end if focusedAppPillIndex == nil

                // Pinned apps or context chips/AI extensions or browser (3-layer swipeable)
                if searchState.activeSmartQueryKey != "clipboard" && !aiMode.isActive && !usesVerticalListDockLayout {
                HStack(spacing: 8) {
                    // Floating selection pill — not shown in context dock (already in search bar)
                    if !showContextInDock { selectionFloatingPill }
                    // Clipboard pill moved to searchBarSection (floats left of the main dock card)

                    Group {
                        if showMediaLayer {
                            mediaControlsInDock
                                .transition(.opacity.combined(with: .move(edge: .trailing)))
                        } else if searchState.activeSmartQueryKey != nil && searchState.activeSmartQueryKey != "clipboard" {
                            appShortcutsInDock
                                .transition(.opacity)
                        } else if showContextInDock {
                            if aiMode.isActive {
                                EmptyView()
                            } else if isGlobalContextActive {
                                // Global context: empty query shows pinned/running; typed query searches
                                // pinned, running, and installed applications.
                                if shouldShowL2UnifiedDockRow {
                                    l2UnifiedDockRow
                                        .transition(.opacity)
                                }
                            } else if hasAIExtensionsToShow {
                                aiExtensionsInDock
                                    .transition(.opacity)
                            } else if shouldShowL2UnifiedDockRow {
                                l2UnifiedDockRow
                                    .transition(.opacity)
                            }
                        } else if !searchState.query.isEmpty {
                            pinnedAppsListView
                        }
                    }
                    .frame(maxWidth: .infinity)
                    .frame(
                        height: showMediaLayer
                            ? (mediaObserver.duration > 0 ? 70 : inputPillHeight)
                            : nil
                    )

                }
                .onHover { hovering in
                    isHoveringDockArea = hovering
                    // When mouse enters the dock area, switch from keyboard nav to hover nav
                    if hovering { l2.pillNavViaKeyboard = false }
                }
                .animation(.spring(response: 0.3, dampingFraction: 0.75), value: showContextInDock)
                .animation(.spring(response: 0.28, dampingFraction: 0.82), value: showMediaLayer)
                }
            }
            .frame(maxWidth: .infinity)
            .padding(.horizontal, 12)
            .padding(.vertical, outerVerticalPadding)

        }
        .frame(maxWidth: .infinity)
    }

    @ViewBuilder
    private var mediaControlsInDock: some View {
        let progress = mediaObserver.duration > 0
            ? min(max(mediaObserver.elapsed / max(mediaObserver.duration, 1), 0), 1)
            : 0

        VStack(spacing: 0) {
            // Album art → app icon (observer) → app icon (running apps scan) → music note
            let resolvedMediaIcon: NSImage? = mediaObserver.appIcon ?? {
                guard !mediaObserver.appName.isEmpty else { return nil }
                let name = mediaObserver.appName.lowercased()
                return NSWorkspace.shared.runningApplications
                    .first(where: { ($0.localizedName ?? "").lowercased() == name })?.icon
            }()

            HStack(spacing: 14) {
                HStack(spacing: 10) {
                    appleMusicIconButton(systemName: "shuffle", disabled: true) {}
                    appleMusicIconButton(systemName: "backward.fill") {
                        mediaObserver.skipBack()
                    }
                    Button {
                        mediaObserver.togglePlayPause()
                    } label: {
                        Image(systemName: mediaObserver.isPlaying ? "pause.fill" : "play.fill")
                            .font(.system(size: 17, weight: .bold))
                            .foregroundStyle(.white)
                            .frame(width: 36, height: 36)
                            .background(Color.accentColor, in: RoundedRectangle(cornerRadius: 10, style: .continuous))
                            .shadow(color: Color.accentColor.opacity(0.35), radius: 8, y: 2)
                    }
                    .buttonStyle(.plain)
                    .help(mediaObserver.isPlaying ? "Pause" : "Play")
                    appleMusicIconButton(systemName: "forward.fill") {
                        mediaObserver.skipForward()
                    }
                    appleMusicIconButton(systemName: "repeat", disabled: true) {}
                }
                .frame(minWidth: 184, alignment: .leading)

                Group {
                    if let art = mediaObserver.artworkImage {
                        Image(nsImage: art)
                            .resizable()
                            .aspectRatio(contentMode: .fill)
                    } else if let icon = resolvedMediaIcon {
                        Image(nsImage: icon)
                            .resizable()
                            .aspectRatio(contentMode: .fit)
                    } else {
                        RoundedRectangle(cornerRadius: 8, style: .continuous)
                            .fill(Color.white.opacity(0.08))
                            .overlay(
                                Image(systemName: "music.note")
                                    .font(.system(size: 15, weight: .semibold))
                                    .foregroundStyle(.secondary)
                            )
                    }
                }
                .frame(width: 38, height: 38)
                .clipShape(RoundedRectangle(cornerRadius: 8, style: .continuous))

                VStack(alignment: .leading, spacing: 2) {
                    Text(
                        mediaObserver.title.isEmpty
                            ? (mediaObserver.appName.isEmpty ? "Now Playing" : mediaObserver.appName)
                            : mediaObserver.title
                    )
                    .font(.system(size: 14, weight: .semibold))
                    .foregroundStyle(.primary)
                    .lineLimit(1)

                    Text(mediaObserver.artist.isEmpty ? mediaObserver.appName : mediaObserver.artist)
                        .font(.system(size: 12, weight: .medium))
                        .foregroundStyle(.secondary)
                        .lineLimit(1)
                }
                .frame(maxWidth: .infinity, alignment: .leading)

                HStack(spacing: 12) {
                    appleMusicIconButton(systemName: "ellipsis") {}
                    appleMusicIconButton(systemName: "quote.bubble", disabled: true) {}
                    appleMusicIconButton(systemName: "list.bullet", disabled: true) {}
                    appleMusicIconButton(systemName: "speaker.wave.2.fill", disabled: true) {}
                }
                .frame(minWidth: 148, alignment: .trailing)
            }
            .padding(.horizontal, 18)
            .frame(height: 58)

            if mediaObserver.duration > 0 {
                GeometryReader { geo in
                    ZStack(alignment: .leading) {
                        Capsule()
                            .fill(Color.white.opacity(0.16))
                        Capsule()
                            .fill(Color.white.opacity(0.72))
                            .frame(width: max(6, geo.size.width * CGFloat(progress)))
                    }
                }
                .frame(height: 3)
                .padding(.horizontal, 18)
                .padding(.bottom, 8)
                .animation(.linear(duration: 0.25), value: mediaObserver.elapsed)
            }
        }
        .frame(maxWidth: .infinity)
        .frame(height: mediaObserver.duration > 0 ? 70 : 58)
        .background {
            ZStack {
                Capsule().fill(.ultraThinMaterial)
                Capsule()
                    .fill(LinearGradient(
                        colors: [Color.white.opacity(0.18), Color.white.opacity(0.035)],
                        startPoint: .top, endPoint: .bottom))
                Capsule()
                    .strokeBorder(
                        LinearGradient(
                            colors: [Color.white.opacity(0.58), Color.white.opacity(0.06)],
                            startPoint: .topLeading, endPoint: .bottomTrailing),
                        lineWidth: 1.5)
                Capsule()
                    .strokeBorder(Color.white.opacity(0.75), lineWidth: 1.5)
                    .blur(radius: 3)
            }
        }
    }

    @ViewBuilder
    private func compactMediaButton(
        systemName: String,
        filled: Bool = false,
        action: @escaping () -> Void
    ) -> some View {
        Button(action: action) {
            Image(systemName: systemName)
                .font(.system(size: filled ? 13 : 12, weight: .semibold))
                .foregroundStyle(filled ? .white : .primary)
                .frame(width: filled ? 30 : 26, height: filled ? 30 : 26)
                .background(
                    filled ? Color.accentColor : Color.primary.opacity(0.07),
                    in: RoundedRectangle(cornerRadius: filled ? 8 : 7, style: .continuous)
                )
        }
        .buttonStyle(.plain)
    }

    @ViewBuilder
    private func appleMusicIconButton(
        systemName: String,
        disabled: Bool = false,
        action: @escaping () -> Void
    ) -> some View {
        Button(action: action) {
            Image(systemName: systemName)
                .font(.system(size: 16, weight: .semibold))
                .foregroundStyle(
                    disabled ? Color.secondary.opacity(0.45) : Color.primary.opacity(0.86)
                )
                .frame(width: 24, height: 32)
                .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        .disabled(disabled)
    }

    /// SF Symbol name for a file extension
    private func fileIcon(for ext: String) -> String {
        switch ext {
        case "pdf": return "doc.richtext"
        case "jpg", "jpeg", "png", "heic", "gif", "webp", "tiff": return "photo"
        case "mp4", "mov", "avi", "mkv", "m4v": return "film"
        case "mp3", "aac", "flac", "wav", "m4a": return "music.note"
        case "zip", "rar", "7z", "tar", "gz": return "archivebox"
        case "doc", "docx", "pages": return "doc.text"
        case "xls", "xlsx", "numbers", "csv": return "tablecells"
        case "ppt", "pptx", "key": return "rectangle.on.rectangle"
        case "swift", "py", "js", "ts", "rb", "go", "rs", "kt":
            return "chevron.left.forwardslash.chevron.right"
        default: return "doc"
        }
    }

    // MARK: - Results Content (for smart positioning)
    @ViewBuilder
    private var resultsContentView: some View {
        // Show different content based on current mode (AI vs Normal)
        // The L3 media dock can still surface search results while typing.
        let content = Group {
            if aiMode.isActive {
                // AI mode: AI Chat section (works on L1/L2/L3)
                aiChatSection
                    .transition(.opacity.combined(with: .scale(scale: 0.98)))
            } else if showContextInDock && !showMediaLayer
                && (searchState.contextApp != nil || searchState.activeSmartQueryKey != nil)
            {
                appPanelView
                    .transition(.opacity.combined(with: .scale(scale: 0.98)))
            } else if showContextInDock && !showMediaLayer
                && shouldShowFinderSearchResultsPanel(for: searchState.query)
            {
                finderFolderSearchResultsPanel
                    .transition(.opacity.combined(with: .scale(scale: 0.98)))
            } else if showContextInDock && !showMediaLayer {
                VStack(spacing: 0) {
                    // Two-column row: chat left + results/filePreview right
                    HStack(spacing: 0) {
                        l2ChatSection
                        if livePanelVisible {
                            switch livePanelMode {
                            case .results, .filePreview:
                                livePanelView
                                    .transition(
                                        .asymmetric(
                                            insertion: .move(edge: .trailing).combined(with: .opacity),
                                            removal: .move(edge: .trailing).combined(with: .opacity)
                                        ))
                            default:
                                EmptyView()
                            }
                        }
                    }
                    .animation(.spring(response: 0.28, dampingFraction: 0.85), value: livePanelVisible)
                    // Terminal drawer below chat (only for .terminal mode)
                    if livePanelVisible, case .terminal = livePanelMode,
                        let term = panelTerminalControllers[activeConsoleKey]
                    {
                        Divider().opacity(0.12)
                        inlineDockTerminalView(term: term)
                    }
                }
                .transition(.opacity.combined(with: .scale(scale: 0.98)))
            } else {
                // Normal mode: Search results (works on L1/L2/L3)
                // L3 stays media-first, but search typing still uses the shared results list.
                indexingProgressSection
                    .transition(.opacity.combined(with: .scale(scale: 0.98)))
                resultsSection
                    .transition(.opacity.combined(with: .scale(scale: 0.98)))
            }
        }

        if settings.effectiveDockAtBottom {
            // In dock mode, add padding to results (match compact dock height)
            content
                .padding(.horizontal, 12)
                .padding(.bottom, 6)
        } else {
            // In normal mode, add subtle padding at top for smooth connection to dock
            content
                .padding(.top, searchState.activeSmartQueryKey == "clipboard" ? 0 : 4)
        }
    }

    @ViewBuilder
    private var finderFolderSearchResultsPanel: some View {
        let scope = resolveDockScope(for: searchState.query)
        let folderPath = currentFinderFolderPath()
        let folderName = URL(fileURLWithPath: folderPath).lastPathComponent
        let query = scope.scopedSearchQuery.trimmingCharacters(in: .whitespacesAndNewlines)

        VStack(alignment: .leading, spacing: 0) {
            HStack(spacing: 8) {
                Image(systemName: "folder.badge.magnifyingglass")
                    .font(.system(size: 11, weight: .semibold))
                    .foregroundStyle(.secondary)
                Text(folderName.isEmpty ? "Current Folder Search" : folderName)
                    .font(.system(size: 13, weight: .semibold))
                    .lineLimit(1)
                Spacer()
                Text("Names + Content")
                    .font(.system(size: 11, weight: .medium))
                    .foregroundStyle(.secondary)
            }
            .padding(.horizontal, 16)
            .padding(.top, 10)
            .padding(.bottom, 8)

            Divider()
                .padding(.horizontal, 12)

            if isFinderSemanticLoading && searchState.results.isEmpty {
                VStack(spacing: 10) {
                    ProgressView()
                    Text("Searching filenames and indexed content in this folder…")
                        .font(.system(size: 13))
                        .foregroundStyle(.secondary)
                        .multilineTextAlignment(.center)
                }
                .frame(maxWidth: .infinity)
                .padding(.vertical, 28)
                .padding(.horizontal, 16)
            } else if !query.isEmpty && searchState.results.isEmpty {
                VStack(spacing: 10) {
                    Image(systemName: "magnifyingglass")
                        .font(.system(size: 18, weight: .medium))
                        .foregroundStyle(.secondary.opacity(0.8))
                    Text("No matches in this Finder folder.")
                        .font(.system(size: 13, weight: .medium))
                        .foregroundStyle(.primary)
                    Text("Try another name or content phrase.")
                        .font(.system(size: 12))
                        .foregroundStyle(.secondary)
                }
                .frame(maxWidth: .infinity)
                .padding(.vertical, 28)
                .padding(.horizontal, 16)
            } else {
                resultsSection
            }
        }
    }

