    private func l2ApprovalCardMeta(_ msg: AIChatMessage) -> (purpose: String, risk: String, isDockCommand: Bool) {
        let sd = msg.structuredData ?? ""
        if sd.hasPrefix("dock_cmd|||") {
            return (String(sd.dropFirst("dock_cmd|||".count)), "Moderate", true)
        }
        let parts = sd.components(separatedBy: "|||/")
        return (parts.first ?? "", parts.count > 1 ? parts[1] : "Unknown", false)
    }

    @ViewBuilder
    private func l2InlineApprovalCard(_ msg: AIChatMessage) -> some View {
        let (purpose, risk, isDockCommand) = l2ApprovalCardMeta(msg)
        let isHighRisk = risk.lowercased().contains("high") || risk.lowercased().contains("critical")
        let isHandled = l2.handledApprovalIds.contains(msg.id)
        let isPending = isDockCommand ? !isHandled : (terminalBridge.pendingApproval != nil)
        let termIconColor: SwiftUI.Color = isHandled ? .green : (isHighRisk ? .orange : .accentColor)

        VStack(alignment: .leading, spacing: 8) {
            HStack(spacing: 6) {
                Image(systemName: "terminal.fill")
                    .font(.system(size: 11, weight: .semibold))
                    .foregroundStyle(termIconColor)
                Text(isHandled ? "Sent to terminal" : "Run command?")
                    .font(.system(size: 11, weight: .semibold))
                Spacer()
                if isHandled {
                    Image(systemName: "checkmark.circle.fill")
                        .font(.system(size: 11))
                        .foregroundStyle(.green)
                } else if isHighRisk {
                    Text(risk)
                        .font(.system(size: 9, weight: .semibold))
                        .foregroundStyle(.orange)
                        .padding(.horizontal, 6).padding(.vertical, 2)
                        .background(Color.orange.opacity(0.15), in: Capsule())
                }
            }
            if !purpose.isEmpty {
                Text(purpose)
                    .font(.system(size: 11))
                    .foregroundStyle(.secondary)
            }
            Text(msg.content)
                .font(.system(size: 11, design: .monospaced))
                .padding(.horizontal, 8).padding(.vertical, 5)
                .background(Color.black.opacity(0.35), in: RoundedRectangle(cornerRadius: 5))
                .frame(maxWidth: .infinity, alignment: .leading)
            if !isHandled {
                HStack(spacing: 8) {
                    Button("Deny") {
                        l2.handledApprovalIds.insert(msg.id)
                        if !isDockCommand { TerminalAIBridge.shared.denyCommand() }
                    }
                    .buttonStyle(.plain)
                    .font(.system(size: 11, weight: .medium))
                    .foregroundStyle(.secondary)
                    .padding(.horizontal, 12).padding(.vertical, 5)
                    .background(Color.primary.opacity(0.08), in: RoundedRectangle(cornerRadius: 6))
                    .disabled(!isPending)
                    Button {
                        if isDockCommand {
                            l2.handledApprovalIds.insert(msg.id)
                            // Ensure terminal is open and visible
                            if !livePanelVisible || livePanelMode != .terminal {
                                withAnimation(.spring(response: 0.28, dampingFraction: 0.85)) {
                                    livePanelMode = .terminal
                                    livePanelVisible = true
                                }
                            }
                            let consoleKey = activeConsoleKey
                            DispatchQueue.main.asyncAfter(deadline: .now() + 0.15) {
                                panelTerminal(for: consoleKey).sendCommand(msg.content)
                            }
                        } else {
                            TerminalAIBridge.shared.approveCommand(msg.content)
                        }
                    } label: {
                        HStack(spacing: 4) {
                            Image(systemName: "play.fill").font(.system(size: 9))
                            Text("Approve & Run")
                        }
                        .font(.system(size: 11, weight: .semibold))
                        .foregroundStyle(.white)
                        .padding(.horizontal, 14).padding(.vertical, 5)
                        .background(isPending ? Color.accentColor : Color.gray, in: RoundedRectangle(cornerRadius: 6))
                    }
                    .buttonStyle(.plain)
                    .disabled(!isPending)
                }
            }
        }
        .padding(12)
        .background(
            RoundedRectangle(cornerRadius: 10)
                .fill(cardBgFill(isHandled: isHandled, isHighRisk: isHighRisk))
        )
        .overlay(
            RoundedRectangle(cornerRadius: 10)
                .strokeBorder(cardBorderColor(isHandled: isHandled, isHighRisk: isHighRisk), lineWidth: 0.5)
        )
        .frame(maxWidth: .infinity, alignment: .leading)
    }

    private func cardBgFill(isHandled: Bool, isHighRisk: Bool) -> SwiftUI.Color {
        if isHandled { return SwiftUI.Color.green.opacity(0.06) }
        if isHighRisk { return SwiftUI.Color.orange.opacity(0.08) }
        return SwiftUI.Color.accentColor.opacity(0.07)
    }

    private func cardBorderColor(isHandled: Bool, isHighRisk: Bool) -> SwiftUI.Color {
        if isHandled { return SwiftUI.Color.green.opacity(0.2) }
        if isHighRisk { return SwiftUI.Color.orange.opacity(0.25) }
        return SwiftUI.Color.accentColor.opacity(0.2)
    }

