                                }
                            }
                            .padding(.horizontal, 16)
                            .padding(.vertical, 12)
                        } else {
                            // List View
                            LazyVStack(spacing: 0) {
                                ForEach(Array(folderItems.enumerated()), id: \.element.id) {
                                    index, item in
                                    FolderItemRow(
                                        item: item, isSelected: selectedItemIndex == index,
                                        iconSize: iconSize.rawValue
                                    )
                                    .id(index)
                                    .contentShape(Rectangle())
                                    .onTapGesture(count: 2) {
                                        openItem(item)
                                    }
                                    .onTapGesture(count: 1) {
                                        selectedItemIndex = index
                                        selectionByKeyboard = false
                                        // Update parent's selected file context
                                        selectedFilePath = item.path
                                    }
                                    .contextMenu {
                                        Button { openItem(item) } label: {
                                            Label("Open", systemImage: "arrow.up.right.square")
                                        }
                                        if item.isDirectory {
                                            Button { navigateIntoFolder(item) } label: {
                                                Label("Enter Folder", systemImage: "folder")
                                            }
                                        }
                                        Button { quickLookItem(item) } label: {
                                            Label("Quick Look", systemImage: "eye")
                                        }
                                        Button { NSWorkspace.shared.selectFile(item.path, inFileViewerRootedAtPath: "") } label: {
                                            Label("Show in Finder", systemImage: "folder.badge.questionmark")
                                        }
                                        Divider()
                                        Button {
                                            let pasteboard = NSPasteboard.general
                                            pasteboard.clearContents()
                                            pasteboard.setString(item.path, forType: .string)
                                        } label: {
                                            Label("Copy Path", systemImage: "doc.on.clipboard")
                                        }
                                    }

                                    if index < folderItems.count - 1 {
